from pathlib import Path


def _resolver_icone() -> str:
    caminhos = []
    if getattr(sys, "frozen", False):
        caminhos.append(Path(sys.executable).resolve().parent / "icon.ico")
        _meipass = getattr(sys, "_MEIPASS", "")
        if _meipass:
            caminhos.append(Path(_meipass) / "icon.ico")
    caminhos.append(Path(r"C:\AutomacaoSAP") / "icon.ico")
    for p in caminhos:
        try:
            if p.is_file() and p.stat().st_size > 0:
                return str(p)
        except Exception:
            continue
    return ""


