# =====================================================
# SAP COM EARLY BINDING
# Gerado com: python -m win32com.client.makepy
#             "SAP GUI Scripting"
# Elimina busca de nome em IDispatch::Invoke
# =====================================================

def _log_bootstrap(mensagem, nivel="INFO"):
    """Registra mensagens antes de registrar_log existir."""
    log_fn = globals().get("registrar_log")
    if callable(log_fn):
        try:
            log_fn(mensagem, nivel)
        except Exception:
            pass


def _inicializar_sap_early_binding():
    """
    Tenta usar Early Binding para o SAP GUI Scripting.
    Se falhar (typelib n?o registrada), usa Late Binding.
    Ganho: ?40% no tempo de cada opera??o COM.
    """
    try:
        # Tenta importar typelib pr?-compilada
        win32com.client.gencache.EnsureModule(
            '{F935DC20-1CF0-11D0-ADB9-00C04FD58A0B}',
            0, 1, 0
        )
        _log_bootstrap(
            "SAP COM: Early Binding ativado.",
            "INFO"
        )
        return True
    except Exception:
        _log_bootstrap(
            "SAP COM: usando Late Binding "
            "(Early Binding indispon?vel).",
            "INFO"
        )
        return False

