# pdfplumber e reportlab são importados sob demanda
# dentro de extrair_dados_rm() e gerar_espelho_nf()
# para reduzir o tempo de inicialização do splash screen
# =====================================================
# LAZY LOADER — importa módulos pesados sob demanda
# com cache thread-safe
# =====================================================

class _LazyModule:
    """
    Carrega um módulo Python somente quando o
    atributo é acessado pela primeira vez.
    Thread-safe via lock.

    Uso:
        pdfplumber = _LazyModule("pdfplumber")
        # Módulo ainda não carregado

        with pdfplumber.open(...) as pdf:
            # Módulo carregado aqui, na primeira vez
    """

    def __init__(self, nome: str):
        self._nome    = nome
        self._modulo  = None
        self._lock    = threading.Lock()
        self._erro    = None

    def _carregar(self):
        with self._lock:
            if self._modulo is None and self._erro is None:
                try:
                    import importlib
                    self._modulo = importlib.import_module(
                        self._nome
                    )
                except ImportError as e:
                    self._erro = e
                    raise

    def __getattr__(self, attr):
        if attr.startswith("_"):
            raise AttributeError(attr)
        self._carregar()
        return getattr(self._modulo, attr)

    def __call__(self, *args, **kwargs):
        self._carregar()
        return self._modulo(*args, **kwargs)


# Módulos pesados como lazy loaders
# (só serão importados quando usados pela primeira vez)
_pdfplumber_lazy  = _LazyModule("pdfplumber")
_PIL_Image_lazy   = _LazyModule("PIL.Image")
_PIL_Draw_lazy    = _LazyModule("PIL.ImageDraw")
_fitz_lazy        = _LazyModule("fitz")   # PyMuPDF


def _pre_carregar_modulos_background():
    """
    Pré-carrega módulos pesados em background
    durante o splash screen, para que estejam
    prontos quando necessários.
    """
    def _carregar():
        for modulo in [
            _pdfplumber_lazy,
            _PIL_Image_lazy,
        ]:
            try:
                modulo._carregar()
            except Exception:
                pass   # módulo opcional

    t = threading.Thread(
        target=_carregar,
        daemon=True,
        name="ModulePreloader"
    )
    t.start()
    return t


