# Suprime OleInitialize e outros avisos C++ do Qt que saem diretamente
# pelo handle fd=2 do Windows, antes de qualquer código Python ser executado.
# A única forma de suprimir é redirecionar o fd nativo temporariamente.
import os as _os_init
import sys as _sys_init

# Suprime mensagens Qt iniciais redirecionando stderr temporariamente.
# ATENÇÃO: bloco não-thread-safe — executado antes de qualquer thread ativa.
# Nenhuma thread deve escrever em stderr durante este bloco.
#
# Em builds .exe gerados com PyInstaller no modo --windowed (sem
# console), sys.stderr é None — não existe console nenhum pra
# redirecionar, e sys.stderr.fileno() quebrava o programa logo na
# inicialização. Como não há console pra vazar mensagem nenhuma nesse
# caso, o truque de redirecionamento é desnecessário — só pula ele e
# cria a QApplication direto.
_stderr_disponivel = (
    _sys_init.stderr is not None
    and hasattr(_sys_init.stderr, "fileno")
)
if _stderr_disponivel:
    try:
        _stderr_fd = _sys_init.stderr.fileno()
    except Exception:
        _stderr_disponivel = False

if _stderr_disponivel:
    _devnull_fd = _os_init.open(_os_init.devnull, _os_init.O_WRONLY)
    _stderr_fd_backup = _os_init.dup(_stderr_fd)      # salva o fd original

    _os_init.dup2(_devnull_fd, _stderr_fd)            # redireciona fd=2 → /dev/null
    try:
        # Nenhuma thread deve ser criada antes deste bloco terminar
        _qapp = QApplication.instance() or QApplication(_sys.argv)
        _p_ico = _resolver_icone()
        if _p_ico:
            from PySide6.QtGui import QIcon as _QIconBoot
            _qapp.setWindowIcon(_QIconBoot(_p_ico))
    finally:
        _os_init.dup2(_stderr_fd_backup, _stderr_fd)  # restaura fd=2 original
        _os_init.close(_devnull_fd)
        _os_init.close(_stderr_fd_backup)
        # A partir daqui, stderr está restaurado e threads podem ser criadas com segurança

    del _devnull_fd, _stderr_fd, _stderr_fd_backup
else:
    # Sem console real (ex.: .exe gerado com --windowed) — nada a
    # redirecionar, cria a QApplication direto.
    _qapp = QApplication.instance() or QApplication(_sys.argv)
    _p_ico = _resolver_icone()
    if _p_ico:
        from PySide6.QtGui import QIcon as _QIconBoot
        _qapp.setWindowIcon(_QIconBoot(_p_ico))

del _os_init, _sys_init, _stderr_disponivel

# Instala o handler para suprimir mensagens Qt posteriores
from PySide6.QtCore import qInstallMessageHandler as _qInstallMessageHandler
from PySide6.QtCore import QtMsgType as _QtMsgType

def _qt_msg_suprimir(msg_type, context, msg):
    _ignorar = (
        "OleInitialize",
        "SetProcessDpiAwareness",
        "qt.qpa",
        "QBackingStore::endPaint",
        "Recursive repaint",
    )
    if any(t in msg for t in _ignorar):
        return
    if msg_type in (_QtMsgType.QtCriticalMsg, _QtMsgType.QtFatalMsg):
        import sys as _s
        _s.stderr.write(f"[Qt] {msg}\n")
        _s.stderr.flush()

_qInstallMessageHandler(_qt_msg_suprimir)



