# =====================================================
# SISTEMA DE DESIGN — Theme, Spacing, Typography
# Fonte única de verdade para constantes visuais.
# Elimina estilos inline repetidos em todo o código.
# =====================================================

class Theme:
    """
    Centraliza todas as constantes de design.
    Uso: Theme.VERDE_PETRO, Theme.font_title(), etc.
    """

    # ── Primárias
    VERDE_PETRO  = "#007A3E"
    VERDE_CLARO  = "#009A4E"
    AMARELO      = "#F5C800"

    # ── Fundos
    BG           = "#101820"
    CARD         = "#101820"
    BORDA        = "#21262D"
    HOVER        = "#101820"

    # ── Texto
    BRANCO       = "#F0F6FC"
    TEXTO        = "#C9D1D9"
    MUTED        = "#8B949E"

    # ── Status
    SUCESSO      = "#238636"
    ALERTA       = "#D29922"
    ERRO         = "#DA3633"
    INFO         = "#1F6FEB"
    SP           = "#6E40C9"

    # ── Espaçamentos
    XS  = 4
    SM  = 8
    MD  = 12
    LG  = 20
    XL  = 32

    # ── Raio de borda
    R_SM = 4
    R_MD = 6
    R_LG = 10

    # ── Tipografia
    @staticmethod
    def font_title(size: int = 14) -> QFont:
        return QFont("Arial Black", size, QFont.Bold)

    @staticmethod
    def font_subtitle(size: int = 10) -> QFont:
        return QFont("Segoe UI", size, QFont.Bold)

    @staticmethod
    def font_body(size: int = 9) -> QFont:
        return QFont("Segoe UI", size)

    @staticmethod
    def font_caption(size: int = 8) -> QFont:
        return QFont("Segoe UI", size)

    @staticmethod
    def font_mono(size: int = 9, bold: bool = False) -> QFont:
        w = QFont.Bold if bold else QFont.Normal
        return QFont("Consolas", size, w)

    @staticmethod
    def font_section() -> QFont:
        """Label de seção em maiúsculas."""
        return QFont("Arial", 8, QFont.Bold)

    # ── Estilos QSS reutilizáveis (strings)
    @staticmethod
    def qss_card(border_color: str = "") -> str:
        cor = border_color or Theme.BORDA
        return (
            f"QFrame#card {{"
            f"  background-color: {Theme.CARD};"
            f"  border-radius: {Theme.R_MD}px;"
            f"  border: 1px solid {cor};"
            f"}}"
        )

    @staticmethod
    def qss_section_label() -> str:
        return (
            f"color: {Theme.VERDE_PETRO};"
            f"letter-spacing: 1px;"
        )

    @staticmethod
    def qss_muted() -> str:
        return f"color: {Theme.MUTED};"

    @staticmethod
    def qss_success() -> str:
        return f"color: {Theme.SUCESSO}; font-weight: bold;"

    @staticmethod
    def qss_error() -> str:
        return f"color: {Theme.ERRO}; font-weight: bold;"

    @staticmethod
    def qss_warning() -> str:
        return f"color: {Theme.ALERTA}; font-weight: bold;"

    @staticmethod
    def qss_info() -> str:
        return f"color: {Theme.INFO};"


