def _aplicar_icone(janela) -> None:
    """Aplica icon.ico na janela e no HWND nativo (barra de tarefas)."""
    caminho = _resolver_icone()
    if not caminho or janela is None:
        return
    try:
        icone = QIcon(caminho)
        janela.setWindowIcon(icone)
        _qapp.setWindowIcon(icone)
    except Exception:
        pass
    try:
        import ctypes
        hwnd = int(janela.winId())
        IMAGE_ICON = 1
        LR_LOADFROMFILE = 0x0010
        LR_DEFAULTSIZE = 0x0040
        hicon32 = ctypes.windll.user32.LoadImageW(
            None, caminho, IMAGE_ICON, 32, 32, LR_LOADFROMFILE,
        )
        hicon16 = ctypes.windll.user32.LoadImageW(
            None, caminho, IMAGE_ICON, 16, 16, LR_LOADFROMFILE,
        )
        hicon = hicon32 or hicon16
        if not hicon:
            hicon = ctypes.windll.user32.LoadImageW(
                None, caminho, IMAGE_ICON, 0, 0,
                LR_LOADFROMFILE | LR_DEFAULTSIZE,
            )
        if hicon:
            WM_SETICON = 0x0080
            ctypes.windll.user32.SendMessageW(hwnd, WM_SETICON, 1, hicon32 or hicon)
            ctypes.windll.user32.SendMessageW(hwnd, WM_SETICON, 0, hicon16 or hicon)
            gcl_big, gcl_sm = -14, -34
            if ctypes.sizeof(ctypes.c_void_p) == 8:
                ctypes.windll.user32.SetClassLongPtrW(hwnd, gcl_big, hicon32 or hicon)
                ctypes.windll.user32.SetClassLongPtrW(hwnd, gcl_sm, hicon16 or hicon)
            else:
                ctypes.windll.user32.SetClassLongW(hwnd, gcl_big, hicon32 or hicon)
                ctypes.windll.user32.SetClassLongW(hwnd, gcl_sm, hicon16 or hicon)
    except Exception:
        pass

