from PySide6.QtCore import QEventLoop as _QEventLoop

def _process_qt_events():
    """Processa eventos Qt sem risco de repintura recursiva."""
    try:
        _qapp.processEvents(
            _QEventLoop.ProcessEventsFlag.ExcludeUserInputEvents
        )
    except Exception:
        pass


