def _diretorio_instalacao() -> Path:
    if getattr(sys, "frozen", False):
        return Path(sys.executable).resolve().parent
    return Path(r"C:\AutomacaoSAP")


def _diretorio_dados() -> Path:
    """
    Pasta gravável. No .exe distribuído NÃO é a pasta do programa
    (Program Files é só leitura): usa %LOCALAPPDATA%\\AutomacaoSAP.
    No Python (desenvolvimento) continua C:\\AutomacaoSAP.
    """
    if getattr(sys, "frozen", False):
        raiz = os.environ.get("LOCALAPPDATA") or str(
            Path.home() / "AppData" / "Local"
        )
        return Path(raiz) / "AutomacaoSAP"
    return Path(r"C:\AutomacaoSAP")


