def _migrar_config_unica(cfg) -> None:
    """Junta config_sharepoint.json + ui_aliases.json + emails_contatos.json em config.json."""
    caminho = Path(cfg.CONFIG_SAP)
    dados = {}
    if caminho.exists():
        try:
            dados = json.loads(caminho.read_text(encoding="utf-8"))
            if not isinstance(dados, dict):
                dados = {}
        except Exception:
            dados = {}
    mudou = False
    antigo_sp = cfg.BASE_DIR / "config_sharepoint.json"
    if antigo_sp.exists() and not dados.get("url_sharepoint"):
        try:
            extra = json.loads(antigo_sp.read_text(encoding="utf-8"))
            if isinstance(extra, dict) and extra.get("url_sharepoint"):
                dados["url_sharepoint"] = extra["url_sharepoint"]
                mudou = True
        except Exception:
            pass
    antigo_ui = cfg.BASE_DIR / "ui_aliases.json"
    if antigo_ui.exists() and not dados.get("ui_aliases"):
        try:
            extra = json.loads(antigo_ui.read_text(encoding="utf-8"))
            if isinstance(extra, dict):
                dados["ui_aliases"] = extra
                mudou = True
        except Exception:
            pass
    antigo_em = cfg.BASE_DIR / "emails_contatos.json"
    if antigo_em.exists():
        try:
            extra = json.loads(antigo_em.read_text(encoding="utf-8"))
            if isinstance(extra, dict):
                bloco = dict(dados.get("emails_contatos") or {})
                bloco.update(extra)
                dados["emails_contatos"] = bloco
                mudou = True
        except Exception:
            pass
        try:
            antigo_em.unlink()
        except Exception:
            pass
    if mudou:
        try:
            caminho.write_text(
                json.dumps(dados, indent=4, ensure_ascii=False),
                encoding="utf-8",
            )
        except Exception:
            return
    for arq in (antigo_sp, antigo_ui):
        try:
            if arq.exists() and (
                (arq == antigo_sp and dados.get("url_sharepoint"))
                or (arq == antigo_ui and dados.get("ui_aliases"))
            ):
                arq.unlink()
        except Exception:
            pass

Config.inicializar()
def _carregar_config_usuario():
    """
    Aplica ajustes de usuário sobre a class Config.
    Depois da unificação, o conteúdo fica em automacao.db.
    """
    dados = None
    try:
        bruto = _kv_get("config_usuario")
        if bruto:
            dados = json.loads(bruto)
    except Exception:
        dados = None
    if not isinstance(dados, dict) or not dados:
        try:
            cfg_path = Config.BASE_DIR / "config_usuario.json"
            if cfg_path.exists():
                dados = json.loads(cfg_path.read_text(encoding="utf-8"))
        except Exception as e:
            print(f"  AVISO: config_usuario.json: {e}")
            return
    if not isinstance(dados, dict):
        return
    for chave, valor in dados.items():
        if hasattr(Config, chave):
            setattr(Config, chave, valor)
    print(
        f"  ⚙  Config do usuário carregada: "
        f"{len(dados)} parâmetro(s)."
    )


_carregar_config_usuario()

