def _carregar_ui_aliases() -> dict:
    dados = json.loads(json.dumps(_UI_ALIASES_PADRAO))
    extra = None
    try:
        bruto = json.loads(_kv_get("config") or "{}")
        if isinstance(bruto, dict) and isinstance(bruto.get("ui_aliases"), dict):
            extra = bruto["ui_aliases"]
    except Exception:
        extra = None
    if extra is None:
        cfg = Path(Config.CONFIG_SAP)
        try:
            if cfg.exists():
                bruto = json.loads(cfg.read_text(encoding="utf-8"))
                if isinstance(bruto, dict) and isinstance(bruto.get("ui_aliases"), dict):
                    extra = bruto["ui_aliases"]
        except Exception as e:
            print(f"  AVISO: ui_aliases em config.json: {e}")
    if extra is None:
        legado = Config.BASE_DIR / "ui_aliases.json"
        try:
            if legado.exists():
                extra = json.loads(legado.read_text(encoding="utf-8"))
        except Exception:
            extra = None
    if isinstance(extra, dict):
        for k, v in extra.items():
            if k == "sap" and isinstance(v, dict) and isinstance(dados.get("sap"), dict):
                dados["sap"].update(v)
            else:
                dados[k] = v
        print("  ⚙  Aliases de UI carregados da configuração.")
    return dados


UI_ALIASES = _carregar_ui_aliases()


def _sap_ids(chave: str) -> list:
    bloco = (UI_ALIASES.get("sap") or {})
    val = bloco.get(chave) or _UI_ALIASES_PADRAO["sap"].get(chave) or []
    if isinstance(val, str):
        return [val]
    return list(val)


def _sap_try_press(session, caminhos: list) -> bool:
    for caminho in caminhos:
        try:
            session.findById(caminho).press()
            return True
        except Exception:
            continue
    return False


def _sap_try_obj(session, caminhos: list):
    for caminho in caminhos:
        try:
            return session.findById(caminho)
        except Exception:
            continue
    return None


def _sem_acento(texto: str) -> str:
    nfd = unicodedata.normalize("NFKD", texto or "")
    return "".join(c for c in nfd if not unicodedata.combining(c))


def _nucleo_rotulo_ui(texto: str) -> str:
    s = _sem_acento(texto).lower()
    s = re.sub(r"^[\d]+[\.\s_\-]*", "", s)
    s = re.sub(r"['`´’]", "", s)
    s = re.sub(r"[^\w\s]", " ", s)
    partes = s.split()
    if len(partes) > 1 and partes[-1] == "s":
        partes = partes[:-1]
    return " ".join(partes)


def _nucleo_pasta_nav(texto: str) -> str:
    s = _nucleo_rotulo_ui(texto)
    s = re.sub(r"\bmedicao mensal\b", "med mensal", s)
    return s


def _nucleos_pasta_equivalentes(a: str, b: str) -> bool:
    if not a or not b:
        return False
    if a == b:
        return True
    if a + "s" == b or b + "s" == a:
        return True
    return False


def _contrato_no_nome_pasta(numero, texto: str) -> bool:
    """Pasta do contrato: basta o número aparecer no nome (SULZER_4600…)."""
    n = re.sub(r"\D", "", str(numero or ""))
    if len(n) < 6:
        return False
    nome = _nome_exibido_pasta_sp(texto)
    if n in nome or n in (texto or ""):
        return True
    compacto = re.sub(r"[\s.\-_/]", "", nome)
    return n in compacto


def _rotulos_ui_coincidem(procurado: str, encontrado: str, exato: bool) -> bool:
    """
    Contrato: o número existe no nome da pasta.
    Demais pastas: acento, pontuação, 10./01. e plural não precisam
    ser iguais. Não usa substring no meio de outro nome (METROVAL).
    """
    p = str(procurado or "").strip()
    e = str(encontrado or "").strip()
    if not p or not e:
        return False
    nome = _nome_exibido_pasta_sp(e)
    if not nome:
        return False

    so_num = re.sub(r"\D", "", p)
    if re.fullmatch(r"\d{6,}", so_num) and p.replace(" ", "") == so_num:
        return _contrato_no_nome_pasta(so_num, e)

    # Pasta do ano: nome deve SER o ano (ex.: "2026").
    # Nunca casar com "BS/SOP/GPS - 2026 - Todos os Documentos - Uso de memória…".
    if re.fullmatch(r"\d{4}", p):
        nome_limpo = (nome or "").strip()
        return nome_limpo == p

    pl, nl = p.lower(), nome.lower()
    if pl == nl:
        return True
    np, nn = _nucleo_pasta_nav(p), _nucleo_pasta_nav(nome)
    if _nucleos_pasta_equivalentes(np, nn):
        return True
    if exato:
        return False
    return False


def _limpar_lixo_ui_nome_pasta_sp(nome: str) -> str:
    """Remove botões da ribbon do SharePoint colados no nome da pasta."""
    n = " ".join((nome or "").split())
    if not n:
        return n
    for padrao in (
        r"\s+Mais Ações\s+Compartilhar\s*",
        r"\s+Mais Ações\s*",
        r"\s+Compartilhar\s*",
        r"\s+More actions\s+Share\s*",
        r"\s+More actions\s*",
        r"\s+Share\s*",
        r"\s+-\s+Todos os Documentos.*$",
        r"\s+-\s+All Documents.*$",
        r"\s+-\s+Uso de mem[oó]ria.*$",
        r"\s+-\s+Memory usage.*$",
    ):
        n = re.sub(padrao, " ", n, flags=re.I).strip()
    return " ".join(n.split())


def _texto_parece_lixo_navegacao_sp(texto: str) -> bool:
    """Título da aba, breadcrumb ou linha da grade que não é pasta."""
    t = " ".join((texto or "").split()).lower()
    if not t:
        return True
    marcadores = (
        "uso de memória", "uso de memoria", "memory usage",
        "todos os documentos", "all documents",
        "bs/sop/gps - documentos",
        " páginas - ", " pages - ",
        "trabalho — microsoft", "trabalho - microsoft",
        "work — microsoft", "work - microsoft",
    )
    for m in marcadores:
        if m in t:
            return True
    if re.search(r"\b\d+\s*mb\b", t):
        return True
    if t.startswith("bs/sop/gps -") and "documentos" in t:
        return True
    return False


def _url_parece_lixo_navegacao_sp(url: str) -> bool:
    u = unquote(str(url or "")).replace("+", " ")
    return _texto_parece_lixo_navegacao_sp(u)


_ultimo_motivo_falha_pasta_sp = ""
_MOTIVO_SP_OK = ""
_MOTIVO_SP_NAO_NA_LISTA = "nao_na_lista"
_MOTIVO_SP_ABERTURA_FALHOU = "abertura_falhou"


def _set_motivo_falha_pasta_sp(motivo: str) -> None:
    globals()["_ultimo_motivo_falha_pasta_sp"] = str(motivo or "")


def _motivo_falha_pasta_sp() -> str:
    return str(globals().get("_ultimo_motivo_falha_pasta_sp") or "")


def _registrar_erro_navegacao_sp(
    janela_sp, nome_tentado: str, detalhe: str = "",
) -> None:
    """Erro de clique/URL — log para diagnóstico; não culpa pasta inexistente."""
    msg = (
        f"AVISO [SP-NAVEGAÇÃO]: possível clique ou URL incorreto ao abrir "
        f"'{nome_tentado}'"
    )
    if detalhe:
        msg += f" — {detalhe}"
    msg += ". O programa vai tentar de novo."
    registrar_log(msg, "AVISO")
    try:
        url = _capturar_url_atual(janela_sp)
        if url:
            registrar_log(f"INFO [SP-NAVEGAÇÃO]: URL atual: {url[:200]}", "INFO")
    except Exception:
        pass
    try:
        _enviar_email_erro_diagnostico(
            f"SharePoint — navegação incorreta em '{nome_tentado}'",
            detalhe or msg,
            LOG_FILE,
        )
    except Exception:
        pass


def _validar_abertura_pasta_sp(
    janela_sp, nome_esperado: str, url_antes: str = "",
) -> bool:
    """False se caiu em título/lixo da UI em vez da pasta real."""
    try:
        url = _capturar_url_atual(janela_sp) or ""
    except Exception:
        url = ""
    if _url_parece_lixo_navegacao_sp(url):
        return False
    nome = _limpar_lixo_ui_nome_pasta_sp(nome_esperado or "")
    if nome and _texto_parece_lixo_navegacao_sp(nome):
        return False
    if url and url_antes and url != url_antes:
        if nome and _url_indica_pasta(url, nome, nome):
            return True
        # Ano/mês numérico na URL
        if re.fullmatch(r"\d{2,4}", nome or ""):
            return nome in unquote(url)
        return True
    if not url_antes and url and not _url_parece_lixo_navegacao_sp(url):
        return True
    return bool(nome and not _texto_parece_lixo_navegacao_sp(nome))


def _nome_exibido_pasta_sp(texto: str) -> str:
    """
    O SharePoint junta 'Selecionar linha', nome da pasta e 'Abre o
    cartão...' num único texto. O nome da pasta é o que importa.
    """
    t = " ".join((texto or "").split())
    fim = (
        r"(?:\s+\d{1,2}\s+de\s+[A-Za-zçÇáéíóúãõ]+"
        r"|\s+Abre o cart"
        r"|\s+Opens the"
        r"|\s+\d+\s+itens"
        r"|\s+\d+\s+items"
        r"|$)"
    )
    m = re.search(rf"(?:pasta|folder)\s+(.+?){fim}", t, re.I)
    if m:
        return _limpar_lixo_ui_nome_pasta_sp(m.group(1).strip())
    # "Selecionar linha Pedidos Abre o cartão..." (PT/EN)
    m2 = re.search(
        rf"(?:selecionar\s+linha|select\s+row)\s+(.+?){fim}",
        t,
        re.I,
    )
    if m2:
        return _limpar_lixo_ui_nome_pasta_sp(m2.group(1).strip())
    return _limpar_lixo_ui_nome_pasta_sp(t)


def _extrair_email_de_texto(texto: str) -> str:
    m = re.search(
        r"[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}",
        texto or "",
        re.I,
    )
    return (m.group(0) if m else "").strip()


def limpar_logs_antigos():
    """
    Um único automacao.log (append). Se passar de 8 MB, vira
    automacao_anterior.log. Logs datados velhos são apagados.
    """
    try:
        unico = Config.LOG_ARQUIVO
        if unico.exists() and unico.stat().st_size > Config.LOG_MAX_BYTES:
            anterior = Config.LOG_DIR / "automacao_anterior.log"
            try:
                if anterior.exists():
                    anterior.unlink()
            except Exception:
                pass
            unico.replace(anterior)
        limite = Config.LOG_RETENCAO_DIAS
        agora = datetime.now()
        for arq in list(Config.LOG_DIR.glob("*.log")) + list(Config.LOG_DIR.glob("*.csv")) + list(Config.LOG_DIR.glob("*.eml")):
            if arq.name in ("automacao.log", "automacao_anterior.log"):
                continue
            try:
                idade = (agora - datetime.fromtimestamp(arq.stat().st_mtime)).days
                if idade > limite:
                    arq.unlink()
            except Exception:
                pass
        pasta_eml = Config.BASE_DIR / "rascunhos_eml"
        if pasta_eml.is_dir():
            for arq in pasta_eml.glob("*.eml"):
                try:
                    idade = (agora - datetime.fromtimestamp(arq.stat().st_mtime)).days
                    if idade > limite:
                        arq.unlink()
                except Exception:
                    pass
    except Exception:
        pass


def _agendar_limpar_logs_antigos():
    """Adia limpeza de logs para não atrasar a abertura do app."""
    try:
        threading.Thread(
            target=limpar_logs_antigos, daemon=True, name="limpar_logs",
        ).start()
    except Exception:
        try:
            limpar_logs_antigos()
        except Exception:
            pass


_agendar_limpar_logs_antigos()

import sqlite3 as _sqlite3
from contextlib import contextmanager as _contextmanager

_DB_PATH = str(Config.BASE_DIR / "automacao.db")
_hist_antigo = Config.BASE_DIR / "historico.db"
if _hist_antigo.exists() and not Path(_DB_PATH).exists():
    try:
        shutil.copy2(_hist_antigo, _DB_PATH)
    except Exception:
        pass


# =====================================================
# POOL DE CONEXÕES SQLITE — reutiliza conexões abertas
# =====================================================

class _SQLitePool:
    """
    Pool de conexões SQLite thread-local.
    Cada thread tem sua própria conexão persistente,
    eliminando o overhead de abrir/fechar por chamada.

    Ganho: −25ms por execução (~50 operações × 0.5ms).
    """

    def __init__(self, db_path: str, max_conns: int = 8):
        self._db_path   = db_path
        self._max_conns = max_conns
        self._local     = threading.local()
        self._all_conns = []
        self._lock      = threading.Lock()

    def _get_conn(self) -> "_sqlite3.Connection":
        """Retorna conexão da thread atual, criando se necessário."""
        if not hasattr(self._local, "conn") or \
                self._local.conn is None:
            conn = _sqlite3.connect(
                self._db_path,
                check_same_thread=False,
                timeout=10
            )
            # Configurações de performance
            conn.execute("PRAGMA journal_mode=DELETE")
            conn.execute("PRAGMA synchronous=NORMAL")
            conn.execute("PRAGMA cache_size=4000")
            conn.execute("PRAGMA temp_store=MEMORY")
            conn.row_factory = _sqlite3.Row
            self._local.conn = conn
            with self._lock:
                self._all_conns.append(conn)
        return self._local.conn

    class _Ctx:
        """Context manager para usar o pool com `with`."""
        def __init__(self, pool):
            self._pool = pool
            self._conn = None

        def __enter__(self):
            self._conn = self._pool._get_conn()
            return self._conn

        def __exit__(self, exc_type, exc_val, exc_tb):
            if exc_type is None:
                try:
                    self._conn.commit()
                except Exception:
                    pass
            else:
                try:
                    self._conn.rollback()
                except Exception:
                    pass
            return False   # não suprime exceções

    def connect(self) -> "_Ctx":
        """Use: `with _db_pool.connect() as con: ...`"""
        return self._Ctx(self)

    def fechar_todos(self):
        with self._lock:
            for conn in self._all_conns:
                try:
                    conn.close()
                except Exception:
                    pass
            self._all_conns.clear()


_db_pool = _SQLitePool(_DB_PATH)

# Garante fechamento correto no encerramento
import atexit as _atexit_db
_atexit_db.register(_db_pool.fechar_todos)

def _db_inicializar():
    with _sqlite3.connect(_DB_PATH) as con:
        con.executescript("""
            CREATE TABLE IF NOT EXISTS execucoes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                empresa TEXT, contrato TEXT, icj TEXT,
                ano TEXT, mes TEXT, data_inicio TEXT, data_fim TEXT,
                tempo_total INTEGER, suc_pedidos INTEGER DEFAULT 0,
                fal_pedidos INTEGER DEFAULT 0, suc_frs INTEGER DEFAULT 0,
                fal_frs INTEGER DEFAULT 0, suc_rm INTEGER DEFAULT 0,
                fal_rm INTEGER DEFAULT 0, suc_esp INTEGER DEFAULT 0,
                fal_esp INTEGER DEFAULT 0, upload_ok INTEGER DEFAULT 0,
                email_ok INTEGER DEFAULT 0,
                resultado TEXT DEFAULT 'PENDENTE', log_path TEXT
            );
            CREATE TABLE IF NOT EXISTS erros (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                execucao_id INTEGER, etapa TEXT,
                mensagem TEXT, timestamp TEXT,
                FOREIGN KEY (execucao_id) REFERENCES execucoes(id)
            );
            CREATE TABLE IF NOT EXISTS etapas (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                execucao_id INTEGER, nome TEXT,
                duracao_s INTEGER, resultado TEXT,
                FOREIGN KEY (execucao_id) REFERENCES execucoes(id)
            );
            CREATE TABLE IF NOT EXISTS kv (
                chave TEXT PRIMARY KEY,
                valor TEXT
            );
            CREATE TABLE IF NOT EXISTS log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                ts TEXT,
                linha TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_exec_id_desc ON execucoes(id DESC);
            CREATE INDEX IF NOT EXISTS idx_exec_contrato ON execucoes(contrato, id DESC);
            CREATE INDEX IF NOT EXISTS idx_etapas_exec_id ON etapas(execucao_id);
            CREATE INDEX IF NOT EXISTS idx_erros_exec_id ON erros(execucao_id);
            CREATE INDEX IF NOT EXISTS idx_log_id ON log(id DESC);
            PRAGMA journal_mode=DELETE;
            PRAGMA synchronous=NORMAL;
        """)


_db_inicializar()


def _kv_get(chave: str, padrao: str = "") -> str:
    try:
        with _db_pool.connect() as con:
            row = con.execute(
                "SELECT valor FROM kv WHERE chave = ?", (chave,)
            ).fetchone()
        if row and row[0] is not None:
            return str(row[0])
    except Exception:
        pass
    return padrao


def _kv_set(chave: str, valor: str) -> None:
    with _db_pool.connect() as con:
        con.execute(
            "INSERT OR REPLACE INTO kv (chave, valor) VALUES (?, ?)",
            (chave, valor),
        )


def _kv_del(chave: str) -> None:
    try:
        with _db_pool.connect() as con:
            con.execute("DELETE FROM kv WHERE chave = ?", (chave,))
    except Exception:
        pass


def _salvar_config_completo(dados: dict) -> None:
    _kv_set("config", json.dumps(dados or {}, ensure_ascii=False, indent=4))


def _importar_arquivos_soltos_para_db() -> None:
    cfg = Path(Config.CONFIG_SAP)
    if cfg.exists() and cfg.suffix == ".json":
        try:
            bruto = json.loads(cfg.read_text(encoding="utf-8"))
            if isinstance(bruto, dict) and bruto and not _kv_get("config"):
                _salvar_config_completo(bruto)
            if _kv_get("config"):
                cfg.unlink()
        except Exception:
            pass
    cp = Config.BASE_DIR / "checkpoint.json"
    if cp.exists():
        try:
            if not _kv_get("checkpoint"):
                _kv_set("checkpoint", cp.read_text(encoding="utf-8"))
            cp.unlink()
        except Exception:
            pass
    antigo_db = Config.BASE_DIR / "historico.db"
    try:
        if antigo_db.exists() and antigo_db.resolve() != Path(_DB_PATH).resolve():
            antigo_db.unlink()
    except Exception:
        pass
    for nome, chave in (
        ("config_usuario.json", "config_usuario"),
        ("config_integracoes.json", "config_integracoes"),
        ("sap_scripts.json", "sap_scripts"),
        ("token_sharepoint_cache.json", "token_sharepoint_cache"),
        ("email_imap_config.json", "email_imap_config"),
    ):
        p = Config.BASE_DIR / nome
        if not p.exists():
            continue
        try:
            if not _kv_get(chave):
                _kv_set(chave, p.read_text(encoding="utf-8"))
            p.unlink()
        except Exception:
            pass
    for arq_log in (
        Config.LOG_ARQUIVO,
        Config.LOG_DIR / "automacao_anterior.log",
    ):
        try:
            if not arq_log.exists() or not arq_log.stat().st_size:
                continue
            texto = arq_log.read_text(encoding="utf-8", errors="replace")[:2_000_000]
            with _db_pool.connect() as con:
                con.execute(
                    "INSERT INTO log (ts, linha) VALUES (?, ?)",
                    (
                        datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                        f"--- importado de {arq_log.name} ---\n{texto}",
                    ),
                )
            arq_log.unlink()
        except Exception:
            pass
    try:
        if Config.LOG_DIR.is_dir() and not any(Config.LOG_DIR.iterdir()):
            Config.LOG_DIR.rmdir()
    except Exception:
        pass


_importar_arquivos_soltos_para_db()
