def db_otimizar():
    """
    Ativa WAL mode e sincronização NORMAL no SQLite.
    Reduz latência de escrita em execuções longas.
    Chamado uma única vez na inicialização.
    """
    try:
        with _sqlite3.connect(_DB_PATH) as con:
            con.execute("PRAGMA journal_mode=DELETE")
            con.execute("PRAGMA synchronous=NORMAL")
    except Exception:
        pass

db_otimizar()
_execucao_id_atual = None

def db_iniciar_execucao(empresa, contrato, icj, ano, mes, log_path):
    global _execucao_id_atual
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    with _db_pool.connect() as con:
        cur = con.execute(
            "INSERT INTO execucoes "
            "(empresa,contrato,icj,ano,mes,data_inicio,log_path) "
            "VALUES (?,?,?,?,?,?,?)",
            (empresa, contrato, icj, ano, mes, ts, log_path)
        )
        _execucao_id_atual = cur.lastrowid
    return _execucao_id_atual


def db_finalizar_execucao(suc_ped,fal_ped,suc_frs,fal_frs,suc_rm,fal_rm,suc_esp,fal_esp,upload_ok,email_ok,tempo_total):
    if _execucao_id_atual is None: return
    # Garante que valores negativos por bug upstream não marquem como OK
    _total_falhas = max(0, fal_ped) + max(0, fal_frs) + max(0, fal_rm) + max(0, fal_esp)
    resultado = "OK" if _total_falhas == 0 else "PARCIAL"

    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    with _sqlite3.connect(_DB_PATH) as con:
        con.execute(
            """UPDATE execucoes SET data_fim=?,tempo_total=?,
               suc_pedidos=?,fal_pedidos=?,suc_frs=?,fal_frs=?,
               suc_rm=?,fal_rm=?,suc_esp=?,fal_esp=?,
               upload_ok=?,email_ok=?,resultado=? WHERE id=?""",
            (ts,tempo_total,suc_ped,fal_ped,suc_frs,fal_frs,
             suc_rm,fal_rm,suc_esp,fal_esp,
             1 if upload_ok else 0, 1 if email_ok else 0,
             resultado, _execucao_id_atual)
        )

def db_registrar_erro(etapa, mensagem):
    if _execucao_id_atual is None: return
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    with _sqlite3.connect(_DB_PATH) as con:
        con.execute("INSERT INTO erros (execucao_id,etapa,mensagem,timestamp) VALUES (?,?,?,?)",
                    (_execucao_id_atual, etapa, mensagem[:500], ts))

def db_registrar_etapa(nome, duracao_s, resultado):
    if _execucao_id_atual is None: return
    with _sqlite3.connect(_DB_PATH) as con:
        con.execute("INSERT INTO etapas (execucao_id,nome,duracao_s,resultado) VALUES (?,?,?,?)",
                    (_execucao_id_atual, nome, duracao_s, resultado))

def db_listar_execucoes(limite=50):
    with _sqlite3.connect(_DB_PATH) as con:
        con.row_factory = _sqlite3.Row
        rows = con.execute(
            """SELECT id,empresa,contrato,mes,ano,data_inicio,tempo_total,resultado,
               suc_pedidos+suc_frs+suc_rm+suc_esp AS total_ok,
               fal_pedidos+fal_frs+fal_rm+fal_esp AS total_fal, log_path
               FROM execucoes ORDER BY id DESC LIMIT ?""", (limite,)
        ).fetchall()
    return [dict(r) for r in rows]
def db_media_etapas(limite_execucoes=20):
    """
    Retorna o tempo médio (segundos) por etapa nas últimas N execuções.
    Resultado: {'Pedidos': 8.2, 'FRS': 45.1, 'RM': 32.0, ...}
    """
    try:
        with _sqlite3.connect(_DB_PATH) as con:
            rows = con.execute(
                """SELECT nome, AVG(duracao_s) as media
                   FROM etapas
                   WHERE execucao_id IN (
                       SELECT id FROM execucoes
                       ORDER BY id DESC
                       LIMIT ?
                   )
                   AND duracao_s IS NOT NULL
                   AND duracao_s > 0
                   GROUP BY nome""",
                (limite_execucoes,)
            ).fetchall()
        return {row[0]: round(row[1], 1) for row in rows}
    except Exception:
        return {}


def _n_contratos_fila() -> int:
    try:
        th = globals().get("_thread_automacao")
        n = len(getattr(th, "fila", None) or [])
        return max(1, int(n or 1))
    except Exception:
        return 1


def _media_para_fila(media_unitaria, n_contratos=None) -> float:
    """Média histórica é por contrato; na fila multiplica pela quantidade."""
    n = max(1, int(n_contratos if n_contratos is not None else _n_contratos_fila()))
    try:
        return float(media_unitaria or 0) * n
    except Exception:
        return 0.0


# Referência de itens usada para escalar o comparativo de tempo (ponto 5).
_ITENS_REF_COMPARATIVO = {
    "Pedidos Serviços": 10.0,
    "Pedidos Materiais": 5.0,
    "FRS": 10.0,
    "RM": 10.0,
    "Espelhos NF Serviços": 10.0,
    "Espelhos NF Materiais": 5.0,
    "Certidões": 3.0,
}


def _media_esperada_comparativo(
    etapa: str, media_db: float, n_itens_por_etapa: dict | None = None,
) -> float:
    """
    Escala a média histórica pelo nº de itens da etapa nesta execução
    (ex.: 14 pedidos vs referência de 10), não pelo nº de contratos.
    """
    media = float(media_db or 0)
    if media <= 0:
        return 0.0
    ref = _ITENS_REF_COMPARATIVO.get(etapa)
    if ref and n_itens_por_etapa:
        n = int(n_itens_por_etapa.get(etapa) or 0)
        if n > 0:
            return media * (n / ref)
    return media


_ETAPAS_COMPARATIVO = (
    "Pedidos Serviços",
    "Pedidos Materiais",
    "FRS",
    "RM",
    "Espelhos NF Serviços",
    "Espelhos NF Materiais",
    "Certidões",
    "Upload SharePoint",
    "Email",
)
_ETAPAS_SO_SERVICOS = (
    "Pedidos Serviços",
    "FRS",
    "RM",
    "Espelhos NF Serviços",
)
_ETAPAS_SO_MATERIAIS = (
    "Pedidos Materiais",
    "Espelhos NF Materiais",
)
_ETAPAS_MATERIAIS_COMPARATIVO = (
    "Pedidos Materiais",
    "Espelhos NF Materiais",
)
_MEDIAS_PADRAO_COMPARATIVO = {
    "Pedidos Serviços": 45.0,
    "Pedidos Materiais": 35.0,
    "FRS": 40.0,
    "RM": 55.0,
    "Espelhos NF Serviços": 20.0,
    "Espelhos NF Materiais": 15.0,
    "Certidões": 120.0,
    "Upload SharePoint": 90.0,
    "Email": 25.0,
}




def _filtrar_etapas_fluxo(
    etapas, tem_servicos=True, tem_materiais=True, so_certidoes=False
):
    """Remove etapas conforme o fluxo (serviços/materiais ou só certidões)."""
    so_certidoes = bool(so_certidoes)
    if so_certidoes:
        keep = {"Iniciando", "Certidões", "Upload SharePoint", "Concluído"}
        return [e for e in etapas if e in keep]
    tem_servicos = bool(tem_servicos)
    tem_materiais = bool(tem_materiais)
    if not tem_servicos and not tem_materiais:
        tem_servicos = True
    saida = []
    for e in etapas:
        if e in _ETAPAS_SO_MATERIAIS and not tem_materiais:
            continue
        if e in _ETAPAS_SO_SERVICOS and not tem_servicos:
            continue
        saida.append(e)
    return saida

def _linhas_comparativo_historico(
    historico_etapas, n_contratos=1, n_itens_por_etapa=None,
):
    """
    Uma linha por etapa da execução, mesmo se o tempo for 0
    (espelho de serviços já gerado no pipeline do RM) ou se o
    banco ainda não tiver média (usa o padrão do painel).
    Etapas de materiais só entram se rodaram nesta execução.
    """
    hist = historico_etapas or {}
    tem_mat = any(e in hist for e in _ETAPAS_MATERIAIS_COMPARATIVO)
    tem_serv = any(e in hist for e in _ETAPAS_SO_SERVICOS)
    so_cert = (
        "Certidões" in hist
        and not tem_mat
        and not tem_serv
        and "Email" not in hist
    )
    if not tem_mat and not tem_serv and not so_cert:
        tem_serv = True
        tem_mat = True
    try:
        medias_db = db_media_etapas(limite_execucoes=20) or {}
    except Exception:
        medias_db = {}
    linhas = []
    for etapa in _filtrar_etapas_fluxo(
        _ETAPAS_COMPARATIVO,
        tem_servicos=tem_serv,
        tem_materiais=tem_mat,
        so_certidoes=so_cert,
    ):
        if etapa in _ETAPAS_MATERIAIS_COMPARATIVO and not tem_mat and not so_cert:
            continue
        dur = int(hist.get(etapa, 0) or 0)
        media = medias_db.get(etapa)
        if media is None:
            media = _MEDIAS_PADRAO_COMPARATIVO.get(etapa)
        if media is None:
            continue
        media = _media_esperada_comparativo(etapa, media, n_itens_por_etapa)
        linhas.append((etapa, dur, float(media)))
    return linhas


def db_tendencia_tempo(contrato: str, limite: int = 20) -> list:
    """
    Retorna lista de (data_inicio, tempo_total) das últimas
    N execuções de um contrato — para exibir tendência.

    Retorna lista de dicts:
        [{"data": "DD/MM", "tempo": 180}, ...]
    """
    try:
        with _sqlite3.connect(_DB_PATH) as con:
            rows = con.execute(
                """SELECT data_inicio, tempo_total
                   FROM execucoes
                   WHERE contrato = ?
                     AND tempo_total > 0
                     AND data_inicio IS NOT NULL
                   ORDER BY id DESC
                   LIMIT ?""",
                (contrato, limite)
            ).fetchall()

        resultado = []
        for data_str, tempo in reversed(rows):
            try:
                dt   = datetime.fromisoformat(data_str)
                data = dt.strftime("%d/%m")
            except Exception:
                data = data_str[:10]
            resultado.append({
                "data":  data,
                "tempo": int(tempo or 0)
            })
        return resultado

    except Exception:
        return []


def db_registrar_historico_etapas(historico: dict):
    """
    Persiste o histórico de tempos por etapa da execução atual no banco.
    Chamado ao final de _executar_automacao, antes de concluir_execucao.emit().
    historico: {'Pedidos': 12, 'FRS': 63, 'RM': 54, ...}
    """
    if _execucao_id_atual is None:
        return
    try:
        with _sqlite3.connect(_DB_PATH) as con:
            for nome, duracao_s in historico.items():
                con.execute(
                    """INSERT OR REPLACE INTO etapas
                       (execucao_id, nome, duracao_s, resultado)
                       VALUES (?, ?, ?, 'OK')""",
                    (_execucao_id_atual, nome, duracao_s)
                )
    except Exception:
        pass
# =====================================================
# CHECKPOINT — salva e recupera estado de execução
# =====================================================

_CHECKPOINT_PATH = "kv:checkpoint"
_ultimo_checkpoint_hash: str = ""


def checkpoint_salvar(estado: dict):
    """
    Persiste o estado atual da execução em JSON.
    X4: Verifica hash antes de escrever — skip se nada mudou.
    """
    global _ultimo_checkpoint_hash
    try:
        import hashlib as _hl
        _estado_sem_ts = {k: v for k, v in estado.items() if k != "ts"}
        _hash_atual = _hl.md5(
            json.dumps(_estado_sem_ts, sort_keys=True).encode()
        ).hexdigest()
        if _hash_atual == _ultimo_checkpoint_hash:
            return
        _ultimo_checkpoint_hash = _hash_atual
        try:
            if "_log_handle" in globals():
                _log_handle.flush()
        except Exception:
            pass
        estado["ts"] = datetime.now().isoformat()
        _kv_set("checkpoint", json.dumps(estado, ensure_ascii=False))
        try:
            registrar_log(
                f'CHECKPOINT salvo: etapa={estado.get("etapa","?")}',
                "INFO",
            )
        except NameError:
            pass
    except Exception as e:
        try:
            registrar_log(f"AVISO [CHECKPOINT]: falha ao salvar: {e}")
        except NameError:
            pass


def checkpoint_carregar() -> dict:
    try:
        bruto = _kv_get("checkpoint")
        if not bruto:
            return {}
        dados = json.loads(bruto)
        return dados if isinstance(dados, dict) else {}
    except Exception:
        return {}


def checkpoint_limpar():
    try:
        global _ultimo_checkpoint_hash
        _ultimo_checkpoint_hash = ""
        _kv_del("checkpoint")
        try:
            registrar_log("CHECKPOINT removido.", "OK")
        except NameError:
            pass
    except Exception as e:
        try:
            registrar_log(f"AVISO [CHECKPOINT]: falha ao remover: {e}")
        except NameError:
            pass


_FILA_SP_OK_KEY = "fila_sp_email_ok"


def _fila_sp_chave(params: dict) -> str:
    return "|".join([
        str(params.get("contrato") or "").strip(),
        str(params.get("ano_ref") or "").strip(),
        str(params.get("mes_pad") or "").strip(),
        str(params.get("periodo") or "").strip(),
    ])


def _fila_sp_ok_carregar() -> set:
    try:
        bruto = _kv_get(_FILA_SP_OK_KEY, "[]")
        dados = json.loads(bruto) if bruto else []
        return set(dados) if isinstance(dados, list) else set()
    except Exception:
        return set()


def _fila_sp_ok_salvar(chaves: set) -> None:
    try:
        _kv_set(_FILA_SP_OK_KEY, json.dumps(sorted(chaves)))
    except Exception:
        pass


def _fila_sp_marcar_ok(params: dict) -> None:
    chaves = _fila_sp_ok_carregar()
    chaves.add(_fila_sp_chave(params))
    _fila_sp_ok_salvar(chaves)


def _fila_sp_ja_ok(params: dict) -> bool:
    return _fila_sp_chave(params) in _fila_sp_ok_carregar()


def _fila_sp_limpar() -> None:
    try:
        _kv_del(_FILA_SP_OK_KEY)
    except Exception:
        pass


def checkpoint_valido(cp: dict, empresa: str, contrato: str) -> bool:
    """
    Verifica se o checkpoint é da mesma empresa/contrato
    e tem menos de 24h.
    """
    if not cp:
        return False
    if cp.get("empresa") != empresa:
        return False
    if cp.get("contrato") != contrato:
        return False
    try:
        ts   = datetime.fromisoformat(cp["ts"])
        diff = (datetime.now() - ts).total_seconds()
        return diff < 86400   # válido por 24h
    except Exception:
        return False

# =====================================================
# SPLASH SCREEN — exibida durante os imports pesados
# =====================================================
class _ParticleSystem(QWidget):
    """
    Sistema de partículas flutuantes para o splash screen.
    Simula névoa de dados em movimento ascendente.
    """

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAttribute(Qt.WA_TranslucentBackground)
        self._particulas = []
        self._inicializar_particulas()
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._atualizar)
        self._timer.start(33)   # ~30fps para suavidade

    def _inicializar_particulas(self):
        import random as _rnd
        W = self.width()  or 480
        H = self.height() or 280
        for _ in range(35):
            self._particulas.append({
                "x":     _rnd.uniform(0, W),
                "y":     _rnd.uniform(0, H),
                "vx":    _rnd.uniform(-0.3, 0.3),
                "vy":    _rnd.uniform(-0.8, -0.2),
                "r":     _rnd.uniform(1.5, 4.0),
                "alpha": _rnd.uniform(0.1, 0.5),
                "pulso": _rnd.uniform(0, 6.28),
            })

    def _atualizar(self):
        import random as _rnd
        W = self.width()  or 480
        H = self.height() or 280
        for p in self._particulas:
            p["x"]    += p["vx"]
            p["y"]    += p["vy"]
            p["pulso"] = (p["pulso"] + 0.05) % 6.28
            p["alpha"] = 0.15 + 0.15 * abs(
                __import__("math").sin(p["pulso"])
            )
            # Reinicia partícula que saiu pela topo
            if p["y"] < -5:
                p["y"] = H + 5
                p["x"] = _rnd.uniform(0, W)
            if p["x"] < -5 or p["x"] > W + 5:
                p["x"] = _rnd.uniform(0, W)
                p["y"] = H + 5
        self.update()

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        for pt in self._particulas:
            cor = QColor(0, 184, 87)
            cor.setAlphaF(pt["alpha"])
            p.setPen(Qt.NoPen)
            p.setBrush(QBrush(cor))
            p.drawEllipse(
                QPointF(pt["x"], pt["y"]),
                pt["r"], pt["r"]
            )
        p.end()


class _LogoPetrobras(QWidget):
    """Assinatura horizontal Petrobras: BR, faixas e logotipo."""

    def __init__(self, tamanho=40, parent=None):
        super().__init__(parent)
        self._tamanho = int(tamanho)
        # Proporção da assinatura horizontal oficial (marca + logotipo).
        self._largura = int(self._tamanho * 4.4)
        self.setFixedSize(self._largura, self._tamanho)
        self.setAttribute(Qt.WA_TranslucentBackground)

    def sizeHint(self):
        from PySide6.QtCore import QSize
        return QSize(self._largura, self._tamanho)

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)

        h = self.height()
        margem = max(1, h * .025)
        fundo = QRectF(margem, margem, self.width() - 2 * margem, h - 2 * margem)
        p.setPen(Qt.NoPen)
        p.setBrush(QBrush(QColor("white")))
        p.drawRect(fundo)

        # Proporções da referência: as duas faixas possuem a mesma largura;
        # apenas a faixa verde inferior é mais alta.
        icon_w = h * .84
        icon_x = fundo.left() + h * .08
        p.setBrush(QBrush(QColor(AMARELO_PETR)))
        p.drawRect(QRectF(icon_x, fundo.top() + h * .16, icon_w, h * .19))
        # Espaço branco deliberado entre a faixa amarela e o bloco verde.
        bloco = QRectF(icon_x, fundo.top() + h * .45, icon_w, h * .53)
        # Verde próprio da marca, separado visualmente do fundo do header.
        p.setBrush(QBrush(QColor("#008C45")))
        p.drawRect(bloco)

        p.setPen(QPen(QColor("white")))
        # Tipografia do monograma calibrada pela altura do próprio bloco;
        # evita que o R encoste na borda em logos compactos.
        fonte = QFont("Arial", max(7, int(bloco.height() * .62)), QFont.Bold)
        fonte.setItalic(True)
        fonte.setStretch(94)
        p.setFont(fonte)
        p.drawText(bloco, Qt.AlignCenter, "BR")

        p.setPen(QPen(QColor(VERDE_PETRO)))
        # A marca precisa caber também na sidebar; reduz proporcionalmente
        # em vez de deixar o texto ser recortado pelo QPainter.
        fonte_nome = QFont("Arial Black", max(7, int(h * .27)), QFont.Black)
        fonte_nome.setItalic(True)
        fonte_nome.setStretch(100)
        fonte_nome.setLetterSpacing(QFont.PercentageSpacing, 100)
        p.setFont(fonte_nome)
        nome = QRectF(icon_x + icon_w + h * .18, fundo.top(),
                      fundo.right() - (icon_x + icon_w + h * .24), h)
        p.drawText(nome, Qt.AlignVCenter | Qt.AlignLeft, "PETROBRAS")
        p.end()


