_ts_log  = datetime.now().strftime("%Y-%m-%d_%H%M%S")
LOG_FILE = _DB_PATH
_log_inserts = 0


class _LogDbSink:
    """Grava o log na tabela `log` de automacao.db (um único arquivo)."""

    def write(self, texto):
        global _log_inserts
        if not texto:
            return
        try:
            with _db_pool.connect() as con:
                con.execute(
                    "INSERT INTO log (ts, linha) VALUES (?, ?)",
                    (
                        datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                        texto,
                    ),
                )
                _log_inserts += 1
                if _log_inserts >= 400:
                    _log_inserts = 0
                    n = con.execute("SELECT COUNT(*) FROM log").fetchone()[0]
                    if n and int(n) > 60000:
                        con.execute(
                            "DELETE FROM log WHERE id IN "
                            "(SELECT id FROM log ORDER BY id LIMIT ?)",
                            (int(n) - 40000,),
                        )
        except Exception:
            pass

    def flush(self):
        pass

    def close(self):
        pass


_log_handle = _LogDbSink()
import atexit
atexit.register(_log_handle.close)


def _log_exportar_txt_temp(somente_execucao_atual: bool = False) -> str:
    fd, path = tempfile.mkstemp(prefix="automacao_", suffix=".log")
    os.close(fd)
    try:
        with _sqlite3.connect(_DB_PATH) as conn:
            rows = conn.execute("SELECT linha FROM log ORDER BY id").fetchall()
        linhas = [str(r[0] or "") for r in rows if r and r[0]]
        if somente_execucao_atual:
            inicio = 0
            for i, ln in enumerate(linhas):
                if re.search(r"EXECU[CÇ][AÃ]O:", ln, re.I):
                    inicio = i
                    if i > 0 and set(linhas[i - 1].strip()) <= {"=", " "}:
                        inicio = i - 1
            linhas = linhas[inicio:]
        with open(path, "w", encoding="utf-8", errors="replace") as f:
            for linha in linhas:
                f.write(linha if linha.endswith("\n") else linha + "\n")
    except Exception:
        pass
    return path


def _abrir_log_para_usuario():
    try:
        os.startfile(_log_exportar_txt_temp())
    except Exception:
        try:
            os.startfile(_DB_PATH)
        except Exception:
            pass


def _abrir_banco_para_usuario():
    """
    Abre o Explorer na pasta do automacao.db, com o arquivo
    selecionado. No .exe isso é %LOCALAPPDATA%\\AutomacaoSAP;
    no .py é a pasta do projeto.
    """
    arquivo = Path(_DB_PATH).expanduser()
    try:
        arquivo.parent.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    try:
        import subprocess
        subprocess.Popen(
            f'explorer /select,"{arquivo}"',
            shell=True,
        )
        return
    except Exception:
        pass
    try:
        os.startfile(str(arquivo.parent))
    except Exception:
        pass


class _TeeStdout:
    """
    Espelha tudo que for escrito em sys.stdout (ou seja, TODO
    print() espalhado pelo arquivo inteiro — não só as chamadas de
    registrar_log()) também no arquivo de log, com hora em cada
    linha. Antes disso, o .log salvo em disco (o mesmo anexado no
    e-mail de erro automático) só recebia o que passava por
    registrar_log() — o restante (a maior parte dos prints dentro de
    abrir_pedido, abrir_rm, processar_frs, extrair_dados_rm etc.)
    aparecia só no console do VSCode e se perdia depois que a janela
    fechava. Agora o .log fica com o mesmo nível de detalhe do
    console.
    """
    def __init__(self, stream_original, arquivo_log):
        self._original      = stream_original
        self._arquivo       = arquivo_log
        self._buffer_linha  = ""

    def write(self, texto):
        try:
            self._original.write(texto)
        except Exception:
            pass
        self._buffer_linha += texto
        while "\n" in self._buffer_linha:
            linha, self._buffer_linha = self._buffer_linha.split("\n", 1)
            if linha.strip():
                ts = datetime.now().strftime("%d/%m/%Y %H:%M:%S")
                try:
                    _log_handle.write(f"[{ts}] {linha}\n")
                except Exception:
                    pass

    def flush(self):
        try:
            self._original.flush()
        except Exception:
            pass
        try:
            _log_handle.flush()
        except Exception:
            pass

    def isatty(self):
        return False


try:
    sys.stdout = _TeeStdout(sys.stdout, LOG_FILE)
except Exception:
    pass

