# TOAST NOTIFICATIONS — feedback não-intrusivo
# =====================================================
# U2: Gerenciador de posicionamento de múltiplos toasts
class _ToastManager:
    """Empilha toasts sem sobreposição."""
    _toasts: list = []

    @classmethod
    def registrar(cls, tw) -> int:
        cls._toasts.append(tw)
        cls._reposicionar()
        return len(cls._toasts) - 1

    @classmethod
    def remover(cls, tw):
        try:
            cls._toasts.remove(tw)
            cls._reposicionar()
        except ValueError:
            pass

    @classmethod
    def _reposicionar(cls):
        sc     = _qapp.primaryScreen().geometry()
        y_base = sc.bottom() - 24
        for tw in reversed(cls._toasts):
            try:
                y_base -= tw.height()
                tw.move(sc.right() - tw.width() - 20, y_base)
                y_base -= 8
            except Exception:
                pass

class ToastNotificacao(QDialog):
    """
    Toast V2 com:
    - Subtítulo opcional
    - Ícone animado para tipo 'processando'
    - Barra de progresso de duração
    - Fade-in/out suave
    - Borda colorida esquerda + fundo semântico
    """

    def __init__(
        self,
        mensagem:  str,
        tipo:      str = "sucesso",
        duracao:   int = 4000,
        subtitulo: str = "",
    ):
        super().__init__()
        self.setWindowFlags(
            Qt.FramelessWindowHint |
            Qt.WindowStaysOnTopHint |
            Qt.Tool
        )
        self.setAttribute(Qt.WA_TranslucentBackground)
        _h = 72 if subtitulo else 56
        self.setFixedSize(390, _h)

        _cfg = {
            "sucesso":     (COR_SUCESSO,  "✅", "#052e16"),
            "erro":        (COR_ERRO,     "❌", "#1a0505"),
            "aviso":       (COR_ALERTA,   "⚠️", "#1a1200"),
            "info":        (COR_INFO,     "ℹ️", "#051b2c"),
            "processando": (VERDE_NEON,   "⟳",  "#052e16"),
        }
        cor, icone, fundo = _cfg.get(tipo, _cfg["info"])

        # Container com fundo semântico e borda esquerda colorida
        container = QFrame(self)
        container.setGeometry(0, 0, 390, _h)
        container.setStyleSheet(f"""
            QFrame {{
                background-color: {fundo};
                border: 1px solid {cor}44;
                border-left: 4px solid {cor};
                border-radius: 10px;
            }}
        """)

        h = QHBoxLayout(container)
        h.setContentsMargins(14, 8, 10, 8)
        h.setSpacing(12)

        # Ícone
        lbl_ic = QLabel(icone)
        lbl_ic.setFont(QFont("Segoe UI Emoji", 18))
        lbl_ic.setFixedWidth(32)
        lbl_ic.setAlignment(Qt.AlignCenter)
        lbl_ic.setStyleSheet("background: transparent;")
        h.addWidget(lbl_ic)

        # Textos
        v_txt = QVBoxLayout()
        v_txt.setSpacing(3)

        lbl_msg = QLabel(mensagem[:65])
        lbl_msg.setFont(QFont("Segoe UI", 10, QFont.Bold))
        lbl_msg.setStyleSheet(
            f"color: {BRANCO}; background: transparent;"
        )
        v_txt.addWidget(lbl_msg)

        if subtitulo:
            lbl_sub = QLabel(subtitulo[:80])
            lbl_sub.setFont(QFont("Consolas", 8))
            lbl_sub.setStyleSheet(
                f"color: {TEXTO_OPACO}; background: transparent;"
            )
            v_txt.addWidget(lbl_sub)

        h.addLayout(v_txt, stretch=1)

        # Botão fechar discreto
        btn_x = QPushButton("×")
        btn_x.setFixedSize(20, 20)
        btn_x.setStyleSheet(f"""
            QPushButton {{
                background: transparent;
                color: {TEXTO_OPACO};
                border: none;
                font-size: 16px;
                font-weight: bold;
                border-radius: 10px;
            }}
            QPushButton:hover {{
                background: {COR_ERRO}33;
                color: {BRANCO};
            }}
        """)
        btn_x.clicked.connect(self._fechar_com_manager)
        h.addWidget(btn_x, alignment=Qt.AlignTop)
        
        # Barra de duração na base
        self._barra_dur = QProgressBar(container)
        self._barra_dur.setGeometry(4, _h - 4, 382, 3)
        self._barra_dur.setRange(0, duracao)
        self._barra_dur.setValue(duracao)
        self._barra_dur.setTextVisible(False)
        self._barra_dur.setStyleSheet(f"""
            QProgressBar {{
                border: none;
                background: transparent;
                border-radius: 1px;
            }}
            QProgressBar::chunk {{
                background: {cor};
                border-radius: 1px;
            }}
        """)

        # Posiciona via ToastManager
        screen = _qapp.primaryScreen().geometry()
        self.move(
            screen.right()  - self.width()  - 24,
            screen.bottom() - self.height() - 64
        )

        # Fade-in
        self._opacidade = QGraphicsOpacityEffect(self)
        self.setGraphicsEffect(self._opacidade)
        self._opacidade.setOpacity(0.0)
        self._anim_in = QPropertyAnimation(
            self._opacidade, b"opacity", self
        )
        self._anim_in.setDuration(200)
        self._anim_in.setStartValue(0.0)
        self._anim_in.setEndValue(1.0)
        self._anim_in.setEasingCurve(QEasingCurve.OutCubic)

        self.show()
        self.lower()
        self._anim_in.start()
        QTimer.singleShot(0, _qapp.processEvents)
        _ToastManager.registrar(self)

        # Timer da barra
        self._tdur = QTimer(self)
        self._tdur.timeout.connect(
            lambda: self._barra_dur.setValue(
                max(0, self._barra_dur.value() - 60)
            )
        )
        self._tdur.start(60)
        QTimer.singleShot(duracao, self._fechar_com_manager)

    def _fechar_com_manager(self):
        # Fade-out antes de remover
        anim_out = QPropertyAnimation(
            self._opacidade, b"opacity", self
        )
        anim_out.setDuration(180)
        anim_out.setStartValue(1.0)
        anim_out.setEndValue(0.0)
        anim_out.setEasingCurve(QEasingCurve.InCubic)

        def _fim():
            _ToastManager.remover(self)
            self.close()

        anim_out.finished.connect(_fim)
        anim_out.start()


from PySide6.QtCore import QObject as _QObjectToast


class _ToastDispatcher(_QObjectToast):
    """
    Garante que o ToastNotificacao seja sempre criado na thread
    principal (thread da GUI), não importa de qual thread toast() foi
    chamado.

    Widgets do Qt (como o QDialog usado no toast) só podem ser criados
    e manipulados na thread principal. A automação roda numa thread
    separada (AutomacaoThread) e chama toast() várias vezes de lá (ex.:
    "Pedidos concluídos: 2/2") — como essa thread não roda um loop de
    eventos do Qt, o QTimer.singleShot usado antes não disparava
    corretamente e o toast acabava sendo criado com a thread errada:
    aparecia na tela mas nunca fechava sozinho, parecendo travado numa
    lista lateral. Emitir um sinal aqui e deixar esta classe (que mora
    na thread principal) criar o widget resolve isso — mesmo padrão
    já usado em `_GuiBridge` para os diálogos de erro.
    """
    pedir = Signal(str, str, int, str)

    def __init__(self):
        super().__init__()
        self.pedir.connect(self._criar)

    def _criar(self, mensagem, tipo, duracao, subtitulo):
        ToastNotificacao(mensagem, tipo, duracao, subtitulo)


_toast_dispatcher = _ToastDispatcher()


def toast(
    mensagem:  str,
    tipo:      str = "sucesso",
    duracao:   int = 4000,
    subtitulo: str = "",
):
    """
    Toasts desativados a pedido — as telinhas no canto que apareciam
    e somiam sozinhas (sucesso de upload, avisos, etc.) não são mais
    exibidas. As mensagens continuam indo pro log normalmente (cada
    chamada de toast() geralmente tem um registrar_log() ao lado) —
    só a notificação visual foi removida.
    """
    return


def _nome_processo_pid(pid) -> str:
    try:
        import psutil as _ps_pid
        return (_ps_pid.Process(int(pid)).name() or "").lower()
    except Exception:
        return ""


def _eh_processo_sap(pid) -> bool:
    n = _nome_processo_pid(pid)
    return n.startswith("sap") or n in ("saplogon.exe", "saplgpad.exe", "wow.exe")


def _eh_janela_sap_logon(titulo: str, pid=None) -> bool:
    """SAP Logon 800 — não é a tela de script; não maximizar/alternar."""
    t = (titulo or "").strip().lower()
    if "sap logon" in t or t.startswith("saplogon"):
        return True
    n = _nome_processo_pid(pid) if pid is not None else ""
    return n in ("saplogon.exe", "saplgpad.exe")


def _sap_maximizar_wnd0(session):
    """Maximiza wnd[0] via COM (compatível com typelib com ou sem parênteses)."""
    if session is None:
        return
    try:
        wnd = session.findById("wnd[0]")
    except Exception:
        return
    for _ in range(2):
        try:
            wnd.maximize()
            return
        except Exception:
            pass
        try:
            mb = wnd.maximize
            if callable(mb):
                mb()
                return
        except Exception:
            pass
        try:
            wnd.iconify = False
            return
        except Exception:
            pass
        time.sleep(0.1)


# Buscar/Extrair: o app fica na frente. SAP só vem à frente no Pedido+.
_SAP_SEGUNDO_PLANO = 0
_SAP_APP_HWNDS = []


def _win32_maximizar_e_focar(hwnd):
    """Restaura/maximiza HWND e tenta trazer à frente (Windows 10/11)."""
    try:
        import win32gui
        import win32process
        import win32con
        import win32api
    except Exception:
        return
    try:
        if win32gui.IsIconic(hwnd):
            win32gui.ShowWindow(hwnd, win32con.SW_RESTORE)
        win32gui.ShowWindow(hwnd, win32con.SW_MAXIMIZE)
        fg = win32gui.GetForegroundWindow()
        if fg == hwnd:
            return
        fg_tid = win32process.GetWindowThreadProcessId(fg)[0]
        tgt_tid = win32process.GetWindowThreadProcessId(hwnd)[0]
        anexou = False
        if fg_tid and tgt_tid and fg_tid != tgt_tid:
            try:
                win32api.AttachThreadInput(fg_tid, tgt_tid, True)
                anexou = True
            except Exception:
                pass
        try:
            win32gui.SetForegroundWindow(hwnd)
            win32gui.BringWindowToTop(hwnd)
        except Exception:
            pass
        finally:
            if anexou:
                try:
                    win32api.AttachThreadInput(fg_tid, tgt_tid, False)
                except Exception:
                    pass
    except Exception:
        pass


def _win32_manter_janela_visivel(hwnd, forcar_frente=False, topmost=True):
    """Coloca a janela do app acima do SAP sem maximizar."""
    if not hwnd:
        return
    try:
        import win32gui
        import win32con
        import win32process
        import win32api
    except Exception:
        return
    try:
        if not win32gui.IsWindow(hwnd):
            return
        if win32gui.IsIconic(hwnd):
            # Usuário minimizou — não trazer de volta durante consulta SAP.
            return
        flags = win32con.SWP_NOMOVE | win32con.SWP_NOSIZE
        if not forcar_frente:
            flags |= win32con.SWP_NOACTIVATE
        inserir = (
            win32con.HWND_TOPMOST if topmost else win32con.HWND_NOTOPMOST
        )
        win32gui.SetWindowPos(hwnd, inserir, 0, 0, 0, 0, flags)
        if not forcar_frente:
            return
        fg = win32gui.GetForegroundWindow()
        if fg == hwnd:
            return
        fg_tid = win32process.GetWindowThreadProcessId(fg)[0]
        tgt_tid = win32process.GetWindowThreadProcessId(hwnd)[0]
        anexou = False
        if fg_tid and tgt_tid and fg_tid != tgt_tid:
            try:
                win32api.AttachThreadInput(fg_tid, tgt_tid, True)
                anexou = True
            except Exception:
                pass
        try:
            win32gui.SetForegroundWindow(hwnd)
            win32gui.BringWindowToTop(hwnd)
        except Exception:
            pass
        finally:
            if anexou:
                try:
                    win32api.AttachThreadInput(fg_tid, tgt_tid, False)
                except Exception:
                    pass
    except Exception:
        pass


def _sap_hwnds_app():
    vivos = []
    for hwnd in list(_SAP_APP_HWNDS):
        try:
            import win32gui
            if win32gui.IsWindow(hwnd):
                vivos.append(hwnd)
        except Exception:
            vivos.append(hwnd)
    return vivos


def _sap_devolver_foco_app(forcar_frente=False):
    """
    Mantém o Sigma-C visível acima do SAP (só na thread principal).
    forcar_frente=False: TOPMOST sem roubar teclado — UI continua livre.
    Não restaura janela se o usuário minimizou.
    """
    if _SAP_SEGUNDO_PLANO <= 0:
        return
    try:
        app = QApplication.instance()
        if app is not None and QThread.currentThread() is not app.thread():
            return
    except Exception:
        pass
    for hwnd in _sap_hwnds_app():
        _win32_manter_janela_visivel(
            hwnd, forcar_frente=forcar_frente, topmost=True
        )


def _sap_iniciar_segundo_plano(*widgets):
    """Buscar/Extrair: não traz o SAP para a frente; app fica visível."""
    global _SAP_SEGUNDO_PLANO
    _SAP_SEGUNDO_PLANO += 1
    for w in widgets:
        if w is None:
            continue
        try:
            hwnd = int(w.winId())
        except Exception:
            continue
        if hwnd and hwnd not in _SAP_APP_HWNDS:
            _SAP_APP_HWNDS.append(hwnd)
    # Uma vez: traz o app à frente. Depois só pulso suave (sem travar/minimizar).
    _sap_devolver_foco_app(forcar_frente=True)


def _sap_pulso_visibilidade_app():
    """Pulso periódico na thread principal — app visível, UI responsiva."""
    _sap_devolver_foco_app(forcar_frente=False)


def _sap_encerrar_segundo_plano():
    global _SAP_SEGUNDO_PLANO
    _SAP_SEGUNDO_PLANO = max(0, _SAP_SEGUNDO_PLANO - 1)
    if _SAP_SEGUNDO_PLANO > 0:
        return
    for hwnd in _sap_hwnds_app():
        _win32_manter_janela_visivel(hwnd, forcar_frente=True, topmost=False)
    _SAP_APP_HWNDS.clear()


def _sap_focar_para_etapa(session=None):
    """Maximiza/foca SAP nas etapas de impressão — ignora modo segundo plano."""
    global _SAP_SEGUNDO_PLANO
    _guard = _SAP_SEGUNDO_PLANO
    _SAP_SEGUNDO_PLANO = 0
    try:
        _maximizar_janelas_sap(session)
        if session is not None:
            try:
                hwnd = int(session.findById("wnd[0]").Handle)
                if hwnd:
                    _win32_maximizar_e_focar(hwnd)
            except Exception:
                pass
    finally:
        _SAP_SEGUNDO_PLANO = _guard


def _sap_focar_janela(session):
    """Maximiza e traz à frente a janela da sessão (sem varrer todas as janelas)."""
    if _SAP_SEGUNDO_PLANO > 0:
        _sap_devolver_foco_app()
        return
    _sap_maximizar_wnd0(session)
    if session is None:
        return
    try:
        hwnd = int(session.findById("wnd[0]").Handle)
        if hwnd:
            _win32_maximizar_e_focar(hwnd)
    except Exception:
        pass


def _maximizar_janelas_sap(session=None):
    """
    Maximiza só a janela da sessão SAP GUI (onde roda o script).
    Não mexe no SAP Logon — isso fazia minimizar/maximizar em loop.
    """
    if _SAP_SEGUNDO_PLANO > 0:
        return
    for tentativa in range(3):
        if session is not None:
            _sap_maximizar_wnd0(session)
            try:
                hwnd = int(session.findById("wnd[0]").Handle)
                if hwnd:
                    _win32_maximizar_e_focar(hwnd)
            except Exception:
                pass
        try:
            import win32gui
            import win32process
            import win32con

            def _callback(hwnd, _):
                try:
                    if not win32gui.IsWindowVisible(hwnd):
                        return
                    titulo = win32gui.GetWindowText(hwnd)
                    if not titulo.strip():
                        return
                    _, pid = win32process.GetWindowThreadProcessId(hwnd)
                    if not _eh_processo_sap(pid):
                        return
                    if _eh_janela_sap_logon(titulo, pid):
                        return
                    _win32_maximizar_e_focar(hwnd)
                except Exception:
                    pass

            win32gui.EnumWindows(_callback, None)
        except Exception:
            pass
        if tentativa < 2:
            time.sleep(0.12)


def _minimizar_janelas_sap():
    """Minimiza o SAP só quando a automação já não precisa dele (SP/e-mail)."""
    try:
        import win32gui
        import win32process
        import win32con

        def _callback(hwnd, _):
            try:
                if not win32gui.IsWindowVisible(hwnd):
                    return
                _, pid = win32process.GetWindowThreadProcessId(hwnd)
                if _eh_processo_sap(pid):
                    win32gui.ShowWindow(hwnd, win32con.SW_MINIMIZE)
            except Exception:
                pass

        win32gui.EnumWindows(_callback, None)
    except Exception:
        pass


def _minimizar_outras_janelas():
    """
    Minimiza janelas de outros programas (Teams, Outlook, navegador
    etc.) antes de começar a usar mouse/teclado no SAP — evita que um
    popup (ex.: notificação do Teams) roube o foco e seja detectado
    como "interferência" no meio da automação. Não minimiza a janela
    do SAP nem as janelas do próprio programa.
    """
    try:
        import win32gui
        import win32process
        import win32con

        _pid_proprio = os.getpid()
        _janelas_minimizadas = []

        def _callback(hwnd, _):
            try:
                if not win32gui.IsWindowVisible(hwnd):
                    return
                titulo = win32gui.GetWindowText(hwnd)
                if not titulo.strip():
                    return
                _, pid = win32process.GetWindowThreadProcessId(hwnd)
                if pid == _pid_proprio:
                    return
                _titulo_lower = titulo.lower()
                # Processo SAP (título costuma ser a transação, ex.
                # 'Necessidade de Liberação') e Edge/Outlook ficam visíveis.
                if _eh_processo_sap(pid):
                    return
                if any(
                    palavra in _titulo_lower
                    for palavra in ("sap", "edge", "outlook")
                ):
                    return
                win32gui.ShowWindow(hwnd, win32con.SW_MINIMIZE)
                _janelas_minimizadas.append(titulo)
            except Exception:
                pass

        win32gui.EnumWindows(_callback, None)
        if _janelas_minimizadas:
            registrar_log(
                "Janelas minimizadas antes da automação: "
                + ", ".join(_janelas_minimizadas[:8])
                + (
                    f" e mais {len(_janelas_minimizadas) - 8}"
                    if len(_janelas_minimizadas) > 8 else ""
                )
            )
    except Exception as _e_min:
        registrar_log(
            f"AVISO: não foi possível minimizar outras janelas: {_e_min}",
            "AVISO"
        )

