import ctypes as _ctypes_hook
import ctypes.wintypes as _wt_hook

_WH_KEYBOARD_LL   = 13
_WH_MOUSE_LL      = 14
_WM_KEYDOWN       = 0x0100
_WM_SYSKEYDOWN    = 0x0104
_WM_MOUSEMOVE     = 0x0200
_WM_LBUTTONDOWN   = 0x0201
_WM_RBUTTONDOWN   = 0x0204
_WM_MBUTTONDOWN   = 0x0207
_WM_MOUSEWHEEL    = 0x020A
_WM_QUIT          = 0x0012
_LLKHF_INJECTED   = 0x00000010
_LLMHF_INJECTED   = 0x00000001


class _KBDLLHOOKSTRUCT(_ctypes_hook.Structure):
    _fields_ = [
        ("vkCode",      _wt_hook.DWORD),
        ("scanCode",    _wt_hook.DWORD),
        ("flags",       _wt_hook.DWORD),
        ("time",        _wt_hook.DWORD),
        ("dwExtraInfo", _ctypes_hook.c_void_p),
    ]


class _MSLLHOOKSTRUCT(_ctypes_hook.Structure):
    _fields_ = [
        ("pt",          _wt_hook.POINT),
        ("mouseData",   _wt_hook.DWORD),
        ("flags",       _wt_hook.DWORD),
        ("time",        _wt_hook.DWORD),
        ("dwExtraInfo", _ctypes_hook.c_void_p),
    ]


_HOOKPROC = _ctypes_hook.WINFUNCTYPE(
    _ctypes_hook.c_ssize_t,
    _ctypes_hook.c_int,
    _ctypes_hook.c_size_t,
    _ctypes_hook.c_ssize_t,
)

_user32 = _ctypes_hook.windll.user32
_user32.SetWindowsHookExW.restype  = _ctypes_hook.c_void_p
_user32.SetWindowsHookExW.argtypes = [
    _ctypes_hook.c_int, _HOOKPROC, _ctypes_hook.c_void_p, _wt_hook.DWORD
]
_user32.CallNextHookEx.restype  = _ctypes_hook.c_ssize_t
_user32.CallNextHookEx.argtypes = [
    _ctypes_hook.c_void_p, _ctypes_hook.c_int,
    _ctypes_hook.c_void_p, _ctypes_hook.c_void_p,
]
_user32.UnhookWindowsHookEx.restype  = _ctypes_hook.c_int
_user32.UnhookWindowsHookEx.argtypes = [_ctypes_hook.c_void_p]
_user32.GetMessageW.restype = _ctypes_hook.c_int
_user32.PostThreadMessageW.argtypes = [
    _wt_hook.DWORD, _ctypes_hook.c_uint,
    _ctypes_hook.c_void_p, _ctypes_hook.c_void_p,
]


class MonitorInterferencia:
    """
    Detecta interferência HUMANA real no mouse/teclado durante a
    automação, sem confundir com os próprios cliques/teclas gerados
    pelo programa (SAP GUI Scripting, pywinauto send_keys/click).

    Usa hooks de baixo nível do Windows (WH_KEYBOARD_LL/WH_MOUSE_LL)
    via ctypes. O Windows marca todo evento gerado por
    SendInput/keybd_event/mouse_event (exatamente o que o pywinauto
    usa por baixo dos panos) com uma flag "injetado" — garantida pelo
    próprio sistema operacional, não é um "achismo" de tempo. Eventos
    com essa flag são sempre ignorados; só eventos SEM ela (hardware
    de verdade) contam como interferência. Comandos do SAP GUI
    Scripting nem passam pelo teclado/mouse do Windows — são chamadas
    COM diretas no processo do SAP — então nem aparecem aqui.
    """

    def __init__(self):
        self.monitorando             = False
        self.interferencia_detectada = threading.Event()
        self.ultimo_alerta           = 0
        self.cooldown_alerta         = 0.4
        self.tipo_interferencia      = ""
        self.lock                    = threading.Lock()
        self._contagem_interferencia = {}
        self._lock_verificar         = threading.Lock()
        self._thread_hook            = None
        self._thread_alerta          = None
        self._thread_id_hook         = None
        # Mantém referência viva dos callbacks C — sem isso o coletor
        # de lixo do Python pode derrubar e o hook quebra em silêncio.
        self._cb_teclado = None
        self._cb_mouse   = None
        # Carência após rearmar: toda vez que o monitor é ligado de
        # novo (iniciar()/retomar()) — o que quase sempre acontece
        # logo depois de você clicar num diálogo real (pré-voo,
        # validação dos espelhos, retry/cancelar) — o resto do seu
        # próprio gesto de clique (soltar o botão, mão ainda saindo
        # de cima dele) ainda gera eventos reais de mouse por alguns
        # décimos de segundo. Sem essa margem, esse resto do SEU
        # clique era pego como se fosse interferência durante a
        # automação.
        self._ignorar_ate = 0.0

    def _sinalizar(self, tipo):
        agora = time.time()
        if agora < self._ignorar_ate:
            # Ainda dentro da carência logo após rearmar — provável
            # resto do seu próprio clique num diálogo, não
            # interferência de verdade durante a automação.
            return
        with self.lock:
            if agora - self.ultimo_alerta < self.cooldown_alerta:
                return
            self.ultimo_alerta      = agora
            self.tipo_interferencia = tipo
        self.interferencia_detectada.set()
        registrar_log(f"⚠ INTERFERÊNCIA DETECTADA: {tipo}")

    def _proc_teclado(self, nCode, wParam, lParam):
        try:
            if nCode == 0 and self.monitorando:
                info = _ctypes_hook.cast(
                    lParam, _ctypes_hook.POINTER(_KBDLLHOOKSTRUCT)
                ).contents
                injetado = bool(info.flags & _LLKHF_INJECTED)
                if not injetado and wParam in (_WM_KEYDOWN, _WM_SYSKEYDOWN):
                    self._sinalizar(f"tecla (código {info.vkCode})")
        except Exception:
            pass
        try:
            n = 0 if nCode is None else int(nCode)
        except Exception:
            n = 0
        try:
            wp = 0 if wParam is None else int(wParam)
        except Exception:
            wp = 0
        try:
            lp = 0 if lParam is None else int(lParam)
        except Exception:
            lp = 0
        try:
            return _user32.CallNextHookEx(None, n, wp, lp)
        except Exception:
            return 0

    def _proc_mouse(self, nCode, wParam, lParam):
        try:
            if nCode == 0 and self.monitorando:
                info = _ctypes_hook.cast(
                    lParam, _ctypes_hook.POINTER(_MSLLHOOKSTRUCT)
                ).contents
                injetado = bool(info.flags & _LLMHF_INJECTED)
                # LLMHF_LOWER_IL_INJECTED (0x02) — também gerado por algumas APIs
                injetado = injetado or bool(info.flags & 0x00000002)
                if not injetado:
                    # NÃO alerta em WM_MOUSEMOVE: SetCursorPos / foco de
                    # janela da própria automação não vêm com flag injetado
                    # e geravam falso positivo no SharePoint (quebrava a
                    # abertura da pasta enquanto o alerta vermelho aparecia).
                    if wParam in (
                        _WM_LBUTTONDOWN, _WM_RBUTTONDOWN, _WM_MBUTTONDOWN
                    ):
                        self._sinalizar("clique do mouse")
                    elif wParam == _WM_MOUSEWHEEL:
                        self._sinalizar("scroll do mouse")
        except Exception:
            pass
        try:
            n = 0 if nCode is None else int(nCode)
        except Exception:
            n = 0
        try:
            wp = 0 if wParam is None else int(wParam)
        except Exception:
            wp = 0
        try:
            lp = 0 if lParam is None else int(lParam)
        except Exception:
            lp = 0
        try:
            return _user32.CallNextHookEx(None, n, wp, lp)
        except Exception:
            return 0

    def _loop_hooks(self):
        """
        Roda numa thread dedicada: instala os 2 hooks de baixo nível
        e mantém um loop de mensagens do Windows rodando (obrigatório
        pra hooks WH_*_LL funcionarem) até parar() mandar WM_QUIT.
        """
        self._cb_teclado = _HOOKPROC(self._proc_teclado)
        self._cb_mouse   = _HOOKPROC(self._proc_mouse)

        hook_teclado = _user32.SetWindowsHookExW(
            _WH_KEYBOARD_LL, self._cb_teclado, None, 0
        )
        hook_mouse = _user32.SetWindowsHookExW(
            _WH_MOUSE_LL, self._cb_mouse, None, 0
        )

        if not hook_teclado or not hook_mouse:
            registrar_log(
                "AVISO [MONITOR]: não foi possível instalar os hooks "
                "de baixo nível — monitor de interferência desativado "
                "nesta execução.",
                "AVISO"
            )

        self._thread_id_hook = _ctypes_hook.windll.kernel32.GetCurrentThreadId()

        msg = _wt_hook.MSG()
        while True:
            resultado = _user32.GetMessageW(_ctypes_hook.byref(msg), None, 0, 0)
            if resultado == 0 or resultado == -1:
                break
            _user32.TranslateMessage(_ctypes_hook.byref(msg))
            _user32.DispatchMessageW(_ctypes_hook.byref(msg))

        if hook_teclado:
            _user32.UnhookWindowsHookEx(hook_teclado)
        if hook_mouse:
            _user32.UnhookWindowsHookEx(hook_mouse)

    def _loop_alerta_rapido(self):
        """Mostra o alerta na hora, sem esperar a próxima ação do SAP."""
        while True:
            th = self._thread_hook
            if th is None:
                break
            try:
                if not th.is_alive() and not self.monitorando:
                    break
            except Exception:
                break
            if self.interferencia_detectada.wait(timeout=0.05):
                if self.monitorando:
                    self.verificar_e_aguardar("mouse/teclado")
                else:
                    time.sleep(0.05)

    def iniciar(self):
        if self.monitorando and self._thread_hook is not None:
            try:
                if self._thread_hook.is_alive():
                    return
            except Exception:
                pass
        self.monitorando = True
        self.interferencia_detectada.clear()
        self._ignorar_ate = time.time() + 0.6
        self._thread_hook = threading.Thread(
            target=self._loop_hooks, daemon=True,
            name="MonitorInterferenciaHook"
        )
        self._thread_hook.start()
        self._thread_alerta = threading.Thread(
            target=self._loop_alerta_rapido, daemon=True,
            name="MonitorInterferenciaAlerta"
        )
        self._thread_alerta.start()
        print("Monitor de interferência ativo (hooks de baixo nível).")

    def pausar(self):
        # Durante telas que a pessoa precisa usar (espelho, Excel, etc.)
        # o hook não pode tratar teclado/mouse como interferência —
        # isso derrubava o programa sem e-mail de erro.
        self.monitorando = False
        self.interferencia_detectada.clear()

    def retomar(self):
        self.monitorando = True
        self.interferencia_detectada.clear()
        self._ignorar_ate = time.time() + 0.6

    def parar(self):
        self.monitorando = False
        self.interferencia_detectada.clear()
        if self._thread_id_hook:
            try:
                _user32.PostThreadMessageW(
                    self._thread_id_hook, _WM_QUIT, 0, 0
                )
            except Exception:
                pass
        if self._thread_hook is not None:
            self._thread_hook.join(timeout=2)
        print("Monitor de interferência encerrado.")

    def verificar_e_aguardar(self, operacao=""):
        if not self.interferencia_detectada.is_set():
            return
        if not self._lock_verificar.acquire(blocking=False):
            return
        try:
            if not self.interferencia_detectada.is_set():
                return
            tipo = self.tipo_interferencia

            contagem = self._contagem_interferencia.get(operacao, 0) + 1
            self._contagem_interferencia[operacao] = contagem

            if contagem > 3:
                registrar_log(
                    f"AVISO: Interferência repetida durante '{operacao}' "
                    f"({tipo}) — já alertado 3x, seguindo sem novo alerta.",
                    "AVISO"
                )
                self.interferencia_detectada.clear()
                self.retomar()
                return

            registrar_log(
                f"⚠ Interferência durante '{operacao}' (alerta {contagem}/3): "
                f"{tipo}. Exibindo alerta..."
            )
            self.pausar()
            mostrar_alerta_interferencia_pyside(tipo)
            registrar_log(
                "OK: Usuário confirmou (ou alerta expirou sozinho). "
                "Retomando automação..."
            )
            self.retomar()
        finally:
            self._lock_verificar.release()

monitor = MonitorInterferencia()

# A1: Flag para evitar reconfigurar impressora já configurada
_impressora_pdf_configurada: bool = False
_impressora_pdf_lock = __import__('threading').Lock()

# UA4: Evento de pausa real da automação
_evento_pausa_automacao = threading.Event()
_evento_pausa_automacao.set()   # começa "não pausado"

_evento_pausa_automacao = threading.Event()
_evento_pausa_automacao.set()


# =====================================================
# SAP SCRIPT RECORDER — Grava e reproduz sequências
# =====================================================

class _SAPScriptRecorder:
    """
    Grava sequências de comandos SAP bem-sucedidos
    e as reproduz em execuções futuras, eliminando
    buscas iterativas de elementos.

    Formato de script: lista de (operacao, args)
    Operações: 'findById', 'sendVKey', 'press',
               'settext', 'select', 'maximize'
    """

    _SCRIPT_FILE = "kv:sap_scripts"

    def __init__(self):
        self._scripts: dict = {}   # chave → lista de ops
        self._gravando       = False
        self._script_atual   = []
        self._chave_atual    = ""
        self._lock           = threading.Lock()
        self._carregar()

    def _carregar(self):
        try:
            bruto = _kv_get("sap_scripts")
            if bruto:
                dados = json.loads(bruto)
                if isinstance(dados, dict):
                    self._scripts = dados
                    registrar_log(
                        f"Scripts SAP carregados: "
                        f"{len(self._scripts)} script(s).",
                        "INFO"
                    )
        except Exception:
            pass

    def _salvar(self):
        try:
            _kv_set(
                "sap_scripts",
                json.dumps(self._scripts, indent=2, ensure_ascii=False),
            )
        except Exception:
            pass

    def iniciar_gravacao(self, chave: str):
        """Inicia gravação de um script para a chave."""
        with self._lock:
            self._gravando    = True
            self._script_atual = []
            self._chave_atual  = chave

    def registrar_op(
        self, operacao: str, elemento: str,
        valor: str = ""
    ):
        """Registra uma operação durante a gravação."""
        if not self._gravando:
            return
        with self._lock:
            self._script_atual.append(
                (operacao, elemento, valor)
            )

    def finalizar_gravacao(self, sucesso: bool):
        """
        Finaliza gravação.
        Só salva se a sequência foi bem-sucedida.
        """
        with self._lock:
            self._gravando = False
            if sucesso and self._script_atual:
                self._scripts[self._chave_atual] = (
                    list(self._script_atual)
                )
                self._salvar()
                registrar_log(
                    f"Script SAP gravado: "
                    f"'{self._chave_atual}' "
                    f"({len(self._script_atual)} ops)",
                    "OK"
                )
            self._script_atual = []
            self._chave_atual  = ""

    def tem_script(self, chave: str) -> bool:
        return chave in self._scripts

    def reproduzir(
        self, session, chave: str
    ) -> bool:
        """
        Reproduz script gravado.
        Retorna True se bem-sucedido.
        """
        script = self._scripts.get(chave)
        if not script:
            return False

        try:
            for operacao, elemento, valor in script:
                el = session.findById(elemento)
                if el is None:
                    return False

                if operacao == "settext":
                    el.text = valor
                elif operacao == "caretPosition":
                    el.caretPosition = int(valor)
                elif operacao == "sendVKey":
                    session.findById(
                        "wnd[0]"
                    ).sendVKey(int(valor))
                elif operacao == "press":
                    el.press()
                elif operacao == "select":
                    el.select()
                elif operacao == "maximize":
                    _sap_maximizar_wnd0(session)
                elif operacao == "selected":
                    el.selected = (valor == "True")
                elif operacao == "setFocus":
                    el.setFocus()
                elif operacao == "invoke":
                    el.invoke()

                # Pequena pausa entre operações
                time.sleep(0.03)

            return True

        except Exception as _e_replay:
            # Script desatualizado — remove para regravar
            registrar_log(
                f"AVISO [SCRIPT]: replay falhou para "
                f"'{chave}': {_e_replay} — removendo.",
                "AVISO"
            )
            with self._lock:
                self._scripts.pop(chave, None)
                self._salvar()
            return False

    def invalidar(self, chave: str):
        """Remove script inválido ou desatualizado."""
        with self._lock:
            if chave in self._scripts:
                del self._scripts[chave]
                self._salvar()

    def limpar_todos(self):
        with self._lock:
            self._scripts.clear()
            self._salvar()


# Instância global
_sap_recorder = _SAPScriptRecorder()
# =====================================================
# THREAD POOL GLOBAL PERSISTENTE
# Criado uma vez e reutilizado em todas as etapas
# =====================================================

from concurrent.futures import ThreadPoolExecutor as _TPE_GLOBAL

class _GlobalThreadPool:
    """
    Pool de threads persistente durante toda a execução.
    Elimina overhead de criação/destruição por etapa.

    Workers por categoria:
      - io_workers:   8  (I/O bound: disco, rede, UIA)
      - cpu_workers:  4  (CPU bound: pdfplumber, reportlab)
    """

    def __init__(self):
        import os
        _cpus            = os.cpu_count() or 4
        self._io_pool    = _TPE_GLOBAL(
            max_workers=8,
            thread_name_prefix="IO"
        )
        self._cpu_pool   = _TPE_GLOBAL(
            max_workers=min(_cpus, 4),
            thread_name_prefix="CPU"
        )
        self._lock       = threading.Lock()
        self._ativo      = True

    @property
    def io(self) -> _TPE_GLOBAL:
        """Pool para operações I/O bound."""
        return self._io_pool

    @property
    def cpu(self) -> _TPE_GLOBAL:
        """Pool para operações CPU bound."""
        return self._cpu_pool

    def submit_io(self, fn, *args, **kwargs):
        """Submete tarefa I/O bound."""
        return self._io_pool.submit(fn, *args, **kwargs)

    def submit_cpu(self, fn, *args, **kwargs):
        """Submete tarefa CPU bound."""
        return self._cpu_pool.submit(fn, *args, **kwargs)

    def encerrar(self):
        """Encerra ambos os pools graciosamente."""
        self._io_pool.shutdown(wait=True, cancel_futures=False)
        self._cpu_pool.shutdown(wait=True, cancel_futures=False)
        self._ativo = False


# Pool global — inicializado no módulo
_thread_pool = _GlobalThreadPool()


# =====================================================
# ASYNC ENGINE — Loop assíncrono persistente
# Gerencia I/O concorrente sem overhead de threads
# =====================================================

import asyncio      as _asyncio
try:
    import aiofiles as _aiofiles
except ImportError:
    _aiofiles = None
try:
    import aiohttp as _aiohttp
except ImportError:
    _aiohttp = None


class _AsyncEngine:
    """
    Motor assíncrono persistente para operações de I/O.

    Roda em thread dedicada com loop asyncio próprio.
    Permite submeter coroutines de qualquer thread via
    run_coroutine_threadsafe().

    Operações suportadas:
    - Leitura/escrita de arquivo (aiofiles)
    - Requisições HTTP (aiohttp — CNPJ API)
    - Escrita de log em batch
    - Gravação de checkpoint
    - Consultas SQLite assíncronas (aiosqlite)
    """

    def __init__(self):
        self._loop:   _asyncio.AbstractEventLoop | None = None
        self._thread: threading.Thread | None           = None
        self._session = None
        self._http2_client = None
        self._lock    = threading.Lock()

    def iniciar(self):
        """Inicia o loop em thread dedicada."""
        if (
            self._loop is not None
            and self._thread is not None
            and self._thread.is_alive()
        ):
            return
        def _rodar_loop():
            if hasattr(_asyncio, "WindowsProactorEventLoopPolicy"):
                try:
                    _asyncio.set_event_loop_policy(
                        _asyncio.WindowsProactorEventLoopPolicy()
                    )
                except Exception:
                    pass
            self._loop = _asyncio.new_event_loop()
            _asyncio.set_event_loop(self._loop)
            # Cria sessão HTTP reutilizável
            self._loop.run_until_complete(
                self._criar_sessao()
            )
            self._loop.run_forever()

        self._thread = threading.Thread(
            target=_rodar_loop,
            daemon=True,
            name="AsyncEngine"
        )
        self._thread.start()

        # Aguarda o loop estar pronto
        _inicio = time.time()
        while (
            self._loop is None
            and time.time() - _inicio < 5
        ):
            time.sleep(0.05)

    async def _criar_sessao(self):
        """Cria sess?es HTTP opcionais com pool/fallback."""
        if _aiohttp is not None:
            _connector = _aiohttp.TCPConnector(
                limit=10,
                ttl_dns_cache=300,
                use_dns_cache=True,
                keepalive_timeout=60,
            )
            self._session = _aiohttp.ClientSession(
                connector=_connector,
                headers={
                    "User-Agent": "AutomacaoSAP/2.0",
                    "Accept":     "application/json",
                },
                timeout=_aiohttp.ClientTimeout(total=10),
            )

        # M22: HTTP/2 para CNPJ quando httpx+h2 estiverem dispon?veis.
        # Mant?m aiohttp/urllib como fallback compat?vel.
        try:
            import httpx as _httpx
            self._http2_client = _httpx.AsyncClient(
                http2=True,
                timeout=10,
                headers={
                    "User-Agent": "AutomacaoSAP/2.0",
                    "Accept":     "application/json",
                },
            )
        except Exception:
            self._http2_client = None

    def submeter(self, coro) -> "_asyncio.Future":
        """
        Submete coroutine ao loop assíncrono.
        Thread-safe — pode ser chamado de qualquer thread.
        Retorna Future que pode ser aguardado ou ignorado.
        """
        if self._loop is None:
            raise RuntimeError(
                "AsyncEngine não iniciado."
            )
        return _asyncio.run_coroutine_threadsafe(
            coro, self._loop
        )

    def executar_sync(self, coro, timeout: float = 30):
        """
        Executa coroutine e aguarda o resultado.
        Bloqueia a thread chamadora até completar.
        """
        fut = self.submeter(coro)
        return fut.result(timeout=timeout)

    async def ler_arquivo(self, caminho: str) -> bytes:
        """L? arquivo de forma ass?ncrona, com fallback sem aiofiles."""
        if _aiofiles is not None:
            async with _aiofiles.open(caminho, "rb") as f:
                return await f.read()
        return await _asyncio.to_thread(Path(caminho).read_bytes)

    async def escrever_arquivo(
        self, caminho: str, conteudo: bytes
    ):
        """Escreve arquivo de forma ass?ncrona, com fallback sem aiofiles."""
        if _aiofiles is not None:
            async with _aiofiles.open(caminho, "wb") as f:
                await f.write(conteudo)
            return
        await _asyncio.to_thread(Path(caminho).write_bytes, conteudo)

    async def consultar_cnpj_async(
        self, cnpj: str
    ) -> dict:
        """
        Consulta CNPJ via aiohttp — completamente async.
        Reutiliza conexão do pool.
        """
        url = (
            f"https://brasilapi.com.br/api/cnpj/v1/{cnpj}"
        )
        try:
            if self._http2_client is not None:
                resp = await self._http2_client.get(url)
                if resp.status_code == 200:
                    return resp.json()
                return {}

            if self._session is not None:
                async with self._session.get(url) as resp:
                    if resp.status == 200:
                        return await resp.json()
                    return {}

            import json as _json_http
            import urllib.request as _ur_http
            def _consultar_sync():
                req = _ur_http.Request(
                    url,
                    headers={
                        "User-Agent": "AutomacaoSAP/2.0",
                        "Accept":     "application/json",
                    },
                )
                with _ur_http.urlopen(req, timeout=10) as resp:
                    if getattr(resp, "status", 200) == 200:
                        return _json_http.loads(resp.read().decode("utf-8"))
                return {}
            return await _asyncio.to_thread(_consultar_sync)
        except Exception:
            return {}

    async def consultar_cnpjs_batch(
        self, cnpjs: list
    ) -> dict:
        """
        Consulta múltiplos CNPJs em paralelo.
        Ganho máximo: N consultas no tempo de 1.
        """
        tarefas = {
            cnpj: self.consultar_cnpj_async(cnpj)
            for cnpj in cnpjs
            if cnpj not in _cache_cnpj
        }
        if not tarefas:
            return {}
        resultados = await _asyncio.gather(
            *tarefas.values(),
            return_exceptions=True
        )
        return {
            cnpj: r
            for cnpj, r in zip(tarefas.keys(), resultados)
            if isinstance(r, dict) and r
        }

    async def escrever_log_batch(
        self, linhas: list, arquivo: str
    ):
        """Escreve m?ltiplas linhas de log em batch."""
        conteudo = "\n".join(linhas) + "\n"
        if _aiofiles is not None:
            async with _aiofiles.open(
                arquivo, "a", encoding="utf-8"
            ) as f:
                await f.write(conteudo)
            return

        def _append_sync():
            with open(arquivo, "a", encoding="utf-8") as f:
                f.write(conteudo)
        await _asyncio.to_thread(_append_sync)

    def encerrar(self):
        """Encerra o loop assíncrono."""
        if self._loop and self._loop.is_running():
            if self._http2_client:
                _asyncio.run_coroutine_threadsafe(
                    self._http2_client.aclose(),
                    self._loop
                ).result(timeout=5)
            if self._session:
                _asyncio.run_coroutine_threadsafe(
                    self._session.close(),
                    self._loop
                ).result(timeout=5)
            self._loop.call_soon_threadsafe(
                self._loop.stop
            )


# Instância global
_async_engine = _AsyncEngine()

import atexit as _atexit_async
_atexit_async.register(_async_engine.encerrar)


import atexit as _atexit_pool
_atexit_pool.register(_thread_pool.encerrar)


# =====================================================
# OBJECT POOL — Reutiliza QTableWidgetItem e QColor
# Reduz pressão sobre o GC do Python
# =====================================================

class _QColorPool:
    """
    Pool de objetos QColor reutilizáveis.
    QColor é criado com frequência no flush_log —
    o pool elimina alocações repetidas para as
    mesmas cores.
    """

    def __init__(self):
        self._cores: dict = {}   # hex → QColor
        self._lock          = threading.Lock()
        # Pré-aquece com as cores mais usadas
        _cores_pre = [
            COR_SUCESSO, COR_ERRO, COR_ALERTA,
            COR_INFO, TEXTO_CLARO, TEXTO_OPACO,
            BRANCO, "#A78BFA", "#0D1117",
        ]
        for cor in _cores_pre:
            self._cores[cor] = QColor(cor)

    def get(self, hex_cor: str) -> QColor:
        """Retorna QColor do pool, criando se necessário."""
        with self._lock:
            if hex_cor not in self._cores:
                self._cores[hex_cor] = QColor(hex_cor)
            return self._cores[hex_cor]

    def __call__(self, hex_cor: str) -> QColor:
        return self.get(hex_cor)


class _QItemPool:
    """
    Pool de QTableWidgetItem reutilizáveis.
    Cada item é 'resetado' antes de ser reutilizado.
    Capacidade: 900 itens (300 linhas × 3 colunas).
    """

    CAPACIDADE = 900

    def __init__(self):
        self._disponíveis: list = []
        self._lock               = threading.Lock()
        # Pré-aloca
        for _ in range(min(100, self.CAPACIDADE)):
            self._disponíveis.append(
                QTableWidgetItem()
            )

    def adquirir(self, texto: str = "") -> QTableWidgetItem:
        """Retorna item do pool ou cria novo."""
        with self._lock:
            if self._disponíveis:
                item = self._disponíveis.pop()
                item.setText(texto)
                item.setData(256, None)
                return item
        # Pool vazio — cria novo
        return QTableWidgetItem(texto)

    def liberar(self, item: QTableWidgetItem):
        """Devolve item ao pool."""
        with self._lock:
            if len(self._disponíveis) < self.CAPACIDADE:
                self._disponíveis.append(item)


# Instâncias globais dos pools
_cor_pool  = _QColorPool()
_item_pool = _QItemPool()



