# ── Buffer assíncrono de log
_log_buffer_async: list = []
_log_buffer_lock         = threading.Lock()
_log_buffer_timer        = None


def _flush_log_async():
    """
    Escreve o buffer em disco de forma assíncrona.
    Chamado a cada 2s pelo timer, e no encerramento.
    """
    global _log_buffer_timer
    with _log_buffer_lock:
        if not _log_buffer_async:
            return
        linhas = list(_log_buffer_async)
        _log_buffer_async.clear()

    try:
        _log_handle.write("".join(linhas))
        _log_handle.flush()
    except Exception:
        pass

    # Re-agenda o próximo flush
    _log_buffer_timer = threading.Timer(2.0, _flush_log_async)
    _log_buffer_timer.daemon = True
    _log_buffer_timer.start()


# Inicia o timer de flush assíncrono
_log_buffer_timer = threading.Timer(2.0, _flush_log_async)
_log_buffer_timer.daemon = True
_log_buffer_timer.start()

# Garante flush no encerramento
import atexit as _atexit_log
_atexit_log.register(_flush_log_async)


def registrar_log(mensagem, nivel="INFO"):
    timestamp = datetime.now().strftime("%d/%m/%Y %H:%M:%S")
    linha     = f"[{timestamp}] {mensagem}"
    print(linha)

    # Enfileira para escrita assíncrona (não bloqueia)
    with _log_buffer_lock:
        _log_buffer_async.append(linha + "\n")

    # Espelha no painel em tempo real
    try:
        if '_painel' in globals() and _painel is not None:
            # Detecta nível automaticamente pelo conteúdo
            nivel_auto = nivel
            msg_lower  = mensagem.lower()
            if nivel == "INFO":
                if mensagem.startswith("OK"):
                    nivel_auto = "OK"
                elif (
                    "erro" in msg_lower or "falha" in msg_lower
                ) and not (                              # ← ADICIONAR
                    "0 falha" in msg_lower              # ← ADICIONAR
                    or "resumo" in msg_lower             # ← ADICIONAR
                ):                                      # ← ADICIONAR
                    nivel_auto = "ERRO"
                elif "aviso" in msg_lower or "timeout" in msg_lower:
                    nivel_auto = "AVISO"
                elif "sap" in msg_lower:
                    nivel_auto = "SAP"
                elif "sharepoint" in msg_lower or "upload" in msg_lower:
                    nivel_auto = "SP"
            _painel.adicionar_log(mensagem[:120], nivel_auto)
    except Exception:
        pass

def iniciar_log(empresa, contrato, ano, mes, pedidos, folhas, rms):
    # Usa _log_handle global — sem abrir/fechar arquivo
    _log_handle.write("\n" + "=" * 60 + "\n")
    _log_handle.write(
        f"EXECUÇÃO: "
        f"{datetime.now().strftime('%d/%m/%Y %H:%M:%S')}\n"
    )
    _log_handle.write(f"Empresa  : {empresa}\n")
    _log_handle.write(f"Contrato : {contrato}\n")
    _log_handle.write(f"Ano      : {ano}\n")
    _log_handle.write(f"Mês      : {mes}\n")
    _log_handle.write(
        f"Pedidos  : {len(pedidos)} — "
        f"{', '.join(pedidos)}\n"
    )
    _log_handle.write(
        f"Folhas   : {len(folhas)} — "
        f"{', '.join(folhas)}\n"
    )
    _log_handle.write(
        f"RMs      : {len(rms)} — "
        f"{', '.join([str(r['rm']) for r in rms])}\n"
    )
    _log_handle.write("=" * 60 + "\n")

# =====================================================
# ENCERRAR COM ERRO
# =====================================================
def _encerrar_processo(codigo: int = 1):
    """
    Derruba o processo na hora. Não chama QApplication.quit() de
    outra thread — isso espera o loop Qt e trava ('não está
    respondendo') depois de Fechar no diálogo de erro.
    """
    os._exit(codigo)


def _reiniciar_programa():
    """
    Abre uma instância nova e encerra esta — usado em 'Outro contrato'.
    Não usa os.execv: no .exe (PyInstaller + Qt) isso deixa a janela
    antiga congelada ('não está respondendo') mesmo com o assistente
    novo já aberto.
    """
    try:
        import subprocess
        if getattr(sys, "frozen", False):
            cmd = [sys.executable]
        else:
            cmd = [sys.executable, *sys.argv]
        kwargs = {"close_fds": True}
        if sys.platform == "win32":
            kwargs["creationflags"] = (
                getattr(subprocess, "DETACHED_PROCESS", 0x00000008)
                | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0x00000200)
            )
        subprocess.Popen(cmd, **kwargs)
    except Exception:
        pass
    try:
        app = QApplication.instance()
        if app is not None:
            app.closeAllWindows()
            app.quit()
    except Exception:
        pass
    os._exit(0)


def _rotulo_fila_contratos(fila, empresa="", contrato="") -> str:
    """Texto único com todos os contratos da fila, sem repetir."""
    vistos = []
    for p in fila or []:
        try:
            emp = str(p.get("empresa") or "").strip()
            ctr = str(p.get("contrato") or "").strip()
        except Exception:
            continue
        txt = f"{emp} - {ctr}".strip(" -")
        if txt and txt not in vistos:
            vistos.append(txt)
    if not vistos:
        return f"{empresa} - {contrato}".strip(" -")
    if len(vistos) == 1:
        return vistos[0]
    return f"{len(vistos)} contratos: " + "  ·  ".join(vistos)


def _enviar_email_erro_diagnostico(
    mensagem: str, detalhes: str, trace: str, esperar: bool = False,
):
    """
    Envia por e-mail (Outlook) um resumo do erro + o log da execução
    em anexo, para levi.vasconcelos@petrobras.com.br.
    esperar=True: aguarda o envio (falha de etapa que não interrompe
    o Qt). Daemon sozinha some quando o processo fecha.
    """
    def _enviar():
        try:
            import getpass
            import socket
            try:
                usuario = getpass.getuser()
                maquina = socket.gethostname()
            except Exception:
                usuario, maquina = "?", "?"
            corpo = (
                f"Usuário : {usuario}\n"
                f"Máquina : {maquina}\n"
                f"Data    : {datetime.now().strftime('%d/%m/%Y %H:%M:%S')}\n"
                f"Log     : {LOG_FILE}\n\n"
                f"Mensagem: {mensagem}\n\n"
                f"Detalhe : {detalhes}\n\n"
                f"Traceback:\n{trace}\n"
            )
            assunto = (
                f"Erro na Automação SAP — "
                f"{datetime.now().strftime('%d/%m/%Y %H:%M')}"
            )
            anexos = []
            try:
                anexos.append(_log_exportar_txt_temp(somente_execucao_atual=True))
            except Exception:
                pass

            # Sempre grava .eml em disco (não depende de COM / login).
            try:
                eml = _montar_eml_rascunho(
                    "levi.vasconcelos@petrobras.com.br",
                    "",
                    assunto,
                    "<pre>" + corpo.replace("<", "&lt;") + "</pre>",
                    corpo,
                    anexos,
                )
                registrar_log(
                    f"OK [EMAIL-ERRO]: diagnóstico salvo em {eml}",
                    "OK",
                )
            except Exception as e_eml:
                eml = None
                registrar_log(
                    f"AVISO [EMAIL-ERRO]: falha ao gerar .eml: {e_eml}",
                    "AVISO",
                )

            enviado = False
            if (
                _outlook_classico_rodando()
                and not _janelas_login_outlook_classico()
            ):
                try:
                    outlook = win32com.client.Dispatch("Outlook.Application")
                    mail = outlook.CreateItem(0)
                    mail.To = "levi.vasconcelos@petrobras.com.br"
                    mail.Subject = assunto
                    mail.Body = corpo
                    for ax in anexos:
                        try:
                            mail.Attachments.Add(str(Path(ax).resolve()))
                        except Exception:
                            pass
                    mail.Send()
                    enviado = True
                    registrar_log("OK [EMAIL-ERRO]: enviado via COM clássico.", "OK")
                except Exception as e_com:
                    registrar_log(
                        f"AVISO [EMAIL-ERRO]: COM clássico não enviou: {e_com}",
                        "AVISO",
                    )

            if not enviado and eml is not None:
                os.startfile(str(eml))
                time.sleep(2.5)
                try:
                    enviado = _enviar_composicao_aberta(assunto)
                except Exception as e_env:
                    enviado = False
                    registrar_log(
                        f"AVISO [EMAIL-ERRO]: falha ao clicar Enviar: {e_env}",
                        "AVISO",
                    )
                registrar_log(
                    "OK [EMAIL-ERRO]: diagnóstico enviado no Outlook."
                    if enviado
                    else "AVISO [EMAIL-ERRO]: composição aberta — "
                    "não confirmou o envio; clique em Enviar.",
                    "OK" if enviado else "AVISO",
                )
        except Exception as e_envio:
            try:
                registrar_log(
                    f"AVISO [EMAIL-ERRO]: não foi possível enviar "
                    f"e-mail de diagnóstico: {e_envio}",
                    "AVISO"
                )
            except Exception:
                pass

    # daemon=True: não segura o processo aberto se o Outlook travar no rótulo
    t = threading.Thread(target=_enviar, daemon=True)
    t.start()
    if esperar:
        t.join(timeout=25)


def _excluir_pasta_com_retry(pasta, tentativas: int = 5, espera: float = 0.6):
    """
    Tenta excluir uma pasta local várias vezes antes de desistir.

    No Windows, um arquivo recém-criado ou recém-lido pode ficar
    brevemente travado (antivírus escaneando, indexação do Windows
    Search, ou o processo que leu ele ainda soltando o handle) mesmo
    que ninguém esteja usando ele de propósito — a primeira tentativa
    de exclusão pode falhar com WinError 32 nesses casos. Repetir
    algumas vezes, com uma pequena espera entre elas, resolve a
    imensa maioria sem precisar saber a causa exata.

    Retorna (sucesso: bool, erro: Exception | None).
    """
    pasta = Path(pasta)
    ultimo_erro = None
    for tentativa in range(1, tentativas + 1):
        try:
            if pasta.exists():
                shutil.rmtree(pasta)
            return True, None
        except Exception as e:
            ultimo_erro = e
            if tentativa < tentativas:
                time.sleep(espera)
    return False, ultimo_erro


def _pasta_local_e_segura(pasta: Path) -> bool:
    texto = str(pasta or "")
    return any(
        nome in texto
        for nome in ("Documents", "Documentos", "OneDrive", "Desktop")
    )


def limpar_dados_locais_do_contrato(params: dict) -> None:
    """
    Apaga o checkpoint e os PDFs deste contrato/período.
    Usado ao Encerrar de propósito ou ao Cancelar o checkpoint
    para recomeçar do SAP.
    """
    checkpoint_limpar()
    if not params:
        return
    raiz = Path(str(params.get("pasta_raiz_local") or ""))
    ano = str(params.get("ano_ref") or "")
    mes = str(params.get("mes_pad") or "")
    alvos = []
    if raiz and ano and mes:
        alvos.append(raiz / ano / mes)
    else:
        for chave in (
            "pasta_pedidos_local",
            "pasta_frs_local",
            "pasta_rm_local",
            "pasta_espelho_local",
        ):
            bruto = params.get(chave)
            if bruto:
                alvos.append(Path(bruto))
    vistos = set()
    for pasta in alvos:
        try:
            pasta = pasta.resolve()
        except Exception:
            pasta = Path(pasta)
        chave = str(pasta).lower()
        if chave in vistos or not pasta.exists():
            continue
        vistos.add(chave)
        if not _pasta_local_e_segura(pasta):
            registrar_log(
                f"AVISO: pasta local não apagada "
                f"(caminho não reconhecido): {pasta}",
                "AVISO",
            )
            continue
        ok, err = _excluir_pasta_com_retry(pasta)
        if ok:
            registrar_log(
                f"OK: pasta local excluída ({pasta}).",
                "OK",
            )
        else:
            registrar_log(
                f"AVISO: não foi possível excluir {pasta}: {err}",
                "AVISO",
            )


_encerrando_erro = False


def _recuperar_para_dashboard(mensagem, detalhes, log_file):
    """Volta à janela principal no Dashboard sem matar o processo."""
    def _ui():
        try:
            monitor.parar()
        except Exception:
            pass
        params = {}
        try:
            th = globals().get("_thread_automacao")
            if th is not None:
                params = getattr(th, "parametros", {}) or {}
        except Exception:
            params = {}
        empresa  = params.get("empresa", "—")
        contrato = params.get("contrato", "—")
        icj      = params.get("icj", "—")
        periodo  = params.get("periodo", "—")
        url_sp   = params.get("URL_SHAREPOINT", "")
        try:
            widget = _criar_widget_dashboard(
                empresa, contrato, icj, periodo,
                0, 0, 0, 0, 0, 0, 0, 0,
                False, False, False, False,
                False, log_file or LOG_FILE,
                tempo_total_s=0,
                url_sharepoint=url_sp,
                historico_etapas={"Interrompido por erro": 0},
                rotulo_contratos=_rotulo_fila_contratos(
                    getattr(globals().get("_thread_automacao"), "fila", None),
                    empresa,
                    contrato,
                ),
                n_contratos=_n_contratos_fila(),
            )
        except Exception:
            widget = QLabel(
                f"Execução interrompida.\n{mensagem}\n{detalhes}\n"
                f"Log: {log_file}"
            )
            widget.setWordWrap(True)
        jp = globals().get("_janela_principal")
        if jp is None:
            try:
                for w in _qapp.topLevelWidgets():
                    if hasattr(w, "inserir_dashboard"):
                        jp = w
                        break
            except Exception:
                jp = None
        if jp is not None:
            try:
                jp.inserir_dashboard(widget)
            except Exception as e_ins:
                try:
                    registrar_log(f"AVISO [DASHBOARD]: inserir falhou: {e_ins}", "AVISO")
                except Exception:
                    pass
            try:
                jp._topbar.set_erro()
            except Exception:
                pass
            try:
                jp.showNormal()
                jp.raise_()
                jp.activateWindow()
            except Exception:
                pass
        else:
            try:
                registrar_log(
                    "AVISO [DASHBOARD]: janela principal não encontrada "
                    "ao voltar do erro.",
                    "AVISO",
                )
            except Exception:
                pass
        try:
            _p = globals().get("_painel")
            if _p is not None:
                _mini = getattr(_p, "_mini_status", None)
                if _mini is not None:
                    _mini.close()
        except Exception:
            pass
        try:
            toast(
                "Erro — checkpoint mantido. Feche o app ou retome depois.",
                "aviso",
                6000,
            )
        except Exception:
            pass

    try:
        QTimer.singleShot(0, _ui)
    except Exception:
        _ui()


def encerrar_com_erro(mensagem, excecao=None, pasta_excluir=None):
    global _encerrando_erro
    if _encerrando_erro:
        return
    _encerrando_erro = True
    try:
        _encerrar_com_erro_impl(mensagem, excecao, pasta_excluir)
    finally:
        _encerrando_erro = False


def _encerrar_com_erro_impl(mensagem, excecao=None, pasta_excluir=None):
    monitor.parar()
    db_registrar_erro("CRÍTICO", mensagem)

    # ── Restaura a janela principal (se minimizada) e fecha o
    # mini-dashboard (se aberto), antes da tela de erro aparecer.
    #
    # encerrar_com_erro() pode ser chamada de QUALQUER thread —
    # incluindo a AutomacaoThread, que é o caso mais comum (erros
    # durante a automação). Métodos de janela do Qt (.close(),
    # .showNormal(), .raise_() etc.) só podem ser chamados com
    # segurança na thread principal da GUI. Chamá-los direto de outra
    # thread pode travar a aplicação inteira sem gerar nenhum erro —
    # foi exatamente isso que causou o "Python não está respondendo"
    # depois das tentativas de SharePoint falharem. Por isso os dois
    # blocos abaixo são despachados via QTimer.singleShot(0, ...),
    # que sempre executa na thread principal, não importa de onde foi
    # chamado (mesmo padrão já usado em atualizar_eta/atualizar_kpi
    # do PainelProgresso).
    def _restaurar_janela_principal():
        try:
            for w in _qapp.topLevelWidgets():
                if hasattr(w, "_topbar"):
                    w._topbar.set_erro()
                    if w.isMinimized():
                        w.showNormal()
                        w.raise_()
                        w.activateWindow()
                    break
        except Exception:
            pass

    def _fechar_mini_dashboard():
        try:
            if '_painel' in globals() and _painel is not None:
                _mini = getattr(_painel, '_mini_status', None)
                if _mini is not None:
                    _mini.close()
        except Exception:
            pass

    QTimer.singleShot(0, _restaurar_janela_principal)
    QTimer.singleShot(0, _fechar_mini_dashboard)

    detalhes = str(excecao) if excecao else ""
    trace    = traceback.format_exc() if excecao else ""
    if pasta_excluir and Path(pasta_excluir).exists():
        sucesso_excl, e_del = _excluir_pasta_com_retry(pasta_excluir)
        if sucesso_excl:
            msg_limpeza = (
                f"Pasta local excluída após erro:\n"
                f"{pasta_excluir}"
            )
            print(f"\n{msg_limpeza}")
            registrar_log(f"LIMPEZA: {msg_limpeza}")
        else:
            msg_falha = (
                f"AVISO: Não foi possível excluir "
                f"a pasta local: {e_del}\n"
                f"Exclua manualmente: {pasta_excluir}"
            )
            print(f"\n{msg_falha}")
            registrar_log(msg_falha)

    try:
        registrar_log("=" * 50)
        registrar_log("ERRO CRÍTICO — AUTOMAÇÃO INTERROMPIDA")
        registrar_log(mensagem)
        if detalhes:
            registrar_log(f"Detalhe: {detalhes}")
        if trace and trace.strip() != "NoneType: None":
            registrar_log(f"Traceback:\n{trace}")
        registrar_log("=" * 50)
    except Exception:
        pass
    print("\n" + "=" * 50)
    print("AUTOMAÇÃO INTERROMPIDA POR ERRO")
    print("=" * 50)
    print(mensagem)
    if detalhes:
        print(f"\nDetalhe: {detalhes}")
    print(f"\nLog salvo em: {LOG_FILE}")
    print("=" * 50)

    # Pasta já foi removida no primeiro bloco acima.
    # Apenas monta a mensagem de status sem nova tentativa de remoção.
    pasta_msg = ""
    if pasta_excluir:
        if Path(str(pasta_excluir)).exists():
            pasta_msg = "⚠ Pasta ainda existe — exclua manualmente."
        else:
            pasta_msg = "✔ Pasta local excluída."
    try:
        # esperar=False: não trava no Outlook (rótulo Pública / Enviar).
        # O diálogo de erro e o dashboard precisam abrir na hora.
        _enviar_email_erro_diagnostico(
            mensagem, detalhes, trace, esperar=False,
        )
    except Exception:
        pass

    try:
        _log_handle.flush()
    except Exception:
        pass
    try:
        acao = _gui_bridge.pedir_erro_critico(
            mensagem,
            detalhes,
            pasta_msg,
            LOG_FILE
        )
    except NameError:
        acao = "dashboard"
        try:
            from PySide6.QtWidgets import QMessageBox
            _app_tmp = QApplication.instance()
            if _app_tmp:
                QMessageBox.critical(
                    None,
                    "Erro Crítico",
                    f"{mensagem}\n\n{detalhes}"
                )
        except Exception:
            pass
    if acao == "retomar":
        _reiniciar_programa()
        return
    if acao == "fechar":
        _encerrar_processo(1)
        return
    _recuperar_para_dashboard(mensagem, detalhes, LOG_FILE)
    # Sem isto a thread de automação continua depois do diálogo
    # (Ir ao dashboard) e gera erros em cascata (login, set_focus).
    try:
        _app_q = QApplication.instance()
        if _app_q is not None and QThread.currentThread() != _app_q.thread():
            raise SystemExit
    except SystemExit:
        raise
    except Exception:
        raise SystemExit


