def carregar_config_sap():
    try:
        bruto = _kv_get("config")
        if bruto:
            dados = json.loads(bruto)
            return dados if isinstance(dados, dict) else {}
    except Exception as e:
        try:
            registrar_log(
                f"AVISO [CONFIG]: dados corrompidos ({e}) — usando vazio.",
                "AVISO",
            )
        except Exception:
            pass
    cfg = Path(CONFIG_SAP)
    if cfg.exists() and cfg.suffix == ".json":
        try:
            with open(cfg, "r", encoding="utf-8") as f:
                dados = json.load(f)
            return dados if isinstance(dados, dict) else {}
        except Exception:
            pass
    return {}

