def _versao_para_tupla(texto: str) -> tuple:
    nums = [int(x) for x in re.findall(r"\d+", texto or "")]
    while len(nums) < 3:
        nums.append(0)
    return tuple(nums[:3])


def _pasta_atualizacao_salva() -> str:
    try:
        return str(carregar_config_sap().get("pasta_atualizacao") or "").strip()
    except Exception:
        return ""


def salvar_pasta_atualizacao(pasta: str, verificar_ao_abrir=None):
    try:
        dados = carregar_config_sap()
    except Exception:
        dados = {}
    dados["pasta_atualizacao"] = str(pasta or "").strip()
    if verificar_ao_abrir is not None:
        dados["verificar_atualizacao_ao_abrir"] = bool(verificar_ao_abrir)
    _salvar_config_completo(dados)


def _raizes_biblioteca_petrobras() -> list:
    nome = "PETROBRAS"
    biblioteca = "BS SOP GPS - CS-II"
    paineis = "09. Paineis"
    saida = []
    vistos = set()
    for raiz in (
        Path(r"C:\Users\GFG7") / nome / biblioteca,
        Path.home() / nome / biblioteca,
    ):
        chave = str(raiz).lower()
        if chave in vistos:
            continue
        vistos.add(chave)
        saida.append((raiz, paineis))
    return saida


def _fontes_atualizacao_candidatas() -> list:
    """ZIP/pasta oficiais. Não é o Desktop/Downloads de quem usa o app."""
    saida = []
    vistos = set()

    def _add(p):
        if not p:
            return
        try:
            r = Path(str(p).strip())
            if not r.exists():
                return
            if r.is_file() and r.suffix.lower() != ".zip":
                return
            if not r.is_file() and not r.is_dir():
                return
            try:
                r = r.resolve()
            except Exception:
                pass
        except Exception:
            return
        chave = str(r).lower()
        if chave in vistos:
            return
        vistos.add(chave)
        saida.append(r)

    _add(_pasta_atualizacao_salva())
    _add(os.environ.get("AUTOMACAOSAP_ATUALIZACAO", ""))
    _add(getattr(Config, "ARQUIVO_OFICIAL_ZIP", ""))
    _add(getattr(Config, "PASTA_OFICIAL_LOCAL", ""))
    for raiz, paineis in _raizes_biblioteca_petrobras():
        _add(raiz / paineis / "AutomacaoSAP.zip")
        _add(raiz / paineis)
        _add(raiz / "AutomacaoSAP.zip")
        if raiz.is_dir():
            try:
                for zip_sp in raiz.glob("*/AutomacaoSAP.zip"):
                    _add(zip_sp)
            except Exception:
                pass
    _add(r"C:\AutomacaoSAP\pacote\AutomacaoSAP")
    return saida


def _ler_marcador_versao_zip(arquivo_zip: Path) -> dict:
    try:
        with zipfile.ZipFile(arquivo_zip, "r") as zf:
            for nome in zf.namelist():
                n = nome.replace("\\", "/").rstrip("/")
                if n.endswith("versao.json"):
                    return json.loads(zf.read(nome).decode("utf-8"))
    except Exception:
        return {}
    return {}


def _ler_marcador_fonte(fonte: Path) -> dict:
    fonte = Path(fonte)
    if fonte.is_file() and fonte.suffix.lower() == ".zip":
        dados = _ler_marcador_versao_zip(fonte)
        if dados:
            return dados
        ao_lado = fonte.with_name("versao.json")
        if ao_lado.is_file():
            try:
                extra = json.loads(ao_lado.read_text(encoding="utf-8"))
                return extra if isinstance(extra, dict) else {}
            except Exception:
                return {}
        return {}
    if fonte.is_dir():
        arq = fonte / "versao.json"
        if arq.is_file():
            try:
                dados = json.loads(arq.read_text(encoding="utf-8"))
                return dados if isinstance(dados, dict) else {}
            except Exception:
                return {}
    return {}


def _mtime_exe_instalado() -> float:
    try:
        if getattr(sys, "frozen", False):
            return Path(sys.executable).stat().st_mtime
    except Exception:
        pass
    return 0.0


def _zip_oficial_na_fonte(fonte: Path) -> Path | None:
    fonte = Path(fonte)
    if fonte.is_file() and fonte.suffix.lower() == ".zip":
        return fonte
    if fonte.is_dir():
        prefer = fonte / "AutomacaoSAP.zip"
        if prefer.is_file():
            return prefer
        zips = sorted(
            fonte.glob("*.zip"),
            key=lambda p: p.stat().st_mtime,
            reverse=True,
        )
        return zips[0] if zips else None
    return None


def _ler_marcador_versao(pasta: Path) -> dict:
    return _ler_marcador_fonte(Path(pasta))


def _gravar_marcador_versao(pasta=None):
    pasta = Path(pasta or Config.INST_DIR)
    payload = {
        "versao": Config.VERSAO,
        "data": Config.DATA,
        "notas": "",
    }
    try:
        pasta.mkdir(parents=True, exist_ok=True)
        (pasta / "versao.json").write_text(
            json.dumps(payload, indent=2, ensure_ascii=False),
            encoding="utf-8",
        )
    except Exception:
        pass


def _caminho_oficial_exibido() -> str:
    salvo = _pasta_atualizacao_salva()
    if salvo:
        return salvo
    zip_padrao = Path(getattr(Config, "ARQUIVO_OFICIAL_ZIP", ""))
    if zip_padrao.exists():
        return str(zip_padrao)
    zip_home = (
        Path.home()
        / "PETROBRAS"
        / "BS SOP GPS - CS-II"
        / "09. Paineis"
        / "AutomacaoSAP.zip"
    )
    if zip_home.exists():
        return str(zip_home)
    if zip_home.parent.is_dir():
        return str(zip_home)
    return str(zip_padrao or zip_home)


def _consultar_atualizacao() -> dict:
    local = Config.VERSAO
    resultado = {
        "ok": False,
        "tem_nova": False,
        "versao_local": local,
        "versao_remota": "",
        "data_remota": "",
        "notas": "",
        "pasta": "",
        "erro": "",
    }
    candidatos = _fontes_atualizacao_candidatas()
    if not candidatos:
        resultado["erro"] = (
            "Não achei AutomacaoSAP.zip no OneDrive PETROBRAS.\n\n"
            "Quem publica: deixe o ZIP mais novo em\n"
            r"C:\Users\GFG7\PETROBRAS\BS SOP GPS - CS-II\09. Paineis\AutomacaoSAP.zip"
            "\n(ou em outra pasta dentro de BS SOP GPS - CS-II).\n\n"
            "Quem usa: sincronize essa biblioteca. O .exe pode ficar "
            "no Desktop ou em Downloads; a atualização sai do ZIP."
        )
        return resultado
    melhor_ver = None
    melhor_mtime = None
    for fonte in candidatos:
        zip_p = _zip_oficial_na_fonte(fonte)
        tem_exe = fonte.is_dir() and (fonte / "AutomacaoSAP.exe").is_file()
        if not tem_exe and zip_p is None:
            continue
        pasta_ref = zip_p if zip_p is not None else fonte
        dados = _ler_marcador_fonte(fonte)
        if zip_p is not None and not dados:
            dados = _ler_marcador_fonte(zip_p)
        ver = str(dados.get("versao") or "").strip()
        if ver:
            cand = {
                "versao": ver,
                "data": str(dados.get("data") or ""),
                "notas": str(dados.get("notas") or ""),
                "pasta": pasta_ref,
                "tupla": _versao_para_tupla(ver),
            }
            if melhor_ver is None or cand["tupla"] > melhor_ver["tupla"]:
                melhor_ver = cand
            continue
        if zip_p is None:
            continue
        try:
            mtime = zip_p.stat().st_mtime
        except Exception:
            continue
        cand = {
            "versao": "ZIP",
            "data": datetime.fromtimestamp(mtime).strftime("%d/%m/%Y"),
            "notas": "",
            "pasta": zip_p,
            "tupla": (0, 0, 0),
            "mtime": mtime,
        }
        if melhor_mtime is None or cand["mtime"] > melhor_mtime["mtime"]:
            melhor_mtime = cand
    melhor = melhor_ver if melhor_ver is not None else melhor_mtime
    if melhor is None:
        resultado["erro"] = (
            "Achei a pasta no OneDrive, mas não tem AutomacaoSAP.zip "
            "(nem AutomacaoSAP.exe). Substitua o ZIP nessa pasta."
        )
        return resultado
    resultado["ok"] = True
    resultado["versao_remota"] = melhor["versao"]
    resultado["data_remota"] = melhor["data"]
    resultado["notas"] = melhor["notas"]
    resultado["pasta"] = str(melhor["pasta"])
    mesma = False
    try:
        mesma = Path(melhor["pasta"]).resolve() == Config.INST_DIR.resolve()
    except Exception:
        pass
    if melhor_ver is not None:
        resultado["tem_nova"] = (
            melhor["tupla"] > _versao_para_tupla(local) and not mesma
        )
    else:
        resultado["tem_nova"] = (
            getattr(sys, "frozen", False)
            and float(melhor.get("mtime") or 0) > (_mtime_exe_instalado() + 60)
            and not mesma
        )
    return resultado


def _localizar_pacote_atualizacao(pasta: Path) -> Path:
    pasta = Path(pasta)
    if pasta.is_file() and pasta.suffix.lower() == ".zip":
        dest = Path(tempfile.mkdtemp(prefix="AutomacaoSAP_zip_"))
        with zipfile.ZipFile(pasta, "r") as zf:
            zf.extractall(dest)
        for cand in [dest, *list(dest.iterdir())]:
            if cand.is_dir() and (cand / "AutomacaoSAP.exe").is_file():
                return cand
        raise RuntimeError(
            "O ZIP oficial não contém AutomacaoSAP.exe. "
            "Empacote a pasta inteira do aplicativo (onedir)."
        )
    if pasta.is_dir() and (pasta / "AutomacaoSAP.exe").is_file():
        return pasta
    zip_p = _zip_oficial_na_fonte(pasta)
    if zip_p is not None:
        return _localizar_pacote_atualizacao(zip_p)
    raise RuntimeError(
        "Não achei AutomacaoSAP.exe nem AutomacaoSAP.zip na origem oficial."
    )


def _aplicar_atualizacao(pasta_oficial: str):
    """Copia o pacote novo e reinicia o .exe (não dá para sobrescrever em uso)."""
    if not getattr(sys, "frozen", False):
        raise RuntimeError(
            "A troca automática só funciona no .exe. "
            "No Python, use o pacote novo em C:\\AutomacaoSAP\\pacote\\AutomacaoSAP."
        )
    import subprocess as _sp_upd
    origem = _localizar_pacote_atualizacao(Path(pasta_oficial))
    destino = Config.INST_DIR.resolve()
    if origem.resolve() == destino:
        raise RuntimeError("A pasta oficial é a mesma da instalação atual.")
    staging = Path(tempfile.mkdtemp(prefix="AutomacaoSAP_upd_"))
    for item in origem.iterdir():
        alvo = staging / item.name
        if item.is_dir():
            shutil.copytree(item, alvo, dirs_exist_ok=True)
        else:
            shutil.copy2(item, alvo)
    exe_dst = destino / "AutomacaoSAP.exe"
    bat = Path(tempfile.gettempdir()) / "AutomacaoSAP_aplicar_update.bat"
    orig_s = str(staging)
    dest_s = str(destino)
    exe_s = str(exe_dst)
    bat.write_text(
        "\r\n".join([
            "@echo off",
            "timeout /t 2 /nobreak >nul",
            f'if exist "{exe_s}" move /Y "{exe_s}" "{exe_s}.old" >nul 2>&1',
            f'robocopy "{orig_s}" "{dest_s}" /E /IS /IT /R:2 /W:1 >nul',
            f'start "" "{exe_s}"',
            f'rmdir /s /q "{orig_s}"',
            'del "%~f0"',
            "",
        ]),
        encoding="utf-8",
    )
    flags = 0
    flags |= int(getattr(_sp_upd, "CREATE_NO_WINDOW", 0) or 0)
    flags |= int(getattr(_sp_upd, "DETACHED_PROCESS", 0) or 0)
    _sp_upd.Popen(
        ["cmd.exe", "/c", str(bat)],
        close_fds=True,
        creationflags=flags,
    )
    app = QApplication.instance()
    if app is not None:
        app.quit()
    os._exit(0)


def _dialogo_atualizacao(parent=None, manual=False, info=None):
    info = info if isinstance(info, dict) else _consultar_atualizacao()
    if not info.get("tem_nova"):
        if manual:
            if info.get("erro"):
                QMessageBox.information(
                    parent,
                    "Atualização",
                    info["erro"],
                )
            else:
                rem = info.get("versao_remota") or info.get("versao_local")
                QMessageBox.information(
                    parent,
                    "Atualização",
                    f"Você já está na versão mais recente.\n\n"
                    f"Local : v{info.get('versao_local')}\n"
                    f"Oficial: v{rem}",
                )
        return False
    notas = (info.get("notas") or "").strip()
    extra = f"\n\n{notas}" if notas else ""
    resp = QMessageBox.question(
        parent,
        "Nova versão disponível",
        f"Há uma versão mais nova do aplicativo.\n\n"
        f"Instalada : v{info.get('versao_local')}  ({Config.DATA})\n"
        f"Oficial   : v{info.get('versao_remota')}"
        + (f"  ({info.get('data_remota')})" if info.get("data_remota") else "")
        + extra
        + "\n\nAtualizar agora? O programa fecha e abre de novo "
        "na tela inicial.",
        QMessageBox.Yes | QMessageBox.No,
        QMessageBox.Yes if not manual else QMessageBox.Yes,
    )
    if resp != QMessageBox.Yes:
        return False
    try:
        _aplicar_atualizacao(info["pasta"])
    except Exception as e:
        QMessageBox.warning(
            parent,
            "Atualização",
            f"Não foi possível atualizar:\n{e}",
        )
    return False


