class _IntegracoesOficiais:
    """Clientes opcionais para SAP RFC/OData e Microsoft Graph.

    A automacao GUI continua sendo o fallback. As APIs so sao usadas quando
    configuradas explicitamente, evitando tentativas de autenticacao inesperadas.
    """

    _TOKEN_CACHE = Config.BASE_DIR / "token_sharepoint_cache.json"
    _CHUNK_SIZE = 5 * 1024 * 1024

    def __init__(self, config=None):
        self.config = config or carregar_config_integracoes()
        self.sp = self.config.get("sharepoint_graph", {})
        self.sap = self.config.get("sap_oficial", {})

    @staticmethod
    def _json_request(url, method="GET", data=None, headers=None, timeout=45):
        import urllib.request as _request
        cabecalhos = {"Accept": "application/json"}
        cabecalhos.update(headers or {})
        req = _request.Request(url, data=data, headers=cabecalhos, method=method)
        with _request.urlopen(req, timeout=timeout) as resposta:
            corpo = resposta.read()
            if not corpo:
                return resposta.status, {}
            return resposta.status, json.loads(corpo.decode("utf-8"))

    @staticmethod
    def _repetir(operacao, descricao, tentativas=4):
        ultimo = None
        for tentativa in range(1, tentativas + 1):
            try:
                return operacao()
            except Exception as e:
                ultimo = e
                if tentativa < tentativas:
                    espera = min(8.0, 0.5 * (2 ** (tentativa - 1)))
                    registrar_log(
                        f"AVISO [{descricao}]: tentativa {tentativa}/{tentativas} falhou; "
                        f"nova tentativa em {espera:.1f}s.", "AVISO"
                    )
                    time.sleep(espera)
        raise ultimo

    def graph_habilitado(self) -> bool:
        obrigatorios = ("tenant_id", "client_id", "site_id", "drive_id")
        return bool(self.sp.get("habilitado")) and all(self.sp.get(k) for k in obrigatorios)

    def configurar_graph_automaticamente(self, url_sharepoint: str) -> bool:
        """Descobre site/drive a partir da URL e persiste a configuração segura.

        O segredo nunca é salvo. Na primeira execução, basta disponibilizar
        SP_GRAPH_TENANT_ID, SP_GRAPH_CLIENT_ID e SP_GRAPH_CLIENT_SECRET; os
        IDs internos do SharePoint são consultados e gravados automaticamente.
        """
        if self.graph_habilitado():
            return True
        try:
            import urllib.parse as _parse_bootstrap
            url = _parse_bootstrap.urlparse(url_sharepoint)
            partes = [p for p in url.path.split("/") if p]
            indice = next(
                (i for i, p in enumerate(partes) if p.lower() in ("sites", "teams")),
                None,
            )
            if indice is None or len(partes) <= indice + 1:
                return False
            site_path = "/".join(partes[indice:indice + 2])
            self.sp.update({
                "habilitado": True,
                "tenant_id": self.sp.get("tenant_id") or os.getenv("SP_GRAPH_TENANT_ID", ""),
                "client_id": self.sp.get("client_id") or os.getenv("SP_GRAPH_CLIENT_ID", ""),
                "client_secret_env": self.sp.get("client_secret_env") or "SP_GRAPH_CLIENT_SECRET",
            })
            if not self.sp["tenant_id"] or not self.sp["client_id"]:
                return False
            headers = {"Authorization": f"Bearer {self._token_graph()}"}
            _, site = self._json_request(
                f"https://graph.microsoft.com/v1.0/sites/{url.netloc}:/{site_path}",
                headers=headers, timeout=30,
            )
            site_id = site.get("id")
            if not site_id:
                return False
            _, drives = self._json_request(
                f"https://graph.microsoft.com/v1.0/sites/{site_id}/drives",
                headers=headers, timeout=30,
            )
            lista_drives = drives.get("value", [])
            drive = next(
                (d for d in lista_drives if d.get("name", "").lower() in ("documents", "documentos", "shared documents", "documentos compartilhados")),
                lista_drives[0] if lista_drives else None,
            )
            if not drive or not drive.get("id"):
                return False
            self.sp.update({"site_id": site_id, "drive_id": drive["id"]})

            # Quando a URL aponta para uma pasta, preserva esse caminho como
            # raiz. Caso aponte para o site, a raiz da biblioteca é usada.
            caminho_remoto = _parse_bootstrap.unquote(
                _parse_bootstrap.parse_qs(url.query).get("id", [""])[0]
            ).strip("/")
            marcadores = (drive.get("name", ""), "Shared Documents", "Documentos Compartilhados")
            for marcador in marcadores:
                pos = caminho_remoto.lower().find(marcador.lower())
                if pos >= 0:
                    caminho_remoto = caminho_remoto[pos + len(marcador):].strip("/")
                    break
            self.sp["pasta_destino"] = self.sp.get("pasta_destino", caminho_remoto)
            self.config["sharepoint_graph"] = self.sp
            _kv_set(
                "config_integracoes",
                json.dumps(self.config, indent=2, ensure_ascii=False),
            )
            registrar_log("OK [GRAPH]: site e biblioteca configurados automaticamente.", "OK")
            return True
        except Exception as erro:
            registrar_log(f"AVISO [GRAPH]: bootstrap automático indisponível: {erro}", "AVISO")
            return False

    def _token_graph(self) -> str:
        agora = time.time()
        try:
            cache = json.loads(_kv_get("token_sharepoint_cache") or "{}")
            if cache.get("expires_at", 0) > agora + 120 and cache.get("access_token"):
                return cache["access_token"]
        except Exception:
            pass

        token_direto = _segredo_do_ambiente(self.sp.get("access_token_env"))
        if token_direto:
            return token_direto

        segredo = _segredo_do_ambiente(self.sp.get("client_secret_env"))
        if not segredo:
            raise RuntimeError(
                "Microsoft Graph exige client_secret_env ou access_token_env configurado."
            )
        import urllib.parse as _parse
        corpo = _parse.urlencode({
            "client_id": self.sp["client_id"],
            "client_secret": segredo,
            "scope": "https://graph.microsoft.com/.default",
            "grant_type": "client_credentials",
        }).encode("utf-8")
        _, dados = self._json_request(
            f"https://login.microsoftonline.com/{self.sp['tenant_id']}/oauth2/v2.0/token",
            method="POST",
            data=corpo,
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            timeout=20,
        )
        token = dados.get("access_token")
        if not token:
            raise RuntimeError("Nao foi possivel obter token Microsoft Graph.")
        try:
            _kv_set("token_sharepoint_cache", json.dumps({
                "access_token": token,
                "expires_at": agora + max(300, int(dados.get("expires_in", 3600)) - 120),
            }, ensure_ascii=False))
        except Exception:
            pass
        return token

    def _graph_url_item(self, caminho_remoto: str) -> str:
        import urllib.parse as _parse
        caminho = "/".join(
            _parse.quote(parte, safe="") for parte in caminho_remoto.strip("/").split("/")
        )
        return (
            f"https://graph.microsoft.com/v1.0/sites/{self.sp['site_id']}/"
            f"drives/{self.sp['drive_id']}/root:/{caminho}"
        )

    def _graph_headers(self):
        return {"Authorization": f"Bearer {self._token_graph()}"}

    def _validar_graph(self, remoto: str, tamanho_esperado: int) -> bool:
        status, dados = self._json_request(
            self._graph_url_item(remoto) + "?$select=id,name,size,lastModifiedDateTime",
            headers=self._graph_headers(), timeout=30,
        )
        return status == 200 and int(dados.get("size", -1)) == int(tamanho_esperado)

    def _upload_graph_arquivo(self, origem: Path, remoto: str) -> bool:
        tamanho = origem.stat().st_size
        headers = self._graph_headers()

        def _envio_pequeno():
            dados = origem.read_bytes()
            status, _ = self._json_request(
                self._graph_url_item(remoto) + ":/content",
                method="PUT", data=dados,
                headers={**headers, "Content-Type": "application/octet-stream"},
                timeout=120,
            )
            if status not in (200, 201):
                raise RuntimeError(f"Graph retornou HTTP {status}")

        def _envio_grande():
            _, sessao = self._json_request(
                self._graph_url_item(remoto) + ":/createUploadSession",
                method="POST", data=b"{}",
                headers={**headers, "Content-Type": "application/json"}, timeout=30,
            )
            url_upload = sessao.get("uploadUrl")
            if not url_upload:
                raise RuntimeError("Graph nao retornou uploadUrl.")
            inicio = 0
            with origem.open("rb") as arquivo:
                while inicio < tamanho:
                    bloco = arquivo.read(self._CHUNK_SIZE)
                    fim = inicio + len(bloco) - 1
                    self._repetir(
                        lambda b=bloco, a=inicio, z=fim: self._json_request(
                            url_upload, method="PUT", data=b,
                            headers={
                                "Content-Length": str(len(b)),
                                "Content-Range": f"bytes {a}-{z}/{tamanho}",
                            }, timeout=120,
                        ),
                        "GRAPH CHUNK", tentativas=4,
                    )
                    inicio = fim + 1

        if tamanho <= 4 * 1024 * 1024:
            self._repetir(_envio_pequeno, "GRAPH UPLOAD")
        else:
            self._repetir(_envio_grande, "GRAPH UPLOAD")
        return self._validar_graph(remoto, tamanho)

    def upload_lotes_graph(self, pastas: dict, contexto: dict):
        """Envia pastas em paralelo e confirma cada arquivo por tamanho no Graph."""
        if not getattr(Config, "USAR_GRAPH_SHAREPOINT", False):
            return None
        if not self.graph_habilitado():
            return None
        base = str(self.sp.get("pasta_destino", "")).format(**contexto).strip("/")
        resultados = {nome: True for nome in pastas}

        def _enviar(nome_pasta, pasta):
            arquivos = [p for p in Path(pasta).rglob("*") if p.is_file()]
            for arquivo in arquivos:
                rel = arquivo.relative_to(Path(pasta)).as_posix()
                remoto = "/".join(p for p in (base, nome_pasta, rel) if p)
                if not self._upload_graph_arquivo(arquivo, remoto):
                    return nome_pasta, False
            return nome_pasta, True

        futuros = [
            _thread_pool.submit_io(_enviar, nome, pasta)
            for nome, pasta in pastas.items()
        ]
        for futuro in futuros:
            nome, ok = futuro.result()
            resultados[nome] = ok
            registrar_log(
                f"{'OK' if ok else 'ERRO'} [GRAPH]: {nome}",
                "OK" if ok else "ERRO",
            )
        return resultados

    def sap_odata(self, recurso: str, parametros=None):
        """Consulta OData SAP quando a empresa fornecer endpoint e token."""
        if not self.sap.get("habilitado") or self.sap.get("modo") != "odata":
            return None
        base = str(self.sap.get("odata_base_url", "")).rstrip("/")
        token = _segredo_do_ambiente(self.sap.get("access_token_env"))
        if not base or not token:
            raise RuntimeError("OData SAP requer odata_base_url e access_token_env.")
        import urllib.parse as _parse
        query = _parse.urlencode(parametros or {}, doseq=True)
        url = f"{base}/{recurso.lstrip('/')}" + (f"?{query}" if query else "")
        _, dados = self._json_request(
            url, headers={"Authorization": f"Bearer {token}"}, timeout=45
        )
        return dados

    def sap_rfc(self, funcao: str, **parametros):
        """Executa RFC/BAPI somente quando pyrfc e parametros autorizados existem."""
        if not self.sap.get("habilitado") or self.sap.get("modo") != "rfc":
            return None
        try:
            from pyrfc import Connection
        except ImportError as e:
            raise RuntimeError("Instale pyrfc para usar SAP RFC/BAPI.") from e
        campos = ("ashost", "sysnr", "client", "user_env", "passwd_env")
        if not all(self.sap.get(c) for c in campos):
            raise RuntimeError("Configuracao RFC SAP incompleta.")
        conexao = Connection(
            ashost=self.sap["ashost"], sysnr=str(self.sap["sysnr"]),
            client=str(self.sap["client"]),
            user=_segredo_do_ambiente(self.sap["user_env"]),
            passwd=_segredo_do_ambiente(self.sap["passwd_env"]),
            lang=self.sap.get("lang", "PT"),
        )
        try:
            return conexao.call(funcao, **parametros)
        finally:
            conexao.close()

    def gerar_pdf_documento(self, tipo: str, destino: Path, **contexto):
        """Gera PDF por RFC/BAPI/OData quando o mapeamento oficial existir.

        `config_integracoes.json` pode declarar `sap_oficial.documentos` por
        tipo (pedido, frs, rm), com `recurso` para OData ou `funcao` para RFC,
        `parametros` usando placeholders como `{pedido}` e `campo_pdf` com o
        campo base64 retornado pela API. Retorna `None` quando não há
        mapeamento, preservando o fallback SAP GUI explicitamente.
        """
        mapa = self.sap.get("documentos", {}).get(tipo, {})
        if not mapa or not self.sap.get("habilitado"):
            return None
        parametros = {
            chave: str(valor).format(**contexto)
            for chave, valor in mapa.get("parametros", {}).items()
        }
        if self.sap.get("modo") == "rfc":
            resposta = self.sap_rfc(mapa["funcao"], **parametros)
        elif self.sap.get("modo") == "odata":
            resposta = self.sap_odata(mapa["recurso"], parametros)
        else:
            return None

        campo_pdf = mapa.get("campo_pdf", "pdf_base64")
        valor = resposta
        for parte in str(campo_pdf).split("."):
            valor = valor.get(parte) if isinstance(valor, dict) else None
        if not valor:
            raise RuntimeError(
                f"Backend SAP não retornou '{campo_pdf}' para {tipo}."
            )
        import base64 as _base64_sap
        dados = _base64_sap.b64decode(valor, validate=True)
        destino = Path(destino)
        destino.parent.mkdir(parents=True, exist_ok=True)
        temporario = destino.with_suffix(destino.suffix + ".part")
        with temporario.open("wb") as arquivo:
            arquivo.write(memoryview(dados))
        os.replace(temporario, destino)
        valido, motivo = validar_pdf_gerado(destino)
        if not valido:
            destino.unlink(missing_ok=True)
            raise RuntimeError(f"PDF oficial inválido: {motivo}")
        registrar_log(f"OK [SAP-{self.sap.get('modo', '').upper()}]: {tipo} exportado.", "OK")
        return True

