def salvar_config_contrato(numero: str):
    """Lembra o último número de contrato digitado, para pré-preencher a tela."""
    try:
        dados = carregar_config_sap()
    except Exception:
        dados = {}
    dados["ultimo_contrato"] = numero
    _salvar_config_completo(dados)


def _chave_periodo_contrato(ano, mes) -> str:
    return f"{int(ano)}-{int(mes):02d}"


def carregar_dados_contrato_salvo(numero: str, ano=None, mes=None) -> dict:
    """
    Dados deste contrato. Se ano/mês forem informados, devolve o
    que foi salvo naquele período (linhas, e-mails). dados_sap
    (empresa, ICJ, gerente, fiscais) fica no contrato, não no mês.
    """
    try:
        dados = carregar_config_sap()
    except Exception:
        dados = {}
    bloco = dados.get("contratos", {}).get(str(numero).strip(), {}) or {}
    if not bloco:
        return {}
    saida = {
        "linhas": list(bloco.get("linhas") or []),
        "pedidos_materiais": list(bloco.get("pedidos_materiais") or []),
        "emails_extra": list(bloco.get("emails_extra") or []),
        "emails_cc_extra": list(bloco.get("emails_cc_extra") or []),
        "email_gerente": bloco.get("email_gerente", "") or "",
        "preposta_nome": bloco.get("preposta_nome", "") or "",
        "dados_sap": dict(bloco.get("dados_sap") or {}),
        "url_sharepoint": bloco.get("url_sharepoint", "") or "",
        "ultimo_ano": bloco.get("ultimo_ano"),
        "ultimo_mes": bloco.get("ultimo_mes"),
    }
    periodos = bloco.get("periodos") or {}
    chave = None
    periodo_explicito = ano is not None and mes is not None
    if periodo_explicito:
        chave = _chave_periodo_contrato(ano, mes)
        # Mês/ano novos deste contrato: não reaproveitar Pedido/FRS/RM/NL
        # do período anterior.
        if chave not in periodos:
            saida["linhas"] = []
            saida["pedidos_materiais"] = []
            return saida
    elif bloco.get("ultimo_ano") is not None and bloco.get("ultimo_mes") is not None:
        chave = _chave_periodo_contrato(
            bloco.get("ultimo_ano"), bloco.get("ultimo_mes")
        )
    if chave and chave in periodos:
        per = periodos[chave] or {}
        if "linhas" in per:
            saida["linhas"] = list(per.get("linhas") or [])
        if "pedidos_materiais" in per:
            saida["pedidos_materiais"] = list(per.get("pedidos_materiais") or [])
        else:
            saida["pedidos_materiais"] = []
        saida["emails_extra"] = list(
            per.get("emails_extra") or saida["emails_extra"]
        )
        saida["emails_cc_extra"] = list(
            per.get("emails_cc_extra") or saida["emails_cc_extra"]
        )
        if per.get("email_gerente"):
            saida["email_gerente"] = per.get("email_gerente")
        if per.get("preposta_nome"):
            saida["preposta_nome"] = per.get("preposta_nome")
        if per.get("url_sharepoint"):
            saida["url_sharepoint"] = per.get("url_sharepoint")
        saida["ano"] = per.get("ano", ano)
        saida["mes"] = per.get("mes", mes)
    return saida


def salvar_dados_contrato(
    numero: str, linhas: list, emails_extra: list,
    email_gerente: str = "", dados_sap: dict | None = None,
    ano=None, mes=None, url_sharepoint: str = "",
    emails_cc_extra: list | None = None,
    preposta_nome: str = "",
    pedidos_materiais: list | None = None,
):
    """
    Salva por contrato e, quando houver ano/mês, também por período.
    Assim julho/2026 de um contrato não mistura com agosto/2026.
    """
    try:
        dados = carregar_config_sap()
    except Exception:
        dados = {}
    contratos = dados.setdefault("contratos", {})
    chave_c = str(numero).strip()
    atual = dict(contratos.get(chave_c) or {})
    periodos = dict(atual.get("periodos") or {})
    cc_extra = (
        list(emails_cc_extra)
        if emails_cc_extra is not None
        else list(atual.get("emails_cc_extra") or [])
    )
    nome_prep = str(preposta_nome or "").strip()
    pmat = (
        list(pedidos_materiais)
        if pedidos_materiais is not None
        else list(atual.get("pedidos_materiais") or [])
    )
    registro = {
        "linhas": linhas,
        "pedidos_materiais": pmat,
        "emails_extra": emails_extra,
        "emails_cc_extra": cc_extra,
        "email_gerente": email_gerente,
        "preposta_nome": nome_prep,
        "dados_sap": dados_sap or atual.get("dados_sap") or {},
        "url_sharepoint": url_sharepoint or atual.get("url_sharepoint", ""),
        "periodos": periodos,
    }
    if ano is not None and mes is not None:
        registro["ultimo_ano"] = int(ano)
        registro["ultimo_mes"] = int(mes)
        periodos[_chave_periodo_contrato(ano, mes)] = {
            "linhas": linhas,
            "pedidos_materiais": pmat,
            "emails_extra": emails_extra,
            "emails_cc_extra": cc_extra,
            "email_gerente": email_gerente,
            "preposta_nome": nome_prep,
            "url_sharepoint": url_sharepoint or registro["url_sharepoint"],
            "ano": int(ano),
            "mes": int(mes),
        }
        registro["periodos"] = periodos
    contratos[chave_c] = registro
    _salvar_config_completo(dados)


def _montar_params_execucao(job: dict) -> dict:
    """Monta o dicionário da thread a partir de um job da fila."""
    empresa = job.get("empresa") or ""
    contrato = str(job.get("contrato") or "").strip()
    data_ref = job.get("data_ref")
    if not isinstance(data_ref, datetime):
        data_ref = datetime(
            int(job.get("ano") or datetime.now().year),
            int(job.get("mes") or datetime.now().month),
            1,
        )
    icj = job.get("icj") or ""
    pedidos = list(dict.fromkeys(job.get("pedidos") or []))
    folhas = list(dict.fromkeys(job.get("folhas") or []))
    _rms_unicos = {}
    for _r in (job.get("rms") or []):
        _k = str(_r.get("rm", "")).strip()
        if _k and _k not in _rms_unicos:
            _rms_unicos[_k] = _r
    rms = list(_rms_unicos.values())
    ano_ref = str(data_ref.year)
    mes_num = data_ref.month
    mes_nome = MESES_PT[mes_num]
    mes_pad = f"{mes_num:02}"
    periodo = f"{mes_nome.capitalize()}/{ano_ref}"
    empresa_limpa = empresa
    for c in ['\\', '/', ':', '*', '?', '"', '<', '>', '|']:
        empresa_limpa = empresa_limpa.replace(c, "-")
    empresa_limpa = empresa_limpa[:40].strip()
    pasta_raiz = Path.home() / "Documents" / f"{empresa_limpa} - {contrato}"
    pasta_ped_pai = pasta_raiz / ano_ref / mes_pad / "Pedidos"
    pasta_ped = pasta_ped_pai / "Pedidos Serviços"
    pasta_frs = pasta_raiz / ano_ref / mes_pad / "FRS"
    pasta_rm = pasta_raiz / ano_ref / mes_pad / "RM"
    pasta_esp_pai = pasta_raiz / ano_ref / mes_pad / "Espelho NF"
    pasta_esp = pasta_esp_pai / "Espelho NF Serviços"
    pasta_ped_mat = pasta_ped_pai / "Pedidos Materiais"
    pasta_esp_mat = pasta_esp_pai / "Espelho NF Materiais"
    pedidos_materiais = list(dict.fromkeys(job.get("pedidos_materiais") or []))
    for p in (pasta_ped_pai, pasta_ped, pasta_frs, pasta_rm, pasta_esp_pai, pasta_esp):
        p.mkdir(parents=True, exist_ok=True)
    if pedidos_materiais:
        pasta_ped_mat.mkdir(parents=True, exist_ok=True)
        pasta_esp_mat.mkdir(parents=True, exist_ok=True)
    pasta_mes_med = pasta_raiz / ano_ref / mes_pad
    pasta_cert_local, cert_fora_mes = _resolver_pasta_certidoes_local(
        contrato, ano_ref, mes_num, mes_nome, pasta_mes_med
    )
    cnpj_job = _so_digitos(job.get("cnpj_contratada") or "")
    if len(cnpj_job) != 14:
        cnpj_job = _so_digitos((job.get("dados_sap") or {}).get("cnpj") or "")
    return {
        "empresa": empresa,
        "contrato": contrato,
        "icj": icj,
        "ano_ref": ano_ref,
        "mes_num": mes_num,
        "mes_nome": mes_nome,
        "mes_pad": mes_pad,
        "periodo": periodo,
        "pedidos": pedidos,
        "folhas": folhas,
        "rms": rms,
        "pedidos_materiais": pedidos_materiais,
        "gerentes": list(job.get("gerentes") or []),
        "fiscais": list(job.get("fiscais") or []),
        "emails_para": list(job.get("emails_para") or []),
        "emails_cc_extra": list(job.get("emails_cc_extra") or []),
        "preposta_nome": job.get("preposta_nome") or "",
        "preposta_email": job.get("preposta_email") or "",
        "preposta_tratamento": job.get("preposta_tratamento") or "Prezada",
        "URL_SHAREPOINT": job.get("url_sharepoint") or "",
        "pasta_pedidos_pai_local": str(pasta_ped_pai),
        "pasta_pedidos_local": str(pasta_ped),
        "pasta_frs_local": str(pasta_frs),
        "pasta_rm_local": str(pasta_rm),
        "pasta_espelho_pai_local": str(pasta_esp_pai),
        "pasta_espelho_local": str(pasta_esp),
        "pasta_pedidos_mat_local": str(pasta_ped_mat),
        "pasta_espelho_mat_local": str(pasta_esp_mat),
        "pasta_raiz_local": str(pasta_raiz),
        "so_certidoes": bool(job.get("so_certidoes")),
        "cnpj_contratada": cnpj_job,
        "pasta_certidoes_local": str(pasta_cert_local),
        "certidoes_fora_do_mes": bool(cert_fora_mes),
    }


def _sap_status_bar(session) -> str:
    try:
        return str(session.findById("wnd[0]/sbar/pane[0]").text or "").strip()
    except Exception:
        return ""


def _validar_autorizacao_sap(session, transacao: str) -> None:
    texto = _sap_status_bar(session)
    if "SEM AUTORIZA" in texto.upper():
        usuario = os.environ.get("USERNAME", "")
        raise RuntimeError(
            f"A chave {usuario} não tem autorização para a transação "
            f"{transacao}. Solicite o acesso necessário."
        )


_RE_ITEM_INEXISTENTE_SAP = re.compile(
    r"n[aã]o existe|nao existe|does not exist|n[aã]o encontrado|"
    r"not found|n[aã]o h[aá]|nenhum(a)?\s+(dado|registro|entrada|"
    r"sele[cç][aã]o)|no values|no data|lista vazia|sem dados|"
    r"n[aã]o foi encontrado|documento .* inv[aá]lido|"
    r"can not be set|cannot be set",
    re.I,
)


def _texto_indica_item_inexistente(texto: str) -> bool:
    t = str(texto or "")
    if _RE_ITEM_INEXISTENTE_SAP.search(t):
        return True
    tl = t.lower()
    if "imprimir" in tl and ("n" in tl and "encontrad" in tl):
        return True
    if "pdf" in tl and "encontrad" in tl:
        return True
    if "falhou nos dois fluxos" in tl:
        return True
    return False


def _erro_parece_conexao_sap(erro) -> bool:
    t = str(erro or "").lower()
    return any(
        x in t
        for x in (
            "objeto desconectado",
            "disconnected from its clients",
            "rpc server",
            "servidor rpc",
            "sem_conexao",
            "sem_sessao",
            "acesso negado",
            "call was rejected by callee",
            "chamada foi rejeitada",
        )
    )


def _sap_sessao_viva(session) -> bool:
    if session is None:
        return False
    try:
        session.findById("wnd[0]")
        return True
    except Exception:
        return False


def _sap_fechou_no_meio(erro=None, session=None) -> bool:
    """True só quando o SAP caiu/fechou, não quando falta um campo na tela."""
    if session is not None and not _sap_sessao_viva(session):
        return True
    return _erro_parece_conexao_sap(erro)


def _reconectar_sap_apos_queda(session, erro, contexto="", maximizar=True):
    """
    Se o SAP fechou no meio, pede para reabrir (conectar_sap já mostra
    o diálogo) e devolve a sessão nova. Se o erro for outro, devolve None.
    """
    if not _sap_fechou_no_meio(erro, session):
        return None
    extra = f" de {contexto}" if contexto else ""
    registrar_log(
        f"AVISO [SAP]: fechou no meio{extra} ({erro}) — "
        "pedindo para reabrir e continuar.",
        "AVISO",
    )
    return conectar_sap(maximizar=maximizar)


def executar_sap_retomando(funcao, *args, session=None, contexto="",
                           maximizar=True, **kwargs):
    """
    Roda funcao(session, *args, **kwargs). Se o SAP fechar no meio,
    pede para reabrir e executa de novo do começo da função.
    Devolve (resultado, session).
    maximizar=False: consulta/extração em segundo plano (dashboard fica
    na frente; não traz o SAP Logon/GUI para o primeiro plano).
    """
    sess = session
    while True:
        if sess is None or not _sap_sessao_viva(sess):
            sess = conectar_sap(maximizar=maximizar)
        try:
            return funcao(sess, *args, **kwargs), sess
        except Exception as e:
            nova = _reconectar_sap_apos_queda(
                sess, e, contexto, maximizar=maximizar
            )
            if nova is not None:
                sess = nova
                continue
            raise


def _fechar_modais_sap(session, ate=2):
    for wnd_idx in range(int(ate or 2), 0, -1):
        try:
            session.findById(f"wnd[{wnd_idx}]").sendVKey(12)
        except Exception:
            pass


def _sap_indica_item_inexistente(session, erro=None) -> bool:
    if _texto_indica_item_inexistente(str(erro or "")):
        return True
    barra = _sap_status_bar(session)
    if _texto_indica_item_inexistente(barra):
        return True
    try:
        w = session.findById("wnd[1]")
        txt = str(getattr(w, "text", "") or "")
        if _texto_indica_item_inexistente(txt):
            return True
    except Exception:
        pass
    return False


def _trocar_numero_lista(lista, antigo, novo):
    if not lista:
        return
    antigo_s = str(antigo)
    novo_s = str(novo)
    for i, v in enumerate(lista):
        if str(v) == antigo_s:
            lista[i] = novo_s
            return


def _so_digitos(texto: str) -> str:
    return re.sub(r"\D", "", str(texto or ""))


def _digitos_esperados_documento(tipo: str) -> int:
    t = str(tipo or "").strip().lower()
    mapa = {
        "pedido": int(getattr(Config, "DIGITOS_PEDIDO", 10) or 0),
        "frs": int(getattr(Config, "DIGITOS_FRS", 10) or 0),
        "rm": int(getattr(Config, "DIGITOS_RM", 0) or 0),
        "nl": int(getattr(Config, "DIGITOS_NL", 0) or 0),
    }
    return mapa.get(t, 0)


def _msg_digitos_documento(tipo: str, valor: str) -> str:
    """Vazio se estiver ok. RM/NL com 0 no Config = sem limite de tamanho."""
    esperado = _digitos_esperados_documento(tipo)
    if not esperado:
        return ""
    qtd = len(_so_digitos(valor))
    if qtd == esperado:
        return ""
    return (
        f"{tipo} incorreto: precisa ter exatamente {esperado} dígitos "
        f"(você digitou {qtd}: {valor}). "
        f"Verifique o {tipo} e corrija."
    )


def _normalizar_numero_documento(tipo: str, valor: str) -> str:
    esperado = _digitos_esperados_documento(tipo)
    bruto = str(valor or "").strip()
    if esperado:
        return _so_digitos(bruto)
    return bruto


def _pedir_correcao_item(tipo: str, valor: str) -> str:
    """Pede o número certo do Pedido/FRS/RM. Vazio = cancelou."""
    if Config.MODO_SILENCIOSO:
        return ""
    tipo_l = str(tipo or "item")
    valor_s = str(valor or "").strip()
    n_dig = _digitos_esperados_documento(tipo_l)
    extra = ""
    if n_dig:
        extra = f"\n\nEste {tipo_l} precisa ter exatamente {n_dig} dígitos."
    msg = (
        f"O {tipo_l} {valor_s} não foi encontrado no SAP.\n\n"
        "Não há o que imprimir, ou o número não passou na verificação "
        "inicial (documento inexistente / lista vazia).\n\n"
        f"Confira esse {tipo_l} e digite o valor correto."
        + extra
    )
    try:
        for _ in range(8):
            novo = _gui_bridge.pedir_texto(
                f"{tipo_l} inválido — corrija",
                msg,
                (
                    f"{n_dig} dígitos"
                    if n_dig
                    else f"Número correto do {tipo_l}"
                ),
                valor_s,
            )
            if not novo:
                return ""
            err = _msg_digitos_documento(tipo_l, novo)
            if not err:
                return _normalizar_numero_documento(tipo_l, novo)
            valor_s = novo
            msg = err + extra + "\n\nDigite de novo o valor correto."
    except Exception:
        return ""
    return ""


def _deve_pedir_correcao_item(erro, session, pdf_nao_gerado, ultima_tentativa) -> bool:
    if Config.MODO_SILENCIOSO:
        return False
    if _erro_parece_conexao_sap(erro):
        return False
    if _sap_indica_item_inexistente(session, erro):
        return True
    t = str(erro or "").lower()
    if "imprimir" in t or ("pdf" in t and "encontrad" in t):
        return True
    if "can not be set" in t or "cannot be set" in t or "property" in t:
        return True
    if ultima_tentativa:
        return True
    return False


def _tentar_corrigir_documento(
    tipo,
    valor,
    session,
    erro,
    pdf_nao_gerado,
    tentativa,
    max_tent,
    listas_str=None,
    item_dict=None,
    chave="rm",
):
    """
    None = não perguntou (continua tentando).
    ''   = perguntou e a pessoa cancelou ou repetiu o mesmo número.
    str  = número novo para repetir a etapa.
    """
    ultima = tentativa >= max_tent
    if not _deve_pedir_correcao_item(erro, session, pdf_nao_gerado, ultima):
        return None
    try:
        _fechar_modais_sap(session)
    except Exception:
        pass
    novo = str(_pedir_correcao_item(tipo, valor) or "").strip()
    if not novo or novo == str(valor or "").strip():
        return ""
    for lst in listas_str or []:
        _trocar_numero_lista(lst, valor, novo)
    if item_dict is not None:
        item_dict[chave] = novo
    registrar_log(
        f"INFO [{str(tipo).upper()}]: valor corrigido {valor} → {novo}",
        "INFO",
    )
    return novo


def _sap_try_get_text(session, caminhos: list) -> str:
    for caminho in caminhos:
        try:
            return str(session.findById(caminho).text or "").strip()
        except Exception:
            continue
    return ""


def _sap_try_focus_get_text(session, caminhos: list) -> str:
    for caminho in caminhos:
        try:
            campo = session.findById(caminho)
            try:
                campo.setFocus()
                campo.caretPosition = len(str(campo.text or ""))
            except Exception:
                pass
            valor = str(campo.text or "").strip()
            if valor:
                _sap_devolver_foco_app()
                return valor
        except Exception:
            continue
    return ""


def _sap_try_set_text(session, caminhos: list, valor: str) -> bool:
    for caminho in caminhos:
        try:
            session.findById(caminho).text = valor
            return True
        except Exception:
            continue
    return False


def _sap_status_liberacao(session) -> str:
    """
    Lê o status real de liberação do contrato (Liberado/Bloqueado), no mesmo
    padrão usado na automação de medição: aperta o botão de status de
    liberação (btn[42]) na tela do contrato já aberta na ME33K e lê o código
    em wnd[1]/usr/txtT16FK-FRGKX. "L" = Liberado; qualquer outro código =
    Bloqueado.
    """
    try:
        if not _sap_try_press(session, _sap_ids("status_liberacao_btn")):
            return ""
        codigo = _sap_try_get_text(session, _sap_ids("status_liberacao_cod"))
        try:
            session.findById("wnd[1]/tbar[0]/btn[12]").press()
        except Exception:
            pass
        if codigo.upper() == "L":
            return "Liberado"
        return "Bloqueado"
    except Exception:
        return ""




