def consultar_dados_contrato_sap(session, numero_sap: str) -> dict:
    """
    Busca no SAP (ME33K) os dados do contrato usados pelo Teste4:
    empresa (contratada), ICJ, gerente, fiscais e status de liberação.

    IDs de tela confirmados no roteiro real de consulta por ME33K
    (mesma rotina usada em consultar_dados_principais_me33k da Etapa 1).
    """
    dados = {"empresa": "", "icj": "", "gerente": "", "fiscais": [], "status_contrato": "", "cnpj": ""}

    _okcd = _sap_try_obj(session, _sap_ids("okcd"))
    if _okcd is None:
        if not _sap_sessao_viva(session):
            raise Exception("sem_sessao")
        raise Exception("SAP: campo de transação (okcd) não encontrado.")
    _okcd.text = "/nme33k"
    session.findById("wnd[0]").sendVKey(0)

    if not _sap_try_set_text(session, _sap_ids("contrato_numero"), numero_sap):
        if not _sap_sessao_viva(session):
            raise Exception("sem_sessao")
        raise Exception("SAP: campo do número do contrato não encontrado.")
    session.findById("wnd[0]").sendVKey(0)

    dados["empresa"] = _sap_try_get_text(session, _sap_ids("empresa"))

    codigo_forn = (
        _sap_try_get_text(
            session,
            [
                "wnd[0]/usr/ctxtEKKO-LIFNR",
                "wnd[0]/usr/txtEKKO-LIFNR",
            ],
        )
        or ""
    ).strip()
    if codigo_forn:
        try:
            cnpj_forn, _cidade_forn = consultar_cnpj_fornecedor_xk03(
                session, codigo_forn
            )
            if cnpj_forn:
                dados["cnpj"] = cnpj_forn
                registrar_log(
                    f"SAP: CNPJ fornecedor {codigo_forn} → {cnpj_forn}",
                    "INFO",
                )
        except Exception as e_cnpj_forn:
            if _sap_fechou_no_meio(e_cnpj_forn, session):
                raise
            registrar_log(
                f"AVISO [SAP CONTRATO]: CNPJ fornecedor não lido: {e_cnpj_forn}",
                "AVISO",
            )

    try:
        tabela_itens = _sap_try_obj(session, _sap_ids("tabela_itens"))
        if tabela_itens is not None:
            tabela_itens.getAbsoluteRow(0).selected = True
        item0 = _sap_try_obj(session, _sap_ids("item_linha0"))
        if item0 is not None:
            item0.setFocus()
        _sap_try_press(session, _sap_ids("btn_detalhe_item"))

        dados["empresa"] = _sap_try_get_text(session, _sap_ids("empresa")) or dados["empresa"]

        if not _sap_try_press(session, _sap_ids("info_adicionais")):
            registrar_log(
                "AVISO [SAP CONTRATO]: botão Informações Adicionais "
                "não encontrado — conferir ui_aliases em config.json.",
                "AVISO",
            )

        gerente_chave = _sap_try_get_text(session, _sap_ids("gerente_chave"))
        gerente_nome  = _sap_try_get_text(session, _sap_ids("gerente_nome"))
        # txtYS_NOME_GERENTE: só o nome (sem BSJD). Fiscal usa a mesma limpeza.
        if gerente_nome:
            dados["gerente"] = (
                _normalizar_nome_pessoa_sap(gerente_nome)
                or gerente_nome.strip()
            )
        else:
            dados["gerente"] = _normalizar_nome_pessoa_sap(gerente_chave) or (
                gerente_chave or ""
            ).strip()

        dados["icj"] = _sap_try_focus_get_text(session, _sap_ids("icj"))

        fiscais: list[str] = []
        tabela = None
        tabela_fiscais = ""
        for _cid in _sap_ids("tabela_fiscais"):
            tabela = _sap_try_obj(session, [_cid])
            if tabela is not None:
                tabela_fiscais = _cid
                break
        try:
            if tabela is None:
                raise Exception("grade de fiscais não encontrada")
            visiveis = int(getattr(tabela, "VisibleRowCount", 3) or 3)
            max_pos = int(getattr(tabela.verticalScrollbar, "Maximum", 0) or 0)
            passo = max(1, visiveis)
            posicoes = list(range(0, max_pos + 1, passo)) if max_pos else [0]
            if max_pos and posicoes[-1] != max_pos:
                posicoes.append(max_pos)
            vistos = set()
            nomes_vistos = set()
            for pos in posicoes:
                try:
                    tabela.verticalScrollbar.Position = pos
                    time.sleep(0.2)
                except Exception:
                    pass
                for linha in range(visiveis):
                    valor = _sap_try_get_text(
                        session,
                        [
                            f"{tabela_fiscais}/txtTI_FISCAIS-TEXT[1,{linha}]",
                            f"{tabela_fiscais}/txtTI_FISCAIS-TEXT[0,{linha}]",
                            f"{tabela_fiscais}/txtTI_FISCAIS-TEXT[2,{linha}]",
                        ],
                    )
                    if not valor or not valor.replace("_", "").strip():
                        continue
                    chave = re.sub(r"\s+", " ", valor).strip().upper()
                    if chave in (
                        "FISCAL", "FISCAIS", "NOME", "NOME DO FISCAL",
                    ):
                        continue
                    nome = _apenas_nome_gerente(chave).upper()
                    if chave in vistos or nome in nomes_vistos:
                        continue
                    ja = False
                    for n in nomes_vistos:
                        if nome and (nome in n or n in nome):
                            ja = True
                            break
                    if ja:
                        continue
                    # Mesma limpeza do gerente (espaços/caixa/chave SAP)
                    limpo = _normalizar_nome_pessoa_sap(valor) or valor.strip()
                    fiscais.append(limpo)
                    vistos.add(chave)
                    if nome:
                        nomes_vistos.add(nome)
        except Exception as e_fiscais:
            if _sap_fechou_no_meio(e_fiscais, session):
                raise
            registrar_log(f"AVISO [SAP CONTRATO]: fiscais nao lidos: {e_fiscais}", "AVISO")
        dados["fiscais"] = fiscais

        session.findById("wnd[0]/tbar[0]/btn[3]").press()

    except Exception as e_info:
        if _sap_fechou_no_meio(e_info, session):
            raise
        registrar_log(f"AVISO [SAP CONTRATO]: informacoes adicionais nao lidas: {e_info}", "AVISO")

    # Lê o status de liberação por último: reentra na tela inicial da
    # ME33K com o mesmo contrato antes de chamar o botão de status
    # (btn[42]), porque esse botão muda a tela e, se fosse chamado antes,
    # atrapalhava a leitura de Gerente/ICJ/Fiscais feita acima.
    try:
        _okcd2 = _sap_try_obj(session, _sap_ids("okcd"))
        if _okcd2 is not None:
            _okcd2.text = "/nme33k"
            session.findById("wnd[0]").sendVKey(0)
        _sap_try_set_text(session, _sap_ids("contrato_numero"), numero_sap)
        session.findById("wnd[0]").sendVKey(0)
        dados["status_contrato"] = _sap_status_liberacao(session)
    except Exception as e_status:
        if _sap_fechou_no_meio(e_status, session):
            raise
        registrar_log(f"AVISO [SAP CONTRATO]: status de liberacao nao lido: {e_status}", "AVISO")

    finalizar_sap(session)
    _sap_devolver_foco_app(forcar_frente=True)
    return dados

