def selecionar_planilha():
    from PySide6.QtWidgets import QFileDialog, QApplication
    # Garante que há uma QApplication ativa antes de abrir o diálogo
    app = QApplication.instance() or _qapp
    arquivo, _ = QFileDialog.getOpenFileName(
        None,
        "Selecione a planilha",
        "",
        "Excel (*.xlsx *.xlsm)"
    )
    return arquivo


def ler_planilha(planilha):
    wb = load_workbook(planilha, data_only=True, read_only=True)
    try:
        ws       = wb["SERVIÇOS"]
        empresa  = str(ws.cell(row=5, column=3).value).strip()
        contrato = str(ws.cell(row=4, column=3).value).strip()
        data_ref = ws.cell(row=7, column=3).value
        icj_v    = ws.cell(row=3, column=3).value
        icj      = str(icj_v).strip() if icj_v else ""

        pedidos = []
        coluna  = 16
        while True:
            valor = ws.cell(row=9, column=coluna).value
            if valor is None:
                break
            valor = str(valor).strip()
            if valor != "":
                pedidos.append(valor)
            coluna += 1

        folhas = []
        coluna = 16
        while True:
            valor = ws.cell(row=10, column=coluna).value
            if valor is None:
                break
            valor = str(valor).strip()
            if valor != "":
                folhas.append(valor)
            coluna += 1

        rms    = []
        coluna = 16
        while True:
            rm_valor = ws.cell(row=11, column=coluna).value
            if rm_valor is None:
                break
            rm_str = str(rm_valor).strip()
            if rm_str != "":
                nl_valor     = ws.cell(row=12, column=coluna).value
                nl_str       = str(nl_valor).strip() if nl_valor else ""
                centro_valor = ws.cell(row=8, column=coluna).value
                centro_str   = str(centro_valor).strip() if centro_valor else ""
                rms.append({
                    "rm":     rm_str,
                    "nl":     nl_str,
                    "centro": centro_str
                })
            coluna += 1

        gerentes = []
        fiscais  = []
        if "dados" in wb.sheetnames:
            wd    = wb["dados"]
            linha = 3
            while True:
                gerente_val = wd.cell(row=linha, column=1).value
                fiscal_val  = wd.cell(row=linha, column=2).value
                if gerente_val is None and fiscal_val is None:
                    break
                if gerente_val:
                    gerentes.append(str(gerente_val).strip())
                if fiscal_val:
                    _fl = _normalizar_nome_pessoa_sap(str(fiscal_val)) or str(
                        fiscal_val
                    ).strip()
                    if _fl:
                        fiscais.append(_fl)
                linha += 1

        # return sempre executado, independente da aba "dados" existir
        return (
            empresa, contrato, data_ref,
            icj, pedidos, folhas, rms,
            gerentes, fiscais
        )

    finally:
        try:
            wb.close()
        except Exception:
            pass



def _periodo_label_job(job: dict) -> str:
    """Mês/ano para tela (evita 'Julho/2026/2026')."""
    periodo = str((job or {}).get("periodo") or "").strip()
    if periodo:
        return periodo
    mes = str((job or {}).get("mes_nome") or "").strip()
    ano = str(
        (job or {}).get("ano_ref")
        or (job or {}).get("ano")
        or ""
    ).strip()
    if mes and ano:
        compacto = mes.replace(" ", "")
        if compacto.endswith("/" + ano) or compacto.endswith(ano):
            return mes
        return f"{mes}/{ano}"
    return mes or "—"


