    def pedir_erro_critico(
        self, mensagem: str, detalhes: str = "",
        pasta_msg: str = "", log_file: str = ""
    ):
        """
        Mostra o diálogo de erro. Se já estiver na thread da GUI,
        chama direto (emit+wait na GUI trava = 'não está respondendo').
        """
        self._acao_erro = "dashboard"
        _app = QApplication.instance()
        _na_gui = (
            _app is not None
            and QThread.currentThread() == _app.thread()
        )
        if _na_gui:
            self._exibir_erro_critico(
                mensagem, detalhes, pasta_msg, log_file or LOG_FILE
            )
            return self._acao_erro
        self._evento_erro.clear()
        self._pedir_erro_critico.emit(
            mensagem, detalhes, pasta_msg, log_file or LOG_FILE
        )
        self._evento_erro.wait(timeout=300)
        return getattr(self, "_acao_erro", "dashboard")

