# Instância global — criada na thread principal
_gui_bridge = _GuiBridge()


def _excepthook_global(tipo, valor, tb):
    """Erros não tratados: log + e-mail + dashboard, sem travar o app."""
    texto = str(valor or "")
    if "WPARAM" in texto and "NoneType" in texto:
        try:
            registrar_log(
                "AVISO [MONITOR]: ignorado erro interno do hook "
                f"({texto}). A automação já tinha concluído.",
                "AVISO",
            )
        except Exception:
            pass
        return
    try:
        traceback.print_exception(tipo, valor, tb)
    except Exception:
        pass
    try:
        encerrar_com_erro(
            f"Erro não tratado: {valor}",
            valor,
        )
    except Exception:
        pass


def _thread_excepthook(args):
    try:
        _excepthook_global(args.exc_type, args.exc_value, args.exc_traceback)
    except Exception:
        pass


sys.excepthook = _excepthook_global
try:
    threading.excepthook = _thread_excepthook
except Exception:
    pass

# ── Estrutura ctypes para flash da barra de tarefas do Windows
# Declarada no nível do módulo para não ser recriada a cada conclusão
import ctypes as _ctypes_winfo

class _FLASHWINFO(_ctypes_winfo.Structure):
    """
    Estrutura Windows FLASHWINFO para FlashWindowEx.
    FLASHW_ALL (dwFlags=3): pisca barra de tarefas e ícone da janela.
    """
    _fields_ = [
        ("cbSize",    _ctypes_winfo.c_uint),
        ("hwnd",      _ctypes_winfo.c_void_p),
        ("dwFlags",   _ctypes_winfo.c_uint),
        ("uCount",    _ctypes_winfo.c_uint),
        ("dwTimeout", _ctypes_winfo.c_uint),
    ]


# =====================================================
# SAP — CONEXÃO (CORRIGIDA)
# =====================================================

def conectar_sap(maximizar=True):
    monitor.pausar()
    while True:
        try:
            SapGuiAuto  = win32com.client.GetObject("SAPGUI")
            application = SapGuiAuto.GetScriptingEngine
            if application.Children.Count == 0:
                raise Exception("sem_conexao")
            connection = application.Children(0)
            if connection.Children.Count == 0:
                raise Exception("sem_sessao")
            session = connection.Children(0)
            try:
                _ = session.findById("wnd[0]").text
            except Exception:
                resposta = _dialogo_retry_cancel(
                    "⚠ SAP sem suporte a script",
                    "⚠ SAP aberto mas scripting NÃO está funcionando.\n\n"
                    "Feche e logue em:\n"
                    "'02 PEP - S/4HANA Produção (SAP SCRIPT)'\n\n"
                    "Clique em Repetir quando logado."
                )
                if not resposta:
                    _encerrar_processo(1)
                continue

            try:
                info      = session.Info
                descricao = str(connection.Description).upper()
                print(
                    f"\nSAP Info:"
                    f"\n  Sistema   : {info.SystemName}"
                    f"\n  Client    : {info.Client}"
                    f"\n  Descrição : {descricao}"
                )

                # CORRIGIDO: Lógica ambiente_correto
                ambiente_correto = ("SCRIPT" in descricao and "02" in descricao)
                if not ambiente_correto:
                    resposta = _dialogo_retry_cancel(
                        "⚠ Ambiente SAP incorreto",
                        "⚠ Ambiente ERRADO!\n\n"
                        f"Atual: '{connection.Description}'\n\n"
                        "Precisa: '02 PEP - S/4HANA Produção (SAP SCRIPT)'\n\n"
                        "1. Feche a sessão atual\n"
                        "2. Abra o SAP Logon 800\n"
                        "3. Logue em '02 PEP'\n\n"
                        "Clique em Repetir quando logado."
                    )
                    if not resposta:
                        _encerrar_processo(1)
                    continue

            except AttributeError:
                try:
                    session.findById("wnd[0]/tbar[0]/okcd").text = ""
                except Exception:
                    resposta = _dialogo_retry_cancel(
                        "⚠ SAP sem suporte a script",
                        "⚠ Não foi possível executar comandos no SAP.\n\n"
                        "Verifique se está logado em:\n"
                        "'02 PEP - S/4HANA Produção (SAP SCRIPT)'\n\n"
                        "Clique em Repetir quando logado."
                    )
                    if not resposta:
                        _encerrar_processo(1)
                    continue

            registrar_log(
                f"OK: SAP conectado — {connection.Description}"
            )
            if maximizar:
                _sap_focar_para_etapa(session)
            return session

        except Exception as e:
            msg_erro = str(e)
            if msg_erro == "sem_conexao":
                titulo  = "SAP sem conexão"
                detalhe = "SAP aberto mas sem conexão ativa.\n\n"
            elif msg_erro == "sem_sessao":
                titulo  = "SAP sem sessão"
                detalhe = "SAP conectado mas sem sessão ativa.\n\n"
            else:
                titulo  = "SAP não encontrado"
                detalhe = "O SAP não está aberto.\n\n"
            resposta = _dialogo_retry_cancel(
                titulo,
                f"⚠ {detalhe}"
                "1. Abra o SAP Logon 800\n"
                "2. Logue em:\n"
                "   '02 PEP - S/4HANA Produção (SAP SCRIPT)'\n\n"
                "Clique em Repetir quando logado."
            )
            if not resposta:
                _encerrar_processo(1)
# =====================================================
# SAP — PEDIDOS
# =====================================================

def abrir_pedido(session, pedido):
    _sap_focar_janela(session)
    session.findById("wnd[0]/tbar[0]/okcd").text = "/nme23n"
    session.findById("wnd[0]").sendVKey(0)
    session.findById("wnd[0]").sendVKey(0)

    # Aguarda tela me23n carregar antes de clicar no botão
    aguardar_campo_sap(session, "wnd[0]/tbar[1]/btn[17]", timeout=0.1)
    session.findById("wnd[0]/tbar[1]/btn[17]").press()

    # Aguarda janela modal de seleção de pedido abrir
    aguardar_janela_sap(session, indice_janela=1, timeout=0.1)

    session.findById(
        "wnd[1]/usr/subSUB0:SAPLMEGUI:0003/ctxtMEPO_SELECT-EBELN"
    ).text = pedido
    session.findById(
        "wnd[1]/usr/subSUB0:SAPLMEGUI:0003/ctxtMEPO_SELECT-EBELN"
    ).caretPosition = len(pedido)
    session.findById("wnd[1]").sendVKey(0)

    # Alguns pedidos (ex.: vinculados a Medição Contratual Simplificada)
    # abrem um popup extra de alerta ("MS - ALERTA Pedido ...") por cima
    # da tela do pedido. Se não for fechado, o botão de imprimir some e a
    # janela "Imprimir" nunca abre. Enter (sendVKey(0)) equivale a clicar
    # no ✔ verde do popup — fecha até 3 popups extras, se houver.
    for _ in range(3):
        try:
            session.findById("wnd[1]")
        except Exception:
            break
        try:
            session.findById("wnd[1]").sendVKey(0)
            time.sleep(0.3)
        except Exception:
            break

    barra = _sap_status_bar(session)
    if _texto_indica_item_inexistente(barra):
        raise Exception(
            f"Pedido {pedido} não encontrado no SAP ({barra})."
        )
    try:
        session.findById(
            "wnd[1]/usr/subSUB0:SAPLMEGUI:0003/ctxtMEPO_SELECT-EBELN"
        )
        raise Exception(
            f"Pedido {pedido} não encontrado no SAP "
            "(a tela de seleção do pedido ainda está aberta)."
        )
    except Exception as e_sel:
        if "não encontrado no SAP" in str(e_sel):
            raise

def imprimir_pedido(session):
    session.findById("wnd[0]/tbar[1]/btn[20]").press()
    session.findById("wnd[0]/mbar/menu[0]/menu[0]").Select()

