# SAP — FRS (ML83)
# =====================================================
# Controle de reutilização da tela ML83 entre folhas FRS
_frs_tela_pronta: bool = False
_frs_tela_lock         = threading.Lock()


# =====================================================
# PIPELINE ENGINE — SAP imprime enquanto disco salva
# =====================================================

class _PDFPipelineEngine:
    """
    Sobrepõe o tempo de espera do Windows (salvar PDF)
    com o próximo comando SAP.

    Uso:
        engine = _PDFPipelineEngine()
        engine.iniciar()
        ...
        abrir_rm(session, rm, centro, contrato)
        selecionar_impressora()
        engine.enfileirar(rm, arquivo_path)   # não espera!
        # SAP já navega para o próximo RM aqui
        ...
        resultados = engine.finalizar()       # espera tudo
    """

    def __init__(self):
        self._fila      = __import__('queue').Queue(maxsize=4)
        self._resultados: dict = {}
        self._lock              = threading.Lock()
        self._worker            = None
        self._ativo             = False

    def iniciar(self):
        self._ativo  = True
        self._worker = threading.Thread(
            target=self._loop_salvar,
            daemon=True,
            name="PDFPipelineWorker"
        )
        self._worker.start()

    def _loop_salvar(self):
        """Worker: consome fila e salva PDFs."""
        # O sentinela controla o encerramento. Não condicione o loop a
        # `_ativo`: `finalizar()` pode ser chamado enquanto ainda há itens
        # pendentes e interromperia o salvamento antes de consumir a fila.
        while True:
            try:
                item = self._fila.get(timeout=30)
            except __import__('queue').Empty:
                continue

            if item is None:   # sentinel de encerramento
                self._fila.task_done()
                break

            doc_id, arquivo = item
            try:
                ok = salvar_pdf(arquivo)
                with self._lock:
                    self._resultados[doc_id] = (ok, str(arquivo))
                if ok:
                    registrar_log(
                        f"OK [PIPELINE]: {arquivo.name} salvo.",
                        "OK"
                    )
                else:
                    registrar_log(
                        f"ERRO [PIPELINE]: {arquivo.name} "
                        f"não confirmado.",
                        "ERRO"
                    )
            except Exception as e:
                with self._lock:
                    self._resultados[doc_id] = (False, "")
                registrar_log(
                    f"ERRO [PIPELINE]: {doc_id} — {e}",
                    "ERRO"
                )
            finally:
                self._fila.task_done()

    def enfileirar(self, doc_id: str, arquivo: Path, timeout: float = 45.0):
        """
        Enfileira o salvamento do PDF.
        Retorna imediatamente — não bloqueia o SAP.
        """
        try:
            # Backpressure explícito: impede que a automação SAP abra mais
            # diálogos do que o Windows consegue materializar em PDF.
            self._fila.put((doc_id, arquivo), timeout=timeout)
        except __import__('queue').Full as erro:
            raise TimeoutError(
                f"Pipeline de PDF saturado ao enfileirar {doc_id}."
            ) from erro

    def finalizar(self, timeout: float = 120.0) -> dict:
        """
        Aguarda todos os PDFs da fila serem salvos.
        Retorna {doc_id: (ok: bool, caminho: str)}.
        """
        self._fila.put(None, timeout=timeout)   # sentinel após os pendentes
        self._ativo = False
        if self._worker:
            self._worker.join(timeout=timeout)
        with self._lock:
            return dict(self._resultados)


def abrir_frs(session, folha):
    print(f"\nProcessando FRS: {folha}")
    e_a = None
