        # Aguarda ML83 carregar — o reset disparou /nml83 sem aguardar
        aguardar_campo_sap(session, "wnd[0]/usr/ctxtS_LBLNI-LOW", timeout=0.1)
        session.findById("wnd[0]/usr/ctxtS_LBLNI-LOW").text = folha
        session.findById("wnd[0]/usr/ctxtS_LBLNI-LOW").caretPosition = len(folha)
        session.findById("wnd[0]").sendVKey(0)
        aguardar_campo_sap(session, "wnd[0]/usr/ctxtS_EBELN-LOW", timeout=0.1)
        session.findById("wnd[0]/usr/ctxtS_EBELN-LOW").setFocus()
        session.findById("wnd[0]/usr/ctxtS_EBELN-LOW").caretPosition = 0
        session.findById("wnd[0]/usr/btn%_S_EBELN_%_APP_%-VALU_PUSH").press()
