        session.findById("wnd[1]/tbar[0]/btn[16]").press()
        session.findById("wnd[1]/tbar[0]/btn[8]").press()
        aguardar_campo_sap(session, "wnd[0]/usr/txtP_KAPPL", timeout=0.1)
        session.findById("wnd[0]/usr/txtP_KAPPL").text = "es"
        session.findById("wnd[0]/usr/txtP_KAPPL").setFocus()
        session.findById("wnd[0]/usr/txtP_KAPPL").caretPosition = 2
        session.findById("wnd[0]").sendVKey(0)
        aguardar_campo_sap(session, "wnd[0]/usr/ctxtP_VSTAT", timeout=0.1)
        session.findById("wnd[0]/usr/ctxtP_VSTAT").text = "1"
        session.findById("wnd[0]/usr/ctxtP_VSTAT").setFocus()
        session.findById("wnd[0]/usr/ctxtP_VSTAT").caretPosition = 1
        session.findById("wnd[0]").sendVKey(0)
        aguardar_campo_sap(session, "wnd[0]/tbar[1]/btn[8]", timeout=0.1)
        session.findById("wnd[0]/tbar[1]/btn[8]").press()
        aguardar_campo_sap(session, "wnd[0]/usr/chk[1,6]", timeout=0.2)
        session.findById("wnd[0]/usr/chk[1,6]").selected = True
        session.findById("wnd[0]/tbar[1]/btn[17]").press()
