        session.findById("wnd[0]/mbar/menu[0]/menu[0]").select()
        aguardar_campo_sap(session, "wnd[0]/tbar[1]/btn[17]", timeout=0.1)

        print(f"FRS {folha} impressa — Fluxo B.")
