def abrir_rm(session, rm, centro, contrato):
    print(
        f"\nProcessando RM: {rm} | "
        f"Centro: {centro} | Contrato: {contrato}"
    )
    session.findById("wnd[0]").maximize
    session.findById("wnd[0]/tbar[0]/okcd").text = "/NYSMEDICAO"
    session.findById("wnd[0]").sendVKey(0)
    aguardar_campo_sap(
        session,
        "wnd[0]/usr/ctxtEKPO-WERKS",
        timeout=0.1
    )

    session.findById("wnd[0]/usr/ctxtEKPO-KONNR").text = contrato
    if str(centro or "").strip():
        session.findById("wnd[0]/usr/ctxtEKPO-WERKS").text = centro
    session.findById("wnd[0]/usr/ctxtYSMEDICAO_FRS-MEDICAO").text = rm
    session.findById("wnd[0]/usr/cmbWC_PARCEIRO").setFocus()
    session.findById("wnd[0]").sendVKey(0)
    barra_rm = _sap_status_bar(session)
    if _texto_indica_item_inexistente(barra_rm):
        raise Exception(
            f"RM {rm} não encontrado no SAP ({barra_rm})."
        )
    aguardar_campo_sap(
        session,
        "wnd[0]/usr/cmbWC_PARCEIRO",
        timeout=0.1
    )
    try:
        combo          = session.findById("wnd[0]/usr/cmbWC_PARCEIRO")
        primeira_opcao = combo.entries(0).key
        print(f"Fornecedor selecionado: {primeira_opcao}")
        combo.key = primeira_opcao
    except Exception as e_combo:
        print(
            f"entries() falhou ({e_combo}), "
            "usando setFocus + sendVKey..."
        )
        session.findById("wnd[0]/usr/cmbWC_PARCEIRO").setFocus()
        session.findById("wnd[0]").sendVKey(0)
        aguardar_campo_sap(session, "wnd[0]/usr/cmbWC_PARCEIRO", timeout=0.1)
    session.findById("wnd[0]/usr/cmbWC_PARCEIRO").setFocus()
    session.findById("wnd[0]").sendVKey(0)
    aguardar_campo_sap(session, "wnd[0]/tbar[1]/btn[16]", timeout=0.1)
    session.findById("wnd[0]/tbar[1]/btn[16]").press()

    aguardar_campo_sap(
        session,
        "wnd[0]/tbar[1]/btn[5]",
        timeout=0.1
    )

    session.findById("wnd[0]/tbar[1]/btn[5]").press()

    # Substituiu time.sleep(1.5) — aguarda relatório renderizar
    aguardar_campo_sap(
        session,
        "wnd[0]/tbar[1]/btn[5]",  # mesmo botão: confirma que a tela estabilizou
        timeout=0.1
    )

    print(f"RM {rm} processado.")


# =====================================================
# SAP — IMPRESSORA (ESPERA DINÂMICA)
# =====================================================

def _titulos_janelas_imprimir():
    return list(UI_ALIASES.get("janelas_imprimir") or ["Imprimir", "Print"])


def _titulos_janelas_salvar_pdf():
    return list(
        UI_ALIASES.get("janelas_salvar_pdf")
        or [
            "Salvar Saída de Impressão como",
            "Salvar como",
            "Save As",
            "Save Print Output As",
        ]
    )


def _hwnds_dialogos_pdf() -> set:
    vistos = set()
    for w in (
        _janelas_win32_titulos(_titulos_janelas_imprimir())
        + _janelas_win32_titulos(_titulos_janelas_salvar_pdf())
    ):
        h = int(getattr(w, "handle", 0) or 0)
        if h:
            vistos.add(h)
    return vistos


def _janela_ainda_existe(hwnd) -> bool:
    if not hwnd:
        return False
    try:
        import win32gui
        return bool(win32gui.IsWindow(int(hwnd)))
    except Exception:
        return int(hwnd) in _hwnds_dialogos_pdf()


def _fechar_hwnd_dialogo(hwnd):
    try:
        import win32gui
        import win32con
        win32gui.PostMessage(int(hwnd), win32con.WM_CLOSE, 0, 0)
    except Exception:
        pass
    try:
        Desktop(backend="win32").window(handle=int(hwnd)).close()
    except Exception:
        pass


def fechar_dialogos_pdf_pendentes():
    """
    Fecha 'Imprimir' e 'Salvar como' que sobraram do PDF anterior.
    Sem isso, o próximo item clica OK na janela velha e grava o PDF
    do documento anterior no arquivo do próximo.
    """
    for _ in range(8):
        pendentes = _hwnds_dialogos_pdf()
        if not pendentes:
            return
        for h in pendentes:
            _fechar_hwnd_dialogo(h)
        time.sleep(0.12)


def preparar_impressao_pdf() -> set:
    """
    Fecha diálogos PDF que sobraram e devolve o snapshot dos hwnds
    atuais. Chamar ANTES de disparar a impressão no SAP, senão o
    fechamento mata o diálogo novo.
    """
    fechar_dialogos_pdf_pendentes()
    return set(_hwnds_dialogos_pdf())


def selecionar_impressora(hwnds_antes=None):
    """
    Seleciona 'Microsoft Print to PDF' e confirma OK.
    Nunca reaproveita um diálogo 'Imprimir' que ficou aberto do item
    anterior (SAP lento / duplicata).
    """
    global _impressora_pdf_configurada
    with _impressora_pdf_lock:
        _ja_configurada = _impressora_pdf_configurada

    print("Aguardando janela Imprimir...")
    _t0_impressora = time.time()
    if hwnds_antes is None:
        hwnds_antes = _hwnds_dialogos_pdf()
    else:
        hwnds_antes = set(hwnds_antes)
    _titulos_imp = _titulos_janelas_imprimir()

    janela = None
    hwnd_nova = 0
    fim_espera = time.time() + 12.0
    while time.time() < fim_espera:
        try:
            for w in _janelas_win32_titulos(_titulos_imp):
                h = int(getattr(w, "handle", 0) or 0)
                if h and h not in hwnds_antes:
                    janela = w
                    hwnd_nova = h
                    print("✓ Janela 'Imprimir' nova encontrada (WIN32)")
                    break
        except Exception:
            pass
        if janela is not None:
            break
        time.sleep(0.12)

    if not janela:
        raise Exception(
            "Janela 'Imprimir' não encontrada após 12s "
            "(nenhum diálogo novo do SAP)."
        )

    from pywinauto import WindowSpecification
    janela = WindowSpecification({"handle": janela.handle})

    if _ja_configurada:
        print("A1: Impressora já configurada — clicando OK diretamente.")
    else:
        impressora_atual = ""
        combo_impressora = None
        try:
            combo_impressora = janela.child_window(class_name="ComboBox")
            impressora_atual = combo_impressora.window_text()
            print(f"Impressora atual: {impressora_atual}")
        except Exception:
            print(
                "Aviso: Não foi possível ler impressora atual. "
                "Vou selecionar mesmo assim."
            )
            impressora_atual = ""

        if impressora_atual.lower() != "microsoft print to pdf":
            print("Selecionando Microsoft Print to PDF...")
            try:
                if combo_impressora is None:
                    combo_impressora = janela.child_window(class_name="ComboBox")
                combo_impressora.select("Microsoft Print to PDF")
                _aguardar_ui_estavel(janela, timeout=0.1)
            except Exception as e_sel:
                print(
                    f"Aviso ao selecionar impressora: {e_sel}."
                    " Continuando..."
                )

    print("Procurando botão OK...")
    ok_clicado = False
    for metodo in ["enter", "auto_id", "title"]:
        try:
            if metodo == "auto_id":
                janela.child_window(
                    title="OK", auto_id="1",
                    control_type="Button"
                ).click()
            elif metodo == "title":
                janela.child_window(
                    title="OK", control_type="Button"
                ).click()
            else:
                janela.set_focus()
                send_keys("{ENTER}")
            ok_clicado = True
            print(f"✓ OK clicado ({metodo})")
            break
        except Exception:
            continue

    if not ok_clicado:
        raise Exception("Botão OK não foi clicado")

    def _esta_fechada():
        return not _janela_ainda_existe(hwnd_nova)

    _janela_fechou = aguardar_condicao(
        _esta_fechada,
        timeout=5.0,
        intervalo=0.1,
        descricao="janela Imprimir fechar após OK"
    )
    if not _janela_fechou:
        _fechar_hwnd_dialogo(hwnd_nova)
        send_keys("{ESC}")
        _janela_fechou = aguardar_condicao(
            _esta_fechada, timeout=2.0, intervalo=0.1
        )
    if not _janela_fechou:
        fechar_dialogos_pdf_pendentes()
        raise Exception(
            "Janela 'Imprimir' ficou aberta após o OK — "
            "não seguimos para não gravar o PDF no arquivo errado."
        )

    with _impressora_pdf_lock:
        _impressora_pdf_configurada = True
    print("✓ Diálogo de impressão confirmado")
    registrar_log(
        f"Impressora: confirmada em {time.time() - _t0_impressora:.2f}s",
        "INFO"
    )


# =====================================================
# SAP — SALVAR PDF (ESPERA DINÂMICA)
# =====================================================

def salvar_pdf(arquivo_destino):
    print(f"\nDestino:\n{arquivo_destino}")
    arquivo_destino.parent.mkdir(parents=True, exist_ok=True)

    _titulos_salvar = UI_ALIASES.get("janelas_salvar_pdf") or [
        "Salvar Saída de Impressão como"
    ]
    # O primeiro PDF do SAP costuma demorar mais para abrir o
    # "Salvar como". Timeout curto (2s) fazia o diálogo aparecer e
    # o programa já ter desistido — aí o pedido era refeito.
    janela_w32 = aguardar_janela_titulo(_titulos_salvar, timeout=8.0)
    if not janela_w32:
        registrar_log("ERRO ao salvar PDF: janela de salvar não apareceu.")
        fechar_dialogos_pdf_pendentes()
        return False
    try:
        TITULO = janela_w32.window_text() or _titulos_salvar[0]
    except Exception:
        TITULO = _titulos_salvar[0]

    # DialogWrapper (retorno de .windows()) não tem child_window.
    # Pedido/FRS/RM usam o mesmo salvar: precisa WindowSpecification.
    janela_spec = None
    try:
        hwnd = getattr(janela_w32, "handle", None)
        if hwnd:
            janela_spec = Desktop(backend="win32").window(handle=hwnd)
    except Exception:
        janela_spec = None
    if janela_spec is None:
        janela_spec = Desktop(backend="win32").window(title=TITULO)

    try:
        janela_spec.set_focus()
    except Exception:
        pass

    try:
        campo = janela_spec.child_window(class_name="Edit")
        campo.set_focus()
        campo.set_edit_text(str(arquivo_destino))
        print("Nome preenchido via UIA.")
        _aguardar_ui_estavel(janela_spec, timeout=0.2)
        janela_spec.set_focus()
        send_keys("{ENTER}")
        print("Salvar confirmado via Win32.")
    except Exception:
        try:
            campo = janela_spec.child_window(class_name="Edit")
            campo.set_edit_text(str(arquivo_destino))
            print("Nome preenchido via win32.")
            _aguardar_ui_estavel(janela_spec, timeout=0.1)
            send_keys("{ENTER}")
            print("Enter pressionado.")
        except Exception as e_w32:
            registrar_log(f"ERRO ao salvar PDF: {e_w32}")
            fechar_dialogos_pdf_pendentes()
            return False

    # ── Espera com IOCP (Windows ReadDirectoryChangesW)
    # Notificação instantânea do SO quando o arquivo aparece
    _TIMEOUT_PDF = 15.0   # segundos (não iterações)
    _TAMANHO_MIN = 512

    def _aguardar_pdf_iocp(
        path: Path, timeout: float, tam_min: int
    ) -> bool:
        """
        Aguarda o PDF via ReadDirectoryChangesW.
        Zero CPU durante a espera — SO notifica quando
        o arquivo é criado/modificado.
        """
        try:
            import ctypes
            import ctypes.wintypes as _wt

            _kernel32 = ctypes.windll.kernel32

            # Abre o diretório para monitoramento
            _dir_path = str(path.parent)
            _hdir = _kernel32.CreateFileW(
                _dir_path,
                0x0001,    # FILE_LIST_DIRECTORY
                0x0007,    # FILE_SHARE_READ/WRITE/DELETE
                None,
                3,         # OPEN_EXISTING
                0x02000000 | 0x10000000,
                # FILE_FLAG_BACKUP_SEMANTICS |
                # FILE_FLAG_OVERLAPPED
                None
            )

            if _hdir == -1:
                raise OSError("Não abriu diretório")

            _buf    = ctypes.create_string_buffer(8192)
            _bytes  = _wt.DWORD(0)
            _inicio = time.time()

            try:
                while time.time() - _inicio < timeout:
                    # FILE_NOTIFY_CHANGE_FILE_NAME |
                    # FILE_NOTIFY_CHANGE_SIZE
                    _ok = _kernel32.ReadDirectoryChangesW(
                        _hdir,
                        _buf, len(_buf),
                        False,   # não recursivo
                        0x00000001 | 0x00000008,
                        ctypes.byref(_bytes),
                        None, None
                    )

                    if not _ok:
                        break

                    # Verifica se o arquivo desejado apareceu
                    if path.exists():
                        _tam = path.stat().st_size
                        if _tam >= tam_min:
                            return True
                        elif _tam > 0:
                            # Crescendo — aguarda mais
                            time.sleep(0.05)

                return False

            finally:
                _kernel32.CloseHandle(_hdir)

        except Exception as _e_iocp:
            # Fallback para polling se IOCP falhar
            registrar_log(
                f"IOCP indisponível: {_e_iocp} "
                f"— usando polling.",
                "INFO"
            )
            return None   # None = usar fallback

    # Tenta IOCP primeiro
    _resultado_iocp = _aguardar_pdf_iocp(
        arquivo_destino, _TIMEOUT_PDF, _TAMANHO_MIN
    )

    if _resultado_iocp is True:
        tamanho = arquivo_destino.stat().st_size
        print(
            f"PDF confirmado via IOCP: "
            f"{arquivo_destino.name} "
            f"({tamanho // 1024} KB)"
        )
        fechar_dialogos_pdf_pendentes()
        return True
    elif _resultado_iocp is False:
        # IOCP falhou (arquivo não apareceu no timeout)
        pass
    else:
        # Fallback: polling original
        for tentativa in range(150):
            time.sleep(0.1)
            try:
                if arquivo_destino.exists():
                    tamanho = arquivo_destino.stat().st_size
                    if tamanho >= _TAMANHO_MIN:
                        print(
                            f"PDF confirmado (polling): "
                            f"{arquivo_destino.name} "
                            f"({tamanho // 1024} KB)"
                        )
                        fechar_dialogos_pdf_pendentes()
                        return True
                    elif tamanho > 0:
                        continue
            except Exception:
                pass


    # Diagnóstico final
    if arquivo_destino.exists():
        tamanho_final = arquivo_destino.stat().st_size
        if tamanho_final == 0:
            registrar_log(
                f"ERRO [PDF]: {arquivo_destino.name} criado com 0 bytes "
                f"— provável falha de impressão no SAP.",
                "ERRO"
            )
            try:
                arquivo_destino.unlink()   # remove arquivo vazio
            except Exception:
                pass
        else:
            registrar_log(
                f"AVISO [PDF]: {arquivo_destino.name} tem apenas "
                f"{tamanho_final} bytes — pode estar incompleto.",
                "AVISO"
            )
    else:
        registrar_log(
            f"ERRO [PDF]: {arquivo_destino.name} não encontrado "
            f"após 15s — diálogo pode ter falhado.",
            "ERRO"
        )

    print(f"AVISO: PDF não válido após 15s: {arquivo_destino.name}")
    fechar_dialogos_pdf_pendentes()
    return False


def finalizar_sap(session):
    try:
        print("\nFechando modais e retornando para tela inicial do SAP...")
        # A3: Fechar qualquer modal aberta antes de navegar
        # Janelas acumuladas aumentam tempo de findById() nas próximas ops
        for wnd_idx in [4, 3, 2, 1]:
            try:
                wnd = session.findById(f"wnd[{wnd_idx}]")
                if wnd is not None:
                    wnd.sendVKey(12)   # F12 = fechar modal
                    time.sleep(0.05)
            except Exception:
                pass   # janela não existe — ok

        session.findById("wnd[0]/tbar[0]/okcd").text = "/n"
        session.findById("wnd[0]").sendVKey(0)
        print("SAP retornado para tela inicial.")
    except Exception as erro:
        registrar_log(f"AVISO ao finalizar SAP: {erro}")

# =====================================================
# VALIDAÇÃO DE PDF — verifica integridade dos arquivos
# gerados antes do upload para o SharePoint
# =====================================================

def validar_pdf_gerado(caminho_pdf: Path) -> tuple:
    """
    Verifica se o PDF foi gerado corretamente.
    Usa mmap para leitura zero-copy — evita syscalls redundantes.
    """
    try:
        p = Path(caminho_pdf)

        # 1 — existência
        if not p.exists():
            return False, "arquivo não encontrado em disco"

        # 2 — tamanho mínimo
        tamanho = p.stat().st_size
        if tamanho < 1024:
            return (
                False,
                f"arquivo muito pequeno ({tamanho} bytes) "
                f"— provável erro de impressão"
            )

        # 3 + 4 — assinatura E lock check em uma única abertura
        # mmap permite leitura sem copiar dados para userspace
        import mmap as _mmap
        try:
            with open(str(p), "rb") as f:
                try:
                    mm = _mmap.mmap(
                        f.fileno(), 0,
                        access=_mmap.ACCESS_READ
                    )
                    header = mm[:5]
                    mm.close()
                except (ValueError, OSError):
                    # mmap pode falhar em arquivos muito pequenos
                    # ou em Windows com arquivo bloqueado
                    f.seek(0)
                    header = f.read(5)
        except PermissionError:
            return (
                False,
                "arquivo bloqueado por outro processo "
                "— aguarde e tente novamente"
            )

        if not header.startswith(b"%PDF"):
            return (
                False,
                "cabeçalho inválido — não é um PDF real"
            )

        return True, ""

    except Exception as e:
        return False, f"erro inesperado na validação: {e}"



def validar_pdfs_pasta(
    pasta:    Path,
    prefixo:  str,
    ids:      list,
    nome_log: str,
    parar_no_primeiro_erro: bool = False,
) -> tuple:
    """
    Valida todos os PDFs de uma categoria em paralelo.

    Retorna (total_ok, total_falha, falhos).
    parar_no_primeiro_erro: True = short-circuit na falha
    """
    if not ids:
        return 0, 0, []

    ok      = 0
    falha   = 0
    falhos  = []
    _lock_v = threading.Lock()

    def _validar_um(id_item):
        # `prefixo` ja inclui o separador (por exemplo, "Pedido_").
        # A virgula usada anteriormente produzia nomes inexistentes como
        # "Pedido_,123.pdf" e invalidava todos os documentos no pre-flight.
        arquivo        = pasta / f"{prefixo}{id_item}.pdf"
        valido, motivo = validar_pdf_gerado(arquivo)
        return id_item, valido, motivo, arquivo.name

    # Paralelo com até 8 workers (I/O bound — pode usar muitos)
    _n_workers_val = min(8, len(ids))

    from concurrent.futures import (
        ThreadPoolExecutor as _TPEV,
        as_completed       as _ACV,
        FIRST_EXCEPTION    as _FE,
    )

    with _TPEV(max_workers=_n_workers_val) as _exv:
        _futsv = {
            _exv.submit(_validar_um, _id): _id
            for _id in ids
        }
        for _fv in _ACV(_futsv):
            try:
                _id_v, _valido, _motivo, _nome = _fv.result()
                with _lock_v:
                    if _valido:
                        ok += 1
                    else:
                        falha  += 1
                        falhos.append(_id_v)
                        registrar_log(
                            f"AVISO [{nome_log}]: PDF inválido — "
                            f"{_nome}: {_motivo}",
                            "AVISO"
                        )
                        if parar_no_primeiro_erro:
                            # Cancela pendentes
                            for _fv2 in _futsv:
                                _fv2.cancel()
                            break
            except Exception as _ev:
                with _lock_v:
                    falha += 1

    if falhos:
        registrar_log(
            f"AVISO [{nome_log}]: {falha} PDF(s) com "
            f"problema: {falhos}",
            "AVISO"
        )
    else:
        registrar_log(
            f"OK [{nome_log}]: {ok} PDF(s) válidos.",
            "OK"
        )

    return ok, falha, falhos


# =====================================================
# UTILITÁRIOS — ESPERA DINÂMICA
# =====================================================

def aguardar_janela_titulo(titulo, timeout=1):
    titulos = list(titulo) if isinstance(titulo, (list, tuple)) else [titulo]
    titulos_l = [str(t).strip().lower() for t in titulos if t]
    fim = time.time() + max(0.2, float(timeout))
    while time.time() < fim:
        try:
            for jan in Desktop(backend="win32").windows():
                try:
                    txt = (jan.window_text() or "").strip()
                except Exception:
                    continue
                if not txt:
                    continue
                tl = txt.lower()
                if txt in titulos or tl in titulos_l:
                    return jan
                if any(a and a in tl for a in titulos_l):
                    return jan
        except Exception:
            pass
        time.sleep(0.15)
    return None

def aguardar_janela_uia(titulo, timeout=1):
    """Aguarda janela UIA aparecer. Retorna Application ou None."""
    for _ in range(int(timeout / 0.2)):
        try:
            app = Application(backend="uia").connect(
                title=titulo, timeout=0.5
            )
            return app
        except Exception:
            pass
        time.sleep(0.2)
    return None

def aguardar_condicao(condicao_fn, timeout=1, intervalo=0.2, descricao=""):
    """Espera ativa: retorna True assim que a condição for satisfeita."""
    inicio = time.time()
    while time.time() - inicio < timeout:
        try:
            if condicao_fn():
                return True
        except Exception:
            pass
        time.sleep(intervalo)
        # SEM _process_qt_events() — roda em thread de fundo
    if descricao:
        registrar_log(f"TIMEOUT aguardando: {descricao}")
    return False
# =====================================================
# HELPERS DE ESPERA DINÂMICA — substitutos de sleep
# Cole logo após aguardar_condicao()
# =====================================================

def _aguardar_ui_estavel(janela, timeout: float = 1.0) -> bool:
    """
    Aguarda qualquer janela parar de mudar sua árvore
    de controles por 2 leituras consecutivas iguais.
    Substitui time.sleep() fixo após cliques em janelas
    Windows, SAP ou SharePoint.
    """
    ultimo     = -1
    repeticoes = 0
    fim        = time.time() + timeout
    while time.time() < fim:
        try:
            total = len(janela.descendants())
            if total == ultimo and total > 0:
                repeticoes += 1
                if repeticoes >= 2:
                    return True
            else:
                repeticoes = 0
                ultimo     = total
        except Exception:
            pass
        time.sleep(0.15)
    return False


def _janelas_win32_titulos(titulos) -> list:
    achadas = []
    vistos = set()
    for t in titulos or []:
        try:
            for w in Desktop(backend="win32").windows(title=t):
                h = int(getattr(w, "handle", 0) or 0)
                if h and h not in vistos:
                    vistos.add(h)
                    achadas.append(w)
        except Exception:
            continue
    return achadas


def _janela_impressora_fechada() -> bool:
    """
    Retorna True quando a janela de imprimir do Windows
    não está mais aberta (PT/EN).
    """
    try:
        return len(_janelas_win32_titulos(
            UI_ALIASES.get("janelas_imprimir") or ["Imprimir"]
        )) == 0
    except Exception:
        return True


def _outlook_janela_aberta() -> bool:
    """
    Retorna True quando qualquer janela do Outlook
    aparecer na área de trabalho.
    """
    try:
        return len(
            Desktop(backend="win32").windows(
                title_re=".*Outlook.*"
            )
        ) > 0
    except Exception:
        return False


def _outlook_esta_rodando() -> bool:
    """
    Detecta se o Outlook (clássico ou novo, o que estiver instalado)
    está de fato em execução — via lista de processos (mais
    confiável, não depende da janela estar visível) com fallback pra
    checagem de janela.
    """
    if _PSUTIL_OK:
        try:
            for proc in _psutil.process_iter(["name"]):
                nome_proc = (proc.info.get("name") or "").lower()
                if nome_proc in ("outlook.exe", "olk.exe"):
                    return True
        except Exception:
            pass
    return _outlook_janela_aberta()


_outlook_rascunho_em = ""


def _marcar_outlook_usado(tipo: str) -> None:
    global _outlook_rascunho_em
    if tipo in ("classico", "novo"):
        _outlook_rascunho_em = tipo


def _abrir_outlook_usado():
    """Abre o mesmo Outlook em que o rascunho foi criado."""
    import subprocess
    usado = (_outlook_rascunho_em or "").strip()
    if not usado:
        if _outlook_classico_rodando() and not _outlook_novo_rodando():
            usado = "classico"
        elif _outlook_novo_rodando():
            usado = "novo"
    ordem = []
    if usado == "classico":
        ordem = [
            lambda: subprocess.Popen(["outlook.exe"]),
            lambda: os.startfile("ms-outlook:"),
            lambda: subprocess.Popen(["olk.exe"]),
        ]
    else:
        ordem = [
            lambda: subprocess.Popen(["olk.exe"]),
            lambda: os.startfile("ms-outlook:"),
            lambda: subprocess.Popen(["outlook.exe"]),
        ]
    ordem.extend([
        lambda: subprocess.Popen(
            ["cmd", "/c", "start", "outlook:"], shell=True
        ),
        lambda: webbrowser.open("https://outlook.office.com/mail/"),
    ])
    for fn in ordem:
        try:
            fn()
            return
        except Exception:
            continue


def _outlook_classico_rodando() -> bool:
    """
    Detecta especificamente o Outlook CLÁSSICO (processo
    outlook.exe) — diferente de _outlook_esta_rodando(), que aceita
    tanto o clássico quanto o novo (olk.exe). Usado antes de tentar a
    automação COM (Dispatch), que só funciona de verdade com o
    clássico.

    Em algumas máquinas com só o novo Outlook instalado,
    "Outlook.Application" ainda está registrado no Windows (resquício
    de uma instalação antiga do Office) e win32com.client.Dispatch()
    não dá NENHUM erro — cria o objeto, aceita To/CC/Assunto/Corpo,
    anexa os arquivos e "salva" sem reclamar — só que o rascunho vai
    pra um perfil MAPI órfão, desconectado da conta que aparece no
    novo Outlook. Resultado: o log mostra sucesso, mas nada aparece
    em lugar nenhum. Checar o processo de verdade antes de tentar
    evita esse falso positivo.
    """
    if not _PSUTIL_OK:
        return False
    try:
        for proc in _psutil.process_iter(["name"]):
            if (proc.info.get("name") or "").lower() == "outlook.exe":
                return True
    except Exception:
        pass
    return False

def _outlook_novo_rodando() -> bool:
    """True se o Outlook NOVO (olk.exe) estiver em execução."""
    if not _PSUTIL_OK:
        return False
    try:
        for proc in _psutil.process_iter(["name"]):
            if (proc.info.get("name") or "").lower() == "olk.exe":
                return True
    except Exception:
        pass
    return False


def _janelas_login_outlook_classico():
    """Títulos típicos de login/ativação do clássico. Lista vazia = nenhum."""
    titulos = []
    padroes = (
        "sign in", "entrar", "conecte-se", "connect to",
        "ativar o office", "activate office",
        "add account", "adicionar conta",
        "choose an account", "escolher uma conta",
        "welcome to outlook", "bem-vindo ao outlook",
    )
    try:
        for w in Desktop(backend="uia").windows():
            try:
                t = (w.window_text() or "").strip()
            except Exception:
                continue
            if not t:
                continue
            tl = t.lower()
            if not any(p in tl for p in padroes):
                continue
            try:
                import psutil as _ps_login
                nome = (
                    _ps_login.Process(w.process_id()).name() or ""
                ).lower()
            except Exception:
                nome = ""
            if nome and nome not in ("outlook.exe", "olk.exe", "winlogon.exe"):
                if "outlook" not in tl and "office" not in tl:
                    continue
            titulos.append(t)
    except Exception:
        pass
    return titulos


def _cc_eml_com_nomes_gal(cc_str: str, nomes_gal_cc=None) -> str:
    """
    Cc do .eml: só SMTP já confirmados.
    Nome sem SMTP NÃO entra no .eml (chip vermelho / corrompe assunto).
    Na 1ª vez o nome é colado no Cc + 1ª sugestão; SMTP é gravado
    e nas próximas execuções já vai no .eml.
    """
    partes = []
    vistos = set()
    for item in _partir_destinatarios_email(
        _destinatarios_para_cabecalho_eml(cc_str, False)
    ):
        ch = item.lower()
        if ch and ch not in vistos and "@" in item:
            vistos.add(ch)
            partes.append(item)
    # nomes_gal_cc ignorados de propósito (resolvidos na UI, não no .eml)
    _ = nomes_gal_cc
    return "; ".join(partes)


def _montar_eml_rascunho(para_str, cc_str, assunto, corpo_html, corpo_txt, anexos):
    """
    .eml padrão MIME (não depende de Tab/resolução).
    X-Unsent=1 pede composição/rascunho no Windows, sem enviar.
    """
    from email import encoders
    from email.mime.base import MIMEBase
    from email.mime.multipart import MIMEMultipart
    from email.mime.text import MIMEText

    msg = MIMEMultipart()
    msg["To"] = para_str or ""
    if cc_str:
        msg["Cc"] = cc_str
    msg["Subject"] = assunto or ""
    msg["X-Unsent"] = "1"

    html_ok = (corpo_html or "").strip() or (
        "<html><body><pre>"
        + (corpo_txt or "").replace("&", "&amp;").replace("<", "&lt;")
        + "</pre></body></html>"
    )
    # Só HTML (sem alternative). O Outlook novo às vezes ignora o HTML
    # do multipart/alternative e deixa só a assinatura + o assunto.
    msg.attach(MIMEText(html_ok, "html", "utf-8"))

    for anexo in anexos or []:
        caminho = Path(anexo)
        if not caminho.exists():
            continue
        with open(caminho, "rb") as f:
            parte = MIMEBase("application", "octet-stream")
            parte.set_payload(f.read())
        encoders.encode_base64(parte)
        parte.add_header(
            "Content-Disposition",
            "attachment",
            filename=_nome_anexo_eml_seguro(caminho.name),
        )
        msg.attach(parte)

    pasta = Path(tempfile.gettempdir())
    destino = pasta / (
        "rascunho_automacao_"
        + datetime.now().strftime("%Y%m%d_%H%M%S")
        + ".eml"
    )
    destino.write_bytes(msg.as_bytes())
    return destino


def _nome_anexo_eml_seguro(nome: str) -> str:
    """Nome ASCII para o Outlook exibir o anexo corretamente (sem 'attachment')."""
    import unicodedata
    n = unicodedata.normalize("NFKD", str(nome or ""))
    n = n.encode("ascii", "ignore").decode("ascii")
    n = re.sub(r"[^\w.\-]+", "_", n).strip("._")
    return n or "anexo.zip"


def _confirmar_dialogo_manter_rascunho() -> bool:
    """
    Clica em Sim no 'Fechar rascunho?'. No Outlook novo esse diálogo
    costuma ser um overlay DENTRO da janela da mensagem (o título
    continua sendo o assunto) — não dá para achar só pelo título.
    Nunca clica em Enviar, Não ou Descartar.
    """
    frases = (
        "salvar este rascunho",
        "deseja salvar",
        "fechar rascunho",
        "save this draft",
        "close draft",
        "antes de fechar",
        "before closing",
        "keep this draft",
    )
    try:
        import psutil as _ps_dlg
    except Exception:
        _ps_dlg = None

    def _eh_outlook(w) -> bool:
        if _ps_dlg is None:
            return True
        try:
            nome = (_ps_dlg.Process(w.process_id()).name() or "").lower()
            return nome in ("olk.exe", "outlook.exe")
        except Exception:
            return False

    def _clicar_sim(raiz) -> bool:
        try:
            botoes = list(raiz.descendants(control_type="Button"))
        except Exception:
            botoes = []
        for btn in botoes:
            try:
                nome = (btn.window_text() or "").strip().lower()
            except Exception:
                continue
            if nome in ("sim", "yes"):
                try:
                    btn.click_input()
                    registrar_log(
                        "OK [EMAIL-EML]: clicado Sim para salvar o rascunho."
                    )
                    return True
                except Exception:
                    continue
        return False

    def _tem_pergunta(raiz) -> bool:
        try:
            tit = (raiz.window_text() or "").lower()
        except Exception:
            tit = ""
        if any(f in tit for f in frases):
            return True
        try:
            for tipo in ("Window", "Pane", "Text", "Document"):
                try:
                    ctrls = raiz.descendants(control_type=tipo)
                except Exception:
                    continue
                for ctrl in ctrls[:80]:
                    try:
                        tx = (ctrl.window_text() or "").lower()
                    except Exception:
                        continue
                    if tx and any(f in tx for f in frases):
                        return True
        except Exception:
            pass
        return False

    try:
        for w in Desktop(backend="uia").windows():
            if not _eh_outlook(w):
                continue
            if not _tem_pergunta(w):
                continue
            if _clicar_sim(w):
                return True
            try:
                send_keys("{ENTER}")
                registrar_log(
                    "OK [EMAIL-EML]: Enter no diálogo de salvar rascunho "
                    "(Sim é o padrão)."
                )
                return True
            except Exception:
                pass
    except Exception as e:
        registrar_log(f"AVISO [EMAIL-EML]: diálogo Sim: {e}", "AVISO")
    return False


def _partir_destinatarios_email(texto: str) -> list:
    partes = []
    for p in re.split(r"[;,]", texto or ""):
        p = p.strip()
        if p:
            partes.append(p)
    return partes


def _item_destinatario_tem_smtp(item: str) -> bool:
    return "@" in (item or "") and "." in (item or "").split("@")[-1]


def _separar_smtp_e_nomes(lista) -> tuple:
    smtp, nomes = [], []
    for item in lista or []:
        item = (item or "").strip()
        if not item:
            continue
        if _item_destinatario_tem_smtp(item):
            smtp.append(item)
        else:
            nomes.append(item)
    return smtp, nomes


def _destinatarios_para_cabecalho_eml(texto: str, incluir_nomes: bool = False) -> str:
    """
    SMTP no cabeçalho. No Cc também entra o nome do fiscal/gerente
    sem SMTP (igual o gerente já resolvido), para o Outlook novo
    copiar o destinatário no rascunho.
    """
    smtp, nomes = _separar_smtp_e_nomes(_partir_destinatarios_email(texto))
    so_smtp = []
    vistos = set()
    for item in smtp:
        m = re.search(r"<?([^<>;\s]+@[^<>;\s]+)>?", item or "")
        em = (m.group(1) if m else item).strip()
        chave = em.lower()
        if em and "@" in em and chave not in vistos:
            vistos.add(chave)
            so_smtp.append(em)
    if incluir_nomes:
        for n in nomes:
            n = str(n or "").strip()
            chave = n.lower()
            if n and chave not in vistos:
                vistos.add(chave)
                so_smtp.append(n)
    return "; ".join(so_smtp)


def _achar_campo_destinatario_outlook(janela, chaves: tuple):
    chaves = tuple(c.lower() for c in chaves)
    preferidos = []
    outros = []
    try:
        ctrls = janela.descendants()
    except Exception:
        ctrls = []
    for ctrl in ctrls[:450]:
        try:
            info = ctrl.element_info
            nome = (info.name or "").strip().lower().rstrip(":")
            tipo = str(getattr(info, "control_type", "") or "").lower()
        except Exception:
            continue
        if not nome:
            continue
        if any(t in tipo for t in ("button", "hyperlink", "menuitem")):
            continue
        tokens = nome.replace("-", " ").replace("/", " ").split()
        if not any(c == nome or c in tokens for c in chaves):
            continue
        if any(t in tipo for t in ("edit", "combo", "custom", "dataitem")):
            preferidos.append(ctrl)
        else:
            outros.append(ctrl)
        if preferidos:
            return preferidos[0]
    return (preferidos or outros or [None])[0]


def _janela_escolha_app_outlook_aberta() -> bool:
    try:
        from pywinauto import Desktop as _DeskApp
        for w in _DeskApp(backend="uia").windows():
            try:
                t = (w.window_text() or "").lower()
            except Exception:
                continue
            if any(
                p in t
                for p in (
                    "como você deseja abrir",
                    "how do you want to open",
                    "escolha um aplicativo",
                    "choose an app",
                    "selecione um aplicativo",
                    "select an app",
                )
            ):
                return True
    except Exception:
        pass
    return False


def _aguardar_escolha_app_outlook(timeout: float = 90.0) -> bool:
    """Espera o usuário escolher o Outlook na janela 'Como abrir' do Windows."""
    if not _janela_escolha_app_outlook_aberta():
        return True
    registrar_log(
        "INFO [EMAIL]: aguardando você escolher o Outlook "
        "na janela do Windows.",
        "INFO",
    )
    fim = time.time() + timeout
    while time.time() < fim:
        if not _janela_escolha_app_outlook_aberta():
            time.sleep(0.5)
            return True
        time.sleep(0.4)
    return not _janela_escolha_app_outlook_aberta()


def _fechar_janelas_cfd_outlook() -> bool:
    """Fecha 'CFD File Open Message Window' e similares órfãs no Outlook."""
    fechou = False
    try:
        from pywinauto import Desktop as _DeskCfd
        for w in _DeskCfd(backend="win32").windows():
            try:
                titulo = (w.window_text() or "").strip()
            except Exception:
                continue
            if not titulo:
                continue
            tl = titulo.lower()
            if "cfd file open message" not in tl and "cfd file" not in tl:
                continue
            try:
                w.close()
                fechou = True
            except Exception:
                try:
                    w.set_focus()
                    send_keys("{ESC}")
                    fechou = True
                except Exception:
                    pass
            if fechou:
                registrar_log(
                    f"OK [EMAIL]: janela fantasma fechada — {titulo}",
                    "OK",
                )
    except Exception:
        pass
    return fechou


def _cancelar_dialogos_salvar_abrir() -> bool:
    """
    ESC só em diálogo #32770 (Salvar Como / Abrir).
    Não mexe em janela do Explorer ('Visão da área de trabalho') —
    isso roubava o foco do Outlook e digitar caía no assunto/corpo.
    """
    fechou = False
    try:
        from pywinauto import Desktop as _DeskDlg
        janelas = list(_DeskDlg(backend="win32").windows())
    except Exception:
        janelas = []
    for w in janelas:
        try:
            titulo = (w.window_text() or "").strip().lower()
            if not titulo:
                continue
            if "dados para faturamento" in titulo:
                continue
            cls = ""
            try:
                cls = (w.class_name() or "")
            except Exception:
                cls = ""
            # Só diálogos de arquivo reais (#32770)
            if cls != "#32770":
                continue
            e_salvar = any(
                p in titulo
                for p in (
                    "salvar como", "save as", "salvar", "save",
                    "área de trabalho", "area de trabalho",
                    "visão da área", "visao da area",
                    "visão da area", "visao da área",
                )
            )
            e_abrir = (
                titulo in ("abrir", "open")
                or titulo.startswith("abrir")
                or titulo.startswith("open")
            )
            if not (e_salvar or e_abrir or "zip" in titulo):
                continue
            try:
                w.set_focus()
            except Exception:
                pass
            send_keys("{ESC}")
            time.sleep(0.25)
            fechou = True
            registrar_log(
                f"AVISO [EMAIL]: diálogo de arquivo fechado "
                f"('{w.window_text()}') — não era o Cc.",
                "AVISO",
            )
        except Exception:
            continue
    _fechar_janelas_cfd_outlook()
    return fechou


def _janela_outlook_uia(janela):
    """
    Outlook novo (WebView): WindowSpecification só com handle
    enxerga ~7 nós e não acha Cc/GAL. O wrapper do Desktop(uia)
    vê o poço de destinatários. Reusa a janela se a árvore já for rica.
    """
    if janela is None:
        return None
    try:
        hwnd = int(getattr(janela, "handle", 0) or 0)
    except Exception:
        return janela
    if not hwnd:
        return janela
    n = 0
    try:
        for _ in janela.descendants():
            n += 1
            if n >= 40:
                return janela
    except Exception:
        pass
    try:
        from pywinauto import Desktop as _Desk
        for w in _Desk(backend="uia").windows():
            try:
                if int(w.handle) == hwnd:
                    return w
            except Exception:
                continue
    except Exception:
        pass
    return janela


def _garantir_foco_composicao_outlook(janela, fechar_seletor: bool = True) -> bool:
    """Só digita se o primeiro plano for olk.exe da composição."""
    _cancelar_dialogos_salvar_abrir()
    if fechar_seletor:
        _fechar_seletor_destinatarios_outlook()
    try:
        janela.set_focus()
    except Exception:
        pass
    time.sleep(0.2)
    try:
        import win32gui as _wg
        import win32process as _wp
        import psutil as _ps_fg
        hwnd = int(_wg.GetForegroundWindow())
        _tid, pid = _wp.GetWindowThreadProcessId(hwnd)
        nome = (_ps_fg.Process(int(pid)).name() or "").lower()
        titulo = (_wg.GetWindowText(hwnd) or "").lower()
    except Exception:
        return False
    if nome != "olk.exe":
        registrar_log(
            f"AVISO [EMAIL-GAL]: primeiro plano é '{nome}' "
            "— não colo o gerente (evita Salvar Como).",
            "AVISO",
        )
        return False
    if any(
        p in titulo
        for p in ("salvar", "abrir", "save as", "open", "área de trabalho")
    ):
        send_keys("{ESC}")
        time.sleep(0.2)
        return False
    return True


def _fechar_seletor_destinatarios_outlook() -> bool:
    """
    ESC no 'Adicionar Destinatários'. Clicar no rótulo Cc abre isso;
    a busca cai em listas de distribuição com ':Nome' na caixa.
    """
    fechou = False
    try:
        from pywinauto import Desktop as _DeskSel
        janelas = list(_DeskSel(backend="uia").windows())
    except Exception:
        return False
    for w in janelas:
        try:
            t = (w.window_text() or "").lower()
            if "adicionar destinat" not in t and "add recipient" not in t:
                continue
            try:
                w.set_focus()
            except Exception:
                pass
            send_keys("{ESC}")
            time.sleep(0.35)
            fechou = True
            registrar_log(
                "AVISO [EMAIL]: fechado 'Adicionar Destinatários' "
                "(não é o campo Cc).",
                "AVISO",
            )
        except Exception:
            continue
    return fechou


def _rotulo_destinatario_outlook(janela, alvos: tuple):
    """
    Texto 'Cc'/'Para' da composição — não o botão (abre o seletor).
    Com anexos a árvore UIA cresce; o teste simples achava o rótulo
    nos primeiros 500 nós. Aqui busca Text primeiro e aceita o
    cabeçalho até 55% da altura (no teste o Cc estava em ~37%).
    """
    wr = janela.rectangle()
    h_jan = max(1, int(wr.bottom - wr.top))
    lim = int(wr.top) + int(h_jan * 0.55)
    melhor, melhor_h = None, 999
    ctrls = []
    try:
        ctrls.extend(list(janela.descendants(control_type="Text"))[:400])
    except Exception:
        pass
    try:
        ctrls.extend(list(janela.descendants())[:2000])
    except Exception:
        pass
    vistos = set()
    for c in ctrls:
        try:
            hid = int(getattr(c.element_info, "handle", 0) or 0)
            chave = hid or id(c)
            if chave in vistos:
                continue
            vistos.add(chave)
            nome = (c.element_info.name or "").strip().lower().rstrip(":")
            if not nome:
                nome = (c.window_text() or "").strip().lower().rstrip(":")
            tipo = str(c.element_info.control_type or "").lower()
            if nome not in alvos:
                continue
            if any(t in tipo for t in ("button", "hyperlink", "menuitem")):
                continue
            r = c.rectangle()
            h = int(r.bottom - r.top)
            if int(r.top) < int(wr.top):
                continue
            if int(r.bottom) > lim or h < 8 or h > 56:
                continue
            if h < melhor_h:
                melhor, melhor_h = c, h
        except Exception:
            continue
    return melhor


def _ativar_aba_mensagem_outlook(janela) -> None:
    """Aba Mensagem — sem ela Para/Cc somem da faixa útil."""
    try:
        for c in janela.descendants()[:3000]:
            try:
                t = (c.window_text() or "").strip().lower()
                tipo = str(c.element_info.control_type or "")
            except Exception:
                continue
            if t == "mensagem" and tipo == "TabItem":
                try:
                    c.click_input()
                except Exception:
                    try:
                        c.select()
                    except Exception:
                        pass
                time.sleep(0.45)
                return
    except Exception:
        pass


def _botao_rotulo_destinatario_outlook(janela, alvos: tuple):
    """
    Botão 'Para' / 'Cc' da composição (Outlook novo).
    Não é o Edit (WebView); o clique vai À DIREITA deste botão.
    """
    alvos_l = tuple(a.lower() for a in alvos)
    try:
        wr = janela.rectangle()
    except Exception:
        return None
    candidatos = []
    try:
        for c in janela.descendants()[:7000]:
            try:
                t = (c.window_text() or "").strip().lower()
                tipo = str(c.element_info.control_type or "")
                r = c.rectangle()
            except Exception:
                continue
            if t not in alvos_l:
                continue
            if tipo not in ("Button", "SplitButton", "Hyperlink", "Text"):
                continue
            # Cabeçalho (abaixo da ribbon ~28%, acima do corpo ~55%)
            y_rel = int(r.top) - int(wr.top)
            h_jan = max(1, int(wr.bottom) - int(wr.top))
            if y_rel < int(h_jan * 0.26) or y_rel > int(h_jan * 0.55):
                continue
            w_btn = int(r.right) - int(r.left)
            if w_btn < 16 or w_btn > 280:
                continue
            # Prefere Button; Text é fallback
            prio = 0 if tipo == "Button" else (
                1 if tipo in ("SplitButton", "Hyperlink") else 2
            )
            candidatos.append((prio, y_rel, abs(w_btn - 80), c))
    except Exception:
        return None
    if not candidatos:
        return None
    candidatos.sort()
    return candidatos[0][3]


def _rolar_composicao_outlook_topo(janela) -> None:
    """Garante que Para/Cc/Assunto estão visíveis antes de colar no Cc."""
    try:
        janela = _janela_outlook_uia(janela)
        if janela is None:
            return
        janela.set_focus()
        _ativar_aba_mensagem_outlook(janela)
        send_keys("^{HOME}")
        time.sleep(0.12)
        for _ in range(3):
            send_keys("{PGUP}")
            time.sleep(0.06)
    except Exception:
        pass


def _foco_parece_destinatario_outlook(janela) -> bool:
    """
    True só se o controle com foco de teclado parece um poço de
    destinatário (Para/Cc), nunca o corpo do e-mail nem o assunto.
    Usado para não colar o nome no lugar errado (corpo) quando o
    clique por coordenada erra o alvo.
    """
    try:
        janela = _janela_outlook_uia(janela)
        if janela is None:
            return False
        for c in janela.descendants()[:500]:
            try:
                if not c.has_keyboard_focus():
                    continue
            except Exception:
                continue
            try:
                aid = ((c.element_info.automation_id or "") or "").lower()
                tipo = str(c.element_info.control_type or "").lower()
            except Exception:
                aid, tipo = "", ""
            if "body" in aid or "corpo" in aid or "subject" in aid:
                return False
            if tipo in ("document", "pane") and not aid:
                return False
            if "_cc" in aid or "-cc" in aid or "recipient" in aid:
                return True
            if tipo in ("edit", "combobox"):
                return True
            return False
        return False
    except Exception:
        return False


def _focar_linha_cc_outlook(janela) -> bool:
    """
    Foca a área vazia do poço Cc para COLAR o nome (Ctrl+V).
    Nunca clica no De:/From nem no e-mail da assinatura (mesmo SMTP).
    Ordem (UIA Outlook novo, janela ~1416x973):
      1) automation_id recipient-well-label-cc / *_CC
      2) Botão 'Cc' → clique à direita (dentro do poço)
      3) Abaixo do botão 'Para'
      4) % da janela ~52% (Cc real; 37% era o De:)
    """
    _fechar_seletor_destinatarios_outlook()
    janela = _janela_outlook_uia(janela)
    if janela is None:
        return False
    try:
        janela.set_focus()
    except Exception:
        return False
    _ativar_aba_mensagem_outlook(janela)
    _rolar_composicao_outlook_topo(janela)
    time.sleep(0.12)

    try:
        wr = janela.rectangle()
    except Exception:
        return False
    h_jan = max(1, int(wr.bottom) - int(wr.top))
    # Para ~45%, Cc ~52%, Assunto ~59%; De: ~37% — NÃO misturar
    y_min = int(wr.top) + int(h_jan * 0.40)
    y_max = int(wr.top) + int(h_jan * 0.58)

    def _na_faixa_cc(r) -> bool:
        cy = (int(r.top) + int(r.bottom)) // 2
        return y_min <= cy <= y_max

    def _clique_area_colar(x, y, rotulo="Cc"):
        # Só a faixa do Cc — evita De: (~37%) e assinatura/corpo
        if y < y_min or y > int(wr.top) + int(h_jan * 0.58):
            return False
        click(coords=(int(x), int(y)))
        time.sleep(0.15)
        if not _foco_parece_destinatario_outlook(janela):
            registrar_log(
                f"AVISO [EMAIL-GAL]: clique em {rotulo} "
                f"({int(x) - int(wr.left)},{int(y) - int(wr.top)}) não focou "
                "um campo de destinatário (provável corpo do e-mail) — ignorando.",
                "AVISO",
            )
            return False
        registrar_log(
            f"INFO [EMAIL-GAL]: foco {rotulo} p/ colar "
            f"({int(x) - int(wr.left)},{int(y) - int(wr.top)}).",
            "INFO",
        )
        return True

    def _clique_direita_poco(r, dx=120, rotulo="Cc"):
        # Área vazia à direita do rótulo/chip — NÃO em cima do endereço
        x = min(int(r.right) + dx, int(wr.right) - 60)
        y = (int(r.top) + int(r.bottom)) // 2
        return _clique_area_colar(x, y, rotulo)

    def _clique_borda_direita_poco(r, rotulo="Cc/poço"):
        # Poço MSG_*_CC: clica perto da borda direita (digitação), não no chip
        x = max(int(r.left) + 80, int(r.right) - 50)
        x = min(x, int(wr.right) - 40)
        y = (int(r.top) + int(r.bottom)) // 2
        return _clique_area_colar(x, y, rotulo)

    # ── 1) Poço Cc (*_CC) na borda direita = área de COLAR (não o De:/chip Levi)
    poco_cc = None
    label_cc = None
    try:
        for c in janela.descendants()[:8000]:
            try:
                aid = ((c.element_info.automation_id or "") or "").lower()
                r = c.rectangle()
            except Exception:
                continue
            if not aid:
                continue
            if aid == "recipient-well-label-cc":
                label_cc = c
                continue
            if aid.endswith("_cc") or aid.endswith("-cc"):
                if "_to" in aid or "subject" in aid or "from" in aid:
                    continue
                if not _na_faixa_cc(r):
                    continue
                if int(r.right) - int(r.left) < 80:
                    continue
                poco_cc = c
                break
    except Exception:
        pass
    if poco_cc is not None:
        try:
            if _clique_borda_direita_poco(poco_cc.rectangle(), "Cc/id-poço"):
                return True
        except Exception:
            pass
    if label_cc is not None:
        try:
            # Longe do rótulo: entra no poço à direita (colar), não no chip
            if _clique_direita_poco(
                label_cc.rectangle(), dx=280, rotulo="Cc/id-label"
            ):
                return True
        except Exception:
            pass

    # ── 2) Botão/texto 'Cc' (faixa ~45–58%; nunca De: em 37%)
    for _ in range(3):
        btn = _botao_rotulo_destinatario_outlook(
            janela, ("cc", "cópia", "copia", "cco")
        )
        txt = _rotulo_destinatario_outlook(
            janela, ("cc", "cópia", "copia", "cco")
        )
        for ctrl, origem in ((btn, "botão"), (txt, "texto")):
            if ctrl is None:
                continue
            try:
                r = ctrl.rectangle()
                if not _na_faixa_cc(r):
                    continue
                if _clique_direita_poco(r, dx=280, rotulo=f"Cc/{origem}"):
                    return True
            except Exception:
                pass
        btn_para = _botao_rotulo_destinatario_outlook(janela, ("para", "to"))
        txt_para = _rotulo_destinatario_outlook(janela, ("para", "to"))
        for ctrl in (btn_para, txt_para):
            if ctrl is None:
                continue
            try:
                r = ctrl.rectangle()
                cy = (int(r.top) + int(r.bottom)) // 2
                if cy < int(wr.top) + int(h_jan * 0.38):
                    continue
                x = min(int(r.right) + 280, int(wr.right) - 60)
                y = int(r.bottom) + 28
                if y < y_min:
                    y = y_min + 10
                if _clique_area_colar(x, y, "Cc/abaixo-Para"):
                    return True
            except Exception:
                pass
        time.sleep(0.2)

    # ── 3) % da janela: Cc ~52%, X ~72% (área vazia p/ colar; 37% era De:)
    try:
        x = int(wr.left) + int((int(wr.right) - int(wr.left)) * 0.72)
        y = int(wr.top) + int(h_jan * 0.52)
        if _clique_area_colar(x, y, "Cc/%52"):
            return True
    except Exception:
        pass

    registrar_log(
        "AVISO [EMAIL-GAL]: não foquei o campo Cc.",
        "AVISO",
    )
    return False


def _colar_nome_no_cc_outlook(janela, nome: str) -> bool:
    """
    Cola o nome NORMALIZADO no Cc (lugar certo) e espera a GAL sugerir.
    Retorna False se não conseguiu focar o Cc.
    """
    nome = (_normalizar_nome_pessoa_sap(nome) or str(nome or "")).strip()
    if not nome:
        return False
    janela = _janela_outlook_uia(janela)
    if janela is None:
        return False
    if not _garantir_foco_composicao_outlook(janela):
        return False
    _rolar_composicao_outlook_topo(janela)
    if not _focar_linha_cc_outlook(janela):
        return False
    send_keys("{END}")
    time.sleep(0.12)
    # Separador se já houver gerente/SMTP no Cc
    send_keys(";")
    time.sleep(0.12)
    _colar_nome_no_outlook(nome)
    registrar_log(
        f"INFO [EMAIL-GAL]: colado no Cc (campo certo): {nome}",
        "INFO",
    )
    # Espera a 1ª sugestão da GAL aparecer (não clica cedo demais)
    fim = time.time() + 4.5
    while time.time() < fim:
        if _primeira_opcao_gal_outlook(janela):
            break
        # Também detecta cartão "Nome - smtp@..."
        try:
            for c in janela.descendants()[:1200]:
                try:
                    t = (c.window_text() or "").strip()
                except Exception:
                    continue
                if "@" in t and not _parece_lixo_sugestao_gal(t):
                    if _smtp_bate_com_nome(nome, _extrair_email_de_texto(t) or ""):
                        time.sleep(0.35)
                        return True
        except Exception:
            pass
        time.sleep(0.25)
    # Sem sugestão GAL → foco provavelmente não estava no Cc
    if not _primeira_opcao_gal_outlook(janela):
        registrar_log(
            "AVISO [EMAIL-GAL]: colei o nome mas a GAL não sugeriu — "
            "foco provavelmente não estava no Cc; desfazendo.",
            "AVISO",
        )
        try:
            send_keys("^z")
            time.sleep(0.15)
        except Exception:
            pass
        return False
    return True


def _selecionar_primeira_sugestao_gal(janela, nome: str) -> str:
    """Aceita a 1ª sugestão GAL (já destacada) — Enter ou clique; grava SMTP."""
    janela = _janela_outlook_uia(janela)
    # Espera a lista/cartão da GAL (após colar o nome)
    escolha = _aguardar_primeira_opcao_gal(janela, timeout=6.0)
    if not escolha:
        smtp = _clicar_sugestao_email_pessoa(janela, nome)
        return smtp or ""
    item, txt_sug = escolha
    if _parece_lixo_sugestao_gal(txt_sug):
        registrar_log(
            f"AVISO [EMAIL-GAL]: ignorei lixo de sugestão: {txt_sug[:80]}",
            "AVISO",
        )
        return _clicar_sugestao_email_pessoa(janela, nome) or ""
    em_sug = _extrair_email_de_texto(txt_sug) or ""
    if em_sug and not _smtp_bate_com_nome(nome, em_sug):
        return _clicar_sugestao_email_pessoa(janela, nome) or ""
    registrar_log(
        f"INFO [EMAIL-GAL]: 1ª opção — {txt_sug[:110]}",
        "INFO",
    )
    # Sugestão já vem destacada: Enter resolve o chip (mais estável que clique)
    try:
        send_keys("{ENTER}")
        time.sleep(0.55)
    except Exception:
        pass
    smtp = em_sug or _extrair_email_de_texto(txt_sug) or ""
    # Se Enter não resolveu, clica o ListItem
    ainda_texto = False
    try:
        for c in (janela.descendants() if janela is not None else [])[:2500]:
            try:
                t = " ".join((c.window_text() or "").split())
            except Exception:
                continue
            if t.lower() == (nome or "").strip().lower() and "@" not in t:
                ainda_texto = True
                break
    except Exception:
        pass
    if ainda_texto or not smtp:
        try:
            from pywinauto import mouse as _mouse
            r = item.rectangle()
            _mouse.click(coords=(
                (int(r.left) + int(r.right)) // 2,
                (int(r.top) + int(r.bottom)) // 2,
            ))
            time.sleep(0.5)
        except Exception:
            try:
                item.click_input()
                time.sleep(0.5)
            except Exception:
                send_keys("{ENTER}")
                time.sleep(0.4)
        if not smtp:
            smtp = _clicar_sugestao_email_pessoa(janela, nome) or ""
    return smtp or ""


def _parece_linha_caixa_entrada_outlook(txt: str) -> bool:
    """Linha da lista de e-mails / campo De — não é a GAL."""
    tl = (txt or "").lower().strip()
    if "[rascunho]" in tl or "[draft]" in tl:
        return True
    if "sem assunto" in tl or "(no subject)" in tl:
        return True
    # Campo De / From da composição (caiu no teste como 'sugestão')
    if tl.startswith("de:") or tl.startswith("from:"):
        return True
    if tl.startswith("para:") or tl.startswith("to:"):
        return True
    if tl.startswith("cc:") or tl.startswith("cco:"):
        return True
    return False


def _parece_lixo_sugestao_gal(txt: str) -> bool:
    """Descarta linhas que não são a 1ª pessoa da GAL."""
    tl = (txt or "").lower().strip()
    if not tl:
        return True
    if _parece_linha_caixa_entrada_outlook(txt):
        return True
    if any(
        x in tl
        for x in (
            "levi.vasconcelos",
            "mostrar mais",
            "show more",
            "distribui",
            "distribution list",
        )
    ):
        return True
    if re.search(r"\.(zip|rar|7z|exe|msi)\b", tl):
        return True
    if "onenote" in tl or "bloco de anota" in tl or "blocos de anota" in tl:
        return True
    if tl.startswith("aplicativos") or tl == "aplicativos":
        return True
    if re.search(r"pedidos[_\s-]*(servi|mat|frs)", tl) and (
        "abrir" in tl or "kb" in tl or ".zip" in tl
    ):
        return True
    return False


def _janelas_gal_outlook(janela) -> list:
    """Composição + diálogo Verificar nomes / seletor (às vezes é outra janela)."""
    saida = []
    vistos = set()

    def _add(w):
        try:
            h = int(w.handle)
        except Exception:
            h = id(w)
        if h in vistos:
            return
        vistos.add(h)
        saida.append(w)

    if janela is not None:
        _add(janela)
    try:
        import psutil as _ps_gal
        for w in Desktop(backend="uia").windows():
            try:
                n = (_ps_gal.Process(w.process_id()).name() or "").lower()
            except Exception:
                continue
            if n not in ("olk.exe", "outlook.exe"):
                continue
            t = (w.window_text() or "").lower()
            if any(
                p in t
                for p in (
                    "destinat", "recipient", "verificar", "check name",
                    "seletor", "address book", "catálogo", "catalogo",
                )
            ):
                _add(w)
    except Exception:
        pass
    return saida


def _primeira_opcao_gal_outlook(janela):
    """Primeira pessoa visível na lista da GAL (não lista de distribuição)."""
    janela = _janela_outlook_uia(janela)
    try:
        _CacheUIA.invalidar(janela)
    except Exception:
        pass
    brutos = []
    for w in _janelas_gal_outlook(janela):
        try:
            brutos.extend(list(w.descendants(control_type="ListItem"))[:80])
            brutos.extend(list(w.descendants(control_type="DataItem"))[:40])
        except Exception:
            continue
    try:
        wr = janela.rectangle() if janela is not None else None
    except Exception:
        wr = None
    pessoas = []
    for it in brutos[:160]:
        try:
            txt = " ".join((it.window_text() or "").split())
            if len(txt) < 3:
                continue
            if wr is not None:
                try:
                    r = it.rectangle()
                    # Itens do seletor (outra janela) podem ficar fora do
                    # retângulo da composição — não descarta por isso.
                    mesma = True
                    try:
                        mesma = int(it.element_info.handle) == int(janela.handle)
                    except Exception:
                        mesma = False
                    if mesma:
                        if int(r.top) < int(wr.top) or int(r.bottom) > int(wr.bottom):
                            continue
                except Exception:
                    pass
            tl = txt.lower()
            if _parece_lixo_sugestao_gal(txt):
                continue
            if any(
                p in tl
                for p in ("distribui", "distribution list", "lista de dist")
            ):
                continue
            pessoas.append((it, txt))
        except Exception:
            continue
    for it, txt in pessoas:
        if "@" in txt:
            return it, txt
    if pessoas:
        return pessoas[0][0], pessoas[0][1]
    return None


def _aguardar_primeira_opcao_gal(janela, timeout: float = 5.0):
    fim = time.time() + timeout
    while time.time() < fim:
        escolha = _primeira_opcao_gal_outlook(janela)
        if escolha:
            return escolha
        time.sleep(0.2)
    return None


def _escolher_sugestao_gal_outlook(janela, nome_sap: str):
    """Mantido: a resolução usa a primeira opção que aparecer."""
    return _primeira_opcao_gal_outlook(janela)


def _focar_destinatario_via_assunto(janela, alvo: str) -> bool:
    return _focar_campo_destinatario_outlook(janela, alvo)


def _clicar_rotulo_destinatario_outlook(janela, qual: str) -> bool:
    return _focar_linha_cc_outlook(janela) if qual == "cc" else False


def _focar_campo_destinatario_outlook(janela, qual: str) -> bool:
    """Foca o Edit de Para/Cc. Não clica no rótulo (abre o seletor)."""
    if qual == "cc":
        # Só o clique à direita do texto Cc — igual ao teste que passou.
        # Fallback por posição (240,130) caía no assunto/corpo.
        return _focar_linha_cc_outlook(janela)
    chaves = ("para", "to")
    campo = _achar_campo_destinatario_outlook(janela, chaves)
    if campo is not None:
        try:
            campo.click_input()
            time.sleep(0.15)
            return True
        except Exception:
            try:
                campo.set_focus()
                time.sleep(0.15)
                return True
            except Exception:
                pass
    return _clicar_campo_destinatario_por_posicao(janela, qual)


def _clicar_campo_destinatario_por_posicao(janela, qual: str) -> bool:
    """
    Fallback: % da altura da janela (ribbon ~28%, Para ~33%, Cc ~37%).
    y fixo 96/118 caía na faixa de FONTE da ribbon.
    """
    try:
        wr = janela.rectangle()
    except Exception:
        return False
    h = max(1, int(wr.bottom) - int(wr.top))
    w = max(1, int(wr.right) - int(wr.left))
    x = int(wr.left) + int(w * 0.28)
    frac = 0.33 if qual == "para" else 0.37
    y = int(wr.top) + int(h * frac)
    try:
        click(coords=(x, y))
        time.sleep(0.25)
        return True
    except Exception:
        return False


def _colar_nome_no_outlook(texto: str) -> None:
    try:
        _definir_clipboard_texto(texto)
    except Exception:
        try:
            win32clipboard.OpenClipboard()
            win32clipboard.EmptyClipboard()
            win32clipboard.SetClipboardText(texto)
            win32clipboard.CloseClipboard()
        except Exception:
            try:
                win32clipboard.CloseClipboard()
            except Exception:
                pass
    send_keys("^v")


def _apagar_ultimo_destinatario_cc(janela) -> None:
    """Tira o chip vermelho/inválido do Cc antes da próxima tentativa."""
    try:
        _focar_linha_cc_outlook(janela)
        send_keys("{END}")
        time.sleep(0.08)
        send_keys("{BACKSPACE}")
        time.sleep(0.12)
        send_keys("{BACKSPACE}")
        time.sleep(0.12)
    except Exception:
        pass


def _clicar_verificar_nomes_outlook(janela) -> bool:
    """Clica o botão da faixa 'Verificar nomes' (Outlook novo).
    NÃO usa Ctrl+K: isso abre Inserir link."""
    try:
        janela.set_focus()
    except Exception:
        pass
    try:
        _cancelar_dialogos_salvar_abrir()
    except Exception:
        pass
    _ativar_aba_mensagem_outlook(janela)
    time.sleep(0.35)
    btn = None
    candidatos = []
    try:
        for c in janela.descendants()[:7000]:
            try:
                t = (c.window_text() or "").strip().lower()
                tipo = str(c.element_info.control_type or "").lower()
            except Exception:
                continue
            if not t:
                continue
            if "button" not in tipo and "menuitem" not in tipo:
                continue
            # Exact + variantes da faixa
            ok = t in (
                "verificar nomes", "verificar nome",
                "check names", "check name",
            )
            if not ok and "verificar" in t and "nome" in t and len(t) < 40:
                ok = True
            if not ok and "check" in t and "name" in t and len(t) < 40:
                ok = True
            if not ok:
                continue
            score = 10 if t in ("verificar nomes", "check names") else 5
            candidatos.append((score, len(t), c, t))
    except Exception:
        candidatos = []
    if candidatos:
        candidatos.sort(key=lambda x: (-x[0], x[1]))
        btn = candidatos[0][2]
    if btn is None:
        registrar_log(
            "AVISO [EMAIL-GAL]: botão Verificar nomes não encontrado na faixa.",
            "AVISO",
        )
        return False
    try:
        from pywinauto import mouse as _mouse
        r = btn.rectangle()
        _mouse.click(coords=(
            (int(r.left) + int(r.right)) // 2,
            (int(r.top) + int(r.bottom)) // 2,
        ))
    except Exception:
        try:
            btn.click_input()
        except Exception:
            try:
                btn.invoke()
            except Exception:
                return False
    registrar_log("INFO [EMAIL-GAL]: clicado Verificar nomes.", "INFO")
    return True


def _clicar_chip_cc_por_nome(janela, nome: str) -> bool:
    """Clica o chip do destinatário no Cc (abre sugestão da GAL)."""
    toks = _tokens_nome_pessoa(nome)
    if len(toks) < 2:
        return False
    try:
        wr = janela.rectangle()
    except Exception:
        wr = None
    # Faixa do Cc: botão Cc ~y=499 (não os 280px antigos da faixa)
    y_min, y_max = 80, 720
    btn_cc = _botao_rotulo_destinatario_outlook(
        janela, ("cc", "cópia", "copia", "cco")
    )
    if btn_cc is not None and wr is not None:
        try:
            br = btn_cc.rectangle()
            y_min = max(80, int(br.top) - int(wr.top) - 40)
            y_max = int(br.bottom) - int(wr.top) + 80
        except Exception:
            pass
    candidatos = []
    try:
        for c in janela.descendants()[:5000]:
            try:
                t = (c.window_text() or "").strip()
                tipo = str(c.element_info.control_type or "")
            except Exception:
                continue
            if not t or len(t) > 120:
                continue
            tl = t.lower()
            if toks[0] not in tl or toks[-1] not in tl:
                continue
            if "prezada" in tl or "medição" in tl or "faturamento" in tl:
                continue
            # Não clicar no chip de OUTRA pessoa (gerente com SMTP)
            emails_chip = _extrair_emails_de_texto(t)
            if emails_chip and not any(
                _smtp_bate_com_nome(nome, e) for e in emails_chip
            ):
                continue
            # Chip só com outro nome + @ → pular
            if "@" in tl and toks[0] not in tl:
                continue
            try:
                r = c.rectangle()
                if wr is not None:
                    y_rel = int(r.top) - int(wr.top)
                    if y_rel < y_min or y_rel > y_max:
                        continue
                cy = (int(r.top) + int(r.bottom)) // 2
            except Exception:
                continue
            score = 2 if tipo == "Group" else 1
            # Prefere chip só com o nome (sem SMTP de terceiro)
            if not emails_chip and toks[0] in tl and toks[-1] in tl:
                score += 4
            if "inválid" in tl or "invalido" in tl or "invalid" in tl:
                score += 3
            # Penaliza linha que junta gerente+fiscal
            if len(emails_chip) > 1 or (
                emails_chip and not _smtp_bate_com_nome(nome, emails_chip[0])
            ):
                score -= 5
            candidatos.append((score, -abs(cy), c, t))
    except Exception:
        pass
    if not candidatos:
        return False
    candidatos.sort(key=lambda x: (-x[0], x[1]))
    _, _, c, t = candidatos[0]
    try:
        from pywinauto import mouse as _mouse
        r = c.rectangle()
        _mouse.click(coords=(
            (int(r.left) + int(r.right)) // 2,
            (int(r.top) + int(r.bottom)) // 2,
        ))
    except Exception:
        try:
            c.click_input()
        except Exception:
            return False
    registrar_log(
        f"INFO [EMAIL-GAL]: clicado chip Cc '{t[:60]}'",
        "INFO",
    )
    return True


def _smtp_bate_com_nome(nome: str, email: str) -> bool:
    """
    SMTP da sugestão tem que ser da pessoa (não o gerente no mesmo Cc).
    Ex.: Mariana → mariana.dantas@… ; rejeita andre.f.alves@…
    """
    email = (email or "").strip().lower()
    if "@" not in email:
        return False
    local = (
        email.split("@")[0]
        .replace(".", " ")
        .replace("_", " ")
        .replace("-", " ")
        .lower()
    )
    toks = _tokens_nome_pessoa(nome)
    if len(toks) < 2:
        return False
    if toks[0] not in local:
        return False
    return any(t in local for t in toks[1:])


def _clicar_sugestao_email_pessoa(janela, nome_sap: str) -> str:
    """
    1ª sugestão com SMTP da PESSOA (não outro chip do Cc).
    Ex.: 'Mariana Dantas Rodrigues - mariana.dantas@petrobras.com.br'
    """
    toks = _tokens_nome_pessoa(nome_sap)
    fim = time.time() + 12
    while time.time() < fim:
        candidatos = []
        wins = list(_janelas_gal_outlook(janela) or [])
        try:
            import psutil as _ps_sug
            for w in Desktop(backend="uia").windows():
                try:
                    n = (_ps_sug.Process(w.process_id()).name() or "").lower()
                except Exception:
                    continue
                if n in ("olk.exe", "outlook.exe"):
                    wins.append(w)
        except Exception:
            pass
        vistos = set()
        for w in wins:
            try:
                h = int(w.handle)
            except Exception:
                h = id(w)
            if h in vistos:
                continue
            vistos.add(h)
            try:
                ctrls = list(w.descendants()[:4500])
            except Exception:
                continue
            for c in ctrls:
                try:
                    txt = " ".join((c.window_text() or "").split())
                    tipo = str(c.element_info.control_type or "")
                except Exception:
                    continue
                if not txt or len(txt) < 5 or "@" not in txt:
                    continue
                if _parece_lixo_sugestao_gal(txt):
                    continue
                tl = txt.lower()
                if "mostrar mais" in tl:
                    continue
                emails = _extrair_emails_de_texto(txt)
                if not emails:
                    em0 = _extrair_email_de_texto(txt)
                    emails = [em0] if em0 else []
                # Vários SMTP no mesmo controle = linha inteira do Cc — pular
                if len(emails) > 1:
                    continue
                for em in emails:
                    em_l = em.lower()
                    if any(
                        x in em_l
                        for x in ("levi.vasconcelos", "livia@", "noreply")
                    ):
                        continue
                    # Obrigatório: e-mail é da pessoa pedida
                    if not _smtp_bate_com_nome(nome_sap, em):
                        continue
                    score = 5
                    if "@petrobras" in em_l:
                        score += 2
                    if toks and toks[0] in tl:
                        score += 2
                    if toks and len(toks) >= 2 and toks[1] in tl:
                        score += 2
                    if tipo in ("ListItem", "DataItem", "Button", "Text"):
                        score += 2
                    if tipo == "Group" and len(txt) > 120:
                        score -= 3
                    # Prefere cartão curto "Nome - smtp"
                    score -= min(8, len(txt) // 40)
                    candidatos.append((score, c, em, txt))
        if candidatos:
            candidatos.sort(key=lambda x: (-x[0], len(x[3])))
            _, item, em, txt = candidatos[0]
            if not _smtp_bate_com_nome(nome_sap, em):
                time.sleep(0.3)
                continue
            registrar_log(
                f"INFO [EMAIL-GAL]: 1ª sugestão — {txt[:110]}",
                "INFO",
            )
            try:
                from pywinauto import mouse as _mouse
                r = item.rectangle()
                _mouse.click(coords=(
                    (int(r.left) + int(r.right)) // 2,
                    (int(r.top) + int(r.bottom)) // 2,
                ))
            except Exception:
                try:
                    item.click_input()
                except Exception:
                    try:
                        send_keys("{ENTER}")
                    except Exception:
                        return ""
            time.sleep(0.7)
            return em.strip()
        time.sleep(0.3)
    return ""


def _escolher_pessoa_seletor_outlook(janela, nome_sap: str) -> str:
    """
    Chip vermelho: clica a primeira pessoa da GAL (Verificar nomes).
    O SMTP vem do que o Outlook mostrar — não se monta e-mail
    a partir do nome (ponto, número ou qualquer outro padrão).
    Não dá ESC: ESC fecha o seletor e o chip fica vermelho.
    """
    # Preferir popup com e-mail visível (Outlook novo)
    smtp = _clicar_sugestao_email_pessoa(janela, nome_sap)
    if smtp:
        return smtp
    escolha = _aguardar_primeira_opcao_gal(janela, timeout=6.0)
    if not escolha:
        return ""
    item, txt = escolha
    registrar_log(
        f"INFO [EMAIL-GAL]: primeira indicação — {txt[:110]}",
        "INFO",
    )
    try:
        from pywinauto import mouse as _mouse
        r = item.rectangle()
        _mouse.click(coords=(
            (int(r.left) + int(r.right)) // 2,
            (int(r.top) + int(r.bottom)) // 2,
        ))
    except Exception:
        try:
            item.click_input()
        except Exception:
            send_keys("{ENTER}")
    time.sleep(0.5)
    send_keys("{ENTER}")
    time.sleep(0.7)
    smtp = _extrair_email_de_texto(txt) or ""
    if not smtp:
        smtp = _clicar_sugestao_email_pessoa(janela, nome_sap)
    if smtp:
        return smtp
    if _chip_cc_resolvido_outlook(janela, nome_sap):
        return "__CHIP_OK__"
    return ""


def _clicar_primeira_sugestao_gal_apos_vn(janela, nome: str = "") -> str:
    """
    Depois de 'Verificar nomes': a 1ª sugestão que o Outlook mostra
    é a do chip vermelho atual. Clica nela (não no campo De:/From).
    """
    nome_limpo = _normalizar_nome_pessoa_sap(nome) or (nome or "")
    fim = time.time() + 7.0
    while time.time() < fim:
        # Prefere cartão com SMTP da pessoa, se já aparecer
        if nome_limpo:
            smtp = _clicar_sugestao_email_pessoa(janela, nome_limpo)
            if smtp:
                return smtp
        escolha = _primeira_opcao_gal_outlook(janela)
        if escolha:
            item, txt = escolha
            if _parece_lixo_sugestao_gal(txt):
                time.sleep(0.25)
                continue
            em = _extrair_email_de_texto(txt) or ""
            registrar_log(
                f"INFO [EMAIL-GAL]: 1ª sugestão (após VN) — {txt[:110]}",
                "INFO",
            )
            try:
                from pywinauto import mouse as _mouse
                r = item.rectangle()
                _mouse.click(coords=(
                    (int(r.left) + int(r.right)) // 2,
                    (int(r.top) + int(r.bottom)) // 2,
                ))
            except Exception:
                try:
                    item.click_input()
                except Exception:
                    send_keys("{DOWN}{ENTER}")
            time.sleep(0.7)
            if em:
                return em.strip()
            if nome_limpo and _chip_cc_resolvido_outlook(janela, nome_limpo):
                return "__CHIP_OK__"
            return "__CHIP_OK__"
        time.sleep(0.3)
    return ""


def _resolver_via_verificar_nomes(janela, nomes_pend: list) -> list:
    """
    Caminho PRINCIPAL (um chip vermelho por vez):
      Verificar nomes → espera → clica a 1ª sugestão
      (repete VN para o próximo chip)
    NÃO cola nome aqui — colar é só fallback externo quando VN
    esgotar as tentativas (ver _resolver_destinatario_obrigatorio_ou_falhar).
    """
    if not nomes_pend:
        return []
    restantes = list(nomes_pend)
    resolvidos = []
    for nome in list(restantes):
        nome_limpo = _normalizar_nome_pessoa_sap(nome) or nome
        if _chip_cc_resolvido_outlook(janela, nome_limpo):
            registrar_log(
                f"OK [EMAIL-GAL]: '{nome_limpo}' já resolvido.",
                "OK",
            )
            resolvidos.append(nome)
            if nome_limpo != nome:
                resolvidos.append(nome_limpo)
            continue
        try:
            _cancelar_dialogos_salvar_abrir()
        except Exception:
            pass
        try:
            janela.set_focus()
        except Exception:
            pass
        time.sleep(0.25)
        smtp = ""

        registrar_log(
            f"INFO [EMAIL-GAL]: Verificar nomes → 1ª sugestão — {nome_limpo}",
            "INFO",
        )
        # Até 2× VN neste chip antes de desistir (sem colar nome)
        for _vn_try in range(1, 3):
            if not _clicar_verificar_nomes_outlook(janela):
                break
            time.sleep(0.8)
            smtp = _clicar_primeira_sugestao_gal_apos_vn(janela, nome_limpo)
            if smtp:
                break
            registrar_log(
                f"AVISO [EMAIL-GAL]: VN {_vn_try}/2 sem sugestão para "
                f"'{nome_limpo}'.",
                "AVISO",
            )
            time.sleep(0.35)

        if not smtp and _chip_cc_resolvido_outlook(janela, nome_limpo):
            smtp = "__CHIP_OK__"
        if not smtp:
            continue
        if smtp != "__CHIP_OK__" and "@" in smtp:
            try:
                for chave_n in (nome, nome_limpo):
                    if not chave_n:
                        continue
                    _emails_arquivo_salvar(chave_n, smtp)
                    _cache_email_gal[chave_n.lower()] = smtp
                tit = _titulo_nome_pessoa(nome_limpo)
                if tit:
                    _emails_arquivo_salvar(tit, smtp)
                    _cache_email_gal[tit.lower()] = smtp
            except Exception:
                pass
            registrar_log(
                f"OK [EMAIL-GAL]: '{nome_limpo}' → {smtp}",
                "OK",
            )
        else:
            registrar_log(
                f"OK [EMAIL-GAL]: '{nome_limpo}' (chip válido na GAL).",
                "OK",
            )
        resolvidos.append(nome)
        if nome_limpo != nome and nome_limpo not in resolvidos:
            resolvidos.append(nome_limpo)
        time.sleep(0.4)
    return [
        n for n in restantes
        if n not in resolvidos
        and (_normalizar_nome_pessoa_sap(n) or n) not in resolvidos
    ]


def _chip_cc_resolvido_outlook(janela, nome: str) -> bool:
    """
    Chip válido no Outlook novo: 'offlineNome' / 'availableNome',
    igual Jucimara. Nome solto ou 'Destinatário inválido' não vale.
    """
    if _composicao_outlook_invalida(janela):
        return False
    toks = _tokens_nome_pessoa(nome)
    if len(toks) < 2:
        return False
    try:
        for c in janela.descendants()[:1400]:
            try:
                t = (c.window_text() or "").strip()
                tipo = str(c.element_info.control_type or "")
            except Exception:
                continue
            if tipo != "Group" or not t:
                continue
            tl = t.lower()
            if toks[0] not in tl or toks[-1] not in tl:
                continue
            if "inválid" in tl or "invalido" in tl or "invalid" in tl:
                return False
            if any(
                p in tl
                for p in ("offline", "available", "away", "busy")
            ):
                return True
    except Exception:
        pass
    return False


def _resolver_destinatario_obrigatorio_ou_falhar(
    janela_comp, nomes_pend: list, esperados: list, anexar_cc: bool = True,
    tentativas: int = 2,
) -> None:
    """
    1ª vez (sem SMTP salvo): cola o nome completo no Cc + 1ª sugestão
    da GAL e grava o SMTP. Nas próximas, o .eml já leva o SMTP.
    Não usa Verificar nomes (faixa/diálogos corrompiam assunto/corpo).
    """
    if not nomes_pend:
        return
    _faltando = list(nomes_pend)
    vezes = max(1, int(tentativas or 2))

    def _atualizar_esperados():
        for esp in esperados or []:
            if not isinstance(esp, dict) or _smtp_de_item(esp.get("email") or ""):
                continue
            nome_e = (esp.get("nome") or "").strip()
            if not nome_e:
                continue
            em = _smtp_de_item(
                _cache_email_gal.get(nome_e.lower(), "")
                or _emails_arquivo_carregar().get(nome_e.lower(), "")
            )
            if em:
                esp["email"] = em

    for _tent in range(1, vezes + 1):
        for _ in range(2):
            try:
                _cancelar_dialogos_salvar_abrir()
            except Exception:
                pass
            if _garantir_foco_composicao_outlook(janela_comp):
                break
            time.sleep(0.2)
        registrar_log(
            f"INFO [EMAIL-GAL]: cola nome + 1ª sugestão "
            f"{_tent}/{vezes} — " + "; ".join(_faltando),
            "INFO",
        )
        try:
            # Só apaga chip vermelho do próprio nome; não remove Levi/SMTP.
            for _n in list(_faltando):
                if _composicao_outlook_invalida(janela_comp) and (
                    not _chip_cc_resolvido_outlook(janela_comp, _n)
                ):
                    blob_cc, _ = _ler_texto_composicao_outlook(janela_comp)
                    toks = _tokens_nome_pessoa(_n)
                    bl = (blob_cc or "").lower()
                    if len(toks) >= 2 and toks[0] in bl and toks[-1] in bl:
                        _apagar_ultimo_destinatario_cc(janela_comp)
            _resolver_destinatarios_gal_na_composicao(
                janela_comp, "", "",
                anexar_cc=True,
                nomes_cc=list(_faltando),
                persistir_smtp=True,
            )
            time.sleep(0.5)
            _atualizar_esperados()
            _faltando = [
                n for n in _faltando
                if not _chip_cc_resolvido_outlook(janela_comp, n)
                and not _smtp_de_item(
                    _cache_email_gal.get(n.lower(), "")
                    or _emails_arquivo_carregar().get(n.lower(), "")
                )
            ]
        except Exception as e_fb:
            registrar_log(
                f"AVISO [EMAIL-GAL]: cola/sugestão {_tent} — {e_fb}",
                "AVISO",
            )
        if not _faltando and not _composicao_outlook_invalida(janela_comp):
            print("  [EMAIL-GAL] Destinatário(s) confirmado(s) (cola + 1ª sugestão).")
            registrar_log(
                "OK [EMAIL-GAL]: destinatário(s) resolvidos "
                "(cola + 1ª sugestão; SMTP gravado).",
                "OK",
            )
            return
        if _tent < vezes:
            time.sleep(0.4)

    if _faltando or _composicao_outlook_invalida(janela_comp):
        raise Exception(
            "Não foi possível resolver o(s) destinatário(s) "
            f"{_faltando or nomes_pend}."
        )
    print("  [EMAIL-GAL] Destinatário(s) confirmado(s).")
    registrar_log("OK [EMAIL-GAL]: destinatário(s) resolvidos.", "OK")


def _resolver_destinatarios_gal_na_composicao(
    janela, para_str: str, cc_str: str,
    anexar_para: bool = False, anexar_cc: bool = False,
    nomes_cc=None,
    persistir_smtp: bool = True,
) -> None:
    """
    No Outlook novo não há COM, mas a GAL da conta logada é a mesma:
    cola o nome do SAP no Para/Cc e aceita a sugestão, como quando
    se digita o nome no clássico.
    anexar_*=True preserva endereços SMTP já vindos do .eml.
    persistir_smtp=False: fallback de erro — só cache em memória.
    """
    def _preencher(chaves, nomes, rotulo, qual_pos, anexar):
        nomes = [n for n in nomes if n]
        if not nomes:
            return
        if not _garantir_foco_composicao_outlook(janela):
            registrar_log(
                f"INFO [EMAIL-GAL]: campo {rotulo} não focado — "
                "mantido o destinatário já gravado no .eml.",
                "INFO",
            )
            return
        # Cc: _colar_nome_no_cc_outlook já foca a área de colar (evita 2–3 cliques).
        if qual_pos != "cc":
            focado = _focar_campo_destinatario_outlook(janela, qual_pos)
            if not focado:
                registrar_log(
                    f"INFO [EMAIL-GAL]: campo {rotulo} não focado — "
                    "mantido o destinatário já gravado no .eml.",
                    "INFO",
                )
                return
            time.sleep(0.25)
        for nome in nomes:
            if "@" in str(nome):
                continue
            busca = _normalizar_nome_pessoa_sap(nome) or (
                _titulo_nome_pessoa(nome) or nome
            )
            blob_cc, _ = _ler_texto_composicao_outlook(janela)
            ja_visivel = _destinatario_ok_na_ui(
                {"nome": busca, "email": ""}, blob_cc, set(),
            )
            erro_chip = _composicao_outlook_invalida(janela)
            if ja_visivel and not erro_chip:
                registrar_log(
                    f"OK [EMAIL-GAL]: {rotulo} '{busca}' já no Cc pelo .eml "
                    "— não colo de novo.",
                    "OK",
                )
                continue
            if ja_visivel and erro_chip:
                registrar_log(
                    f"AVISO [EMAIL-GAL]: chip inválido para '{busca}' — "
                    "apago e resolvo uma vez na GAL.",
                    "AVISO",
                )
                _apagar_ultimo_destinatario_cc(janela)
            if not _garantir_foco_composicao_outlook(janela):
                registrar_log(
                    f"AVISO [EMAIL-GAL]: {rotulo} sem foco no Outlook — "
                    "não colo (diálogo de arquivo?).",
                    "AVISO",
                )
                continue
            if qual_pos == "cc":
                if not _colar_nome_no_cc_outlook(janela, busca):
                    continue
                _em_item = _selecionar_primeira_sugestao_gal(janela, nome)
            else:
                if not _focar_campo_destinatario_outlook(janela, qual_pos):
                    registrar_log(
                        f"AVISO [EMAIL-GAL]: {rotulo} perdeu o foco — "
                        "não colo no corpo/assunto.",
                        "AVISO",
                    )
                    continue
                send_keys("{END}")
                time.sleep(0.1)
                _colar_nome_no_outlook(busca)
                registrar_log(
                    f"INFO [EMAIL-GAL]: colado no {rotulo} o nome completo: {busca}",
                    "INFO",
                )
                time.sleep(0.5)
                _em_item = _selecionar_primeira_sugestao_gal(janela, nome)
            time.sleep(0.5)
            erro_ui = _composicao_outlook_invalida(janela)
            if erro_ui:
                registrar_log(
                    f"ERRO [EMAIL-GAL]: {rotulo} '{busca}' ficou "
                    f"vermelho — {erro_ui}. Próxima tentativa com "
                    "o nome completo e a primeira opção da GAL.",
                    "ERRO",
                )
                raise Exception(f"destinatário vermelho: {erro_ui}")
            if _em_item:
                try:
                    _cache_email_gal[nome.lower()] = _em_item
                    tit = _titulo_nome_pessoa(nome)
                    if tit:
                        _cache_email_gal[tit.lower()] = _em_item
                    so = _apenas_nome_gerente(nome)
                    if so:
                        _cache_email_gal[so.lower()] = _em_item
                    ch = _extrair_chave_sap(nome)
                    if ch:
                        _cache_email_gal[ch.lower()] = _em_item
                    if persistir_smtp:
                        _emails_arquivo_salvar(nome, _em_item)
                        if tit:
                            _emails_arquivo_salvar(tit, _em_item)
                        if so:
                            _emails_arquivo_salvar(so, _em_item)
                        if ch:
                            _emails_arquivo_salvar(ch, _em_item)
                except Exception:
                    pass
            registrar_log(
                f"OK [EMAIL-GAL]: {rotulo} '{nome}' → "
                + (f"{_em_item}" if _em_item else "(sem SMTP na sugestão)")
            )

    try:
        _preencher(
            ("para", "to"),
            _partir_destinatarios_email(para_str),
            "Para",
            "para",
            anexar_para,
        )
        _preencher(
            ("cc", "cco", "bcc", "cópia", "copia"),
            list(nomes_cc or []) or _partir_destinatarios_email(cc_str),
            "Cc",
            "cc",
            anexar_cc,
        )
    except Exception as e:
        registrar_log(f"ERRO [EMAIL-GAL]: resolução na composição: {e}", "ERRO")
        raise


def _smtp_de_item(item: str) -> str:
    m = re.search(r"<?([^<>;\s]+@[^<>;\s]+)>?", item or "")
    em = (m.group(1) if m else (item or "")).strip()
    if "@" in em and "." in em.split("@")[-1]:
        return em
    return ""


def _ler_texto_composicao_outlook(janela) -> tuple:
    partes = []
    try:
        partes.append(janela.window_text() or "")
    except Exception:
        pass
    try:
        for c in janela.descendants()[:900]:
            try:
                t = (c.window_text() or "").strip()
                if t:
                    partes.append(t)
            except Exception:
                continue
            try:
                n = (c.element_info.name or "").strip()
                if n:
                    partes.append(n)
            except Exception:
                pass
            try:
                v = c.get_value()
                if v:
                    partes.append(str(v).strip())
            except Exception:
                pass
    except Exception:
        pass
    blob = " ".join(partes)
    emails = {e.lower() for e in _extrair_emails_de_texto(blob)}
    return blob, emails


def _composicao_outlook_invalida(janela) -> str:
    """Erro real de destinatário (não o aviso 'fora da organização')."""
    padroes = (
        "não foi possível reconhecer",
        "couldn't find",
        "no suggestions",
        "não reconhec",
        "invalid recipient",
        "we didn't find",
        "não encontramos",
        "check the email",
        "verifique o endereço",
        "is not valid",
        "não é válido",
        "destinatário inválido",
        "destinatario invalido",
    )
    ignorar = (
        "fora da sua organização",
        "outside your organization",
        "external",
    )
    try:
        for c in janela.descendants()[:900]:
            try:
                t = (c.window_text() or "").strip()
            except Exception:
                continue
            tl = t.lower()
            if not t or len(t) > 220:
                continue
            if any(p in tl for p in ignorar):
                continue
            if any(p in tl for p in padroes):
                return t
            if ("inválid" in tl or "invalido" in tl or "invalid" in tl) and (
                "destinat" in tl
            ):
                return t
    except Exception:
        pass
    return ""


def _destinatario_ok_na_ui(esp: dict, blob: str, emails_ui: set) -> bool:
    """
    Outlook novo mostra chip de NOME (Andre Filipe…), não o SMTP.
    Aceita SMTP, parte local (patricia.tosta → patricia tosta) ou
    primeiro+último nome.
    """
    em = _smtp_de_item(esp.get("email") or "")
    nome = (esp.get("nome") or "").strip()
    bl = (blob or "").lower()
    if em:
        em_l = em.lower()
        if em_l in emails_ui or em_l in bl:
            return True
        local = em.split("@")[0].lower()
        if len(local) >= 4 and local in bl:
            return True
        local_esp = local.replace(".", " ").replace("_", " ").replace("-", " ")
        if local_esp and local_esp in bl:
            return True
        toks_l = [p for p in re.split(r"[.\-_]+", local) if len(p) > 1]
        if len(toks_l) >= 2 and toks_l[0] in bl and toks_l[-1] in bl:
            return True
    toks = _tokens_nome_pessoa(nome)
    if len(toks) >= 2 and toks[0] in bl and toks[-1] in bl:
        return True
    return False


def _validar_destinatarios_na_ui(janela, esperados: list) -> tuple:
    """
    Confere Para e Cc (manuais e automáticos). Sem SMTP confirmado
    o destinatário não passa — nome solto no chip vermelho não vale.
    """
    if not esperados:
        return False, ["nenhum destinatário esperado"]
    blob, emails_ui = _ler_texto_composicao_outlook(janela)
    erro = _composicao_outlook_invalida(janela)
    if erro:
        registrar_log(
            f"ERRO [EMAIL]: Outlook marcou destinatário inválido: {erro}",
            "ERRO",
        )
    faltando = []
    for esp in esperados:
        nome = (esp.get("nome") or "").strip()
        em = _smtp_de_item(esp.get("email") or "")
        if not em and nome:
            for chave_c in (
                nome.lower(),
                (_apenas_nome_gerente(nome) or "").lower(),
                (_extrair_chave_sap(nome) or "").lower(),
            ):
                if not chave_c:
                    continue
                em = _smtp_de_item(
                    _cache_email_gal.get(chave_c, "")
                    or _emails_arquivo_carregar().get(chave_c, "")
                )
                if em:
                    esp["email"] = em
                    break
        rotulo = em or nome or "?"
        if not em:
            if erro:
                registrar_log(
                    f"ERRO [EMAIL]: {rotulo} em vermelho — "
                    "não segue como se o rascunho estivesse certo.",
                    "ERRO",
                )
                faltando.append(rotulo)
                continue
            if _chip_cc_resolvido_outlook(janela, nome):
                registrar_log(
                    f"OK [EMAIL-VALIDA]: {esp.get('campo','')} {rotulo} "
                    "(chip válido na GAL).",
                    "OK",
                )
                continue
            registrar_log(
                f"ERRO [EMAIL]: {rotulo} sem SMTP — não pode ir no rascunho.",
                "ERRO",
            )
            faltando.append(rotulo)
            continue
        if _destinatario_ok_na_ui(esp, blob, emails_ui):
            registrar_log(
                f"OK [EMAIL-VALIDA]: {esp.get('campo','')} {rotulo}",
                "OK",
            )
        elif em and not erro:
            # WebView2 do Outlook novo não expõe o SMTP do chip.
            # Sem aviso de destinatário inválido, o .eml já gravou o Cc.
            registrar_log(
                f"OK [EMAIL-VALIDA]: {esp.get('campo','')} {rotulo} "
                "(chip no Outlook; SMTP no .eml).",
                "OK",
            )
        else:
            registrar_log(
                f"ERRO [EMAIL-VALIDA]: não confirmei {rotulo} "
                f"no {esp.get('campo','campo')} do rascunho.",
                "ERRO",
            )
            faltando.append(rotulo)
    if erro and not faltando:
        registrar_log(
            f"AVISO [EMAIL-VALIDA]: Outlook marcou aviso "
            f"({erro}) — destinatários já estão no rascunho.",
            "AVISO",
        )
    return (not faltando), faltando


def _validar_recipients_outlook_com(mail, esperados: list) -> tuple:
    achados = []
    try:
        mail.Recipients.ResolveAll()
    except Exception:
        pass
    try:
        n = int(mail.Recipients.Count)
    except Exception:
        n = 0
    for i in range(1, n + 1):
        try:
            r = mail.Recipients.Item(i)
        except Exception:
            continue
        smtp = ""
        try:
            eu = r.AddressEntry.GetExchangeUser()
            if eu:
                smtp = (eu.PrimarySmtpAddress or "").strip()
        except Exception:
            pass
        if not smtp:
            try:
                smtp = _smtp_de_item(r.Address or "")
            except Exception:
                smtp = ""
        resolved = False
        try:
            resolved = bool(r.Resolved)
        except Exception:
            resolved = bool(smtp)
        nome_r = ""
        try:
            nome_r = r.Name or ""
        except Exception:
            pass
        achados.append((resolved, smtp.lower(), nome_r.lower()))
    faltando = []
    for esp in esperados:
        em = _smtp_de_item(esp.get("email") or "").lower()
        toks = _tokens_nome_pessoa(esp.get("nome") or "")
        ok = False
        for resolved, smtp, nome_r in achados:
            if em and smtp == em and resolved:
                ok = True
                break
            if em and em.split("@")[0] in smtp and resolved:
                ok = True
                break
            if toks and len(toks) >= 2 and toks[0] in nome_r and toks[-1] in nome_r and resolved:
                ok = True
                break
        if not ok:
            faltando.append(em or esp.get("nome") or "?")
    return (not faltando), faltando


def _janela_principal_outlook_novo():
    """Janela principal do olk (lista), não a composição."""
    import psutil as _ps
    melhor = None
    melhor_area = 0
    try:
        for w in Desktop(backend="uia").windows():
            try:
                nome = (_ps.Process(w.process_id()).name() or "").lower()
                if nome != "olk.exe":
                    continue
                tit = (w.window_text() or "").strip()
                tl = tit.lower()
                if not tit:
                    continue
                # Composição costuma ter o assunto longo no título
                if " - dados para faturamento" in tl or "teste " in tl[:20]:
                    continue
                r = w.rectangle()
                area = max(0, int(r.right - r.left)) * max(0, int(r.bottom - r.top))
                if area > melhor_area:
                    melhor_area = area
                    melhor = w
            except Exception:
                continue
    except Exception:
        return None
    return melhor


def _abrir_pasta_rascunhos_outlook(janela) -> bool:
    """Clica Rascunhos / Drafts na navegação do Outlook novo."""
    if janela is None:
        return False
    try:
        janela.set_focus()
    except Exception:
        pass
    time.sleep(0.3)
    alvos = ("rascunhos", "drafts")
    candidatos = []
    try:
        for c in janela.descendants()[:5000]:
            try:
                t = (c.window_text() or "").strip()
                if not t:
                    continue
                tl = t.lower()
                tipo = str(c.element_info.control_type or "")
            except Exception:
                continue
            ok_nome = False
            for a in alvos:
                if tl == a or tl.startswith(a):
                    ok_nome = True
                    break
                if a in tl and len(t) < 60:
                    ok_nome = True
                    break
            if not ok_nome:
                continue
            if tipo not in (
                "TreeItem", "ListItem", "Button", "Text",
                "Hyperlink", "TabItem", "DataItem",
            ):
                continue
            try:
                r = c.rectangle()
                x = (int(r.left) + int(r.right)) // 2
            except Exception:
                x = 0
            score = 5 if tipo == "TreeItem" else (
                3 if tipo in ("ListItem", "DataItem") else 1
            )
            if tl.startswith(alvos[0]) or tl.startswith(alvos[1]):
                score += 4
            candidatos.append((score, x, c, t))
    except Exception:
        pass
    if not candidatos:
        registrar_log(
            "AVISO [EMAIL]: pasta Rascunhos não encontrada na navegação.",
            "AVISO",
        )
        return False
    candidatos.sort(key=lambda x: (-x[0], x[1]))
    _, _, ctrl, nome = candidatos[0]
    try:
        from pywinauto import mouse as _mouse
        r = ctrl.rectangle()
        _mouse.click(coords=(
            (int(r.left) + int(r.right)) // 2,
            (int(r.top) + int(r.bottom)) // 2,
        ))
    except Exception:
        try:
            ctrl.click_input()
        except Exception:
            return False
    registrar_log(f"INFO [EMAIL]: abriu pasta '{nome[:40]}'.", "INFO")
    time.sleep(1.2)
    return True


def _trecho_assunto_para_rascunho(assunto: str) -> str:
    """Trecho estável do assunto para achar o item certo entre vários rascunhos."""
    a = " ".join((assunto or "").split())
    if not a:
        return ""
    # Contrato SAP no assunto (ex.: 4600674798) é o melhor discriminador
    m = re.search(r"\b(46\d{8})\b", a)
    if m:
        return m.group(1)
    if len(a) > 48:
        return a[:48].strip()
    return a


def _achar_item_rascunho_por_assunto(janela, assunto: str):
    """
    Na lista de Rascunhos, acha o item do nosso e-mail.
    Com vários rascunhos: prioriza o nº do contrato (46xxxxxxxx);
    não abre o 'primeiro da lista' por clique cego.
    """
    if janela is None:
        return None
    assunto_l = " ".join((assunto or "").lower().split())
    chave = _trecho_assunto_para_rascunho(assunto).lower()
    contrato = bool(re.fullmatch(r"46\d{8}", chave or ""))
    if not assunto_l and not chave:
        return None
    candidatos = []
    try:
        ctrls = list(janela.descendants()[:8000])
    except Exception:
        ctrls = []
    for c in ctrls:
        try:
            t = " ".join((c.window_text() or "").split())
            if not t or len(t) < 8:
                continue
            tl = t.lower()
            tipo = str(c.element_info.control_type or "")
        except Exception:
            continue
        if tipo not in (
            "ListItem", "DataItem", "TreeItem", "Button", "Text", "Group",
        ):
            continue
        # Nunca abrir e-mail de diagnóstico / erro da automação
        if "erro na automação" in tl or "erro na automacao" in tl:
            continue
        if tl.startswith("erro na"):
            continue
        # Com contrato no assunto: só entra quem tem o mesmo nº
        if contrato and chave not in tl:
            continue
        # Rascunho de medição: precisa parecer o nosso (não Caixa de Entrada)
        parece_nosso = (
            "dados para faturamento" in tl
            or "infrared" in tl
            or "[rascunho]" in tl
            or "[draft]" in tl
        )
        if contrato and not parece_nosso:
            continue
        bate = False
        if assunto_l and assunto_l in tl:
            bate = True
        elif chave and chave in tl and parece_nosso:
            bate = True
        elif (not contrato) and len(assunto_l) >= 24 and assunto_l[:24] in tl:
            bate = True
        if not bate:
            continue
        score = 0
        if tipo in ("ListItem", "DataItem"):
            score += 4
        if "[rascunho]" in tl or "[draft]" in tl:
            score += 8
        if assunto_l and assunto_l in tl:
            score += 8
        if chave and chave in tl:
            score += 10 if contrato else 5
        if "dados para faturamento" in tl:
            score += 6
        if "infrared" in tl:
            score += 4
        if "sem assunto" in tl or "(no subject)" in tl:
            score -= 5
        # Linha da lista, não o painel inteiro
        if len(t) > 350:
            score -= 4
        # Score mínimo alto: evita abrir item fraco da Caixa de Entrada
        if score < 14:
            continue
        try:
            r = c.rectangle()
            top = int(r.top)
        except Exception:
            top = 0
        candidatos.append((score, top, c, t))
    if not candidatos:
        registrar_log(
            f"AVISO [EMAIL]: nenhum rascunho na lista bate com "
            f"{'contrato ' + chave if contrato else assunto_l[:40]!r}.",
            "AVISO",
        )
        return None
    # Melhor score; se empatar, o mais acima (mais recente na lista)
    candidatos.sort(key=lambda x: (-x[0], x[1]))
    melhor = candidatos[0]
    registrar_log(
        f"INFO [EMAIL]: {len(candidatos)} rascunho(s) candidato(s); "
        f"aberto (score={melhor[0]}): {melhor[3][:90]!r}",
        "INFO",
    )
    return melhor[2]


def _abrir_item_rascunho_outlook(item) -> bool:
    """Abre o rascunho (duplo clique / Enter)."""
    if item is None:
        return False
    try:
        from pywinauto import mouse as _mouse
        r = item.rectangle()
        cx = (int(r.left) + int(r.right)) // 2
        cy = (int(r.top) + int(r.bottom)) // 2
        _mouse.click(coords=(cx, cy))
        time.sleep(0.35)
        _mouse.double_click(coords=(cx, cy))
    except Exception:
        try:
            item.click_input()
            time.sleep(0.2)
            item.double_click_input()
        except Exception:
            try:
                item.set_focus()
                send_keys("{ENTER}")
            except Exception:
                return False
    time.sleep(1.5)
    return True


def _composicao_por_assunto_outlook(assunto: str, timeout: float = 15.0):
    """Espera a janela/aba de composição com o assunto."""
    import psutil as _ps
    trecho = (assunto or "").lower()
    if not trecho:
        return None
    chave = _trecho_assunto_para_rascunho(assunto).lower()
    fim = time.time() + timeout
    while time.time() < fim:
        try:
            for w in Desktop(backend="uia").windows():
                try:
                    tit = (w.window_text() or "").strip()
                    tl = tit.lower()
                    if not tit:
                        continue
                    nome = (_ps.Process(w.process_id()).name() or "").lower()
                    if nome not in ("olk.exe", "outlook.exe"):
                        continue
                    if trecho in tl or (chave and chave in tl):
                        if tl in ("outlook", "mail", "e-mail"):
                            continue
                        return w
                except Exception:
                    continue
        except Exception:
            pass
        time.sleep(0.4)
    return None


def _assunto_na_composicao_outlook(janela) -> str:
    """Assunto atual: título da janela ou campo Assunto/Subject."""
    try:
        tit = (janela.window_text() or "").strip()
    except Exception:
        tit = ""
    # Composição costuma usar o próprio assunto como título
    if tit and tit.lower() not in ("outlook", "mail", "e-mail", "mensagem"):
        # Remove sufixos tipo " - Mensagem"
        tit2 = re.sub(
            r"\s*[-–]\s*(mensagem|message|outlook).*$",
            "",
            tit,
            flags=re.I,
        ).strip()
        if tit2:
            return tit2
    try:
        for c in janela.descendants()[:2500]:
            try:
                nome = (c.element_info.name or "").strip().lower()
                tipo = str(c.element_info.control_type or "")
                val = ""
                try:
                    val = str(c.get_value() or "").strip()
                except Exception:
                    val = (c.window_text() or "").strip()
            except Exception:
                continue
            if not val or len(val) < 8:
                continue
            if tipo not in ("Edit", "Document", "ComboBox"):
                continue
            if any(
                x in nome
                for x in ("assunto", "subject")
            ):
                return val
    except Exception:
        pass
    return tit or ""


def _focar_campo_assunto_outlook(janela) -> bool:
    try:
        janela.set_focus()
    except Exception:
        return False
    _ativar_aba_mensagem_outlook(janela)
    time.sleep(0.15)
    try:
        wr = janela.rectangle()
    except Exception:
        return False
    # Botão/rótulo Assunto → clique à direita (campo)
    for c in janela.descendants()[:4000]:
        try:
            t = (c.window_text() or "").strip().lower()
            tipo = str(c.element_info.control_type or "")
            r = c.rectangle()
        except Exception:
            continue
        if t not in ("assunto", "subject"):
            continue
        if tipo not in ("Button", "Text", "Hyperlink", "SplitButton"):
            continue
        y_rel = int(r.top) - int(wr.top)
        if y_rel < 80 or y_rel > 900:
            continue
        try:
            from pywinauto import mouse as _mouse
            x = min(int(r.right) + 80, int(wr.right) - 60)
            y = (int(r.top) + int(r.bottom)) // 2
            _mouse.click(coords=(x, y))
            time.sleep(0.25)
            return True
        except Exception:
            continue
    # Fallback: Tab a partir do Cc (Para → Cc → Assunto)
    if _focar_linha_cc_outlook(janela):
        send_keys("{TAB}")
        time.sleep(0.2)
        return True
    return False


def _garantir_assunto_outlook(janela, assunto_esperado: str) -> bool:
    """
    Se o assunto foi apagado/alterado na GAL, recoloca o original.
    """
    esperado = " ".join((assunto_esperado or "").split())
    if not esperado:
        return True
    atual = " ".join((_assunto_na_composicao_outlook(janela) or "").split())
    contrato = ""
    m = re.search(r"\b(46\d{8})\b", esperado)
    if m:
        contrato = m.group(1)
    ok = True
    if contrato and contrato not in atual:
        ok = False
    if "faturamento" in esperado.lower() and "faturamento" not in atual.lower():
        ok = False
    if len(atual) < max(20, int(len(esperado) * 0.7)):
        ok = False
    # Início do assunto (empresa) sumiu / foi truncado
    prefixo = esperado[:24].lower()
    if prefixo and prefixo not in atual.lower():
        ok = False
    if ok:
        return True
    registrar_log(
        f"AVISO [EMAIL]: assunto alterado ('{atual[:70]}') — "
        f"restaurando.",
        "AVISO",
    )
    try:
        _cancelar_dialogos_salvar_abrir()
    except Exception:
        pass
    if not _focar_campo_assunto_outlook(janela):
        registrar_log(
            "ERRO [EMAIL]: não foquei o campo Assunto para restaurar.",
            "ERRO",
        )
        return False
    try:
        send_keys("^a")
        time.sleep(0.12)
        _colar_nome_no_outlook(esperado)
        time.sleep(0.35)
    except Exception as e:
        registrar_log(f"ERRO [EMAIL]: falha ao colar assunto — {e}", "ERRO")
        return False
    novo = " ".join((_assunto_na_composicao_outlook(janela) or "").split())
    if contrato and contrato in novo and prefixo[:12] in novo.lower():
        registrar_log("OK [EMAIL]: assunto restaurado.", "OK")
        return True
    if contrato and contrato in (janela.window_text() or ""):
        registrar_log("OK [EMAIL]: assunto restaurado (título).", "OK")
        return True
    registrar_log(
        f"AVISO [EMAIL]: assunto ainda duvidoso após restaurar: '{novo[:70]}'",
        "AVISO",
    )
    return False


def _revisar_rascunho_na_pasta_rascunhos(
    assunto: str,
    nomes_pend: list | None = None,
    esperados: list | None = None,
) -> bool:
    """
    O vermelho do destinatário às vezes só aparece depois de gravar
    em Rascunhos. Abre a pasta, seleciona O rascunho deste assunto
    (entre vários), reabre e corrige GAL se precisar.
    """
    nomes_pend = [n for n in (nomes_pend or []) if n]
    lista_esp = list(esperados or [])
    registrar_log(
        "INFO [EMAIL]: conferindo rascunho na pasta Rascunhos "
        f"(assunto: {(assunto or '')[:60]}).",
        "INFO",
    )
    # Fecha composição aberta com esse assunto, se ainda estiver
    try:
        w_aberta = _composicao_por_assunto_outlook(assunto, timeout=1.0)
        if w_aberta is not None:
            try:
                w_aberta.set_focus()
                send_keys("^s")
                time.sleep(0.4)
                send_keys("^w")
                time.sleep(0.5)
                _confirmar_dialogo_manter_rascunho()
            except Exception:
                pass
    except Exception:
        pass

    principal = _janela_principal_outlook_novo()
    if principal is None:
        registrar_log(
            "AVISO [EMAIL]: janela principal do Outlook não encontrada "
            "para abrir Rascunhos.",
            "AVISO",
        )
        return False
    if not _abrir_pasta_rascunhos_outlook(principal):
        return False
    time.sleep(0.8)
    # Lista pode precisar de refresh
    try:
        principal.set_focus()
    except Exception:
        pass
    item = _achar_item_rascunho_por_assunto(principal, assunto)
    if item is None:
        # Tenta de novo após breve espera (sync)
        time.sleep(1.5)
        principal = _janela_principal_outlook_novo() or principal
        item = _achar_item_rascunho_por_assunto(principal, assunto)
    if item is None:
        registrar_log(
            "ERRO [EMAIL]: não achei o rascunho na pasta Rascunhos "
            f"com assunto '{(assunto or '')[:70]}'.",
            "ERRO",
        )
        return False
    if not _abrir_item_rascunho_outlook(item):
        registrar_log("ERRO [EMAIL]: falha ao abrir o rascunho da lista.", "ERRO")
        return False
    janela = _composicao_por_assunto_outlook(assunto, timeout=18.0)
    if janela is None:
        # Assunto pode ter sido corrompido — tenta pelo nº do contrato
        chave = _trecho_assunto_para_rascunho(assunto)
        if chave:
            janela = _composicao_por_assunto_outlook(chave, timeout=8.0)
    if janela is None:
        registrar_log(
            "ERRO [EMAIL]: rascunho aberto, mas composição não apareceu.",
            "ERRO",
        )
        return False
    try:
        janela.set_focus()
    except Exception:
        pass
    time.sleep(1.0)

    # Assunto pode ter sido corrompido na tentativa anterior de GAL
    try:
        _garantir_assunto_outlook(janela, assunto)
    except Exception as e_ass:
        registrar_log(f"AVISO [EMAIL]: checagem de assunto — {e_ass}", "AVISO")

    # Agora o vermelho costuma já ter aparecido
    erro = _composicao_outlook_invalida(janela)
    nomes_gal = []
    for n in nomes_pend:
        if _chip_cc_resolvido_outlook(janela, n):
            registrar_log(
                f"OK [EMAIL]: em Rascunhos, '{n}' já está resolvido.",
                "OK",
            )
            continue
        nomes_gal.append(n)
    # Também pega nomes dos esperados sem SMTP ainda visíveis no Cc
    for esp in lista_esp:
        if not isinstance(esp, dict):
            continue
        if _smtp_de_item(esp.get("email") or ""):
            continue
        nome_e = (esp.get("nome") or "").strip()
        if not nome_e or nome_e in nomes_gal:
            continue
        if _chip_cc_resolvido_outlook(janela, nome_e):
            continue
        toks = _tokens_nome_pessoa(nome_e)
        blob, _ = _ler_texto_composicao_outlook(janela)
        bl = (blob or "").lower()
        if len(toks) >= 2 and toks[0] in bl and toks[-1] in bl:
            nomes_gal.append(nome_e)
        elif erro:
            nomes_gal.append(nome_e)
    if erro:
        registrar_log(
            f"AVISO [EMAIL]: em Rascunhos apareceu destinatário inválido — "
            f"{erro}",
            "AVISO",
        )
    if nomes_gal or erro:
        try:
            _resolver_destinatario_obrigatorio_ou_falhar(
                janela,
                nomes_gal or list(nomes_pend),
                lista_esp,
                anexar_cc=True,
                tentativas=2,
            )
        except Exception as e_gal:
            registrar_log(
                f"ERRO [EMAIL]: GAL no rascunho reaberto — {e_gal}",
                "ERRO",
            )
        for esp in lista_esp:
            if not isinstance(esp, dict) or _smtp_de_item(esp.get("email") or ""):
                continue
            nome_e = (esp.get("nome") or "").strip()
            if not nome_e:
                continue
            em = _smtp_de_item(
                _cache_email_gal.get(nome_e.lower(), "")
                or _emails_arquivo_carregar().get(nome_e.lower(), "")
            )
            if em:
                esp["email"] = em
        try:
            _garantir_assunto_outlook(janela, assunto)
        except Exception:
            pass

    ok_dest, faltando = _validar_destinatarios_na_ui(janela, lista_esp)
    if not ok_dest:
        registrar_log(
            "ERRO [EMAIL]: rascunho em Rascunhos ainda inválido — "
            + "; ".join(faltando),
            "ERRO",
        )
    # Sempre repor o assunto (GAL / cliques errados podem truncar)
    try:
        _garantir_assunto_outlook(janela, assunto)
    except Exception:
        pass
    try:
        janela.set_focus()
        send_keys("^s")
        time.sleep(0.5)
        send_keys("^w")
        time.sleep(0.5)
        _confirmar_dialogo_manter_rascunho()
    except Exception:
        pass
    if ok_dest:
        registrar_log(
            "OK [EMAIL]: rascunho conferido/corrigido na pasta Rascunhos.",
            "OK",
        )
    return bool(ok_dest)


def _fechar_composicao_novo_outlook(
    assunto: str,
    timeout: float = 8.0,
    para_str: str = "",
    cc_str: str = "",
    nomes_gal_cc=None,
    esperados=None,
) -> bool:
    """
    Fecha SÓ a mensagem no Outlook novo; deixa o item em Rascunhos.
    2 janelas olk.exe -> Alt+F4 na composição.
    1 janela (aba) -> Ctrl+W, nunca Alt+F4 no Outlook inteiro.
    Depois reabre pela pasta Rascunhos (o vermelho às vezes só
    aparece aí) e corrige se precisar.
    """
    from pywinauto import WindowSpecification
    import psutil as _ps

    def _janelas_assunto():
        achadas = []
        trecho = (assunto or "").lower()
        if not trecho:
            return achadas
        try:
            for w in Desktop(backend="uia").windows():
                try:
                    titulo = (w.window_text() or "").strip()
                    if trecho not in titulo.lower():
                        continue
                    nome = (_ps.Process(w.process_id()).name() or "").lower()
                    if nome != "olk.exe":
                        continue
                    if titulo.strip().lower() in ("outlook", "mail", "e-mail"):
                        continue
                    achadas.append(w)
                except Exception:
                    continue
        except Exception:
            pass
        return achadas

    def _qtd_olk():
        n = 0
        try:
            for p in _ps.process_iter(["name"]):
                if (p.info.get("name") or "").lower() == "olk.exe":
                    n += 1
        except Exception:
            pass
        # Fallback: conta janelas olk
        if n == 0:
            try:
                for w in Desktop(backend="uia").windows():
                    try:
                        nome = (_ps.Process(w.process_id()).name() or "").lower()
                        if nome == "olk.exe":
                            n += 1
                    except Exception:
                        continue
            except Exception:
                pass
        return n

    fim = time.time() + timeout
    alvo = None
    while time.time() < fim:
        achadas = _janelas_assunto()
        if achadas:
            alvo = achadas[0]
            break
        time.sleep(0.12)
    if alvo is None:
        registrar_log(
            "AVISO [EMAIL-EML]: composição do novo Outlook não "
            "apareceu a tempo.",
            "AVISO",
        )
        return False

    try:
        hwnd = int(alvo.handle)
        try:
            import win32gui as _wgui
            import win32con as _wcon
            _wgui.SetForegroundWindow(hwnd)
        except Exception:
            _wgui = None
            _wcon = None
            janela = WindowSpecification({"handle": hwnd})
            janela.set_focus()
    except Exception as e:
        registrar_log(f"AVISO [EMAIL-EML]: foco na composição: {e}", "AVISO")
        return False

    time.sleep(0.2)
    _cancelar_dialogos_salvar_abrir()
    # NÃO usar WindowSpecification só-handle: some a árvore UIA (Cc/GAL).
    janela_comp = _janela_outlook_uia(alvo)
    if janela_comp is None:
        try:
            janela_comp = _janela_outlook_uia(
                WindowSpecification({"handle": hwnd})
            )
        except Exception:
            janela_comp = WindowSpecification({"handle": hwnd})
    nomes_pend = [
        n for n in (nomes_gal_cc or []) if n
        and not any(
            "@" in str((e or {}).get("email") or "")
            for e in (esperados or [])
            if isinstance(e, dict)
            and (e.get("nome") or "").strip().lower() == str(n).strip().lower()
        )
    ]
    lista_esp = list(esperados or [])
    if not lista_esp:
        for em in _partir_destinatarios_email(
            _destinatarios_para_cabecalho_eml(para_str)
        ):
            lista_esp.append(
                {"email": em, "nome": "", "campo": "para", "origem": "manual"}
            )
        for em in _partir_destinatarios_email(
            _destinatarios_para_cabecalho_eml(cc_str, False)
        ):
            lista_esp.append(
                {"email": em, "nome": "", "campo": "cc", "origem": "automatico"}
            )
        for n in nomes_pend:
            lista_esp.append(
                {"email": "", "nome": n, "campo": "cc", "origem": "automatico"}
            )
    if nomes_pend:
        registrar_log(
            "INFO [EMAIL]: .eml só com SMTP; gerente/fiscal sem SMTP — "
            "cola nome + 1ª sugestão: " + "; ".join(nomes_pend),
            "INFO",
        )
        # Nomes NÃO vêm no .eml — espera Para/Cc na UI e cola.
        fim_ui = time.time() + 8.0
        while time.time() < fim_ui:
            if (
                _botao_rotulo_destinatario_outlook(
                    janela_comp, ("cc", "cópia", "copia", "cco")
                )
                or _rotulo_destinatario_outlook(
                    janela_comp, ("cc", "cópia", "copia", "cco")
                )
                or _botao_rotulo_destinatario_outlook(janela_comp, ("para", "to"))
                or _rotulo_destinatario_outlook(janela_comp, ("para", "to"))
            ):
                break
            time.sleep(0.4)
        time.sleep(0.4)
        nomes_gal = []
        for _n in nomes_pend:
            if _chip_cc_resolvido_outlook(janela_comp, _n):
                registrar_log(
                    f"OK [EMAIL]: {_n} já resolvido no Cc (chip válido).",
                    "OK",
                )
                continue
            nomes_gal.append(_n)
        if nomes_gal:
            erro_ini = _composicao_outlook_invalida(janela_comp)
            if erro_ini:
                registrar_log(
                    f"AVISO [EMAIL]: destinatário vermelho após .eml — "
                    f"{erro_ini}. Cola nome + 1ª sugestão da GAL.",
                    "AVISO",
                )
            try:
                _resolver_destinatario_obrigatorio_ou_falhar(
                    janela_comp, nomes_gal, lista_esp, anexar_cc=True,
                    tentativas=2,
                )
            except Exception as e_ger:
                registrar_log(
                    f"ERRO [EMAIL]: GAL não resolveu — {e_ger}",
                    "ERRO",
                )
            for esp in lista_esp:
                if not isinstance(esp, dict) or _smtp_de_item(esp.get("email") or ""):
                    continue
                nome_e = (esp.get("nome") or "").strip()
                if not nome_e:
                    continue
                em = _smtp_de_item(
                    _cache_email_gal.get(nome_e.lower(), "")
                    or _emails_arquivo_carregar().get(nome_e.lower(), "")
                )
                if em:
                    esp["email"] = em
            try:
                _garantir_assunto_outlook(janela_comp, assunto)
            except Exception:
                pass
        time.sleep(0.4)
        try:
            janela_comp.set_focus()
            send_keys("^s")
            time.sleep(0.5)
        except Exception:
            pass
    ok_dest, faltando = _validar_destinatarios_na_ui(janela_comp, lista_esp)
    if not ok_dest:
        registrar_log(
            "ERRO [EMAIL]: rascunho NÃO validado — "
            + "; ".join(faltando),
            "ERRO",
        )
    # Fecha a composição. O Outlook novo muitas vezes grava o rascunho
    # sozinho e não mostra "Salvar este rascunho?" — a janela some e
    # o item já está em Rascunhos.
    fechou = False
    for _tent_fechar in range(4):
        try:
            if _wgui is not None and _wcon is not None:
                _wgui.PostMessage(hwnd, _wcon.WM_CLOSE, 0, 0)
            else:
                separada = _qtd_olk() >= 2
                janela = WindowSpecification({"handle": hwnd})
                janela.set_focus()
                if separada:
                    send_keys("%{F4}")
                else:
                    send_keys("^w")
        except Exception as e:
            registrar_log(f"AVISO [EMAIL-EML]: fechar composição: {e}", "AVISO")
        time.sleep(0.35)
        if _confirmar_dialogo_manter_rascunho():
            time.sleep(0.35)
        if not _janelas_assunto():
            fechou = True
            break

    if not _outlook_novo_rodando():
        registrar_log(
            "AVISO [EMAIL-EML]: olk.exe fechou por inteiro ao "
            "tentar fechar só a mensagem.",
            "AVISO",
        )
        return False

    if not fechou and _janelas_assunto():
        _confirmar_dialogo_manter_rascunho()
        time.sleep(0.8)
        fechou = not _janelas_assunto()

    if fechou:
        registrar_log(
            "OK [EMAIL-EML]: composição fechada — rascunho no Outlook "
            "(com ou sem diálogo Salvar).",
            "OK",
        )
    else:
        registrar_log(
            "AVISO [EMAIL-EML]: composição ainda visível — "
            "confira Rascunhos; clique em Sim se o Outlook perguntar.",
            "AVISO",
        )

    # Deu certo na composição → pronto. Só vai a Rascunhos se falhou
    # a validação Para/Cc (chip vermelho / SMTP ausente).
    _fechar_janelas_cfd_outlook()
    if ok_dest and fechou:
        return True
    if fechou and not ok_dest:
        try:
            ok_rev = _revisar_rascunho_na_pasta_rascunhos(
                assunto,
                nomes_pend=nomes_pend or list(nomes_gal_cc or []),
                esperados=lista_esp,
            )
            return bool(ok_rev)
        except Exception as e_rev:
            registrar_log(
                f"AVISO [EMAIL]: revisão em Rascunhos falhou — {e_rev}",
                "AVISO",
            )
            return False
    return bool(ok_dest) and bool(fechou)


def _enviar_composicao_aberta(assunto: str, timeout: float = 25.0) -> bool:
    """
    Na composição aberta: clica Enviar. Se abrir o diálogo de rótulo,
    seleciona Pública e clica Enviar NO DIÁLOGO. Só True se fechar.
    """
    from pywinauto import WindowSpecification
    import psutil as _ps

    trecho = (assunto or "").lower()
    if not trecho:
        return False

    def _composicao_ainda_aberta() -> bool:
        try:
            for w in Desktop(backend="uia").windows():
                try:
                    titulo = (w.window_text() or "").strip()
                    if trecho not in titulo.lower():
                        continue
                    nome = (_ps.Process(w.process_id()).name() or "").lower()
                    if nome not in ("olk.exe", "outlook.exe"):
                        continue
                    if titulo.strip().lower() in ("outlook", "mail", "e-mail"):
                        continue
                    return True
                except Exception:
                    continue
        except Exception:
            pass
        return False

    def _achar_composicao():
        try:
            for w in Desktop(backend="uia").windows():
                try:
                    titulo = (w.window_text() or "").strip()
                    if trecho not in titulo.lower():
                        continue
                    nome = (_ps.Process(w.process_id()).name() or "").lower()
                    if nome not in ("olk.exe", "outlook.exe"):
                        continue
                    if titulo.strip().lower() in ("outlook", "mail", "e-mail"):
                        continue
                    return w
                except Exception:
                    continue
        except Exception:
            pass
        return None

    def _dialogo_rotulo_aberto() -> bool:
        try:
            for w in Desktop(backend="uia").windows():
                try:
                    t = ((w.window_text() or "") + " " + (
                        getattr(w.element_info, "name", "") or ""
                    )).lower()
                except Exception:
                    continue
                if "rótulo de confidencialidade" in t or "sensitivity label" in t:
                    return True
                if "adicionar rótulo" in t:
                    return True
                # Modal filho (Outlook novo): título no Window interno
                try:
                    for c in w.descendants(control_type="Window")[:40]:
                        ct = (c.window_text() or "").lower()
                        if "rótulo" in ct or "confidencialidade" in ct:
                            return True
                        if "adicionar rótulo" in ct:
                            return True
                except Exception:
                    pass
                try:
                    for c in w.descendants()[:350]:
                        n = (c.window_text() or "").strip().lower()
                        if "selecionar um rótulo" in n:
                            return True
                        if "adicionar rótulo de confidencialidade" in n:
                            return True
                except Exception:
                    pass
        except Exception:
            pass
        return False

    def _clicar_enviar_composicao(janela) -> bool:
        """Enviar da composição — não clica no diálogo de rótulo."""
        try:
            for ctrl in janela.descendants()[:500]:
                try:
                    nome = (
                        (ctrl.window_text() or "")
                        or (getattr(ctrl.element_info, "name", "") or "")
                    ).strip().lower()
                except Exception:
                    continue
                if nome in ("enviar", "send"):
                    try:
                        ctrl.click_input()
                        return True
                    except Exception:
                        try:
                            ctrl.click()
                            return True
                        except Exception:
                            continue
        except Exception:
            pass
        try:
            send_keys("^{ENTER}")
            return True
        except Exception:
            return False

    fim = time.time() + timeout
    alvo = None
    while time.time() < fim:
        alvo = _achar_composicao()
        if alvo is not None:
            break
        time.sleep(0.4)
    if alvo is None:
        return False
    try:
        janela = WindowSpecification({"handle": int(alvo.handle)})
        janela.set_focus()
    except Exception:
        try:
            alvo.set_focus()
            janela = alvo
        except Exception:
            return False
    time.sleep(0.6)

    # Enviar na composição → Outlook exige rótulo e abre o modal
    _clicar_enviar_composicao(janela)
    time.sleep(1.0)

    # Enquanto o modal estiver aberto: Pública no dropdown + Enviar do modal
    fim_rotulo = time.time() + 20
    while time.time() < fim_rotulo:
        if _dialogo_rotulo_aberto():
            if _aplicar_rotulo_confidencialidade_publica():
                time.sleep(1.2)
            else:
                time.sleep(0.5)
            continue
        if not _composicao_ainda_aberta():
            return True
        # Sem modal e composição ainda aberta: tentar Enviar de novo 1x
        break

    if _composicao_ainda_aberta() and not _dialogo_rotulo_aberto():
        alvo2 = _achar_composicao()
        if alvo2 is not None:
            try:
                janela = WindowSpecification({"handle": int(alvo2.handle)})
                janela.set_focus()
            except Exception:
                try:
                    alvo2.set_focus()
                    janela = alvo2
                except Exception:
                    pass
            time.sleep(0.4)
            _clicar_enviar_composicao(janela)
            time.sleep(1.0)
            fim_rotulo2 = time.time() + 15
            while time.time() < fim_rotulo2:
                if _dialogo_rotulo_aberto():
                    _aplicar_rotulo_confidencialidade_publica()
                    time.sleep(1.0)
                    continue
                if not _composicao_ainda_aberta():
                    return True
                time.sleep(0.4)

    fim2 = time.time() + 12
    while time.time() < fim2:
        if _dialogo_rotulo_aberto():
            _aplicar_rotulo_confidencialidade_publica()
            time.sleep(0.8)
        if not _composicao_ainda_aberta():
            return True
        time.sleep(0.4)
    return not _composicao_ainda_aberta()


def _aplicar_rotulo_confidencialidade_publica() -> bool:
    """
    Modal 'Adicionar rótulo de confidencialidade' (filho ou top-level):
    1) Button 'Selecionar um rótulo'
    2) clica 'Pública' na lista
    3) Enviar NO MODAL (não na composição).
    Fluxo validado no teste isolado _teste_outlook_gal_rotulo.py.
    """
    alvos_titulo = (
        "rótulo de confidencialidade",
        "adicionar rótulo",
        "sensitivity label",
    )
    try:
        janelas = list(Desktop(backend="uia").windows())
    except Exception:
        return False

    def _nome_ctrl(ctrl) -> str:
        try:
            return (
                (ctrl.window_text() or "")
                or (getattr(ctrl.element_info, "name", "") or "")
            ).strip()
        except Exception:
            return ""

    def _tipo_ctrl(ctrl) -> str:
        try:
            return str(getattr(ctrl.element_info, "control_type", "") or "")
        except Exception:
            return ""

    def _mouse_click_ctrl(ctrl) -> bool:
        try:
            from pywinauto import mouse as _mouse
            r = ctrl.rectangle()
            _mouse.click(coords=(
                (int(r.left) + int(r.right)) // 2,
                (int(r.top) + int(r.bottom)) // 2,
            ))
            return True
        except Exception:
            try:
                ctrl.click_input()
                return True
            except Exception:
                try:
                    ctrl.click()
                    return True
                except Exception:
                    return False

    dlg = None
    # 1) Window filho com título do modal
    for w in janelas:
        try:
            for c in w.descendants(control_type="Window")[:50]:
                ct = _nome_ctrl(c).lower()
                if any(a in ct for a in alvos_titulo):
                    dlg = c
                    break
        except Exception:
            continue
        if dlg is not None:
            break
    # 2) Janela top-level com o título
    if dlg is None:
        for w in janelas:
            try:
                t = (_nome_ctrl(w) + " " + (
                    getattr(w.element_info, "name", "") or ""
                )).lower()
            except Exception:
                continue
            if any(a in t for a in alvos_titulo):
                dlg = w
                break
    # 3) Qualquer olk que tenha o botão "Selecionar um rótulo"
    if dlg is None:
        for w in janelas:
            try:
                for c in w.descendants()[:500]:
                    n = _nome_ctrl(c).strip().lower()
                    if "selecionar um rótulo" in n or "adicionar rótulo" in n:
                        dlg = w
                        break
            except Exception:
                continue
            if dlg is not None:
                break
    if dlg is None:
        return False
    try:
        dlg.set_focus()
    except Exception:
        pass
    time.sleep(0.25)

    # Escopo de busca: diálogo + pai (lista Pública às vezes sobe)
    escopos = [dlg]
    try:
        for w in janelas:
            escopos.append(w)
    except Exception:
        pass

    # Já mostra Pública no combo?
    ja_tem_publica = False
    try:
        for ctrl in dlg.descendants()[:500]:
            n = _nome_ctrl(ctrl).strip().lower()
            if n in ("pública", "publica", "public"):
                ja_tem_publica = True
                break
    except Exception:
        pass

    if not ja_tem_publica:
        abriu = False
        try:
            for ctrl in dlg.descendants()[:600]:
                n = _nome_ctrl(ctrl).strip().lower()
                tipo = _tipo_ctrl(ctrl)
                if "selecionar um rótulo" not in n and "select a label" not in n:
                    continue
                if tipo and tipo not in ("Button", "ComboBox", "SplitButton", ""):
                    continue
                if _mouse_click_ctrl(ctrl):
                    abriu = True
                    registrar_log(
                        "INFO [EMAIL-ERRO]: abriu Selecionar um rótulo.",
                        "INFO",
                    )
                    time.sleep(0.7)
                    break
        except Exception:
            pass
        if not abriu:
            # Botão pode estar na janela pai da composição
            for esc in escopos:
                try:
                    for ctrl in esc.descendants()[:800]:
                        n = _nome_ctrl(ctrl).strip().lower()
                        if "selecionar um rótulo" in n:
                            if _mouse_click_ctrl(ctrl):
                                abriu = True
                                time.sleep(0.7)
                                break
                except Exception:
                    continue
                if abriu:
                    break

        escolheu = False
        alvos_exatos = ("pública", "publica", "public")
        for esc in escopos:
            try:
                for it in esc.descendants()[:900]:
                    n = _nome_ctrl(it).strip().lower()
                    if n not in alvos_exatos:
                        continue
                    if _mouse_click_ctrl(it):
                        escolheu = True
                        registrar_log(
                            "INFO [EMAIL-ERRO]: clicou Pública.",
                            "INFO",
                        )
                        break
            except Exception:
                continue
            if escolheu:
                break
        if not escolheu:
            try:
                dlg.set_focus()
            except Exception:
                pass
            try:
                send_keys("{HOME}")
                time.sleep(0.12)
                send_keys("{DOWN}")
                time.sleep(0.12)
                send_keys("{DOWN}")
                time.sleep(0.12)
                send_keys("{ENTER}")
                escolheu = True
                registrar_log(
                    "INFO [EMAIL-ERRO]: Pública via HOME+2×↓+Enter.",
                    "INFO",
                )
            except Exception:
                return False
        if not escolheu:
            return False
        time.sleep(0.55)

    # Enviar SOMENTE no modal (não no ribbon da composição)
    fim_env = time.time() + 12
    while time.time() < fim_env:
        candidatos_env = []
        try:
            for ctrl in dlg.descendants()[:500]:
                n = _nome_ctrl(ctrl).strip().lower()
                tipo = _tipo_ctrl(ctrl)
                if n not in ("enviar", "send"):
                    continue
                if tipo and tipo not in ("Button", "SplitButton", ""):
                    continue
                try:
                    if hasattr(ctrl, "is_enabled") and not ctrl.is_enabled():
                        continue
                except Exception:
                    pass
                try:
                    ei = getattr(ctrl, "element_info", None)
                    if ei is not None and hasattr(ei, "enabled") and not ei.enabled:
                        continue
                except Exception:
                    pass
                candidatos_env.append(ctrl)
        except Exception:
            pass
        for ctrl in candidatos_env:
            if _mouse_click_ctrl(ctrl):
                registrar_log(
                    "OK [EMAIL-ERRO]: rótulo de confidencialidade = Pública.",
                    "OK",
                )
                return True
        time.sleep(0.35)
    return False


def _criar_rascunho_via_eml_novo_outlook(
    para_str, cc_str, assunto, corpo_html, corpo_txt, anexos,
    nomes_gal_cc=None,
    esperados=None,
) -> bool:
    """
    Caminho do Outlook NOVO (testado): gera .eml, abre no olk,
    espera rascunho, fecha a mensagem. Não envia.
    """
    try:
        if not _outlook_novo_rodando():
            try:
                import subprocess
                subprocess.Popen(["olk.exe"])
            except Exception:
                try:
                    os.startfile("ms-outlook:")
                except Exception as e:
                    registrar_log(
                        f"AVISO [EMAIL-EML]: não abriu olk.exe: {e}",
                        "AVISO",
                    )
                    return False
            aguardar_condicao(
                _outlook_novo_rodando,
                timeout=20,
                intervalo=0.5,
                descricao="Outlook novo abrir",
            )
            time.sleep(3.0)

        if not _outlook_novo_rodando():
            return False

        eml = _montar_eml_rascunho(
            _destinatarios_para_cabecalho_eml(para_str),
            _cc_eml_com_nomes_gal(cc_str, nomes_gal_cc),
            assunto,
            corpo_html, corpo_txt, anexos,
        )
        os.startfile(str(eml))
        _aguardar_escolha_app_outlook(timeout=90.0)
        aguardar_condicao(
            _outlook_novo_rodando,
            timeout=4,
            intervalo=0.15,
            descricao="Outlook novo abrir o rascunho",
        )

        if _outlook_classico_rodando() and not _outlook_novo_rodando():
            if _janelas_login_outlook_classico():
                registrar_log(
                    "AVISO [EMAIL-EML]: .eml caiu no clássico pedindo "
                    "login — tratado como erro.",
                    "AVISO",
                )
                return False
            registrar_log(
                "AVISO [EMAIL-EML]: Windows abriu o clássico, não o novo.",
                "AVISO",
            )
            return False

        if _fechar_composicao_novo_outlook(
            assunto, para_str=para_str, cc_str=cc_str,
            nomes_gal_cc=nomes_gal_cc or [],
            esperados=esperados or [],
        ):
            _fechar_janelas_cfd_outlook()
            registrar_log(
                "OK: Rascunho via .eml no Outlook novo "
                "(mensagem fechada; conferir Rascunhos)."
            )
            return True

        registrar_log(
            "AVISO [EMAIL-EML]: .eml aberto, mas não confirmou "
            "fechamento da composição — conferir Rascunhos.",
            "AVISO",
        )
        return False
    except Exception as e:
        registrar_log(f"AVISO [EMAIL-EML]: falhou — {e}", "AVISO")
        return False

def _garantir_outlook_aberto(timeout: float = 20.0) -> bool:
    """
    Não mistura os dois apps. Se já houver um aberto, não abre o outro.
    Se estiver tudo fechado: tenta olk.exe (novo); se não houver,
    tenta outlook.exe (clássico de quem só tem ele).
    """
    import subprocess

    if _outlook_novo_rodando() or _outlook_classico_rodando():
        return True

    registrar_log(
        "AVISO [OUTLOOK]: nenhum Outlook aberto — tentando o NOVO "
        "(olk.exe)...",
        "AVISO",
    )
    try:
        subprocess.Popen(["olk.exe"])
    except Exception:
        try:
            os.startfile("ms-outlook:")
        except Exception:
            pass

    if aguardar_condicao(
        _outlook_novo_rodando, timeout=timeout, intervalo=0.5,
        descricao="Outlook novo abrir",
    ):
        time.sleep(3.0)
        registrar_log("OK [OUTLOOK]: Outlook novo aberto.", "OK")
        return True

    registrar_log(
        "AVISO [OUTLOOK]: novo indisponível — tentando clássico "
        "(outlook.exe) para quem só tem ele.",
        "AVISO",
    )
    try:
        subprocess.Popen(["outlook.exe"])
    except Exception as e_abrir:
        registrar_log(
            f"AVISO [OUTLOOK]: não abriu clássico: {e_abrir}",
            "AVISO",
        )
        return False

    if aguardar_condicao(
        _outlook_classico_rodando, timeout=timeout, intervalo=0.5,
        descricao="Outlook clássico abrir",
    ):
        time.sleep(3.0)
        if _janelas_login_outlook_classico():
            registrar_log(
                "AVISO [OUTLOOK]: clássico abriu pedindo login — "
                "não usar COM.",
                "AVISO",
            )
            return False
        registrar_log("OK [OUTLOOK]: Outlook clássico aberto.", "OK")
        return True

    registrar_log(
        "AVISO [OUTLOOK]: nenhum Outlook abriu a tempo.",
        "AVISO",
    )
    return False


# =====================================================
# ESPELHO NF — EXTRAÇÃO DO PDF DO RM (VERSÃO FINAL - CORRIGIDA)
# =====================================================
# =====================================================
# SAP — ESPELHO NF (YSENF_REL_ESPELHO)
# =====================================================
# =====================================================
# ESPERA DINÂMICA SAP — substitui time.sleep() fixos
# =====================================================
# =====================================================
# TIMEOUT ADAPTATIVO V2 — Percentil P95 + lock
# Mais robusto que média: ignora picos de rede/SAP
# =====================================================
_hist_timeout_campo: dict  = {}
_hist_timeout_lock          = threading.Lock()
_hist_timeout_persistido    = {}   # carregado do banco na inicialização


def _hist_timeout_carregar():
    """
    Carrega histórico de timeouts do banco SQLite
    para que o P95 já esteja calibrado desde a 1ª
    execução do dia.
    """
    global _hist_timeout_persistido
    try:
        with _sqlite3.connect(_DB_PATH) as con:
            rows = con.execute(
                "SELECT campo, tempos FROM timeout_hist "
                "WHERE campo IS NOT NULL"
            ).fetchall()
            for campo, tempos_json in rows:
                try:
                    _hist_timeout_persistido[campo] = (
                        json.loads(tempos_json)
                    )
                except Exception:
                    pass
    except Exception:
        pass   # tabela ainda não existe — ok


def _hist_timeout_persistir():
    """
    Persiste o histórico de timeouts no banco.
    Chamado no encerramento da execução.
    """
    try:
        with _sqlite3.connect(_DB_PATH) as con:
            con.execute("""
                CREATE TABLE IF NOT EXISTS timeout_hist (
                    campo TEXT PRIMARY KEY,
                    tempos TEXT
                )
            """)
            with _hist_timeout_lock:
                dados = dict(_hist_timeout_campo)
            for campo, tempos in dados.items():
                con.execute(
                    "INSERT OR REPLACE INTO timeout_hist "
                    "(campo, tempos) VALUES (?, ?)",
                    (campo, json.dumps(tempos[-30:]))
                )
    except Exception:
        pass


def _timeout_adaptativo(
    caminho: str, default: float = 0.5
) -> float:
    """
    Retorna timeout baseado em P95 + predição linear.

    Algoritmo:
      1. Calcula P95 do histórico (base)
      2. Detecta tendência (subida/descida) via
         regressão linear simples nos últimos 5 valores
      3. Ajusta P95 pela tendência prevista
      4. Aplica limites de segurança

    Resultado: timeout que antecipa degradação do SAP
    em vez de apenas reagir a ela.
    """
    with _hist_timeout_lock:
        hist = list(
            _hist_timeout_campo.get(caminho, [])
        )

    # Completa com histórico persistido
    if len(hist) < 5:
        hist_p = _hist_timeout_persistido.get(
            caminho, []
        )
        hist   = hist_p + hist

    n = len(hist)
    if n < 3:
        return default

    # P95 base
    sorted_hist = sorted(hist)
    idx_p95     = min(int(n * 0.95), n - 1)
    p95         = sorted_hist[idx_p95]

    # Regressão linear simples nos últimos 6 pontos
    # para detectar tendência de aumento
    ultimos = hist[-6:] if len(hist) >= 6 else hist
    n_u     = len(ultimos)

    if n_u >= 4:
        # Mínimos quadrados sem numpy
        _xs = list(range(n_u))
        _ys = ultimos
        _sx  = sum(_xs)
        _sy  = sum(_ys)
        _sxx = sum(x * x for x in _xs)
        _sxy = sum(x * y for x, y in zip(_xs, _ys))
        _den = n_u * _sxx - _sx * _sx

        if abs(_den) > 1e-10:
            # Coeficiente angular (tendência por amostra)
            _slope = (n_u * _sxy - _sx * _sy) / _den

            # Predição para próxima amostra
            _pred_prox = (
                _ys[-1] + _slope
                if _slope > 0.005   # tendência de alta
                else _ys[-1]
            )

            # Ajusta P95 pela predição
            p95 = max(p95, _pred_prox * 1.3)

    resultado = max(p95 * 1.4, 0.10)
    resultado = min(resultado, default * 5, 10.0)
    return resultado



def aguardar_campo_sap(session, caminho_elemento, timeout=0.5):
    """
    Aguarda campo SAP aparecer com timeout adaptativo P95.
    Polling a cada 80ms (era 150ms) — 46% mais responsivo.
    """
    _timeout_real = _timeout_adaptativo(
        caminho_elemento, default=timeout
    )
    _t_inicio = time.time()

    while time.time() - _t_inicio < _timeout_real:
        try:
            el = session.findById(caminho_elemento)
            if el is not None:
                _t_real = time.time() - _t_inicio
                with _hist_timeout_lock:
                    hist = _hist_timeout_campo.setdefault(
                        caminho_elemento, []
                    )
                    hist.append(_t_real)
                    # Janela deslizante de 30 amostras
                    if len(hist) > 30:
                        _hist_timeout_campo[caminho_elemento] = (
                            hist[-30:]
                        )
                return el
        except Exception:
            pass
        time.sleep(0.08)   # era 0.15 — 46% mais responsivo

    registrar_log(
        f"TIMEOUT SAP aguardando: {caminho_elemento} "
        f"(limite={_timeout_real:.2f}s)",
        "AVISO"
    )
    return None


# Carrega histórico persistido na inicialização
_hist_timeout_carregar()

def aguardar_qualquer_campo_sap(
    session,
    caminhos: list,
    timeout: float = 1.0,
) -> tuple:
    """
    A2: Aguarda o primeiro de vários campos aparecer.
    Retorna (caminho_encontrado, elemento) ou (None, None).
    Mais eficiente que chamadas sequenciais em sequências alternativas.
    """
    inicio = time.time()
    while time.time() - inicio < timeout:
        for caminho in caminhos:
            try:
                el = session.findById(caminho)
                if el is not None:
                    return caminho, el
            except Exception:
                pass
        time.sleep(0.05)   # polling mais frequente — múltiplos campos
    registrar_log(
        f"TIMEOUT aguardando qualquer campo: {caminhos[:2]}...",
        "AVISO"
    )
    return None, None

def aguardar_janela_sap(session, indice_janela=1, timeout=0.5):
    caminho = f"wnd[{indice_janela}]"
    inicio  = time.time()
    while time.time() - inicio < timeout:
        try:
            janela = session.findById(caminho)
            if janela is not None:
                return True
        except Exception:
            pass
        time.sleep(0.15)
        # SEM _process_qt_events() — roda em thread de fundo
    registrar_log(f"TIMEOUT SAP aguardando janela: {caminho}")
    return False


def abrir_espelho_nf_sap(session, contrato, rm):
    print(f"\nGerando Espelho NF SAP — Contrato: {contrato} | RM: {rm}")
    session.findById("wnd[0]").maximize
    session.findById("wnd[0]/tbar[0]/okcd").text = "/nysenf_rel_espelho"
    session.findById("wnd[0]").sendVKey(0)

    # era: time.sleep(1.5)
    aguardar_campo_sap(session, "wnd[0]/usr/ctxtS_CONTRA-LOW", timeout=0.1)

    session.findById("wnd[0]/usr/ctxtS_CONTRA-LOW").text = contrato
    session.findById("wnd[0]/usr/ctxtS_RM-LOW").text = rm
    session.findById("wnd[0]/usr/ctxtS_RM-LOW").setFocus()
    session.findById("wnd[0]/usr/ctxtS_RM-LOW").caretPosition = len(rm)
    session.findById("wnd[0]/tbar[1]/btn[8]").press()

    # era: time.sleep(2.0) — aguarda grid/shellcont carregar
