    session.findById("wnd[0]/shellcont/shell").selectedRows = "0"
    session.findById("wnd[0]/shellcont/shell").clickCurrentCell()

    # era: time.sleep(1.0) — aguarda toolbar ficar ativa após click
    aguardar_campo_sap(session, "wnd[0]/shellcont/shell", timeout=0.1)

    session.findById("wnd[0]/shellcont/shell").pressToolbarButton("&PRINT_BACK")

    # era: time.sleep(1.5) — aguarda janela modal de impressão abrir
    aguardar_janela_sap(session, indice_janela=1, timeout=0.2)

    session.findById("wnd[1]/usr/ctxtPRI_PARAMS-PDEST").text = "locl"
    session.findById("wnd[1]/usr/ctxtPRI_PARAMS-PDEST").caretPosition = 4
    session.findById("wnd[1]/tbar[0]/btn[13]").press()

    # era: time.sleep(1.5) — aguarda modal fechar
    inicio = time.time()
    while time.time() - inicio < 8:
        try:
            session.findById("wnd[1]")
        except Exception:
            break
        time.sleep(0.15)

    print(f"Espelho NF SAP gerado para RM {rm}.")
