def _lista_variantes_pasta(chave: str, extra=None) -> list:
    saida = []
    arq = (UI_ALIASES.get("pastas_sharepoint") or {}).get(chave) or []
    for x in list(arq) + list(_VARIANTES_PASTAS_SP.get(chave) or []) + list(extra or []):
        t = (x or "").strip()
        if t and t not in saida:
            saida.append(t)
    return saida or [chave]


