def _modulo_certidoes():
    """Carrega o módulo de certidões em namespace isolado (sem colidir nomes)."""
    global _MOD_CERTIDOES
    if _MOD_CERTIDOES is not None:
        return _MOD_CERTIDOES
    import base64
    import types
    src = ""
    try:
        src = base64.b64decode(_SRC_CERTIDOES_B64.encode("ascii")).decode("utf-8")
    except Exception:
        src = ""
    if not (src or "").strip():
        raise RuntimeError(
            "Módulo de certidões não foi embutido no aplicativo."
        )
    mod = types.ModuleType("_certidoes_embutido")
    exec(compile(src, "<certidoes>", "exec"), mod.__dict__)
    _MOD_CERTIDOES = mod
    return mod


def _tipo_certidao_no_nome(nome: str) -> str:
    """cndt / crf / cnd — CNDT vem antes para não confundir com CND."""
    t = unicodedata.normalize("NFKD", nome or "")
    t = "".join(c for c in t if not unicodedata.combining(c)).lower()
    if "cndt" in t:
        return "cndt"
    if "crf" in t:
        return "crf"
    if re.search(r"(^|[^a-z0-9])cnd([^a-z0-9]|$)", t):
        return "cnd"
    if "cnd" in t:
        return "cnd"
    return ""


def _regra_nome_pasta_sp(chave: str) -> str:
    regras = {
        "medicao": (
            "Crie a pasta de medição com o nome: 10. Medição"
        ),
        "med_mensal": (
            "Crie a pasta mensal com o nome: 01. Medicao Mensal"
        ),
        "certidoes": (
            "Crie a pasta com o nome: Certidões"
        ),
        "ano": (
            "Crie a pasta do ano com 4 dígitos, exemplo: 2026"
        ),
        "mes": (
            "Crie a pasta do mês no padrão 08.Ago "
            "(número com 2 dígitos + ponto + abreviação)."
        ),
        "Pedidos Pai": "Crie a pasta: Pedidos",
        "FRS": "Crie a pasta: FRS",
        "RM": "Crie a pasta: RM",
        "Espelho NF Pai": "Crie a pasta: Espelho NF",
        "Pedidos Serviços": "Crie a pasta: Pedidos Serviços",
        "Pedidos Materiais": "Crie a pasta: Pedidos Materiais",
        "Espelho NF Serviços": "Crie a pasta: Espelho NF Serviços",
        "Espelho NF Materiais": "Crie a pasta: Espelho NF Materiais",
    }
    return regras.get(chave) or (
        f"Crie a pasta com o nome padrão da categoria ({chave})."
    )


def _mensagem_pasta_sp_nao_encontrada(chave: str, variantes) -> str:
    vars_txt = ", ".join(list(variantes or [])[:12]) or "(nenhuma variante mapeada)"
    extra = ""
    if len(list(variantes or [])) > 12:
        extra = " ..."
    return (
        f"Não achei a pasta de '{chave}' no SharePoint.\n\n"
        "Ou a pasta ainda não existe, ou o nome não está entre as "
        "variantes que o programa já conhece.\n\n"
        "O que fazer:\n"
        "1) Renomeie a pasta que já existe para uma destas variantes:\n"
        f"   {vars_txt}{extra}\n\n"
        "2) Se a pasta não existir, crie-a seguindo a regra:\n"
        f"   {_regra_nome_pasta_sp(chave)}\n\n"
        "Depois clique em OK para o programa tentar de novo.\n"
        "Cancelar encerra esta etapa."
    )


def _abrir_pasta_variantes(janela_sp, nomes) -> str:
    url_antes = ""
    try:
        url_antes = _capturar_url_atual(janela_sp) or ""
    except Exception:
        pass
    todas_nao_lista = True
    for nome in nomes:
        print(f"\nTentando pasta: '{nome}'...")
        _set_motivo_falha_pasta_sp(_MOTIVO_SP_OK)
        if abrir_pasta_sharepoint(janela_sp, nome, exato=False):
            if _validar_abertura_pasta_sp(janela_sp, nome, url_antes):
                print(f"✓ Pasta encontrada: '{nome}'")
                return nome
            _registrar_erro_navegacao_sp(
                janela_sp, nome, "abriu mas a tela não é a pasta esperada"
            )
            todas_nao_lista = False
            if url_antes:
                _recarregar_pasta_origem_sp(janela_sp, url_antes)
            continue
        motivo = _motivo_falha_pasta_sp()
        if motivo == _MOTIVO_SP_NAO_NA_LISTA:
            continue
        todas_nao_lista = False
        _registrar_erro_navegacao_sp(
            janela_sp, nome, f"motivo={motivo or 'abertura'}"
        )
        if url_antes:
            _recarregar_pasta_origem_sp(janela_sp, url_antes)
    if todas_nao_lista:
        _set_motivo_falha_pasta_sp(_MOTIVO_SP_NAO_NA_LISTA)
    else:
        _set_motivo_falha_pasta_sp(_MOTIVO_SP_ABERTURA_FALHOU)
    return ""


def _pedir_e_abrir_pasta_sp(
    janela_sp, nomes, chave, thread=None, tentativas=4
) -> str:
    """
    Tenta as variantes; se nenhuma existir (nome fora do padrão), pede
    para renomear ou criar. Se o erro for clique/URL errado, registra
    log e tenta de novo sem acusar pasta inexistente.
    """
    nomes = [n for n in (nomes or []) if n]
    if not nomes:
        nomes = [chave] if chave else []
    for n in range(max(1, int(tentativas or 1))):
        achou = _abrir_pasta_variantes(janela_sp, nomes)
        if achou:
            return achou
        motivo = _motivo_falha_pasta_sp()
        if motivo == _MOTIVO_SP_ABERTURA_FALHOU:
            registrar_log(
                f"AVISO [SP]: navegação incorreta em '{chave}' — "
                "tentando novamente (não é pasta inexistente).",
                "AVISO",
            )
            try:
                _CacheUIA.invalidar(janela_sp)
            except Exception:
                pass
            time.sleep(1.0)
            continue
        if thread is None:
            return ""
        ok = thread.aguardar_confirmacao(
            "Pasta não encontrada no SharePoint",
            "__PASTA_SP__" + _mensagem_pasta_sp_nao_encontrada(chave, nomes),
        )
        if not ok:
            return ""
        try:
            _CacheUIA.invalidar(janela_sp)
        except Exception:
            pass
        time.sleep(1.0)
    return ""


def _variantes_pasta_mes_cert(ano_ref, mes_num, mes_nome) -> list:
    try:
        mes_i = int(mes_num)
    except Exception:
        mes_i = 0
    pad = f"{mes_i:02d}" if mes_i else str(mes_num or "")
    abrev = MESES_ABREV_PT.get(mes_i, "") or str(mes_nome or "")[:3]
    cap = (abrev[:1].upper() + abrev[1:].lower()) if abrev else ""
    nome = str(mes_nome or "")
    saida = []
    for n in (
        f"{pad}.{cap}",
        f"{pad}. {cap}",
        f"{pad}.{abrev}",
        f"{pad}.{abrev.capitalize()}",
        f"{pad}.{abrev.upper()}",
        f"{pad}. {abrev.capitalize()}",
        f"{pad}.{nome.capitalize()}" if nome else "",
        f"{pad}. {nome.capitalize()}" if nome else "",
        nome,
        nome.capitalize() if nome else "",
    ):
        t = (n or "").strip()
        if t and t not in saida:
            saida.append(t)
    return saida


def _subpasta_por_variantes(pasta: Path, nomes) -> Path | None:
    try:
        if not pasta or not Path(pasta).is_dir():
            return None
        filhos = {p.name.lower(): p for p in Path(pasta).iterdir() if p.is_dir()}
    except Exception:
        return None
    for nome in nomes or []:
        alvo = (nome or "").strip().lower()
        if not alvo:
            continue
        if alvo in filhos:
            return filhos[alvo]
        for atual, p in filhos.items():
            if alvo in atual or atual in alvo:
                return p
    return None


def _pastas_contratos_vigentes_local() -> list:
    saida = []
    vistos = set()
    bases = [
        Path.home() / "PETROBRAS" / "BS SOP GPS - CS-II",
    ]
    try:
        bases.append(
            Path("C:/Users") / os.environ.get("USERNAME", "") / "PETROBRAS"
            / "BS SOP GPS - CS-II"
        )
    except Exception:
        pass
    for base in bases:
        for nome in (
            "4.Contratos vigentes",
            "4. Contratos vigentes",
            "4.Contratos Vigentes",
        ):
            p = Path(base) / nome
            try:
                chave = str(p.resolve()).lower()
            except Exception:
                chave = str(p).lower()
            if chave in vistos:
                continue
            if p.is_dir():
                vistos.add(chave)
                saida.append(p)
    return saida


def _criar_pasta_mes_cert(pasta_ano_ou_cert: Path, ano_ref, mes_num, mes_nome) -> Path:
    ano_p = Path(pasta_ano_ou_cert)
    if ano_p.name != str(ano_ref):
        ano_p = Path(pasta_ano_ou_cert) / str(ano_ref)
    ano_p.mkdir(parents=True, exist_ok=True)
    nomes = _variantes_pasta_mes_cert(ano_ref, mes_num, mes_nome)
    existente = _subpasta_por_variantes(ano_p, nomes)
    if existente:
        return existente
    padrao = nomes[0] if nomes else f"{int(mes_num):02d}.{MESES_ABREV_PT.get(int(mes_num), 'mes')}"
    dest = ano_p / padrao
    dest.mkdir(parents=True, exist_ok=True)
    return dest


def _resolver_pasta_certidoes_local(
    contrato, ano_ref, mes_num, mes_nome, pasta_mes_medicao
):
    """
    Prioriza .../10. Medição/01. Medicao Mensal/Certidões/{ano}/{mês}
    se essa árvore já existir. Senão usa a pasta do mês da medição
    (mesmo lugar de Pedidos/FRS/RM).
    Retorna (Path, fora_do_mes: bool).
    """
    contrato = str(contrato or "").strip()
    vars_med = _lista_variantes_pasta("medicao")
    vars_mm = _lista_variantes_pasta("med_mensal")
    vars_cert = _lista_variantes_pasta("certidoes")
    meses = _variantes_pasta_mes_cert(ano_ref, mes_num, mes_nome)
    if contrato:
        for root in _pastas_contratos_vigentes_local():
            try:
                filhos = list(root.iterdir())
            except Exception:
                continue
            for pasta_c in filhos:
                try:
                    if not pasta_c.is_dir() or contrato not in pasta_c.name:
                        continue
                except Exception:
                    continue
                med = _subpasta_por_variantes(pasta_c, vars_med)
                if not med:
                    continue
                mm = _subpasta_por_variantes(med, vars_mm)
                if not mm:
                    continue
                cert = _subpasta_por_variantes(mm, vars_cert)
                if not cert:
                    continue
                ano_p = cert / str(ano_ref)
                if ano_p.is_dir():
                    mes_p = _subpasta_por_variantes(ano_p, meses)
                    if mes_p:
                        return mes_p, True
                return _criar_pasta_mes_cert(cert, ano_ref, mes_num, mes_nome), True
    pasta_mes = Path(pasta_mes_medicao) if pasta_mes_medicao else None
    if pasta_mes:
        pasta_mes.mkdir(parents=True, exist_ok=True)
        dest = pasta_mes / "Certidoes"
        dest.mkdir(parents=True, exist_ok=True)
        return dest, False
    dest = Path.home() / "Documents" / "Certidoes"
    dest.mkdir(parents=True, exist_ok=True)
    return dest, False


def _cnpj_contratada_dos_rms(pasta_rm, rms) -> str:
    for r in rms or []:
        rm_id = str((r or {}).get("rm") or "").strip()
        if not rm_id:
            continue
        pdf = Path(pasta_rm) / f"RM_{rm_id}.pdf"
        if not pdf.exists():
            continue
        try:
            texto = _extrair_texto_pdf_rapido(pdf)
        except Exception:
            texto = ""
        m = _RE_CNPJ_FORN.search(texto or "")
        if not m:
            continue
        dig = _so_digitos(m.group(1))
        if len(dig) == 14:
            return dig
    return ""


def _baixar_certidoes_contrato(cnpj, sap, pasta, thread=None, uf="RJ") -> list:
    """Baixa CNDT, CRF e CND via Edge/Playwright e devolve a lista de resultados."""
    cnpj = _so_digitos(cnpj)
    sap = _so_digitos(sap)
    pasta = Path(pasta)
    pasta.mkdir(parents=True, exist_ok=True)
    if len(cnpj) != 14:
        raise RuntimeError(
            "CNPJ da contratada precisa ter 14 dígitos para emitir as certidões."
        )
    mod = _modulo_certidoes()
    try:
        from playwright.sync_api import sync_playwright
    except Exception as e:
        raise RuntimeError(
            "Playwright não está instalado neste computador. "
            "Instale com: pip install playwright && playwright install msedge"
        ) from e
    resultados = []
    stamp = time.strftime("%Y%m%d_%H%M%S")
    sequencia = ("cndt", "crf", "cnd")
    registrar_log(
        f"CERTIDÕES: iniciando baixa CNPJ={cnpj} contrato={sap} pasta={pasta}",
        "INFO",
    )
    with sync_playwright() as pw:
        browser = pw.chromium.launch(
            channel="msedge",
            headless=False,
            slow_mo=40,
            args=["--start-maximized", "--disable-print-preview"],
        )
        context = browser.new_context(accept_downloads=True, no_viewport=True)
        page = context.new_page()
        try:
            if hasattr(mod, "_maximizar_edge"):
                mod._maximizar_edge(page)
        except Exception:
            pass
        for i, escolhido in enumerate(sequencia, start=1):
            dest = pasta / f"{escolhido.upper()}_{cnpj}_{stamp}_{i}.pdf"
            if thread is not None:
                try:
                    thread.atualizar_sub(
                        f"{escolhido.upper()} ({i}/{len(sequencia)})"
                    )
                    thread.atualizar_progresso(i, len(sequencia))
                except Exception:
                    pass
            print(f"\n----- {i}/{len(sequencia)} {escolhido.upper()} -----")
            try:
                if escolhido == "cndt":
                    item = mod.emitir_cndt(page, context, cnpj, dest, sap)
                elif escolhido == "crf":
                    item = mod.emitir_crf(
                        page, context, cnpj, dest, sap, uf=uf or "RJ"
                    )
                else:
                    item = mod.emitir_cnd(page, context, cnpj, dest, sap)
                resultados.append(item)
            except Exception as exc:
                registrar_log(
                    f"ERRO [CERTIDÃO {escolhido.upper()}]: {exc}",
                    "ERRO",
                )
                resultados.append(
                    {
                        "tipo": escolhido.upper(),
                        "ok": None,
                        "detalhe": f"{escolhido.upper()}: ERRO ({exc})",
                        "arquivo": "",
                    }
                )
        try:
            browser.close()
        except Exception:
            pass
    for item in resultados:
        marca = {True: "OK", False: "PENDENCIA", None: "?"}.get(
            item.get("ok"), "?"
        )
        registrar_log(
            f"CERTIDÃO [{marca}] {item.get('detalhe') or item.get('tipo')}",
            "OK" if item.get("ok") is True else "AVISO",
        )
    return resultados


def _executar_etapa_certidoes(params, thread, pasta_rm_local=None, rms=None) -> list:
    pasta = Path(params.get("pasta_certidoes_local") or "")
    if not pasta:
        pasta, fora = _resolver_pasta_certidoes_local(
            params.get("contrato"),
            params.get("ano_ref"),
            params.get("mes_num"),
            params.get("mes_nome"),
            Path(params.get("pasta_raiz_local") or "")
            / str(params.get("ano_ref") or "")
            / str(params.get("mes_pad") or ""),
        )
        params["pasta_certidoes_local"] = str(pasta)
        params["certidoes_fora_do_mes"] = bool(fora)
    cnpj = _so_digitos(params.get("cnpj_contratada") or "")
    if len(cnpj) != 14:
        cnpj = _so_digitos((params.get("dados_sap") or {}).get("cnpj") or "")
        if cnpj:
            params["cnpj_contratada"] = cnpj
    if len(cnpj) != 14:
        cnpj = _cnpj_contratada_dos_rms(
            pasta_rm_local or params.get("pasta_rm_local") or "",
            rms if rms is not None else params.get("rms") or [],
        )
        if cnpj:
            params["cnpj_contratada"] = cnpj
    if thread is not None:
        thread.avancar_etapa("Certidões", "CNDT + CRF + CND")
    resultados = _baixar_certidoes_contrato(
        cnpj,
        params.get("contrato") or "",
        pasta,
        thread=thread,
        uf=params.get("uf_contratada") or "RJ",
    )
    try:
        thread.atualizar_kpi(
            "cert",
            sum(1 for r in resultados if r.get("ok") is True),
            max(len(resultados), 1),
        )
    except Exception:
        pass
    problemas = [
        r for r in resultados
        if r.get("ok") is not True
    ]
    if problemas and thread is not None:
        linhas = []
        for r in problemas:
            linhas.append(
                f"- {r.get('tipo') or '?'}: {r.get('detalhe') or 'sem validade OK'}"
            )
        thread.aguardar_confirmacao(
            "Certidões — ciente da validade",
            "__CERTIDOES_CIENTE__" + "\n".join(linhas),
        )
    return resultados



def _encontrar_pasta_sharepoint_na_tela(janela_sp, categoria: str) -> str:
    """
    Uma passada na lista visível (cache UIA já fresco).
    Não invalida a árvore — _nome_pasta_na_arvore_sp fazia
    descendants() de novo e custava dezenas de segundos.
    """
    try:
        controles = _CacheUIA.get(janela_sp) or []
    except Exception:
        controles = []
    tipos_ok = set(
        UI_ALIASES.get("tipos_item_sharepoint")
        or ["Button", "Hyperlink", "ListItem"]
    )
    for variante in _lista_variantes_pasta(categoria):
        for ctrl in controles:
            try:
                texto = (ctrl.window_text() or "").strip()
                if not texto:
                    continue
                tipo = str(ctrl.element_info.control_type or "")
                if tipo not in tipos_ok:
                    continue
                if _eh_wrapper_linha_sp(texto) or _texto_parece_arquivo_sp(texto):
                    continue
                if not _rotulos_ui_coincidem(variante, texto, False):
                    continue
                nome = _nome_exibido_pasta_sp(texto) or variante
                tl = (nome or "").lower()
                if categoria in ("Pedidos Pai", "Espelho NF Pai"):
                    if any(x in tl for x in ("servi", "materi", "frs")):
                        continue
                return nome
            except Exception:
                continue
    return ""


def _encontrar_pasta_sharepoint(janela_sp, categoria: str) -> str:
    """
    Procura a pasta já existente no SharePoint para a categoria dada
    (Pedidos/FRS/RM/Espelho NF), testando várias variações de nome
    (singular/plural, com apóstrofo, nome por extenso etc.) em vez de só
    o nome exato. Invalida o cache UIA (a lista do mês não pode ficar
    com a árvore da pasta Pedidos) e rola a grade virtualizada.
    Retorna o nome exato encontrado, ou "" se não existir.
    """
    try:
        _CacheUIA.invalidar(janela_sp)
    except Exception:
        pass
    nome = _encontrar_pasta_sharepoint_na_tela(janela_sp, categoria)
    if nome:
        return nome
    for _ in range(4):
        try:
            _rolar_lista_interna_sharepoint(janela_sp, rapido=True)
        except Exception:
            break
        time.sleep(0.08)
        try:
            _CacheUIA.invalidar(janela_sp)
        except Exception:
            pass
        nome = _encontrar_pasta_sharepoint_na_tela(janela_sp, categoria)
        if nome:
            return nome
        try:
            if _scrollbar_lista_no_fim(janela_sp):
                break
        except Exception:
            break
    return ""


def _parece_linha_pasta_sp(texto: str) -> bool:
    """
    True só para linha de PASTA na grade do SharePoint.
    Não conta chrome do Edge nem texto solto (causava '75 pastas').
    """
    t = (texto or "").strip()
    if not t or len(t) > 220:
        return False
    if _texto_parece_arquivo_sp(t):
        return False
    if _e_titulo_aba_ou_janela_sp(t):
        return False
    if _varios_contratos_no_texto(t):
        return False
    tl = t.lower()
    # Marcadores reais de linha de pasta no SP
    if not (
        "selecionar linha" in tl
        or "select row" in tl
        or re.search(r"\bpasta\s+\S", tl)
        or re.search(r"\bfolder\s+\S", tl)
    ):
        return False
    nome = (_nome_exibido_pasta_sp(t) or "").strip()
    if not nome or len(nome) > 120:
        return False
    if _texto_parece_arquivo_sp(nome):
        return False
    return True


def _qtd_pastas_lista_sp(janela_sp) -> int:
    """Só pastas na grade — arquivos PDF/ZIP não contam."""
    n = 0
    vistos = set()
    try:
        controles = _CacheUIA.get(janela_sp) or []
    except Exception:
        return 0
    tipos_ok = set(
        UI_ALIASES.get("tipos_item_sharepoint")
        or ["Button", "Hyperlink", "ListItem", "Link"]
    )
    for ctrl in controles:
        try:
            texto = (ctrl.window_text() or "").strip()
            if not _parece_linha_pasta_sp(texto):
                continue
            tipo = str(ctrl.element_info.control_type or "")
            if tipo not in tipos_ok:
                continue
            nome = (_nome_exibido_pasta_sp(texto) or texto).strip().lower()
            if not nome or nome in vistos:
                continue
            vistos.add(nome)
            n += 1
        except Exception:
            continue
    return n


def _inventariar_pastas_mes_sp(janela_sp) -> dict:
    """
    Uma passagem só nas pastas de 1º nível do mês
    (Pedidos / FRS / RM / Espelho NF). Ignora arquivos.
    Rolagem só se houver pastas de verdade demais para a tela.
    """
    _t0 = time.time()
    chaves = ("Pedidos Pai", "FRS", "RM", "Espelho NF Pai", "certidoes")
    out = {c: "" for c in chaves}
    try:
        _CacheUIA.get(janela_sp)
    except Exception:
        pass
    if _texto_pasta_vazia_sp(janela_sp):
        print(f"  Inventário mês: pasta vazia ({time.time() - _t0:.1f}s).")
        return out

    def _preencher_faltantes():
        for cat in chaves:
            if out[cat]:
                continue
            out[cat] = _encontrar_pasta_sharepoint_na_tela(janela_sp, cat) or ""

    _preencher_faltantes()
    faltam = [c for c, n in out.items() if not n]
    if not faltam:
        print(f"  Inventário mês: {time.time() - _t0:.1f}s (completo, sem rolagem).")
        return out

    # Nenhuma das 4 categorias na 1ª passagem: no mês típico o upload
    # cria — não conta pastas de novo (UIA extra).
    if len(faltam) == 4:
        print(
            f"  Inventário mês: {time.time() - _t0:.1f}s "
            "(categorias ausentes — serão criadas)."
        )
        return out

    n_pastas = _qtd_pastas_lista_sp(janela_sp)
    # Mês típico: 0–6 pastas. Se faltam categorias e cabem na tela, não
    # existem (upload cria) — não gastar UIA rolando à toa.
    _CABEM_TELA = 8
    if n_pastas <= _CABEM_TELA:
        print(
            f"  Inventário mês: {time.time() - _t0:.1f}s "
            f"({n_pastas} pasta(s), sem rolagem — faltantes serão criadas)."
        )
        return out

    # Lista longa de pastas: no máx. 2 rolagens (não 4)
    max_rolagens = min(2, 1 + (n_pastas - _CABEM_TELA) // 8)
    rolagens = 0
    for _ in range(max_rolagens):
        try:
            _rolar_lista_interna_sharepoint(janela_sp, rapido=True)
        except Exception:
            break
        rolagens += 1
        time.sleep(0.05)
        try:
            _CacheUIA.invalidar(janela_sp)
            _CacheUIA.get(janela_sp)
        except Exception:
            pass
        _preencher_faltantes()
        faltam = [c for c, n in out.items() if not n]
        if not faltam:
            break
        try:
            if _scrollbar_lista_no_fim(janela_sp):
                break
        except Exception:
            break

    print(
        f"  Inventário mês: {time.time() - _t0:.1f}s "
        f"({n_pastas} pastas, {rolagens} rolagem(ns))."
    )
    return out


def _qtd_itens_lista_sp(janela_sp) -> int:
    """Itens da grade (pastas/arquivos), não chrome do Edge."""
    n = 0
    try:
        controles = _CacheUIA.get(janela_sp) or []
    except Exception:
        return 0
    for ctrl in controles:
        try:
            texto = (ctrl.window_text() or "").strip()
            if not texto or len(texto) > 180:
                continue
            tipo = str(ctrl.element_info.control_type or "")
            if tipo not in ("Button", "Hyperlink", "ListItem", "Link"):
                continue
            if _eh_wrapper_linha_sp(texto) or _e_titulo_aba_ou_janela_sp(texto):
                continue
            n += 1
        except Exception:
            continue
    return n


def _texto_pasta_vazia_sp(janela_sp) -> bool:
    """SharePoint já abriu a pasta, só não tem arquivo/subpasta."""
    frases = (
        "esta pasta está vazia",
        "this folder is empty",
        "não há itens",
        "nao ha itens",
        "there are no items",
        "nenhum item",
        "nenhum arquivo",
        "nothing here",
        "arraste arquivos",
        "drag files",
        "drop files here",
        "arraste e solte",
    )
    try:
        ctrls = _CacheUIA.get(janela_sp) or []
    except Exception:
        ctrls = []
    for ctrl in ctrls[:400]:
        try:
            t = (ctrl.window_text() or "").strip().lower()
        except Exception:
            continue
        if not t or len(t) > 140:
            continue
        if any(f in t for f in frases):
            return True
    return False


def _grade_biblioteca_sp_pronta(janela_sp) -> bool:
    """
    A lista do mês já apareceu (cabeçalho, linhas ou 'vazia').
    Usa o cache UIA; só invalida 1x se ainda não estiver pronta.
    """
    def _ok() -> bool:
        if _cabecalhos_faixa_lista_sp(janela_sp):
            return True
        if _linhas_pasta_lista_sp(janela_sp):
            return True
        if _texto_pasta_vazia_sp(janela_sp):
            return True
        return _qtd_itens_lista_sp(janela_sp) >= 1

    if _ok():
        return True
    try:
        _CacheUIA.invalidar(janela_sp)
    except Exception:
        pass
    return _ok()


def _lista_sp_pronta(janela_sp, categorias_mes: bool = False) -> bool:
    """True quando a grade já renderizou — com ou sem pastas de categoria."""
    return _grade_biblioteca_sp_pronta(janela_sp)


def _esperar_pagina_sp_carregada(
    janela_sp, timeout=20, categorias_mes=False, recarregar=True
) -> bool:
    """
    Dois casos distintos:
      - Grade ainda não apareceu → espera / F5 (não carregou).
      - Grade visível (outros arquivos ou vazia) sem Pedidos/FRS/RM/
        Espelho → carregou; essas pastas não existem; o upload cria.
    recarregar=False: não manda F5 (evita reload desnecessário).
    """
    print("  Aguardando a lista da pasta carregar...")
    inicio = time.time()
    fim = inicio + timeout
    recargas = 0
    while time.time() < fim:
        if _lista_sp_pronta(janela_sp, categorias_mes=categorias_mes):
            if categorias_mes:
                print(
                    "  Lista do mês carregada "
                    "(upload cria Pedidos/FRS/RM/Espelho se faltarem)."
                )
            else:
                print("  Lista da pasta carregada.")
            return True
        if (
            recarregar
            and recargas < 1
            and time.time() - inicio >= 3.5
        ):
            print("  Grade ainda não apareceu — recarregando (1/1)...")
            try:
                janela_sp.set_focus()
                send_keys("{F5}")
            except Exception:
                pass
            recargas += 1
        time.sleep(0.15)
    print("  AVISO: lista da pasta não carregou após espera e recarga.")
    return False


def _ids_em_nome_arquivo(nome: str) -> set:
    """Números de Pedido/FRS/RM (8 a 12 dígitos) presentes no nome."""
    return set(re.findall(r"\d{8,12}", nome or ""))


def _texto_sp_e_o_arquivo_enviado(esperado: str, texto: str) -> bool:
    """Não aceita P-68 no lugar do nosso Pedido_N.pdf nem .pdfor.pdf."""
    e = (esperado or "").lower().strip()
    t = (texto or "").lower().strip()
    if not e or not t:
        return False
    if "pdfor" in t or t.endswith(".pdf.pdf"):
        return False
    if t == e:
        return True
    return bool(re.search(r"(?:^|[\s/])" + re.escape(e) + r"(?:$|[\s])", t))


def arquivo_ja_existe_sharepoint(janela_sp, numero):
    try:
        controles = _CacheUIA.get(janela_sp)      # ← usa cache
    except Exception:
        return False
    num = str(numero or "").strip()
    if not num:
        return False
    for ctrl in controles:
        try:
            texto = ctrl.window_text().strip()
            if num in _ids_em_nome_arquivo(texto) or num in texto:
                print(f"\nArquivo {numero} já existe — pulando.")
                return True
        except Exception:
            pass
    return False

def validar_upload(janela_sp, nome_esperado, timeout=10):
    """
    Aguarda o arquivo aparecer na UI do SharePoint.
    Parâmetro timeout = número de segundos máximos de espera.
    Detecta erros visíveis na UI a cada ~3s.
    """
    print(f"\nValidando upload: '{nome_esperado}'...")
    nome_lower = nome_esperado.lower().strip()
    passos = max(1, int(timeout))
    intervalo = 0.35

    for tentativa in range(passos):

        try:
            if tentativa == 0 or tentativa % 2 == 1:
                _CacheUIA.invalidar(janela_sp)
            controles = _CacheUIA.get(janela_sp)
            for ctrl in controles:
                try:
                    if nome_lower in ctrl.window_text().strip().lower():
                        if _texto_sp_e_o_arquivo_enviado(
                            nome_esperado, ctrl.window_text()
                        ):
                            print(f"Upload validado: '{nome_esperado}' encontrado.")
                            return True
                except Exception:
                    pass
        except Exception:
            pass

        # Diagnóstico a cada ~3s — detecta erros visíveis na UI
        if tentativa > 0 and tentativa % 8 == 0:
            try:
                for ctrl in janela_sp.descendants():
                    try:
                        texto = ctrl.window_text().strip()
                        for err in [
                            "não foi possível", "falhou", "erro",
                            "could not", "failed", "error",
                            "arquivo não encontrado", "caminho inválido",
                        ]:
                            if err in texto.lower() and 5 < len(texto) < 200:
                                registrar_log(
                                    f"⚠ [VALIDAÇÃO] Erro detectado na UI "
                                    f"({tentativa}s): '{texto}'"
                                )
                    except Exception:
                        pass
            except Exception:
                pass

        print(
            f"Aguardando '{nome_esperado}'... "
            f"{tentativa + 1}/{passos}"
        )
        time.sleep(intervalo)

    registrar_log(
        f"ERRO [VALIDAÇÃO]: '{nome_esperado}' não confirmado após {timeout}s.\n"
        f"  Causas possíveis:\n"
        f"  1. Caminho inserido incorretamente no diálogo\n"
        f"  2. Upload iniciado mas SP demorou mais que {timeout}s\n"
        f"  3. Sessão do Edge expirou ou página recarregada\n"
        f"  4. Arquivo com mesmo nome já existia e SP não atualizou a UI\n"
        f"  → Verifique manualmente a pasta no SharePoint."
    )
    return False


_MARCAS_FALHA_UPLOAD_SP = (
    "não foi carregado",
    "nao foi carregado",
    "wasn't uploaded",
    "was not uploaded",
    "weren't uploaded",
    "were not uploaded",
    "failed to upload",
    "não foi possível carregar",
    "nao foi possivel carregar",
    "couldn't upload",
    "could not upload",
    "unable to upload",
    "upload failed",
)


def _textos_marca_upload_sp(janela_sp, marcas, excluir=(), profundo=False) -> set:
    """Toasts de upload. Por padrão só o cache UIA — descendants() a cada
    poll deixava o SharePoint lento (~minutos)."""
    achados = set()
    ctrls = []
    try:
        ctrls.extend(_CacheUIA.get(janela_sp) or [])
    except Exception:
        pass
    if profundo:
        try:
            extra = janela_sp.descendants()
            if extra:
                ids = {id(c) for c in ctrls}
                for c in extra[:400]:
                    if id(c) not in ids:
                        ctrls.append(c)
        except Exception:
            pass
    for ctrl in ctrls:
        try:
            tx = (ctrl.window_text() or "").strip()
        except Exception:
            continue
        if not tx or len(tx) > 280:
            continue
        tl = tx.lower()
        if any(m in tl for m in excluir):
            continue
        if any(m in tl for m in marcas):
            achados.add(tx)
    return achados


def _textos_falha_upload_sp(janela_sp, profundo=False) -> set:
    """Toasts do SharePoint: '1 item não foi carregado para 07. Julho'."""
    return _textos_marca_upload_sp(
        janela_sp, _MARCAS_FALHA_UPLOAD_SP, profundo=profundo
    )


def _texto_falha_upload_sp(janela_sp) -> str:
    achados = _textos_falha_upload_sp(janela_sp)
    if not achados:
        return ""
    return sorted(achados, key=len)[0]


_MARCAS_SUCESSO_UPLOAD_SP = (
    "itens foram carregados",
    "item foi carregado",
    "uploaded to",
    "was uploaded",
    "were uploaded",
    "carregado para",
)


def _textos_sucesso_upload_sp(janela_sp, profundo=False) -> set:
    return _textos_marca_upload_sp(
        janela_sp, _MARCAS_SUCESSO_UPLOAD_SP,
        excluir=_MARCAS_FALHA_UPLOAD_SP, profundo=profundo,
    )


def _aguardar_nova_falha_upload_sp(janela_sp, antes, timeout=3.0) -> str:
    """Texto de um toast de falha que apareceu depois do upload, ou vazio."""
    antes = set(antes or ())
    try:
        _CacheUIA.invalidar(janela_sp)
    except Exception:
        pass
    fim = time.time() + timeout
    while time.time() < fim:
        profundo = (fim - time.time()) < 0.45
        novos = _textos_falha_upload_sp(janela_sp, profundo=profundo) - antes
        if novos:
            return sorted(novos, key=len)[0]
        time.sleep(0.25)
    novos = _textos_falha_upload_sp(janela_sp, profundo=True) - antes
    if novos:
        return sorted(novos, key=len)[0]
    return ""


def _aguardar_sucesso_upload_sp(janela_sp, timeout=6.0) -> str:
    try:
        _CacheUIA.invalidar(janela_sp)
    except Exception:
        pass
    fim = time.time() + timeout
    while time.time() < fim:
        profundo = (fim - time.time()) < 0.45
        achados = _textos_sucesso_upload_sp(janela_sp, profundo=profundo)
        if achados:
            return sorted(achados, key=len)[0]
        time.sleep(0.25)
    achados = _textos_sucesso_upload_sp(janela_sp, profundo=True)
    if achados:
        return sorted(achados, key=len)[0]
    return ""


def _arquivos_a_confirmar_upload(pasta_local):
    try:
        pasta = Path(pasta_local)
        if not pasta.exists():
            return []
        return [p for p in pasta.iterdir() if p.is_file()]
    except Exception:
        return []


def _arquivo_visto_na_lista_sp(textos_lower, arquivo: Path) -> bool:
    """True se o arquivo local aparece na pasta já aberta do SharePoint."""
    nome = (arquivo.name or "").lower()
    stem = (arquivo.stem or "").lower()
    stem_espaco = stem.replace("_", " ")
    ids = _ids_em_nome_arquivo(arquivo.name)
    for t in textos_lower:
        if not t:
            continue
        if nome and nome in t:
            return True
        if stem and stem in t:
            return True
        if stem_espaco and stem_espaco in t:
            return True
        ids_t = _ids_em_nome_arquivo(t)
        if ids and (ids & ids_t) and (
            _texto_parece_arquivo_sp(t) or ".pdf" in t
        ):
            return True
    return False


def _conteudo_upload_confirmado_sp(janela_sp, pasta_local, timeout=8) -> bool:
    """
    Confere se os arquivos locais estão DENTRO da pasta já aberta.
    Pasta visível na lista do mês (mesmo vazia) não conta.
    """
    esperados = _arquivos_a_confirmar_upload(pasta_local)
    if not esperados:
        return False
    fim = time.time() + max(2, int(timeout))
    while True:
        try:
            _CacheUIA.invalidar(janela_sp)
        except Exception:
            pass
        if _texto_pasta_vazia_sp(janela_sp):
            if time.time() >= fim:
                return False
            time.sleep(0.45)
            continue
        textos = []
        try:
            for ctrl in _CacheUIA.get(janela_sp) or []:
                try:
                    t = (ctrl.window_text() or "").strip()
                except Exception:
                    continue
                if t:
                    textos.append(t.lower())
        except Exception:
            pass
        if esperados and all(
            _arquivo_visto_na_lista_sp(textos, p) for p in esperados
        ):
            return True
        if time.time() >= fim:
            return False
        time.sleep(0.45)


def esperar_sharepoint_estavel(janela_sp, timeout: int = 2,
                                intervalo: float = 0.3) -> bool:
    """
    Aguarda a árvore UIA do SharePoint parar de mudar.
    Substitui time.sleep() fixos na navegação de pastas.
    Retorna True quando estável, False se timeout.
    """
    if not getattr(Config, "SP_ESPERA_DINAMICA", True):
        time.sleep(min(timeout, 3))
        return True

    ultimo_total   = -1
    repeticoes_est = 0
    fim            = time.time() + timeout
    # 1 invalidação no início — o loop reusa o cache
    try:
        _CacheUIA.invalidar(janela_sp)
    except Exception:
        pass

    while time.time() < fim:
        try:
            total = len(_CacheUIA.get(janela_sp))

            if total == ultimo_total and total > 0:
                itens = _qtd_itens_lista_sp(janela_sp)
                grade_ok = (
                    itens >= 1
                    or bool(_cabecalhos_faixa_lista_sp(janela_sp))
                    or _texto_pasta_vazia_sp(janela_sp)
                )
                if grade_ok:
                    repeticoes_est += 1
                    if repeticoes_est >= 2:
                        return True
                else:
                    repeticoes_est = 0
            else:
                repeticoes_est = 0
                ultimo_total   = total
                # Só re-lê UIA quando a árvore ainda está mudando
                try:
                    _CacheUIA.invalidar(janela_sp)
                except Exception:
                    pass

        except Exception:
            pass

        time.sleep(intervalo)

    return False


_MARCAS_LOGIN_SP = (
    "login.microsoftonline",
    "login.live.com",
    "sign in to your account",
    "entrar na sua conta",
    "pick an account",
    "escolher uma conta",
    "use your password",
    "use a senha da sua conta",
    "conta da microsoft",
    "microsoft account",
    "vamos começar",
    "let's get you signed in",
)


def _texto_janela_sharepoint(janela) -> str:
    partes = []
    try:
        partes.append(janela.window_text() or "")
    except Exception:
        pass
    try:
        for ctrl in janela.descendants()[:150]:
            try:
                tx = (ctrl.window_text() or "").strip()
                if tx and len(tx) < 400:
                    partes.append(tx)
            except Exception:
                continue
    except Exception:
        pass
    return " ".join(partes).lower()


def _sharepoint_parece_login(janela) -> bool:
    t = _texto_janela_sharepoint(janela)
    if not t:
        return False
    if any(m in t for m in _MARCAS_LOGIN_SP):
        lista_ok = any(
            p in t for p in (
                "med mensal", "10. medição", "10. medic",
                "biblioteca de documentos", "document library",
            )
        )
        if lista_ok and "login.microsoftonline" not in t:
            return False
        return True
    return False


def _pids_msedge() -> set:
    pids = set()
    try:
        import psutil
        for p in psutil.process_iter(["name", "pid"]):
            if (p.info.get("name") or "").lower() == "msedge.exe":
                pids.add(int(p.info["pid"]))
    except Exception:
        pass
    return pids


def _titulo_nao_e_edge(titulo: str) -> bool:
    t = (titulo or "").lower()
    return any(
        p in t
        for p in (
            "visual studio code",
            "cursor agents",
            "automacao sap",
            "automação sap",
        )
    )


def _enum_janelas_msedge() -> list:
    """Janelas visíveis do Microsoft Edge (não VS Code/Cursor/Electron)."""
    itens = []
    try:
        import win32gui
        import win32process
        pids = _pids_msedge()

        def _cb(hwnd, _):
            try:
                if not win32gui.IsWindowVisible(hwnd):
                    return
                if win32gui.GetParent(hwnd):
                    return
                _, pid = win32process.GetWindowThreadProcessId(hwnd)
                titulo = win32gui.GetWindowText(hwnd) or ""
                if not titulo.strip():
                    return
                if _titulo_nao_e_edge(titulo):
                    return
                tl = titulo.lower()
                if pids:
                    if pid not in pids:
                        return
                elif "microsoft edge" not in tl:
                    return
                cls = win32gui.GetClassName(hwnd) or ""
                itens.append(
                    {
                        "hwnd": int(hwnd),
                        "titulo": titulo,
                        "pid": pid,
                        "cls": cls,
                    }
                )
            except Exception:
                pass

        win32gui.EnumWindows(_cb, None)
    except Exception:
        pass
    return itens


def _score_janela_edge_sharepoint(item: dict, hwnds_antes: set) -> int:
    t = (item.get("titulo") or "").lower()
    if _titulo_nao_e_edge(t):
        return -100
    score = 0
    hwnd = item.get("hwnd")
    if hwnds_antes and hwnd not in hwnds_antes:
        score += 35
    if "microsoft edge" in t:
        score += 8
    if "sharepoint" in t and "microsoft edge" in t:
        score += 50
    if any(p in t for p in ("documentos", "bs/sop", "contratos vigentes")):
        score += 40
    if "onedrive" in t:
        score += 12
    if "login.microsoftonline" in t or "entrar na sua conta" in t:
        score += 6
    if "teams" in t and "sharepoint" not in t and "documentos" not in t:
        score -= 20
    return score


def _restaurar_hwnd(hwnd) -> None:
    try:
        import win32gui
        import win32con
        if win32gui.IsIconic(hwnd):
            win32gui.ShowWindow(hwnd, win32con.SW_RESTORE)
        win32gui.ShowWindow(hwnd, win32con.SW_SHOW)
        try:
            win32gui.SetForegroundWindow(hwnd)
        except Exception:
            pass
    except Exception:
        pass


_janela_sp_ativa = None


def _janela_sp_valida(jan) -> bool:
    if jan is None:
        return False
    try:
        if hasattr(jan, "exists") and not jan.exists(timeout=0.8):
            return False
        jan.set_focus()
        return True
    except Exception:
        return False


def _conectar_hwnd_edge(hwnd):
    _restaurar_hwnd(hwnd)
    app = Application(backend="uia").connect(handle=hwnd, timeout=3)
    return app.window(handle=hwnd) or app.top_window()


def _exe_msedge() -> str:
    for p in (
        Path(r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe"),
        Path(r"C:\Program Files\Microsoft\Edge\Application\msedge.exe"),
    ):
        if p.is_file():
            return str(p)
    return ""


def _esperar_janela_edge_sharepoint(timeout: float = 22.0):
    """
    Espera a aba carregar e conecta no Edge real (Documentos/SharePoint),
    não no VS Code. hwnd novo não é obrigatório — aba reusa a janela.
    """
    fim = time.time() + timeout
    melhor = None
    melhor_sc = -10
    while time.time() < fim:
        for item in _enum_janelas_msedge() or []:
            sc = _score_janela_edge_sharepoint(item, set())
            if sc > melhor_sc:
                melhor_sc = sc
                melhor = item
        if melhor is not None and melhor_sc >= 40:
            registrar_log(
                "INFO [SHAREPOINT]: Edge conectado — "
                f"'{melhor.get('titulo', '')[:80]}' "
                f"(score={melhor_sc}).",
                "INFO",
            )
            try:
                return _conectar_hwnd_edge(melhor["hwnd"])
            except Exception:
                pass
        time.sleep(0.4)
    if melhor is None:
        return None
    try:
        return _conectar_hwnd_edge(melhor["hwnd"])
    except Exception:
        return None


def _abrir_ou_reusar_janela_sharepoint(url: str, timeout: float = 18.0):
    """
    Edge já aberto: nova aba com o link (qualquer monitor).
    Edge fechado: janela nova.
    Entre contratos da fila: reusa a mesma janela e navega pela URL.
    """
    global _janela_sp_ativa
    jan = _janela_sp_ativa if _janela_sp_valida(_janela_sp_ativa) else None
    if jan is not None:
        try:
            if _navegar_via_endereco(jan, url):
                _janela_sp_ativa = jan
                registrar_log(
                    "SHAREPOINT: mesma janela do Edge — link inicial.",
                    "INFO",
                )
                esperar_sharepoint_estavel(jan, timeout=2.5)
                return jan
        except Exception:
            jan = None
        _janela_sp_ativa = None

    import subprocess
    exe = _exe_msedge()
    edge_aberto = bool(_pids_msedge())
    if edge_aberto:
        print("Edge já aberto — abrindo o link numa aba nova...")
        registrar_log("SHAREPOINT: Edge já aberto — nova aba.", "INFO")
    else:
        print("Edge fechado — abrindo uma janela nova...")
        registrar_log("SHAREPOINT: Edge fechado — nova janela.", "INFO")
    if exe:
        cmd = [exe, url] if edge_aberto else [exe, "--new-window", url]
        subprocess.Popen(
            cmd,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    else:
        webbrowser.open(url)

    jan = _esperar_janela_edge_sharepoint(timeout=max(float(timeout), 22.0))
    if jan is None:
        return None
    try:
        jan.set_focus()
    except Exception:
        pass
    esperar_sharepoint_estavel(jan, timeout=4)
    _janela_sp_ativa = jan
    return jan


def _conectar_janela_edge_sharepoint(hwnds_antes: set, timeout: float = 18.0):
    """
    Com várias janelas do Edge abertas, Application.connect(title_re=...Edge...)
    falha (vários matches) ou pega a janela errada. Escolhe a janela nova
    ou a que tem SharePoint no título e conecta pelo hwnd.
    """
    fim = time.time() + timeout
    melhor = None
    melhor_score = -10
    while time.time() < fim:
        for item in _enum_janelas_msedge():
            sc = _score_janela_edge_sharepoint(item, hwnds_antes)
            if sc > melhor_score:
                melhor_score = sc
                melhor = item
        if melhor is not None and melhor_score >= 8:
            try:
                _restaurar_hwnd(melhor["hwnd"])
                app = Application(backend="uia").connect(
                    handle=melhor["hwnd"], timeout=2
                )
                jan = app.window(handle=melhor["hwnd"])
                if jan is None:
                    jan = app.top_window()
                registrar_log(
                    "INFO [SHAREPOINT]: Edge conectado — "
                    f"'{melhor.get('titulo', '')[:80]}' "
                    f"(score={melhor_score}).",
                    "INFO",
                )
                return jan
            except Exception:
                pass
        time.sleep(0.35)
    if melhor is not None:
        try:
            _restaurar_hwnd(melhor["hwnd"])
            app = Application(backend="uia").connect(
                handle=melhor["hwnd"], timeout=3
            )
            return app.window(handle=melhor["hwnd"]) or app.top_window()
        except Exception as e:
            registrar_log(
                f"AVISO [SHAREPOINT]: connect pelo hwnd falhou: {e}",
                "AVISO",
            )
    return None


_sp_sessao_ok = False


def _aguardar_login_onedrive_sharepoint(janela, thread) -> bool:
    """
    Se o Edge abriu a tela de login do Microsoft/OneDrive/SharePoint,
    pede para o usuário logar e espera a lista aparecer.
    """
    global _sp_sessao_ok
    if janela is None:
        return False
    try:
        esperar_sharepoint_estavel(janela, timeout=3)
    except Exception:
        pass
    if not _sharepoint_parece_login(janela):
        _sp_sessao_ok = True
        return True
    if _sp_sessao_ok:
        registrar_log(
            "SHAREPOINT: sessão já autenticada nesta execução — "
            "seguindo sem tela de validação.",
            "INFO",
        )
        try:
            esperar_sharepoint_estavel(janela, timeout=6)
        except Exception:
            pass
        return True
    registrar_log(
        "AVISO [SHAREPOINT]: tela de login detectada "
        "(OneDrive/SharePoint). Pedindo login.",
        "AVISO",
    )
    for _n in range(8):
        thread.aguardar_confirmacao(
            "Login SharePoint / OneDrive",
            "O SharePoint ou o OneDrive pediu login.\n\n"
            "Faça login na janela do Edge (conta Petrobras).\n"
            "Quando a pasta/lista do SharePoint aparecer, clique em OK.\n\n"
            "A automação só continua depois do login.",
        )
        try:
            esperar_sharepoint_estavel(janela, timeout=5)
        except Exception:
            pass
        if not _sharepoint_parece_login(janela):
            registrar_log("OK [SHAREPOINT]: login confirmado.")
            _sp_sessao_ok = True
            return True
        registrar_log(
            "AVISO [SHAREPOINT]: ainda parece tela de login — "
            "aguardando de novo.",
            "AVISO",
        )
    return False


def validar_upload_lote(janela_sp, nomes_esperados: list,
                        timeout: int = 10) -> bool:
    """
    Valida vários arquivos em uma única varredura repetida da UI.
    Mais rápido que chamar validar_upload() para cada arquivo.
    """
    # Deduplica mantendo ordem — evita validar o mesmo nome duas vezes
    _vistos = set()
    esperados = []
    for n in nomes_esperados:
        n_str = str(n).lower().strip()
        if n_str and n_str not in _vistos:
            esperados.append(n_str)
            _vistos.add(n_str)

    if not esperados:
        return True

    fim         = time.time() + timeout
    encontrados = {nome: False for nome in esperados}

    while time.time() < fim:
        # S2: set para O(1) lookup — era O(n×m) com lista
        try:
            _CacheUIA.invalidar(janela_sp)
            controles = _CacheUIA.get(janela_sp)
            textos_set = set()
            for ctrl in controles:
                try:
                    tx = ctrl.window_text().strip().lower()
                    if tx:
                        textos_set.add(tx)
                        # S2: Adicionar também substrings longas
                        if len(tx) > 10:
                            for palavra in tx.split():
                                if len(palavra) > 4:
                                    textos_set.add(palavra)
                except Exception:
                    pass
        except Exception:
            textos_set = set()

        for nome in esperados:
            if not encontrados[nome]:
                # S2: any() sobre set é O(1) average vs O(n) sobre lista
                encontrados[nome] = any(
                    _texto_sp_e_o_arquivo_enviado(nome, tx)
                    for tx in textos_set
                )

        if all(encontrados.values()):
            registrar_log(
                f"OK [VALIDACAO]: lote confirmado com "
                f"{len(esperados)} arquivo(s).",
                "OK"
            )
            return True

        pendentes = [n for n, ok in encontrados.items() if not ok]
        print(f"Aguardando lote SharePoint: {len(pendentes)} pendente(s)")
        time.sleep(0.3)

    pendentes = [n for n, ok in encontrados.items() if not ok]
    registrar_log(
        f"AVISO [VALIDACAO]: lote não confirmado. Pendentes: {pendentes}",
        "AVISO"
    )
    return False


# =====================================================
# HELPER — verifica se popup de upload está visível
# Usado para substituir time.sleep() fixos após clique
# =====================================================

def _popup_visivel(janela_sp) -> bool:
    """
    Retorna True se o botão 'Carregar' do popup
    de confirmação de upload estiver visível na UI.
    Usado em aguardar_condicao() para espera dinâmica.
    """
    try:
        for ctrl in janela_sp.descendants():
            try:
                texto = ctrl.window_text().strip()
                tipo  = ctrl.element_info.control_type
                if texto == "Carregar" and tipo == "Button":
                    return True
            except Exception:
                pass
    except Exception:
        pass
    return False


def _botao_sp_visivel(janela_sp, texto_botao: str) -> bool:
    """
    Retorna True se qualquer botão com o texto informado
    estiver visível na janela do SharePoint.
    Genérico — serve para qualquer botão SP.
    """
    try:
        _CacheUIA.invalidar(janela_sp)
        for ctrl in _CacheUIA.get(janela_sp):
            try:
                if (
                    ctrl.window_text().strip().lower()
                    == texto_botao.lower()
                    and ctrl.element_info.control_type == "Button"
                ):
                    return True
            except Exception:
                pass
    except Exception:
        pass
    return False


def _dialogo_arquivo_fechado(titulo_dialogo: str) -> bool:
    """
    Retorna True quando a janela do diálogo de arquivo
    do Windows NÃO está mais aberta.
    Útil para aguardar o fim do upload de forma dinâmica.
    """
    try:
        janelas = Desktop(backend="win32").windows(
            title=titulo_dialogo
        )
        return len(janelas) == 0
    except Exception:
        return True   # assume fechado em caso de erro

def confirmar_popup_carregar(janela_sp):
    """
    Aguarda e clica no botão 'Carregar' do popup de confirmação.

    Melhorias aplicadas:
      - Usa aguardar_condicao() para detectar o popup dinamicamente
        em vez de time.sleep(3) fixo antes de procurar
      - time.sleep(2) → 0.8s após clique (era fixo, agora reduzido)
      - time.sleep(1) → 0.4s entre tentativas (era fixo)
    """
    confirmado = False

    for tentativa in range(10):
        try:
            controles = janela_sp.descendants()
            for ctrl in controles:
                try:
                    texto = ctrl.window_text().strip()
                    tipo  = ctrl.element_info.control_type
                    nomes_popup = UI_ALIASES.get("botoes_popup_upload") or ["Carregar"]
                    if tipo == "Button" and any(
                        _rotulos_ui_coincidem(n, texto, exato=True)
                        or texto.strip() == n
                        for n in nomes_popup
                    ):
                        cx, cy = centro_ctrl(ctrl)
                        print(
                            f"\nPopup encontrado!\n"
                            f"Centro: ({cx},{cy})"
                        )
                        try:
                            ctrl.invoke()
                        except Exception:
                            try:
                                ctrl.click_input()
                            except Exception:
                                click(coords=(cx, cy))

                        # ✅ Era: time.sleep(2) — agora espera dinâmica
                        # Aguarda o popup fechar (botão sumir da UI)
                        aguardar_condicao(
                            lambda: not _popup_visivel(janela_sp),
                            timeout=1,
                            intervalo=0.15,
                            descricao="popup Carregar fechar"
                        )
                        # S3: sleep(0.8) removido — aguardar_condicao já garantiu
                        confirmado = True
                        break
                except Exception:
                    pass
        except Exception:
            pass

        if confirmado:
            break

        print(f"Aguardando popup... tentativa {tentativa + 1}")
        # ✅ Era: time.sleep(1) — reduzido para 0.4s
        time.sleep(0.4)

    return confirmado

def _confirmar_dialogo_abrir(timeout=1):
    """
    Clica no botão de confirmação do diálogo de arquivo do Windows.
    Usa win32 direto — mesmo padrão rápido do salvar_pdf().
    """
    titulos = [
        "Selecionar pasta para carregar",
        "Abrir",
        "Selecionar arquivo",
        "Open",
    ]

    janela = None
    for titulo in titulos:
        janela = aguardar_janela_titulo(titulo, timeout=0.5)
        if janela:
            break

    if not janela:
        send_keys("{ENTER}")
        time.sleep(0.2)
        return False

    # ── Mesmo padrão do salvar_pdf: win32 direto, sem UIA
    botoes_alvo = ["Carregar", "Abrir", "&Abrir", "Open", "&Open"]
    for nome_btn in botoes_alvo:
        try:
            btn = janela.child_window(
                title=nome_btn,
                class_name="Button"
            )
            if btn.exists(timeout=0.1):
                btn.click_input()
                time.sleep(0.15)
                return True
        except Exception:
            continue

    # Fallback: botão padrão ID=1 (IDOK do Windows)
    try:
        janela.child_window(auto_id="1").click_input()
        time.sleep(0.15)
        return True
    except Exception:
        pass

    # Último recurso
    send_keys("{ENTER}")
    time.sleep(0.2)
    return True



def _fechar_dialogo_caminho_invalido() -> bool:
    """Clica OK em 'Nome de pasta inválido' / caminho colado errado."""
    fechou = False
    try:
        from pywinauto import Desktop as _DeskInv
        janelas = list(_DeskInv(backend="win32").windows())
    except Exception:
        janelas = []
    for w in janelas:
        try:
            titulo = (w.window_text() or "").strip()
            if not titulo:
                continue
            tl = titulo.lower()
            if not any(
                p in tl
                for p in (
                    "selecionar pasta",
                    "abrir",
                    "open",
                    "upload",
                )
            ):
                continue
            try:
                w.set_focus()
            except Exception:
                pass
            for ctrl in w.descendants():
                try:
                    txt = (ctrl.window_text() or "").strip().lower()
                except Exception:
                    txt = ""
                if "nome de pasta inv" in txt or "invalid folder" in txt:
                    try:
                        w.child_window(title="OK", class_name="Button").click_input()
                    except Exception:
                        send_keys("{ENTER}")
                    time.sleep(0.2)
                    fechou = True
                    registrar_log(
                        "AVISO [DIÁLOGO]: fechado aviso de pasta inválida.",
                        "AVISO",
                    )
                    break
            if fechou:
                break
        except Exception:
            continue
    return fechou


def _ler_caminho_campo_dialogo():
    """Lê o texto do campo Pasta/Nome do diálogo de arquivo."""
    titulos = [
        "Selecionar pasta para carregar",
        "Selecionar pasta",
        "Abrir",
        "Selecionar arquivo",
        "Open",
    ]
    for titulo in titulos:
        janela = aguardar_janela_titulo(titulo, timeout=0.35)
        if not janela:
            continue
        for auto_id in ("1148", "1001", "1152"):
            try:
                ed = janela.child_window(auto_id=auto_id, class_name="Edit")
                if ed.exists(timeout=0.05):
                    return (ed.window_text() or "").strip()
            except Exception:
                continue
        try:
            for ed in janela.descendants(class_name="Edit"):
                txt = (ed.window_text() or "").strip()
                if txt:
                    return txt
        except Exception:
            pass
    return ""


def _caminho_dialogo_parece_valido(caminho_esperado: str, lido: str) -> bool:
    esp = str(Path(caminho_esperado).resolve())
    lid = (lido or "").strip().strip('"')
    if not lid:
        return False
    if re.match(r"^[a-zA-Z]:\\", lid):
        lid = lid[1:]
    if lid.startswith(esp) or esp.endswith(lid) or lid.endswith(Path(esp).name):
        return True
    if re.search(r"^[a-zA-Z]C:\\", lido or ""):
        return False
    return esp.lower() in lid.lower()


def digitar_caminho_dialogo(caminho):
    """
    Cola o(s) caminho(s) no diálogo de arquivo via clipboard.
    NÃO envia Enter nem clica Abrir — responsabilidade do chamador.
    Aguarda o diálogo aparecer ANTES de colar (garante foco correto).
    """
    caminhos_lista = []
    s = caminho.strip()
    if s.startswith('"'):
        import shlex
        try:
            caminhos_lista = shlex.split(s)
        except Exception:
            caminhos_lista = [s.strip('"')]
    else:
        caminhos_lista = [s]

    caminhos_lista = [str(Path(c).resolve()) for c in caminhos_lista]
    caminho_principal = caminhos_lista[0]
    for c in caminhos_lista:
        if not Path(c).exists():
            registrar_log(f"ERRO [DIÁLOGO]: Arquivo não encontrado: {c}")
            return False

    print(f"\nColando {len(caminhos_lista)} arquivo(s) no diálogo...")

    # Arquivo único: cola sem aspas — diálogo Windows rejeita aspas no campo Nome
    # Múltiplos: mantém aspas (sintaxe do Windows para seleção múltipla)
    texto_clipboard = caminhos_lista[0] if len(caminhos_lista) == 1 else (
        " ".join(f'"{c}"' for c in caminhos_lista)
    )

    titulos_dialogo = [
        "Selecionar pasta para carregar",
        "Selecionar pasta",
        "Abrir",
        "Selecionar arquivo",
        "Upload",
    ]
    for tentativa in range(1, 4):
        _fechar_dialogo_caminho_invalido()
        try:
            win32clipboard.OpenClipboard()
            win32clipboard.EmptyClipboard()
            win32clipboard.SetClipboardText(texto_clipboard)
            win32clipboard.CloseClipboard()
        except Exception as e_clip:
            registrar_log(f"AVISO [CLIPBOARD]: {e_clip}")
            return None

        janela = None
        for titulo in titulos_dialogo:
            janela = aguardar_janela_titulo(titulo, timeout=1.2)
            if janela:
                try:
                    janela.set_focus()
                except Exception:
                    pass
                break
        else:
            time.sleep(0.3)

        # Seleciona o campo sem Ctrl+A (evita 'a' colado antes do caminho).
        send_keys("{HOME}")
        time.sleep(0.05)
        send_keys("+{END}")
        time.sleep(0.05)
        send_keys("^v")
        time.sleep(0.2)

        lido = _ler_caminho_campo_dialogo()
        if _caminho_dialogo_parece_valido(caminho_principal, lido):
            registrar_log(
                f"OK [DIÁLOGO]: {len(caminhos_lista)} arquivo(s) colado(s)"
                + (f" (tentativa {tentativa})" if tentativa > 1 else "")
            )
            return True

        registrar_log(
            f"AVISO [DIÁLOGO]: caminho colado inválido "
            f"('{lido[:80]}') — tentativa {tentativa}/3.",
            "AVISO",
        )
        if _fechar_dialogo_caminho_invalido():
            time.sleep(0.25)
            continue
        send_keys("{ESC}")
        time.sleep(0.25)

    registrar_log(
        f"ERRO [DIÁLOGO]: não consegui colar o caminho correto: "
        f"{caminho_principal}",
        "ERRO",
    )
    return False


def fazer_upload_pasta_inteira(janela_sp, pasta_local, nome_log):
    """
    Faz upload de uma pasta inteira para o SharePoint.

    Substituições de time.sleep fixo aplicadas:
      - espera=3 → espera=1  no clicar_botao_em "criar ou carregar"
      - time.sleep(2) → aguarda UI reagir dinamicamente (0.5s teto)
      - espera=5 → espera=2  no clicar_botao_em "carregamento de pasta"
      - time.sleep(3) → aguardar_condicao popup aparecer (teto 6s)
      - time.sleep(5) → esperar_sharepoint_estavel() dinâmico
    """
    nome_pasta = Path(pasta_local).name
    arquivos   = list(Path(pasta_local).glob("*"))

    if not arquivos:
        registrar_log(
            f"AVISO [{nome_log}]: "
            f"Pasta '{nome_pasta}' vazia — upload ignorado."
        )
        return True

    print(
        f"\nUpload de pasta inteira: "
        f"{nome_pasta} ({len(arquivos)} arquivo(s))"
    )

    esperar_sharepoint_estavel(janela_sp, timeout=0.4)
    try:
        _esperar_pagina_sp_carregada(janela_sp, timeout=1)
    except Exception:
        pass

    # ── Tenta primeiro "Carregamento de pasta"
    tentou_pasta = False

    clicou_criar = False
    for _t_btn in range(1, 4):
        if clicar_botao_em(janela_sp, "criar ou carregar", espera=0.25):
            clicou_criar = True
            break
        esperar_sharepoint_estavel(janela_sp, timeout=0.6)
        time.sleep(0.35)

    if clicou_criar:
        time.sleep(0.28)
        _clicou_pasta = clicar_botao_em(
            janela_sp, "carregamento de pasta", espera=0.25
        )

        if not _clicou_pasta:
            send_keys("{ESC}")
            _aguardar_ui_estavel(janela_sp, timeout=0.2)
            if clicar_botao_em(janela_sp, "criar ou carregar", espera=0.25):
                time.sleep(0.28)
                _clicou_pasta = clicar_botao_em(
                    janela_sp, "carregamento de pasta", espera=0.25
                )

        if _clicou_pasta:
            tentou_pasta = True
            pasta_ok = False
            for _t_up in range(1, 4):
                resultado_dialogo = digitar_caminho_dialogo(str(pasta_local))
                if resultado_dialogo is False:
                    registrar_log(
                        f"ERRO [{nome_log}]: "
                        f"Pasta não encontrada: {pasta_local}"
                    )
                    send_keys("{ESC}")
                    break
                if resultado_dialogo is None:
                    continue
                _confirmar_dialogo_abrir(timeout=1)
                if _fechar_dialogo_caminho_invalido():
                    registrar_log(
                        f"AVISO [{nome_log}]: caminho inválido após "
                        f"Carregar — tentativa {_t_up}/3.",
                        "AVISO",
                    )
                    time.sleep(0.3)
                    continue
                pasta_ok = True
                break
            if not pasta_ok:
                send_keys("{ESC}")
                return False

            # Aumenta timeout para pastas com caminhos longos
            esperar_sharepoint_estavel(janela_sp, timeout=0.5)

            if not clicar_botao_em(janela_sp, "Carregar", exato=True):
                send_keys("{TAB},{TAB},{ENTER}")

                # ✅ Era: time.sleep(2) — agora dinâmico
                aguardar_condicao(
                    lambda: _popup_visivel(janela_sp),
                    timeout=1,
                    intervalo=0.15,
                    descricao="popup Carregar aparecer (TAB+ENTER)"
                )

            print("\nAguardando popup de confirmação...")

            # ✅ Era: time.sleep(3) antes de confirmar_popup_carregar
            # Agora aguarda o popup aparecer dinamicamente
            aguardar_condicao(
                lambda: _popup_visivel(janela_sp),
                timeout=1,
                intervalo=0.2,
                descricao="popup Carregar aparecer"
            )

            confirmar_popup_carregar(janela_sp)

            # ✅ Era: time.sleep(5) após confirmar popup
            # Agora aguarda SharePoint estabilizar
            esperar_sharepoint_estavel(janela_sp, timeout=0.5)

            ok = validar_upload(janela_sp, nome_pasta, timeout=4)
            if ok:
                # Pasta na lista NÃO prova que o arquivo entrou.
                # O SharePoint cria a pasta vazia e mostra
                # "1 item não foi carregado para 07. Julho".
                esperar_sharepoint_estavel(janela_sp, timeout=0.2)
                falha_toast = _texto_falha_upload_sp(janela_sp)
                if falha_toast:
                    registrar_log(
                        f"AVISO [{nome_log}]: SharePoint avisou "
                        f"falha de carregamento: '{falha_toast}'. "
                        f"Pasta '{nome_pasta}' pode estar vazia "
                        f"— o conteúdo será conferido e reenviado.",
                        "AVISO",
                    )
                else:
                    registrar_log(
                        f"OK [{nome_log}]: "
                        f"Pasta '{nome_pasta}' visível na lista "
                        f"(conteúdo será conferido)."
                    )
                return True

            registrar_log(
                f"AVISO [{nome_log}]: "
                f"Upload de pasta não confirmado."
            )
            return False
        else:
            registrar_log(
                f"AVISO [{nome_log}]: "
                f"'Carregamento de pasta' não disponível."
            )
            send_keys("{ESC}")
            return False
    else:
        registrar_log(
            f"ERRO [{nome_log}]: "
            f"'Criar ou carregar' não encontrado."
        )
        return False

    return False


def _tratar_popup_duplicado_sp(janela_sp) -> bool:
    """
    Detecta o popup do SharePoint quando já há arquivo parecido.
    Cancela o carregamento — não substitui o PDF de outra pessoa
    e não cria cópia com nome quebrado (ex.: .pdfor.pdf).
    """
    _INDICADORES = {
        "Substituir tudo", "Manter tudo", "Decidir para cada",
        "Replace all", "Keep both", "Manter os dois",
        "Já existem itens", "already exist",
    }
    _CANCELAR = {
        "Cancelar", "Cancel", "Não", "No",
        "Manter os arquivos existentes", "Keep existing",
    }

    for _ in range(5):
        time.sleep(0.2)
        try:
            # Varredura única: coleta todos os textos em um passo só
            controles = janela_sp.descendants()
            textos_ctrl = {}
            for ctrl in controles:
                try:
                    txt = ctrl.window_text().strip()
                    if txt:
                        textos_ctrl[txt] = ctrl
                except Exception:
                    pass

            # Verifica se há indicador de popup
            _tem_popup = any(t in textos_ctrl for t in _INDICADORES)
            if not _tem_popup:
                # Tenta também via win32 (janela separada)
                janelas_popup = Desktop(backend="win32").windows(
                    title_re=".*Substituir.*|.*Replace.*|.*Already.*"
                )
                if janelas_popup:
                    for jp in janelas_popup:
                        try:
                            for ctrl in jp.descendants():
                                try:
                                    t = ctrl.window_text().strip()
                                    if t in _CANCELAR:
                                        try:
                                            ctrl.invoke()
                                        except Exception:
                                            ctrl.click_input()
                                        registrar_log(
                                            "OK [SP]: Popup duplicado cancelado "
                                            "(não substitui nem cria cópia).",
                                            "OK"
                                        )
                                        return True
                                except Exception:
                                    pass
                        except Exception:
                            pass
                continue

            # Clica em Cancelar / manter os arquivos existentes
            for alvo in _CANCELAR:
                if alvo in textos_ctrl:
                    ctrl_alvo = textos_ctrl[alvo]
                    try:
                        ctrl_alvo.invoke()
                    except Exception:
                        ctrl_alvo.click_input()
                    registrar_log(
                        "OK [SP]: Popup duplicado cancelado "
                        "(não substitui nem cria cópia).",
                        "OK"
                    )
                    return True
            # Se chegou aqui: indicador estava presente mas botão alvo
            # não foi encontrado em textos_ctrl — aguarda próxima iteração
        except Exception:
            pass
    return False


def _capturar_url_atual(janela_sp) -> str:
    """
    Copia a URL atual da barra de endereço do Edge (Ctrl+L + Ctrl+C) e
    lê do clipboard. Usada para guardar a URL da pasta do mês assim
    que ela é aberta — depois disso, voltar pra ela não depende mais
    do breadcrumb do SharePoint aparecer na tela (que some quando a
    janela está estreita, só mostrando o nome da pasta atual).
    """
    try:
        janela_sp.set_focus()
        time.sleep(0.1)
        send_keys("^l")
        time.sleep(0.15)
        send_keys("^c")
        time.sleep(0.15)
        send_keys("{ESC}")
        win32clipboard.OpenClipboard()
        try:
            texto = win32clipboard.GetClipboardData(
                win32clipboard.CF_UNICODETEXT
            )
        except TypeError:
            texto = win32clipboard.GetClipboardData()
        win32clipboard.CloseClipboard()
        texto = (texto or "").strip()
        return texto if texto.startswith("http") else ""
    except Exception:
        try:
            win32clipboard.CloseClipboard()
        except Exception:
            pass
        return ""


def _navegar_via_endereco(janela_sp, url: str) -> bool:
    """
    Navega direto para a URL informada digitando na barra de endereço
    do Edge (Ctrl+L + colar + Enter). Funciona igual não importa o
    tamanho da janela — diferente do clique no breadcrumb (que some
    quando a janela é estreita) ou do Alt+Left (nem sempre confiável
    no SharePoint).
    """
    if not url:
        return False
    try:
        janela_sp.set_focus()
        time.sleep(0.1)
        send_keys("^l")
        time.sleep(0.15)
        win32clipboard.OpenClipboard()
        win32clipboard.EmptyClipboard()
        win32clipboard.SetClipboardText(url)
        win32clipboard.CloseClipboard()
        send_keys("^a")
        time.sleep(0.05)
        send_keys("^v")
        time.sleep(0.15)
        send_keys("{ENTER}")
        try:
            _CacheUIA.invalidar(janela_sp)
        except Exception:
            pass
        _esperar_pagina_sp_carregada(janela_sp, timeout=4)
        return True
    except Exception:
        return False


def executar_uploads_sharepoint(
    janela_sp,
    pasta_pedidos_local,
    pasta_frs_local,
    pasta_rm_local,
    pasta_espelho_local,
    mes_nome,
    contexto_api=None,
    url_pasta_mes="",
    pasta_pedidos_mat_local=None,
    pasta_espelho_mat_local=None,
    pasta_pedidos_pai_local=None,
    pasta_espelho_pai_local=None,
    pasta_certidoes_local=None,
):
    resultados = {
        "pedidos": False, "frs": False,
        "rm": False, "espelho": False,
        "pedidos_mat": False, "espelho_mat": False,
        "certidoes": False,
    }

    def _excluir_pasta_local_pos_upload(pasta_categoria, categoria_nome):
        """
        Apaga a pasta local dessa categoria assim que o upload dela é
        confirmado no SharePoint, em vez de esperar até o fim de tudo
        (e-mail incluso). Mesma proteção de segurança da limpeza final:
        só apaga se o caminho estiver dentro de uma pasta de usuário
        conhecida (evita excluir algo fora do padrão por engano).
        Tenta várias vezes antes de desistir — ver
        _excluir_pasta_com_retry.
        """
        try:
            _pasta_str = str(pasta_categoria)
            _pasta_segura = any(
                nome in _pasta_str
                for nome in ["Documents", "Documentos", "OneDrive", "Desktop"]
            )
            if _pasta_segura and Path(pasta_categoria).exists():
                _sucesso_cat, _erro_cat = _excluir_pasta_com_retry(pasta_categoria)
                if _sucesso_cat:
                    registrar_log(
                        f"LIMPEZA: pasta local de {categoria_nome} excluída após upload."
                    )
                    print(f"  ✓ Pasta local de {categoria_nome} excluída após upload.")
                else:
                    registrar_log(
                        f"AVISO [LIMPEZA {categoria_nome}]: não foi possível excluir "
                        f"após várias tentativas: {_erro_cat}",
                        "AVISO"
                    )
        except Exception as _e_limpeza:
            registrar_log(f"AVISO [LIMPEZA {categoria_nome}]: {_e_limpeza}", "AVISO")

    # =====================================================
    # Função auxiliar: volta para a pasta do mês
    # usando o breadcrumb do SharePoint (mais confiável)
    # =====================================================
    def voltar_para_pasta_mes(mes_nome_busca, pasta_atual=None):
        """
        Volta para a pasta do mês. Ordem de tentativa:
          1. Navega direto pela URL capturada quando a pasta do mês
             foi aberta pela 1ª vez — funciona não importa o tamanho
             da janela (não depende do breadcrumb aparecer na tela).
          2. Clica no breadcrumb do SharePoint (rápido quando visível).
          3. Alt+Left como último recurso.

        pasta_atual: nome da subpasta de onde estamos saindo (ex.:
        "Pedidos"). Usado para rejeitar falsos positivos nos métodos
        2 e 3 — o texto de alguns controles (ex.: a URL) continua
        contendo o nome do mês mesmo quando ainda estamos dentro da
        subpasta anterior, porque o caminho completo é
        ".../Julho/Pedidos".
        """
        print(f"\nVoltando para pasta '{mes_nome_busca}'...")
        janela_sp.set_focus()
        time.sleep(0.2)   # espera mínima após set_focus para o SO processar o foco

        # Método 1 — navegação direta pela URL, se capturada. É o mais
        # confiável: quando a janela do Edge está estreita (não em
        # tela cheia), o SharePoint recolhe o breadcrumb e mostra só o
        # nome da pasta atual — os métodos 2 e 3 dependem desse
        # breadcrumb aparecer, e por isso vinham falhando.
        if url_pasta_mes:
            if _navegar_via_endereco(janela_sp, url_pasta_mes):
                try:
                    _CacheUIA.invalidar(janela_sp)
                except Exception:
                    pass
                print("  Retornou para pasta do mês (via URL).")
                return True

        def _texto_confirma_mes(texto):
            if mes_nome_busca.lower() not in texto.lower():
                return False
            if pasta_atual and pasta_atual.lower() in texto.lower():
                return False
            return True

        # Método 2 — Tenta clicar no breadcrumb do mês
        try:
            controles = janela_sp.descendants()
            for ctrl in controles:
                try:
                    texto = ctrl.window_text().strip()
                    tipo  = ctrl.element_info.control_type
                    if (
                        _texto_confirma_mes(texto)
                        and tipo in ["Button", "Hyperlink", "Link"]
                    ):
                        print(f"  Clicando breadcrumb: '{texto}'")
                        try:
                            ctrl.invoke()
                        except Exception:
                            ctrl.click_input()
                        esperar_sharepoint_estavel(
                            janela_sp, timeout=0.5
                        )
                        print("  Retornou para pasta do mês.")
                        return True
                except Exception:
                    pass
        except Exception:
            pass

        # Método 3 — Alt+Left até encontrar a pasta do mês
        print("  Breadcrumb não encontrado — usando Alt+Left...")
        for _ in range(4):
            janela_sp.set_focus()
            send_keys("%{LEFT}")
            esperar_sharepoint_estavel(janela_sp, timeout=0.5)

            try:
                controles = janela_sp.descendants()
                for ctrl in controles:
                    try:
                        texto = ctrl.window_text().strip()
                        if _texto_confirma_mes(texto):
                            print(
                                f"  Encontrou pasta do mês: '{texto}'"
                            )
                            return True
                    except Exception:
                        pass
            except Exception:
                pass

        print("  AVISO: Não confirmou retorno para pasta do mês.")
        return False


    # =====================================================
    # Função auxiliar: listar arquivos existentes no SP
    # =====================================================
    def listar_arquivos_sharepoint(janela_sp_local):
        """
        Captura nomes de arquivos/pastas visíveis na UI do SharePoint.

        A lista do SharePoint é virtualizada: pastas com muitos
        arquivos (60+) só mostram na árvore UIA os itens renderizados
        na tela naquele instante — não a pasta inteira. Isso fazia a
        contagem de "arquivos existentes" variar entre execuções (ex.:
        80 numa vez, 62 noutra, dependendo de onde a lista já estava
        rolada) e fazia o programa achar que um arquivo não existia —
        e reenviar ele duplicado — só porque aquele item específico
        não estava entre os renderizados no momento da varredura.

        Correção: rola a lista até o fim, acumulando os nomes vistos
        em cada posição, e só para quando 2 rolagens seguidas não
        trazem nenhum arquivo novo (mesmo critério de parada usado na
        busca do contrato, em "Procurando contrato na lista...").
        """
        arquivos_vistos = set()

        def _capturar_pagina_atual():
            try:
                esperar_sharepoint_estavel(janela_sp_local, timeout=0.6)
                _CacheUIA.invalidar(janela_sp_local)
                controles = _CacheUIA.get(janela_sp_local)
            except Exception:
                return
            if not controles:
                return
            for ctrl in controles:
                try:
                    texto_raw = ctrl.window_text()
                    if texto_raw is None:
                        continue
                    texto = str(texto_raw).strip()
                    if not texto or len(texto) < 3:
                        continue
                    tipo_raw = ctrl.element_info.control_type
                    if tipo_raw is None:
                        continue
                    tipo = str(tipo_raw)
                    tipos_aceitos = {"Button", "Link", "ListItem",
                                     "Hyperlink", "Text", "DataItem"}
                    if tipo in tipos_aceitos:
                        arquivos_vistos.add(texto.lower().strip())
                except Exception:
                    pass

        _capturar_pagina_atual()

        try:
            cx_scroll, cy_scroll = ponto_scroll_seguro(janela_sp_local)
        except Exception:
            cx_scroll, cy_scroll = None, None

        if cx_scroll is not None:
            _sem_novidade = 0
            for _ in range(40):
                _total_antes = len(arquivos_vistos)
                try:
                    _rodar_roda_mouse(cx_scroll, cy_scroll, 5)
                except Exception:
                    break
                _capturar_pagina_atual()
                if len(arquivos_vistos) == _total_antes:
                    _sem_novidade += 1
                    if _sem_novidade >= 2:
                        break
                else:
                    _sem_novidade = 0

        return list(arquivos_vistos)


    # =====================================================
    # Função auxiliar: upload inteligente (só o que falta)
    # =====================================================
    def upload_arquivos_faltantes(
        janela_sp_local, pasta_local, prefixo_nome, nome_log
    ):
        pdfs = list(Path(pasta_local).glob("*.pdf"))
        if not pdfs:
            registrar_log(f"AVISO [{nome_log}]: Nenhum PDF encontrado.")
            return False

        existentes = listar_arquivos_sharepoint(janela_sp_local)
        print(f"\n  Arquivos no SharePoint: {len(existentes)}")

        faltando = []
        # Pré-calcula os "tokens" de cada arquivo já existente no
        # SharePoint (separando por _, -, espaço, .) uma única vez —
        # permite reconhecer o número mesmo que o arquivo lá esteja
        # escrito com separador diferente do nosso padrão (ex.:
        # "RM 86.pdf" em vez de "RM_86.pdf"), sem risco de falso
        # positivo mesmo para números curtos (ex.: "86"), porque a
        # comparação é por palavra inteira, não por trecho qualquer
        # do texto.
        _tokens_existentes = [
            (arq, set(re.split(r"[_\-\s.]+", arq)) - {""})
            for arq in existentes
        ]

        for pdf in pdfs:
            stem   = pdf.stem.lower()
            ids_local = _ids_em_nome_arquivo(pdf.name) or _ids_em_nome_arquivo(stem)
            nome_local = pdf.name.lower()

            ja_existe = False
            for arq, toks in _tokens_existentes:
                ids_sp = _ids_em_nome_arquivo(arq)
                if nome_local == arq or nome_local in arq:
                    ja_existe = True
                    break
                if ids_local and (ids_local & ids_sp):
                    ja_existe = True
                    registrar_log(
                        f"INFO [{nome_log}]: {pdf.name} não enviado — "
                        f"número {sorted(ids_local & ids_sp)} já está "
                        f"no SharePoint como '{arq}'.",
                        "INFO",
                    )
                    break
                numero = stem.replace(prefixo_nome.lower(), "").strip()
                if numero and numero in toks:
                    ja_existe = True
                    break


            if ja_existe:
                print(f"  ✓ Já existe: {pdf.name}")
                registrar_log(f"OK [{nome_log}]: {pdf.name} já existe — pulado.")
            else:
                faltando.append(pdf)
                print(f"  ✗ Faltando: {pdf.name}")

        if not faltando:
            print(f"  → Todos os arquivos já existem. Nada a enviar.")
            return True

        print(f"\n  Enviando {len(faltando)} arquivo(s) faltante(s)...")

        # ── Estratégia adaptativa baseada no COMPRIMENTO DO CAMINHO
        #
        # O diálogo "Abrir" do Windows tem limite de ~259 chars no campo
        # de texto. Quando múltiplos arquivos são passados entre aspas,
        # o total de chars pode ultrapassar esse limite e o Windows
        # trunca silenciosamente, enviando o arquivo errado ou nenhum.
        #
        # Solução: calcular o tamanho real do caminho composto e limitar
        # o lote de forma que o total nunca exceda o limite seguro.
        #
        # Limite conservador: 200 chars (deixa margem para o Windows)
        _LIMITE_CHARS_DIALOGO = 200

        def _calcular_n_lote_seguro(lista_pdfs: list) -> int:
            """
            Calcula quantos arquivos cabem em um lote sem ultrapassar
            o limite de caracteres do campo de texto do diálogo Windows.

            Formato do caminho composto: "arq1" "arq2" "arq3"
            Cada arquivo contribui: len(str(pdf)) + 3 (aspas + espaço)
            """
            if not lista_pdfs:
                return 1

            # Comprimento do primeiro arquivo (todos têm caminho similar)
            _comprimento_base = len(str(lista_pdfs[0])) + 3  # +3: aspas+espaço

            if _comprimento_base >= _LIMITE_CHARS_DIALOGO:
                # Caminho único já é muito longo — envia 1 por vez sem aspas
                registrar_log(
                    f"AVISO [{nome_log}]: Caminho muito longo "
                    f"({_comprimento_base} chars) — upload 1 por vez.",
                    "AVISO"
                )
                return 1

            # Quantos cabem dentro do limite?
            _n = max(1, _LIMITE_CHARS_DIALOGO // _comprimento_base)

            return 1

        try:
            _n_lote = _calcular_n_lote_seguro(faltando)
        except Exception:
            # Fallback seguro: 1 por vez se cálculo falhar
            _n_lote = 1
            registrar_log(
                f"AVISO [{nome_log}]: Erro no cálculo de lote "
                f"— usando 1 arquivo por vez.",
                "AVISO"
            )


        def _montar_lotes(lista_pdfs, n_por_lote):
            """Divide lista em sublistas de tamanho n_por_lote."""
            return [
                lista_pdfs[i: i + n_por_lote]
                for i in range(0, len(lista_pdfs), n_por_lote)
            ]

        lotes = _montar_lotes(faltando, _n_lote)

        # Log informativo com o comprimento do caminho
        try:
            _comp_exemplo = len(str(faltando[0])) if faltando else 0
        except Exception:
            _comp_exemplo = 0
        print(
            f"\n  Estratégia SP: {_n_lote} arquivo(s)/lote "
            f"→ {len(lotes)} lote(s) ({len(faltando)} faltante(s)). "
            f"[caminho: {_comp_exemplo} chars]"
        )



        enviado_lote  = True
        falhos_global = []

        for num_lote, arquivos_lote in enumerate(lotes, start=1):
            print(f"\n  ── Lote {num_lote}/{len(lotes)}: {len(arquivos_lote)} arquivo(s)")
            # Se lote tem 1 arquivo: cola sem aspas (mais compatível)
            # Se tem 2: usa aspas duplas (sintaxe multi-seleção Windows)
            if len(arquivos_lote) == 1:
                caminho_multi = str(arquivos_lote[0])
            else:
                caminho_multi = " ".join(
                    f'"{str(pdf)}"' for pdf in arquivos_lote
                )


            # ── Atualiza ETA no painel
            try:
                restantes = len(lotes) - num_lote + 1
                t_medio   = _painel._ultimo_t_sp if _painel._ultimo_t_sp > 0 else 15
                est_s     = int(restantes * t_medio)
                if est_s >= 60:
                    est_txt = f"{est_s // 60}m {est_s % 60}s restantes"
                else:
                    est_txt = f"{est_s}s restantes"
                _painel.atualizar_eta(
                    f"☁  {nome_log}  |  lote {num_lote}/{len(lotes)}"
                    f"  |  est. {est_txt}"
                )
            except Exception:
                pass

            enviado_este_lote = False
            for tentativa_lote in range(3):
                if tentativa_lote > 0:
                    print(f"  🔄 Tentativa {tentativa_lote + 1}/3 (lote {num_lote})...")
                    esperar_sharepoint_estavel(
                        janela_sp_local, timeout=1
                    )


                janela_sp_local.set_focus()
                send_keys("{ESC}")
                _CacheUIA.invalidar(janela_sp_local)


                # Passo 1 — "Criar ou carregar"
                if not clicar_botao_em(janela_sp_local, "criar ou carregar", espera=0.3):
                    registrar_log(
                        f"ERRO [{nome_log}]: 'Criar ou carregar' não encontrado "
                        f"(lote {num_lote}, tentativa {tentativa_lote + 1})."
                    )
                    continue

                # ✅ ERA: time.sleep(0.2) após clicar "criar ou carregar"
                # Aguarda o menu dropdown expandir com os itens
                aguardar_condicao(
                    lambda: _botao_sp_visivel(
                        janela_sp_local, "carregamento de arquivos"
                    ),
                    timeout=0.5,
                    intervalo=0.1,
                    descricao="menu carregamento de arquivos aparecer"
                )


                # Passo 2 — "Carregamento de arquivos"
                if not clicar_botao_em(janela_sp_local, "carregamento de arquivos", espera=0.3):
                    registrar_log(
                        f"AVISO [{nome_log}]: 'Carregamento de arquivos' não encontrado "
                        f"(lote {num_lote}, tentativa {tentativa_lote + 1})."
                    )
                    send_keys("{ESC}")
                    # ✅ ERA: time.sleep(0.5) após ESC para fechar menu
                    # Aguarda menu fechar dinamicamente
                    _aguardar_ui_estavel(janela_sp_local, timeout=0.2)

                    continue

                # Passo 3 — Cola o caminho no diálogo
                resultado_dialogo = digitar_caminho_dialogo(caminho_multi)

                if resultado_dialogo is False:
                    registrar_log(
                        f"ERRO [{nome_log}]: Arquivo não encontrado em disco "
                        f"(lote {num_lote})."
                    )
                    enviado_este_lote = False
                    break

                # Passo 4 — Confirma o diálogo de arquivo do Windows
                _confirmar_dialogo_abrir(timeout=1)

                # Trata popup "Já existem itens" do SharePoint
                _tratar_popup_duplicado_sp(janela_sp_local)

                # Aguarda upload — timeout reduzido para 60s
                timeout_lote = min(60, 8 + len(arquivos_lote) * 5)

                # Espera mínima antes de validar
                time.sleep(0.1)




                # Valida + mede tempo SP
                _t0_sp = time.time()

                # Inclui múltiplas formas de busca por arquivo
                nomes_validar = []
                for pdf in arquivos_lote:
                    nomes_validar.append(pdf.name.lower())

                if getattr(Config, "SP_VALIDAR_LOTE", True):
                    ok_lote = validar_upload_lote(
                        janela_sp_local,
                        nomes_validar,
                        timeout=timeout_lote
                    )
                else:
                    primeiro_numero = nomes_validar[0]
                    ultimo_numero   = nomes_validar[-1]
                    ok_primeiro     = validar_upload(
                        janela_sp_local, primeiro_numero,
                        timeout=timeout_lote
                    )
                    ok_ultimo = (
                        validar_upload(janela_sp_local, ultimo_numero, timeout=3)
                        if len(nomes_validar) > 1 else ok_primeiro
                    )
                    ok_lote = ok_primeiro and ok_ultimo

                try:
                    _painel.registrar_tempo_sp(round(time.time() - _t0_sp, 1))
                except Exception:
                    pass

                if ok_lote:
                    registrar_log(
                        f"OK [{nome_log}]: Lote {num_lote} "
                        f"({len(arquivos_lote)} arquivo(s)) enviado."
                    )
                    enviado_este_lote = True
                    break
                else:
                    registrar_log(
                        f"AVISO [{nome_log}]: Lote {num_lote} não confirmado "
                        f"(tentativa {tentativa_lote + 1})."
                    )

            if not enviado_este_lote:
                falhos_global.extend(arquivos_lote)
                enviado_lote = False
                registrar_log(
                    f"⚠ [{nome_log}]: Lote {num_lote} NÃO confirmado após 3 tentativas.\n"
                    f"  Arquivos: {[p.name for p in arquivos_lote]}"
                )

        if not enviado_lote:
            registrar_log(
                f"⚠ [{nome_log}]: {len(falhos_global)} arquivo(s) NÃO enviados:\n"
                f"  {[p.name for p in falhos_global]}\n"
                f"  → Re-execute o programa para tentar novamente."
            )
            try:
                _painel.limpar_eta()
            except Exception:
                pass
            return False

        try:
            _painel.limpar_eta()
        except Exception:
            pass

        return True


    def _abrir_pasta_categoria(nome, chave):
        """Abre pasta na lista; se falhar (cache após voltar do mês), usa URL."""
        try:
            _CacheUIA.invalidar(janela_sp)
        except Exception:
            pass
        time.sleep(0.25)
        if abrir_pasta_sharepoint(janela_sp, nome, exato=False):
            return True
        for _var in _lista_variantes_pasta(chave):
            if _var == nome:
                continue
            print(f"Tentando pasta: '{_var}'...")
            if abrir_pasta_sharepoint(janela_sp, _var, exato=False):
                return True
        # Após voltar via URL, a lista UIA às vezes atrasa — navega direto
        if url_pasta_mes and nome:
            dest = _url_entrar_subpasta_sp(url_pasta_mes, nome)
            if dest and dest != url_pasta_mes:
                print(f"  abrindo '{nome}' via URL da pasta do mês...")
                if _navegar_via_endereco(janela_sp, dest):
                    esperar_sharepoint_estavel(janela_sp, timeout=0.5)
                    _esperar_pagina_sp_carregada(janela_sp, timeout=2)
                    return True
            for _var in _lista_variantes_pasta(chave):
                dest = _url_entrar_subpasta_sp(url_pasta_mes, _var)
                if not dest or dest == url_pasta_mes:
                    continue
                print(f"  abrindo '{_var}' via URL...")
                if _navegar_via_endereco(janela_sp, dest):
                    esperar_sharepoint_estavel(janela_sp, timeout=0.5)
                    _esperar_pagina_sp_carregada(janela_sp, timeout=2)
                    return True
        return False

    def _enviar_e_confirmar_categoria(
        chave_resultado,
        chave_pasta,
        pasta_local,
        prefixo,
        nome_log,
        nome_pasta,
        existe_antes,
        apagar_local,
        pasta_voltar,
    ):
        """
        Upload só é sucesso se o arquivo estiver DENTRO da pasta.
        Pasta criada vazia (toast 'não foi carregado') → abre e reenvia.
        """
        print("\n" + "=" * 40)
        print(f"UPLOAD — {nome_log}")
        print("=" * 40)

        entrou = False
        ok = False

        if existe_antes:
            print(f"Pasta '{nome_pasta}' existe — verificando conteúdo...")
            # Já estamos na pasta do mês (inventário) — NÃO recarregar
            # a URL do mês (isso duplicava 'Aguardando lista...' ~10s).
            if _abrir_pasta_categoria(nome_pasta, chave_pasta):
                entrou = True
                esperar_sharepoint_estavel(janela_sp, timeout=0.4)
            else:
                registrar_log(
                    f"ERRO [{nome_log}]: Não foi possível abrir "
                    f"pasta '{nome_pasta}'."
                )
        else:
            print(
                f"Pasta de {nome_log} não existe (nenhuma variante "
                "encontrada) — upload da pasta inteira..."
            )
            ok_up = fazer_upload_pasta_inteira(janela_sp, pasta_local, nome_log)
            # validar_upload já confirmou a pasta — não re-varrer UIA
            # (cada descendants() no Edge custa vários segundos).
            falha_toast = ""
            try:
                falha_toast = _texto_falha_upload_sp(janela_sp) or ""
            except Exception:
                falha_toast = ""
            if ok_up and not falha_toast:
                ok = True
                try:
                    _cache_pastas_mes[chave_pasta] = nome_pasta
                except Exception:
                    pass
                registrar_log(
                    f"OK [{nome_log}]: upload confirmado "
                    "(pasta visivel na lista)."
                )
                print(
                    f"  ✓ Upload de '{nome_log}' confirmado "
                    "pelo status do SharePoint."
                )
            elif falha_toast:
                registrar_log(
                    f"AVISO [{nome_log}]: SharePoint: '{falha_toast}'. "
                    "A pasta pode ter sido criada sem o arquivo — "
                    "vou abrir e reenviar o conteúdo.",
                    "AVISO",
                )
                try:
                    _CacheUIA.invalidar(janela_sp)
                except Exception:
                    pass
                nome_agora = (
                    _encontrar_pasta_sharepoint_na_tela(janela_sp, chave_pasta)
                    or nome_pasta
                )
                try:
                    _cache_pastas_mes[chave_pasta] = nome_agora
                except Exception:
                    pass
                pasta_na_lista = pasta_existe_sharepoint(
                    janela_sp, nome_agora, exato=False
                )
                if pasta_na_lista and _abrir_pasta_categoria(nome_agora, chave_pasta):
                    entrou = True
                    esperar_sharepoint_estavel(janela_sp, timeout=0.5)
                    _esperar_pagina_sp_carregada(janela_sp, timeout=1)
                else:
                    registrar_log(
                        f"ERRO [{nome_log}]: falha no carregamento "
                        f"e pasta '{nome_agora}' nao abriu."
                    )
            else:
                registrar_log(
                    f"ERRO [{nome_log}]: Pasta '{nome_pasta}' "
                    "nao apareceu apos o carregamento."
                )

        if entrou:
            for tentativa in range(3):
                if _conteudo_upload_confirmado_sp(
                    janela_sp,
                    pasta_local,
                    timeout=4 if tentativa == 0 else 3,
                ):
                    ok = True
                    registrar_log(
                        f"OK [{nome_log}]: conteúdo confirmado na pasta "
                        f"(arquivo dentro, não só a pasta vazia)."
                    )
                    print(
                        f"  ✓ Conteúdo de '{nome_log}' confirmado "
                        "no SharePoint."
                    )
                    break
                print(
                    f"  Conteúdo incompleto ou pasta vazia "
                    f"(tentativa {tentativa + 1}/3) — "
                    "reenviando arquivos..."
                )
                registrar_log(
                    f"AVISO [{nome_log}]: pasta sem o arquivo esperado "
                    f"— reenvio {tentativa + 1}/3.",
                    "AVISO",
                )
                upload_arquivos_faltantes(
                    janela_sp, pasta_local, prefixo, nome_log
                )
            if not ok:
                registrar_log(
                    f"ERRO [{nome_log}]: pasta no SharePoint sem o "
                    "conteúdo após as tentativas de reenvio."
                )

        try:
            if ok:
                toast(
                    f"SP {chave_pasta}: upload confirmado ✓",
                    "sucesso",
                    3000,
                )
            else:
                toast(
                    f"SP {chave_pasta}: verificar uploads ⚠",
                    "aviso",
                    5000,
                )
        except Exception:
            pass

        if ok and apagar_local:
            _excluir_pasta_local_pos_upload(pasta_local, chave_pasta)

        if entrou:
            janela_sp.set_focus()
            voltar_para_pasta_mes(mes_nome, pasta_voltar)
            esperar_sharepoint_estavel(janela_sp, timeout=0.5)

        resultados[chave_resultado] = ok
        return ok


    def _tem_pdfs_cat(pasta):
        try:
            pp = Path(pasta) if pasta else None
            return bool(pp and pp.exists() and any(pp.glob("*.pdf")))
        except Exception:
            return False

    def _enviar_pai_aninhado(
        chave_pai, nome_padrao, pasta_pai, filhos, chave_res, apagar_pai,
    ):
        """
        Sobe a pasta pai (Pedidos / Espelho NF) com as subpastas
        Serviços e Materiais. Se o pai já existe, entra e inclui
        só o que faltar.
        Antes de cada filho: garante que está NO PAI (não dentro
        de Serviços ao subir Materiais).
        """
        pasta_pai = Path(pasta_pai) if pasta_pai else None
        filhos_ok = [f for f in filhos if _tem_pdfs_cat(f["pasta"])]
        if not pasta_pai or not pasta_pai.exists() or not filhos_ok:
            return False
        nome_pai = _cache_pastas_mes.get(chave_pai) or ""
        existe_pai = bool(nome_pai)
        nome_pai = nome_pai or nome_padrao
        print(
            f"\nPasta {nome_padrao}: "
            + (f"Sim ({nome_pai})" if existe_pai else "Não")
        )
        if not existe_pai:
            ok = _enviar_e_confirmar_categoria(
                chave_res, chave_pai, pasta_pai, filhos_ok[0]["prefixo"],
                nome_padrao.upper(), nome_pai, False, apagar_pai, nome_padrao,
            )
            for f in filhos_ok:
                resultados[f["chave_res"]] = ok
            return ok

        if not _abrir_pasta_categoria(nome_pai, chave_pai):
            registrar_log(
                f"ERRO [{nome_padrao}]: não abriu pasta pai '{nome_pai}'."
            )
            return False
        esperar_sharepoint_estavel(janela_sp, timeout=0.4)
        _esperar_pagina_sp_carregada(janela_sp, timeout=2)

        def _esta_no_pai_aninhado() -> bool:
            """True só se a lista do pai mostra alguma subpasta filho."""
            try:
                _CacheUIA.invalidar(janela_sp)
            except Exception:
                pass
            for ff in filhos_ok:
                if _encontrar_pasta_sharepoint_na_tela(
                    janela_sp, ff["chave_pasta"]
                ):
                    return True
            # Pai vazio ainda: nenhuma subpasta — usa URL/título se possível
            return False

        def _garantir_no_pai_aninhado() -> bool:
            """
            Volta para Pedidos / Espelho NF antes do próximo filho.
            Não confia só em Alt+LEFT (fica preso em Serviços).
            """
            if _esta_no_pai_aninhado():
                return True
            try:
                janela_sp.set_focus()
                send_keys("%{LEFT}")
                esperar_sharepoint_estavel(janela_sp, timeout=0.5)
                _esperar_pagina_sp_carregada(janela_sp, timeout=2)
            except Exception:
                pass
            if _esta_no_pai_aninhado():
                return True
            print(f"  Voltando ao pai '{nome_pai}' (mês → pasta)...")
            voltar_para_pasta_mes(mes_nome, nome_pai)
            if not _abrir_pasta_categoria(nome_pai, chave_pai):
                registrar_log(
                    f"ERRO [{nome_padrao}]: não consegui voltar à pasta "
                    f"pai '{nome_pai}' antes do próximo upload.",
                    "ERRO",
                )
                return False
            _esperar_pagina_sp_carregada(janela_sp, timeout=2)
            return True

        ok_all = True
        for f in filhos_ok:
            if not _garantir_no_pai_aninhado():
                resultados[f["chave_res"]] = False
                ok_all = False
                continue
            try:
                _CacheUIA.invalidar(janela_sp)
            except Exception:
                pass
            nome_f = (
                _encontrar_pasta_sharepoint_na_tela(janela_sp, f["chave_pasta"])
                or ""
            )
            existe_f = bool(nome_f)
            nome_f = nome_f or f["nome_padrao"]
            print(
                f"  Subpasta {f['nome_padrao']}: "
                + ("Sim" if existe_f else "Não")
            )
            if not existe_f:
                # Obrigatório: upload da pasta inteira só no PAI
                if not _garantir_no_pai_aninhado():
                    resultados[f["chave_res"]] = False
                    ok_all = False
                    continue
                toasts_antes = _textos_falha_upload_sp(janela_sp)
                fazer_upload_pasta_inteira(
                    janela_sp, f["pasta"], f["nome_log"]
                )
                falha_toast = _aguardar_nova_falha_upload_sp(
                    janela_sp, toasts_antes, timeout=2.0
                )
                sucesso_toast = ""
                if not falha_toast:
                    sucesso_toast = _aguardar_sucesso_upload_sp(
                        janela_sp, timeout=2.5
                    )
                visivel = pasta_existe_sharepoint(
                    janela_sp, nome_f, exato=False
                )
                ok_f = (bool(sucesso_toast or visivel) and not falha_toast)
                # Após criar a pasta, continua no pai (próximo filho)
                if not _garantir_no_pai_aninhado():
                    ok_f = False
            else:
                if abrir_pasta_sharepoint(janela_sp, nome_f, exato=False):
                    _esperar_pagina_sp_carregada(janela_sp, timeout=2)
                    ok_f = _conteudo_upload_confirmado_sp(
                        janela_sp, f["pasta"], timeout=4
                    )
                    if not ok_f:
                        upload_arquivos_faltantes(
                            janela_sp, f["pasta"], f["prefixo"], f["nome_log"]
                        )
                        ok_f = _conteudo_upload_confirmado_sp(
                            janela_sp, f["pasta"], timeout=4
                        )
                    # Sempre volta ao PAI antes do próximo filho
                    if not _garantir_no_pai_aninhado():
                        ok_f = False
                else:
                    ok_f = False
            resultados[f["chave_res"]] = ok_f
            ok_all = ok_all and ok_f
        voltar_para_pasta_mes(mes_nome, nome_pai)
        if ok_all and apagar_pai:
            _excluir_pasta_local_pos_upload(pasta_pai, nome_padrao)
        resultados[chave_res] = ok_all
        return ok_all

    # =====================================================
    # Verifica quais pastas existem (estando na pasta do mês)
    # Pai Pedidos / Espelho NF + FRS + RM.
    # =====================================================
    # Inventário ÚNICO na pasta do mês (1 rolagem) — não
    # revalida Pedidos/FRS/RM/Espelho antes de cada upload.
    # =====================================================
    _cache_pastas_mes = _inventariar_pastas_mes_sp(janela_sp)
    print("\nInventário pasta do mês (uma passagem):")
    for _ck, _cv in _cache_pastas_mes.items():
        if _ck in ("Pedidos Pai", "FRS", "RM", "Espelho NF Pai", "certidoes"):
            print(f"  {_ck}: {_cv or 'Não'}")
    registrar_log(
        "INFO [SP]: inventário mês — "
        + ", ".join(
            f"{k}={'sim' if v else 'não'}"
            for k, v in _cache_pastas_mes.items()
            if k in ("Pedidos Pai", "FRS", "RM", "Espelho NF Pai", "certidoes")
        ),
        "INFO",
    )

    # =====================================================
    pasta_ped_pai = Path(pasta_pedidos_pai_local) if pasta_pedidos_pai_local else (
        Path(pasta_pedidos_local).parent if pasta_pedidos_local else None
    )
    pasta_esp_pai = Path(pasta_espelho_pai_local) if pasta_espelho_pai_local else (
        Path(pasta_espelho_local).parent if pasta_espelho_local else None
    )

    filhos_ped = []
    if _tem_pdfs_cat(pasta_pedidos_local):
        filhos_ped.append({
            "chave_pasta": "Pedidos Serviços",
            "pasta": pasta_pedidos_local,
            "prefixo": "Pedido_",
            "nome_padrao": "Pedidos Serviços",
            "nome_log": "PEDIDOS SERVICOS",
            "chave_res": "pedidos",
        })
    if _tem_pdfs_cat(pasta_pedidos_mat_local):
        filhos_ped.append({
            "chave_pasta": "Pedidos Materiais",
            "pasta": pasta_pedidos_mat_local,
            "prefixo": "Pedido_",
            "nome_padrao": "Pedidos Materiais",
            "nome_log": "PEDIDOS MATERIAIS",
            "chave_res": "pedidos_mat",
        })
    if filhos_ped and pasta_ped_pai:
        _enviar_pai_aninhado(
            "Pedidos Pai", "Pedidos", pasta_ped_pai, filhos_ped, "pedidos", True,
        )
    else:
        nome_pasta_pedidos = (
            _cache_pastas_mes.get("Pedidos Serviços")
            or _cache_pastas_mes.get("Pedidos Pai")
            or ""
        )
        existe_pedidos = bool(nome_pasta_pedidos)
        nome_pasta_pedidos = nome_pasta_pedidos or "Pedidos Serviços"
        print(
            f"\nPasta Pedidos Serviços: "
            f"{'Sim (' + nome_pasta_pedidos + ')' if existe_pedidos else 'Não'}"
        )
        _enviar_e_confirmar_categoria(
            "pedidos", "Pedidos Serviços", pasta_pedidos_local, "Pedido_",
            "PEDIDOS", nome_pasta_pedidos, existe_pedidos, True, "Pedidos",
        )

    nome_pasta_frs = _cache_pastas_mes.get("FRS") or ""
    existe_frs = bool(nome_pasta_frs)
    nome_pasta_frs = nome_pasta_frs or "FRS"
    print(f"Pasta FRS       : {'Sim (' + nome_pasta_frs + ')' if existe_frs else 'Não'}")

    _enviar_e_confirmar_categoria(
        "frs", "FRS", pasta_frs_local, "FRS_",
        "FRS", nome_pasta_frs, existe_frs, True, "FRS",
    )

    nome_pasta_rm = _cache_pastas_mes.get("RM") or ""
    existe_rm = bool(nome_pasta_rm)
    nome_pasta_rm = nome_pasta_rm or "RM"
    print(f"Pasta RM        : {'Sim (' + nome_pasta_rm + ')' if existe_rm else 'Não'}")

    _enviar_e_confirmar_categoria(
        "rm", "RM", pasta_rm_local, "RM_",
        "RM", nome_pasta_rm, existe_rm, False, "RM",
    )

    filhos_esp = []
    if _tem_pdfs_cat(pasta_espelho_local):
        filhos_esp.append({
            "chave_pasta": "Espelho NF Serviços",
            "pasta": pasta_espelho_local,
            "prefixo": "Espelho_NF_RM_",
            "nome_padrao": "Espelho NF Serviços",
            "nome_log": "ESPELHO NF SERVICOS",
            "chave_res": "espelho",
        })
    if _tem_pdfs_cat(pasta_espelho_mat_local):
        filhos_esp.append({
            "chave_pasta": "Espelho NF Materiais",
            "pasta": pasta_espelho_mat_local,
            "prefixo": "EspelhoNF_Pedido",
            "nome_padrao": "Espelho NF Materiais",
            "nome_log": "ESPELHO NF MATERIAIS",
            "chave_res": "espelho_mat",
        })
    if filhos_esp and pasta_esp_pai:
        _enviar_pai_aninhado(
            "Espelho NF Pai", "Espelho NF", pasta_esp_pai,
            filhos_esp, "espelho", False,
        )
    else:
        nome_pasta_espelho = (
            _cache_pastas_mes.get("Espelho NF Serviços")
            or _cache_pastas_mes.get("Espelho NF Pai")
            or ""
        )
        existe_espelho = bool(nome_pasta_espelho)
        nome_pasta_espelho = nome_pasta_espelho or "Espelho NF Serviços"
        print(
            f"Pasta Espelho NF Serviços: "
            f"{'Sim (' + nome_pasta_espelho + ')' if existe_espelho else 'Não'}"
        )
        _enviar_e_confirmar_categoria(
            "espelho", "Espelho NF Serviços", pasta_espelho_local,
            "Espelho_NF_RM_",
            "ESPELHO NF", nome_pasta_espelho, existe_espelho, False, "Espelho",
        )

    # ── Certidões (CNDT / CRF / CND)
    nome_pasta_cert = _cache_pastas_mes.get("certidoes") or ""
    existe_cert = bool(nome_pasta_cert)
    vars_cert = _lista_variantes_pasta("certidoes")
    nome_pasta_cert = nome_pasta_cert or (vars_cert[0] if vars_cert else "Certidões")
    pasta_cert_path = Path(pasta_certidoes_local) if pasta_certidoes_local else None
    pdfs_cert = []
    if pasta_cert_path and pasta_cert_path.is_dir():
        vistos_cert = set()
        for ext in ("*.pdf", "*.PDF"):
            for arq in pasta_cert_path.glob(ext):
                if arq.name.lower() in vistos_cert:
                    continue
                if _tipo_certidao_no_nome(arq.name):
                    vistos_cert.add(arq.name.lower())
                    pdfs_cert.append(arq)
    if pdfs_cert:
        print(
            f"\nCertidões: {len(pdfs_cert)} PDF(s) "
            f"({', '.join(_tipo_certidao_no_nome(p.name).upper() or '?' for p in pdfs_cert)})"
        )
        _enviar_e_confirmar_categoria(
            "certidoes",
            "certidoes",
            pasta_cert_path,
            "",
            "CERTIDOES",
            nome_pasta_cert,
            existe_cert,
            False,
            "Certidões",
        )
    else:
        resultados["certidoes"] = True
        print("\nCertidões: nenhum PDF local para enviar.")

    return resultados



