class _LinhaSAP(QWidget):
    """Linha colorida com nome + contadores ok/falha."""
    def __init__(self, label, sucesso, falha, parent=None):
        super().__init__(parent)
        self.setStyleSheet("background-color: transparent;")
        layout = QHBoxLayout(self)
        layout.setContentsMargins(12, 2, 12, 2)
        layout.setSpacing(0)

        lbl = QLabel(f"  {label}")
        lbl.setFont(QFont("Consolas", 10))
        lbl.setStyleSheet("color: #e0e0f0;")

        cor = "#00c5a0" if falha == 0 else "#ff6b6b"
        val = QLabel(f"{sucesso:>2} ✓   {falha:>2} ✗")
        val.setFont(QFont("Consolas", 10))
        val.setStyleSheet(f"color: {cor}; font-weight: bold;")
        val.setAlignment(Qt.AlignRight | Qt.AlignVCenter)

        layout.addWidget(lbl, stretch=1)
        layout.addWidget(val)


class _LinhaUpload(QWidget):
    """Linha colorida com nome + status OK/VERIFICAR."""
    def __init__(self, label, ok_bool, parent=None):
        super().__init__(parent)
        self.setStyleSheet("background-color: transparent;")
        layout = QHBoxLayout(self)
        layout.setContentsMargins(12, 2, 12, 2)
        layout.setSpacing(0)

        lbl = QLabel(f"  {label}")
        lbl.setFont(QFont("Consolas", 10))
        lbl.setStyleSheet("color: #e0e0f0;")

        cor   = "#00c5a0" if ok_bool else "#ff6b6b"
        icone = "✅ OK" if ok_bool else "❌ VERIFICAR"
        val   = QLabel(icone)
        val.setFont(QFont("Consolas", 10))
        val.setStyleSheet(f"color: {cor}; font-weight: bold;")
        val.setAlignment(Qt.AlignRight | Qt.AlignVCenter)

        layout.addWidget(lbl, stretch=1)
        layout.addWidget(val)


def _criar_card(titulo_secao):
    """
    Cria um QFrame escuro com título de seção.
    Retorna (frame_externo, layout_interno).
    Usa CINZA_CARD da paleta atual — sem hardcode de cor.
    """
    frame = QFrame()
    frame.setObjectName("card")
    # Sem styleSheet inline — herda do QSS_DARK global
    # que já define QFrame#card com CINZA_CARD correto

    v = QVBoxLayout(frame)
    v.setSpacing(1)
    v.setContentsMargins(0, 6, 0, 6)

    lbl = QLabel(f"  {titulo_secao}")
    lbl.setFont(QFont("Arial", 9, QFont.Bold))
    lbl.setStyleSheet("color: #7ec8e3; padding-left: 10px;")
    v.addWidget(lbl)

    sep = QFrame()
    sep.setFrameShape(QFrame.HLine)
    sep.setStyleSheet("background-color: #2c2c4e; max-height: 1px;")
    v.addWidget(sep)

    return frame, v
