# F1-3 — MONITOR DE STATUS DOS SISTEMAS
# =====================================================

from PySide6.QtCore import QThread, Signal as _QSignal

class MonitorSistemas(QThread):
    status_atualizado = _QSignal(dict)
    INTERVALO = 60  # segundos

    def run(self):
        import pythoncom
        pythoncom.CoInitialize()   # ← COM por thread (win32com no _checar_sap)
        try:
            while not self.isInterruptionRequested():
                resultado = {
                    "sap":        self._checar_sap(),
                    "sharepoint": self._checar_sharepoint(),
                }
                resultado.update(self._checar_outlook_detalhe())
                self.status_atualizado.emit(resultado)
                for _ in range(self.INTERVALO * 2):
                    if self.isInterruptionRequested():
                        return
                    import time as _t; _t.sleep(0.5)
        finally:
            pythoncom.CoUninitialize()   # ← libera ao encerrar

    def _checar_sap(self):
        try:
            import win32com.client as _w
            obj = _w.GetObject("SAPGUI")
            return obj.GetScriptingEngine.Children.Count > 0
        except Exception:
            return False

    def _checar_sharepoint(self):
        try:
            if _PSUTIL_OK:
                for proc in _psutil.process_iter(["name"]):
                    n = (proc.info.get("name") or "").lower()
                    if n in ("msedge.exe", "msedgewebview2.exe"):
                        return True
            return False
        except Exception:
            return False

    def _checar_outlook(self):
        """True se o novo OU o clássico (logado) estiver no ar."""
        try:
            if _outlook_novo_rodando():
                return True
            if (
                _outlook_classico_rodando()
                and not _janelas_login_outlook_classico()
            ):
                return True
            return False
        except Exception:
            return False

    def _checar_outlook_detalhe(self) -> dict:
        novo = _outlook_novo_rodando()
        classico = (
            _outlook_classico_rodando()
            and not _janelas_login_outlook_classico()
        )
        return {
            "outlook": novo or classico,
            "outlook_novo": novo,
            "outlook_classico": classico,
        }


class _DotAnimado(QWidget):
    """
    Indicador circular animado para status de sistema.
    ONLINE: pulso suave em verde
    OFFLINE: vermelho estático
    VERIFICANDO: rotação em âmbar
    """

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setFixedSize(16, 16)
        self._online     = None   # None = verificando
        self._pulso      = 0.0
        self._pulso_dir  = 1.0
        self._rotacao    = 0.0

        self._timer = QTimer(self)
        self._timer.timeout.connect(self._tick)
        self._timer.start(80)   # 12fps — LED não precisa de 25fps

    def _tick(self):
        if self._online is None:
            # Rotação enquanto verifica
            self._rotacao = (self._rotacao + 8) % 360
        else:
            # Pulso quando definido
            self._pulso += 0.06 * self._pulso_dir
            if self._pulso >= 1.0:
                self._pulso_dir = -1.0
            elif self._pulso <= 0.0:
                self._pulso_dir = 1.0
        self.update()

    def set_online(self, online: bool | None):
        self._online = online
        self.update()

    def paintEvent(self, _):
        import math
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)

        W, H  = self.width(), self.height()
        cx, cy = W / 2, H / 2
        R_ext  = 7
        R_int  = 4

        if self._online is None:
            # Arco giratório (verificando)
            cor = QColor(COR_ALERTA)
            pen = QPen(cor, 2, Qt.SolidLine)
            pen.setCapStyle(Qt.RoundCap)
            p.setPen(pen)
            p.setBrush(Qt.NoBrush)
            p.drawArc(
                QRectF(cx - R_ext, cy - R_ext,
                       R_ext * 2, R_ext * 2),
                int(self._rotacao * 16),
                200 * 16
            )

        elif self._online:
            # Halo pulsante verde
            alpha = int(20 + 40 * self._pulso)
            halo  = QColor(35, 134, 54, alpha)
            p.setPen(Qt.NoPen)
            p.setBrush(QBrush(halo))
            R_halo = R_ext + 2 + int(2 * self._pulso)
            p.drawEllipse(
                QPointF(cx, cy), R_halo, R_halo
            )
            # Ponto central sólido
            p.setBrush(QBrush(QColor(COR_SUCESSO)))
            p.drawEllipse(QPointF(cx, cy), R_int, R_int)

        else:
            # Vermelho estático com X
            p.setPen(Qt.NoPen)
            p.setBrush(QBrush(QColor(COR_ERRO)))
            p.drawEllipse(QPointF(cx, cy), R_int, R_int)
            # X
            pen_x = QPen(QColor(COR_ERRO).lighter(150), 1.5)
            pen_x.setCapStyle(Qt.RoundCap)
            p.setPen(pen_x)
            d = 2.5
            p.drawLine(
                QPointF(cx - d, cy - d),
                QPointF(cx + d, cy + d)
            )
            p.drawLine(
                QPointF(cx + d, cy - d),
                QPointF(cx - d, cy + d)
            )

        p.end()


class PainelStatusSistemas(QFrame):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setObjectName("card")
        self.setFixedHeight(168)
        self.setStyleSheet(f"""
            QFrame#card {{
                background-color: {CINZA_BG};
                border-top: 1px solid {CINZA_BORDA};
                border-radius: 0;
            }}
        """)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(10, 7, 10, 7)
        layout.setSpacing(4)

        self._indicadores_dot: dict = {}
        self._indicadores_lbl: dict = {}

        sistemas = [
            ("sap", "SAP"),
            ("sharepoint", "SharePoint"),
            ("outlook_novo", "Outlook novo"),
            ("outlook_classico", "Outlook clássico"),
        ]

        for chave, sistema in sistemas:
            h = QHBoxLayout()
            h.setSpacing(7)
            h.setContentsMargins(2, 0, 2, 0)

            dot = _DotAnimado()
            lbl_nome = QLabel(sistema)
            lbl_nome.setFont(QFont("Segoe UI", 8, QFont.Bold))
            lbl_nome.setStyleSheet(f"color: {TEXTO_CLARO};")
            lbl_nome.setMinimumWidth(108)

            lbl_det = QLabel("Verificando")
            lbl_det.setFont(QFont("Consolas", 7))
            lbl_det.setStyleSheet(f"color: {TEXTO_OPACO};")

            h.addWidget(dot, alignment=Qt.AlignVCenter)
            h.addWidget(lbl_nome)
            h.addWidget(lbl_det, stretch=1)

            layout.addLayout(h)
            self._indicadores_dot[chave] = dot
            self._indicadores_lbl[chave] = lbl_det

        legenda = QLabel("● Verde: conectado  •  Vermelho: indisponível")
        legenda.setFont(QFont("Segoe UI", 6))
        legenda.setWordWrap(True)
        legenda.setStyleSheet(f"color: {TEXTO_OPACO};")
        layout.addWidget(legenda)

        self._monitor = MonitorSistemas()
        self._monitor.status_atualizado.connect(self._atualizar)
        self._monitor.start()

    def _atualizar(self, status: dict):
        for chave, dot in self._indicadores_dot.items():
            online = status.get(chave, None)
            dot.set_online(online)
            if online is True:
                if chave == "outlook_novo":
                    txt_ok = "olk.exe ativo"
                elif chave == "outlook_classico":
                    txt_ok = "outlook.exe logado"
                else:
                    txt_ok = "Conectado"
                self._indicadores_lbl[chave].setText(txt_ok)
                self._indicadores_lbl[chave].setStyleSheet(
                    f"color: {COR_SUCESSO}; font-family: Consolas; font-size: 7px;"
                )
                dot.setToolTip(f"{chave.upper()}: conectado e disponível")
            elif online is False:
                self._indicadores_lbl[chave].setText("Indisponível")
                self._indicadores_lbl[chave].setStyleSheet(
                    f"color: {COR_ERRO}; font-family: Consolas; font-size: 7px;"
                )
                dot.setToolTip(f"{chave.upper()}: indisponível ou não detectado")
            else:
                self._indicadores_lbl[chave].setText("Verificando")
                self._indicadores_lbl[chave].setStyleSheet(
                    f"color: {COR_ALERTA}; font-family: Consolas; font-size: 7px;"
                )
                dot.setToolTip(f"{chave.upper()}: verificando estado")

    def parar(self):
        self._monitor.requestInterruption()
        self._monitor.quit()
        self._monitor.wait(2000)

# =====================================================
# SPARKLINE DE CPU — mini-gráfico de linha no rodapé
# =====================================================

class _SparklineCPU(QWidget):
    """
    Mini-gráfico de linha mostrando os últimos 30 valores de CPU.
    Renderizado via QPainter — zero dependências externas.
    Estilo GitHub: linha verde com área preenchida abaixo.
    """

    PONTOS   = 30
    COR_BG   = QColor("#101820")
    COR_LINE = QColor("#238636")
    COR_FILL = QColor(35, 134, 54, 40)   # verde com alpha 40

    def __init__(self, parent=None):
        super().__init__(parent)
        self._dados: list = []
        self.setToolTip("CPU — últimos 30s")
        self.setAttribute(Qt.WA_TranslucentBackground)

    def adicionar(self, valor: float):
        """Adiciona novo ponto de CPU (0–100) e redesenha."""
        self._dados.append(max(0.0, min(100.0, valor)))
        if len(self._dados) > self.PONTOS:
            self._dados = self._dados[-self.PONTOS:]
        self.update()

    def paintEvent(self, _):
        if len(self._dados) < 2:
            return

        from PySide6.QtGui import QPainterPath

        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)

        w = self.width()
        h = self.height()

        # Fundo escuro
        p.fillRect(self.rect(), self.COR_BG)

        n     = len(self._dados)
        passo = w / (n - 1)

        def _px(i, v):
            """Converte índice + valor (0–100) para QPointF."""
            x = i * passo
            y = h - (v / 100.0) * (h - 2) - 1
            return QPointF(x, y)

        # ── Área preenchida sob a linha
        path_fill = QPainterPath()
        path_fill.moveTo(QPointF(0.0, float(h)))
        for i, v in enumerate(self._dados):
            path_fill.lineTo(_px(i, v))
        path_fill.lineTo(QPointF((n - 1) * passo, float(h)))
        path_fill.closeSubpath()
        p.setPen(Qt.NoPen)
        p.setBrush(QBrush(self.COR_FILL))
        p.drawPath(path_fill)

        # ── Linha principal
        pen = QPen(self.COR_LINE, 1.5)
        pen.setCapStyle(Qt.RoundCap)
        pen.setJoinStyle(Qt.RoundJoin)
        p.setPen(pen)
        p.setBrush(Qt.NoBrush)
        path_line = QPainterPath()
        path_line.moveTo(_px(0, self._dados[0]))
        for i, v in enumerate(self._dados[1:], start=1):
            path_line.lineTo(_px(i, v))
        p.drawPath(path_line)

        # ── Ponto atual (último valor) — círculo verde sólido
        px_ult = _px(n - 1, self._dados[-1])
        p.setBrush(QBrush(self.COR_LINE))
        p.setPen(Qt.NoPen)
        p.drawEllipse(px_ult, 2.5, 2.5)

        p.end()

