# =====================================================
# LOG MODEL — QAbstractTableModel virtualizado
# Suporta até 10.000 entradas sem degradação visual.
# Substitui QTableWidget por QTableView + model.
# =====================================================

from PySide6.QtCore import QAbstractTableModel, QModelIndex


class _LogModel(QAbstractTableModel):
    """
    Model de dados para a tabela de log.

    Vantagens sobre QTableWidget:
    - Renderiza apenas as linhas visíveis (virtualização)
    - Filtro/busca recalcula índices sem recriar widgets
    - Separação clara entre dados e apresentação
    """

    COLUNAS = ["Hora", "Nível", "Mensagem"]
    MAX_ENTRADAS = 10_000

    _CORES = {
        "INFO":  QColor("#C9D1D9"),
        "OK":    QColor("#238636"),
        "ERRO":  QColor("#DA3633"),
        "AVISO": QColor("#D29922"),
        "SAP":   QColor("#1F6FEB"),
        "SP":    QColor("#A78BFA"),
    }

    def __init__(self, parent=None):
        super().__init__(parent)
        # Buffer interno: list de (hora: str, nivel: str, msg: str)
        self._dados: list = []
        # Índices visíveis após filtro
        self._vis: list = []
        # Filtros ativos
        self._f_nivel: str = "Todos"
        self._f_busca: str = ""

    # ── Interface QAbstractTableModel (obrigatória) ──────────────

    def rowCount(self, parent=QModelIndex()) -> int:
        return len(self._vis)

    def columnCount(self, parent=QModelIndex()) -> int:
        return 3

    def data(self, index: QModelIndex, role: int = Qt.DisplayRole):
        if not index.isValid() or index.row() >= len(self._vis):
            return None

        hora, nivel, msg = self._dados[self._vis[index.row()]]
        col = index.column()

        if role == Qt.DisplayRole:
            return [hora, nivel, msg][col]

        if role == Qt.ForegroundRole:
            if col == 0:
                return QColor(Theme.MUTED)
            return self._CORES.get(nivel, self._CORES["INFO"])

        if role == Qt.TextAlignmentRole:
            if col in (0, 1):
                return Qt.AlignCenter
            return Qt.AlignLeft | Qt.AlignVCenter

        return None

    def headerData(
        self,
        section: int,
        orientation: Qt.Orientation,
        role: int = Qt.DisplayRole
    ):
        if orientation == Qt.Horizontal and role == Qt.DisplayRole:
            return self.COLUNAS[section]
        return None

    # ── API pública ──────────────────────────────────────────────

    def adicionar(self, hora: str, nivel: str, msg: str):
        """
        Adiciona uma entrada ao buffer.
        Thread-safe via QTimer — chame sempre da GUI.
        """
        self._dados.append((hora, nivel, msg))

        # Limita buffer
        if len(self._dados) > self.MAX_ENTRADAS:
            excesso = len(self._dados) - self.MAX_ENTRADAS
            self._dados = self._dados[excesso:]
            # Recalcula completo após truncamento
            self.beginResetModel()
            self._recalcular()
            self.endResetModel()
            return

        # Verifica se a nova entrada passa no filtro
        if self._passa_filtro(hora, nivel, msg):
            pos = len(self._vis)
            self.beginInsertRows(QModelIndex(), pos, pos)
            self._vis.append(len(self._dados) - 1)
            self.endInsertRows()

    def definir_filtro(self, nivel: str, busca: str):
        """Aplica filtro e reconstrói os índices visíveis."""
        self._f_nivel = nivel
        self._f_busca = busca.lower().strip()
        self.beginResetModel()
        self._recalcular()
        self.endResetModel()

    def limpar(self):
        """Remove todas as entradas."""
        self.beginResetModel()
        self._dados.clear()
        self._vis.clear()
        self.endResetModel()

    @property
    def buffer(self) -> list:
        """Retorna cópia do buffer para exportação CSV."""
        return list(self._dados)

    # ── Internos ─────────────────────────────────────────────────

    def _passa_filtro(self, hora: str, nivel: str, msg: str) -> bool:
        if self._f_nivel not in ("Todos", nivel):
            return False
        if self._f_busca and self._f_busca not in msg.lower():
            return False
        return True

    def _recalcular(self):
        """Reconstrói _vis completo — chame dentro de beginResetModel."""
        self._vis = [
            i
            for i, (h, n, m) in enumerate(self._dados)
            if self._passa_filtro(h, n, m)
        ]
# =====================================================
# UA1: Delegate para colorir fundo das linhas do log
# =====================================================

class _LogDelegate(QStyledItemDelegate):
    """Pinta fundo colorido nas linhas ERRO e AVISO do log."""

    _FUNDOS = {
        "ERRO":  "#1A0505",
        "AVISO": "#1A1200",
    }

    def paint(self, painter, option, index):
        # Coluna 1 = nível
        nivel_idx = index.sibling(index.row(), 1)
        nivel     = nivel_idx.data() or ""
        fundo     = self._FUNDOS.get(nivel)
        if fundo:
            painter.fillRect(option.rect, QColor(fundo))
        super().paint(painter, option, index)



