class _PainelAlertas(QFrame):
    """
    Painel retrátil de alertas exibido sobre o PainelProgresso.
    Não bloqueia a UI — acumula alertas com severidade e ação sugerida.
    """
    # Signal emitido quando o usuário clica em "Tentar Novamente"
    from PySide6.QtCore import Signal as _SigAl
    tentar_novamente = _SigAl(str)   # passa o id do alerta

    _CORES = {
        "CRITICO": ("#EF4444", "🔴"),
        "AVISO":   ("#F59E0B", "🟡"),
        "INFO":    ("#3B82F6", "🔵"),
    }

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setObjectName("card")
        self.setStyleSheet(f"""
            QFrame#card {{
                background-color: {CINZA_BG};
                border-left: 3px solid #EF4444;
                border-radius: 6px;
            }}
        """)
        self.setMinimumWidth(300)
        self.setMaximumWidth(340)
        self._alertas: list = []

        v = QVBoxLayout(self)
        v.setContentsMargins(10, 8, 10, 8)
        v.setSpacing(4)

        # Cabeçalho
        h_cab = QHBoxLayout()
        lbl_titulo = QLabel("⚠  ALERTAS")
        lbl_titulo.setFont(QFont("Arial", 8, QFont.Bold))
        lbl_titulo.setStyleSheet(f"color: {COR_ERRO}; letter-spacing: 1px;")
        btn_limpar = QPushButton("✖ Limpar")
        btn_limpar.setFixedHeight(16)
        btn_limpar.setFixedWidth(52)
        btn_limpar.setStyleSheet(f"""
            QPushButton {{
                background: transparent;
                color: {TEXTO_OPACO};
                border: none;
                font-size: 7px;
            }}
            QPushButton:hover {{ color: {COR_ERRO}; }}
        """)
        btn_limpar.clicked.connect(self._limpar_todos)
        h_cab.addWidget(lbl_titulo)
        h_cab.addStretch()
        h_cab.addWidget(btn_limpar)
        v.addLayout(h_cab)

        sep = QFrame()
        sep.setFrameShape(QFrame.HLine)
        sep.setStyleSheet(f"background: {CINZA_BORDA}; max-height: 1px;")
        v.addWidget(sep)

        # Área scrollável de alertas
        self._scroll = QScrollArea()
        self._scroll.setWidgetResizable(True)
        self._scroll.setFrameShape(QFrame.NoFrame)
        self._scroll.setStyleSheet("background: transparent;")
        self._scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)

        self._container = QWidget()
        self._container.setStyleSheet("background: transparent;")
        self._v_cont = QVBoxLayout(self._container)
        self._v_cont.setContentsMargins(0, 0, 0, 0)
        self._v_cont.setSpacing(4)
        self._v_cont.addStretch()

        self._scroll.setWidget(self._container)
        v.addWidget(self._scroll, stretch=1)

        self._contador = QLabel("0 alerta(s)")
        self._contador.setFont(QFont("Consolas", 7))
        self._contador.setStyleSheet(f"color: {TEXTO_OPACO};")
        v.addWidget(self._contador)

        self.hide()

    def adicionar_alerta(
        self,
        mensagem: str,
        severidade: str = "AVISO",
        acao_sugerida: str = "",
        id_alerta: str = "",
        pode_tentar_novamente: bool = False,
    ):
        """Adiciona um novo card de alerta ao painel."""
        cor, icone = self._CORES.get(severidade.upper(), self._CORES["AVISO"])

        card = QFrame()
        card.setStyleSheet(f"""
            QFrame {{
                background-color: #111827;
                border-left: 3px solid {cor};
                border-radius: 4px;
            }}
        """)
        v_card = QVBoxLayout(card)
        v_card.setContentsMargins(8, 6, 8, 6)
        v_card.setSpacing(3)

        # Linha 1 — ícone + severidade + hora
        h1 = QHBoxLayout()
        lbl_ic = QLabel(f"{icone} {severidade.upper()}")
        lbl_ic.setFont(QFont("Arial", 7, QFont.Bold))
        lbl_ic.setStyleSheet(f"color: {cor};")
        hora = datetime.now().strftime("%H:%M:%S")
        lbl_hora = QLabel(hora)
        lbl_hora.setFont(QFont("Consolas", 7))
        lbl_hora.setStyleSheet(f"color: {TEXTO_OPACO};")
        h1.addWidget(lbl_ic)
        h1.addStretch()
        h1.addWidget(lbl_hora)
        v_card.addLayout(h1)

        # Linha 2 — mensagem
        lbl_msg = QLabel(mensagem[:120])
        lbl_msg.setFont(QFont("Segoe UI", 8))
        lbl_msg.setStyleSheet(f"color: {TEXTO_CLARO};")
        lbl_msg.setWordWrap(True)
        v_card.addWidget(lbl_msg)

        # Linha 3 — ação sugerida (opcional)
        if acao_sugerida:
            lbl_acao = QLabel(f"→ {acao_sugerida}")
            lbl_acao.setFont(QFont("Segoe UI", 7))
            lbl_acao.setStyleSheet(f"color: {COR_ALERTA};")
            lbl_acao.setWordWrap(True)
            v_card.addWidget(lbl_acao)

        # Linha 4 — botão tentar novamente (opcional)
        if pode_tentar_novamente and id_alerta:
            btn_retry = QPushButton("🔄  Tentar Novamente")
            btn_retry.setFixedHeight(20)
            btn_retry.setStyleSheet(f"""
                QPushButton {{
                    background: {CINZA_CARD};
                    color: {VERDE_NEON};
                    border: 1px solid {VERDE_NEON};
                    border-radius: 3px;
                    font-size: 8px;
                    font-weight: bold;
                    padding: 0 6px;
                }}
                QPushButton:hover {{
                    background: {VERDE_PETRO};
                    color: white;
                }}
            """)
            _id = id_alerta
            btn_retry.clicked.connect(lambda: self.tentar_novamente.emit(_id))
            v_card.addWidget(btn_retry)

        # Insere ANTES do stretch
        self._v_cont.insertWidget(self._v_cont.count() - 1, card)
        self._alertas.append({
            "id": id_alerta,
            "severidade": severidade,
            "mensagem": mensagem,
            "widget": card,
        })
        self._atualizar_contador()
        self.show()
        self._scroll.verticalScrollBar().setValue(
            self._scroll.verticalScrollBar().maximum()
        )

    def _limpar_todos(self):
        for a in self._alertas:
            try:
                a["widget"].deleteLater()
            except Exception:
                pass
        self._alertas.clear()
        self._atualizar_contador()
        self.hide()

    def _atualizar_contador(self):
        n = len(self._alertas)
        self._contador.setText(f"{n} alerta(s)")
        # Muda cor da borda conforme severidade máxima
        tem_critico = any(a["severidade"] == "CRITICO" for a in self._alertas)
        tem_aviso   = any(a["severidade"] == "AVISO"   for a in self._alertas)
        cor_borda   = COR_ERRO if tem_critico else (COR_ALERTA if tem_aviso else COR_INFO)
        self.setStyleSheet(f"""
            QFrame#card {{
                background-color: {CINZA_BG};
                border-left: 3px solid {cor_borda};
                border-radius: 6px;
            }}
        """)

    @property
    def tem_critico(self) -> bool:
        return any(a["severidade"] == "CRITICO" for a in self._alertas)

