    def _aplicar_estilo_timeline(self, w, estado):
        _estilos_cont = {
            "feito":    (
                f"border-radius:13px; background:{COR_SUCESSO}; "
                f"border:2px solid {COR_SUCESSO};",
                "✓", COR_SUCESSO,
                f"color:{COR_SUCESSO}; font-weight:bold;"
            ),
            "atual":    (
                f"border-radius:13px; background:#1A1500; "
                f"border:2px solid {AMARELO_PETR};",
                "▶", AMARELO_PETR,
                f"color:{BRANCO}; font-weight:bold;"
            ),
            "pendente": (
                f"border-radius:13px; background:{CINZA_CARD}; "
                f"border:2px solid {CINZA_BORDA};",
                "○", TEXTO_OPACO,
                f"color:{TEXTO_OPACO};"
            ),
            "erro":     (
                f"border-radius:13px; background:#1A0505; "
                f"border:2px solid {COR_ERRO};",
                "✕", COR_ERRO,
                f"color:{COR_ERRO}; font-weight:bold;"
            ),
        }
        qss_cont, emoji, cor_ic, qss_lbl = _estilos_cont.get(
            estado, _estilos_cont["pendente"]
        )

        for child in w.findChildren(QWidget):
            nm = child.objectName()
            if nm.startswith("ic_cont_"):
                child.setStyleSheet(qss_cont)

        for child in w.findChildren(QLabel):
            nm = child.objectName()
            if nm.startswith("ic_"):
                child.setText(emoji)
                child.setStyleSheet(
                    f"color:{cor_ic}; background:transparent; border:none;"
                )
            elif nm.startswith("lbl_"):
                child.setStyleSheet(qss_lbl)

        for child in w.findChildren(QPushButton):
            if child.objectName().startswith("btn_rep_"):
                child.setVisible(estado == "erro")

    def _atualizar_timeline(self, etapa_atual):
        chegou = False
        for etapa in self.ETAPAS:
            w = self._etapa_widgets.get(etapa)
            if w is None:
                continue
            if etapa == etapa_atual:
                estado = "atual"
                chegou = True
                for child in w.findChildren(QLabel):
                    if child.objectName() == f"ic_{etapa}":
                        child.setText(self._IC["atual"])
            elif not chegou:
                estado = "feito"
                for child in w.findChildren(QLabel):
                    if child.objectName() == f"ic_{etapa}":
                        child.setText(self._IC["feito"])
            else:
                estado = "pendente"
                for child in w.findChildren(QLabel):
                    if child.objectName() == f"ic_{etapa}":
                        child.setText(self._IC["pendente"])
            self._aplicar_estilo_timeline(w, estado)

    def _mini_card(self, titulo, valor_inicial, attr_name):
        frame = QFrame()
        frame.setObjectName("card")
        v = QVBoxLayout(frame)
        v.setContentsMargins(10, 6, 10, 6)
        v.setSpacing(2)
