    def adicionar_log(self, mensagem, nivel="INFO"):
        """Pode ser chamado de QUALQUER thread."""
        try:
            self._log_signal.emit(mensagem[:120], nivel)
        except Exception:
            pass

    def _adicionar_log_gui(self, mensagem: str, nivel: str):
        if self._encerrado:
            return

        hora = datetime.now().strftime("%H:%M:%S")
        # G5: Destaca números grandes (RM, pedido, FRS) com marcador
        try:
            mensagem_fmt = _RE_NUM_LOG.sub(
                lambda m: f"[{m.group(1)}]", mensagem
            )
        except Exception:
            mensagem_fmt = mensagem
        self._log_fila.append((hora, nivel, mensagem_fmt))

        # Proteção: se a fila crescer demais (thread muito rápida),
        # descarta as entradas mais antigas para não consumir memória
        if len(self._log_fila) > 1000:
            self._log_fila = self._log_fila[-1000:]

    def _flush_log(self):
        """
        Processa a fila de log em lote — chamado a cada 200ms.
        Sempre roda na thread GUI (QTimer conectado no __init__).

        Operações realizadas em lote:
          1. Copia e limpa a fila
          2. Atualiza buffer CSV (para exportação)
          3. Alimenta o _LogModel virtualizado
          4. Auto-scroll se usuário estava no fim da tabela
        """
        if not self._log_fila or self._encerrado:
            return

        # Copia e limpa a fila atomicamente
        lote = self._log_fila[:]
        self._log_fila.clear()

        # ── 1. Atualiza buffer CSV
        self._log_buffer.extend(lote)
        if len(self._log_buffer) > 500:
            self._log_buffer = self._log_buffer[-500:]

        # ── 2. Alimenta o model virtualizado (_LogModel)
        try:
            # Detecta se o usuário está no fim da tabela
            # antes de inserir (para não forçar scroll
            # se ele estiver lendo entradas antigas)
            sb         = self._log_tabela.verticalScrollBar()
            estava_fim = sb.value() >= sb.maximum() - 30

            for hora, nivel, mensagem in lote:
                self._log_model.adicionar(hora, nivel, mensagem)

            # Auto-scroll apenas se estava no fim
            if estava_fim:
                self._log_tabela.scrollToBottom()

        except AttributeError:
            # Fallback: _log_model não existe ou lançou AttributeError interno.
            # Verifica se _log_tabela é QTableWidget antes de chamar
            # métodos exclusivos dessa classe (insertRow, setRowHeight etc.)
            from PySide6.QtWidgets import QTableWidget as _QTW_check
            if not isinstance(self._log_tabela, _QTW_check):
                # QTableView não suporta insertRow/setRowHeight diretamente.
                # Ignora o fallback silenciosamente.
                return
            cores_nivel = {
                "INFO":  "#0D1117",   # C3: fundo neutro
                "OK":    COR_SUCESSO,
                "ERRO":  COR_ERRO,
                "AVISO": COR_ALERTA,
                "SAP":   COR_INFO,
                "SP":    "#A78BFA",
            }
            filtro = self._log_filtro.currentText()
            busca  = self._log_busca.text().lower().strip()

            for hora, nivel, mensagem in lote:
                if filtro != "Todos" and filtro != nivel:
                    continue
                if busca and busca not in mensagem.lower():
                    continue

                cor = cores_nivel.get(nivel, "#C9D1D9")
                row = self._log_tabela.rowCount()
                self._log_tabela.insertRow(row)
                self._log_tabela.setRowHeight(row, 16)

                # Usa pool de objetos — zero alocação
                item_hora  = _item_pool.adquirir(hora)
                item_nivel = _item_pool.adquirir(nivel)
                item_msg   = _item_pool.adquirir(mensagem)

                item_hora.setForeground(
                    _cor_pool(TEXTO_OPACO)
                )
                item_nivel.setForeground(_cor_pool(cor))
                item_msg.setForeground(_cor_pool(cor))


                self._log_tabela.setItem(row, 0, item_hora)
                self._log_tabela.setItem(row, 1, item_nivel)
                self._log_tabela.setItem(row, 2, item_msg)

            # Limita a 300 linhas visíveis
            while self._log_tabela.rowCount() > 300:
                self._log_tabela.removeRow(0)

            self._log_tabela.scrollToBottom()


    def _filtrar_log(self):
        """Delega filtro ao model — sem recriar widgets."""
        filtro = self._log_filtro.currentText()
        busca  = self._log_busca.text()
        try:
            self._log_model.definir_filtro(filtro, busca)
            self._log_tabela.scrollToBottom()
        except Exception:
            pass


    def _exportar_log_csv(self):
        """Exporta o buffer de log para CSV em C:\\AutomacaoSAP\\Logs\\."""
        try:
            import csv as _csv
            ts  = datetime.now().strftime("%Y%m%d_%H%M%S")
            dst = Path(tempfile.gettempdir()) / f"log_painel_{ts}.csv"
            # Usa o buffer do model se disponível, senão o buffer legado
            dados = (
                self._log_model.buffer
                if hasattr(self, "_log_model")
                else self._log_buffer
            )
            with open(str(dst), "w", newline="", encoding="utf-8") as f:
                w = _csv.writer(f)
                w.writerow(["Hora", "Nível", "Mensagem"])
                w.writerows(dados)
            registrar_log(f"OK: Log exportado → {dst.name}", "OK")
        except Exception as e:
            registrar_log(
                f"AVISO: Falha ao exportar log CSV: {e}", "AVISO"
            )


    def marcar_erro_etapa(self, nome_etapa):
        w = self._etapa_widgets.get(nome_etapa)
        if w:
            self._aplicar_estilo_timeline(w, "erro")
            for child in w.findChildren(QLabel):
                if child.objectName() == f"ic_{nome_etapa}":
                    child.setText(self._IC["erro"])

        # Sincroniza com o fluxograma
        try:
            from PySide6.QtCore import QTimer
            _nome = nome_etapa
            QTimer.singleShot(
                0,
                lambda: [
                    widget._fluxo_widget.marcar_erro(_nome)
                    for widget in _qapp.topLevelWidgets()
                    if hasattr(widget, "_fluxo_widget")
                ]
            )
        except Exception:
            pass
