def db_consultar_assistente(pergunta: str) -> str:
    """
    Assistente simples: responde perguntas sobre o histórico
    usando SQL pré-definido — sem LLM, sem dependência externa.
    """
    pergunta_l = pergunta.lower().strip()

    try:
        with _sqlite3.connect(_DB_PATH) as con:
            con.row_factory = _sqlite3.Row

            # ── Tempo médio geral
            if any(w in pergunta_l for w in ["tempo médio", "media", "média"]):
                row = con.execute(
                    "SELECT AVG(tempo_total) as media, COUNT(*) as n "
                    "FROM execucoes WHERE tempo_total > 0"
                ).fetchone()
                if row and row["n"] > 0:
                    m = int(row["media"])
                    return (
                        f"Tempo médio das {row['n']} execuções: "
                        f"{m // 60}m {m % 60}s."
                    )
                return "Ainda não há execuções suficientes para calcular a média."

            # ── Contrato mais lento
            if any(w in pergunta_l for w in ["mais lento", "mais demorado", "demora mais"]):
                row = con.execute(
                    "SELECT contrato, AVG(tempo_total) as media, COUNT(*) as n "
                    "FROM execucoes WHERE tempo_total > 0 "
                    "GROUP BY contrato ORDER BY media DESC LIMIT 1"
                ).fetchone()
                if row:
                    m = int(row["media"])
                    return (
                        f"Contrato mais lento: {row['contrato']} "
                        f"com média de {m // 60}m {m % 60}s "
                        f"em {row['n']} execução(ões)."
                    )

            # ── Últimas falhas
            if any(w in pergunta_l for w in ["falha", "falhou", "erro", "parcial"]):
                rows = con.execute(
                    "SELECT empresa, contrato, data_inicio, resultado "
                    "FROM execucoes WHERE resultado != 'OK' "
                    "ORDER BY id DESC LIMIT 5"
                ).fetchall()
                if not rows:
                    return "Nenhuma falha registrada nas execuções recentes."
                linhas = [
                    f"  • {r['contrato']} — {r['resultado']} "
                    f"({(r['data_inicio'] or '')[:10]})"
                    for r in rows
                ]
                return "Últimas execuções com falha:\n" + "\n".join(linhas)

            # ── Total de execuções
            if any(w in pergunta_l for w in ["total", "quantas", "quantos"]):
                row = con.execute(
                    "SELECT COUNT(*) as n, "
                    "SUM(CASE WHEN resultado='OK' THEN 1 ELSE 0 END) as ok "
                    "FROM execucoes"
                ).fetchone()
                if row and row["n"]:
                    taxa = int(row["ok"] / row["n"] * 100)
                    return (
                        f"Total de execuções: {row['n']}  |  "
                        f"OK: {row['ok']}  |  "
                        f"Taxa de sucesso: {taxa}%."
                    )

            # ── Última execução
            if any(w in pergunta_l for w in ["última", "ultimo", "recente"]):
                row = con.execute(
                    "SELECT empresa, contrato, data_inicio, "
                    "tempo_total, resultado "
                    "FROM execucoes ORDER BY id DESC LIMIT 1"
                ).fetchone()
                if row:
                    t = int(row["tempo_total"] or 0)
                    return (
                        f"Última execução: {row['contrato']}\n"
                        f"Empresa: {(row['empresa'] or '')[:50]}\n"
                        f"Data: {(row['data_inicio'] or '')[:16]}\n"
                        f"Duração: {t // 60}m {t % 60}s\n"
                        f"Resultado: {row['resultado']}"
                    )

            # ── Contrato mais executado
            if any(w in pergunta_l for w in ["mais executado", "frequente", "frequência"]):
                row = con.execute(
                    "SELECT contrato, COUNT(*) as n "
                    "FROM execucoes GROUP BY contrato "
                    "ORDER BY n DESC LIMIT 1"
                ).fetchone()
                if row:
                    return (
                        f"Contrato mais executado: {row['contrato']} "
                        f"com {row['n']} execuções."
                    )

    except Exception as e:
        return f"Erro ao consultar o banco: {e}"

    return (
        "Não entendi. Tente perguntar:\n"
        "  • 'tempo médio'\n"
        "  • 'contrato mais lento'\n"
        "  • 'últimas falhas'\n"
        "  • 'total de execuções'\n"
        "  • 'última execução'\n"
        "  • 'contrato mais executado'"
    )

class HeatmapExecucoes(QWidget):
    """
    Heatmap estilo GitHub: 52 semanas × 7 dias.
    Cor por resultado: OK=verde, PARCIAL=amarelo,
    sem execução=cinza escuro.
    """

    _C_VAZIO    = QColor("#1F2937")
    _C_OK       = QColor("#008542")
    _C_PARCIAL  = QColor("#F59E0B")
    _C_ERRO     = QColor("#EF4444")
    _C_HOVER    = QColor("#60A5FA")

    CELULA = 13   # px por célula
    GAP    = 2    # px entre células

    def __init__(self, parent=None):
        super().__init__(parent)
        self._dados: dict = {}   # "AAAA-MM-DD" → "OK"|"PARCIAL"|"ERRO"
        self._hover: str  = ""
        self.setMouseTracking(True)
        self._calcular_tamanho()
        self.setToolTip("")

    def _calcular_tamanho(self):
        w = 53 * (self.CELULA + self.GAP) + 30   # 53 semanas + labels
        h = 7  * (self.CELULA + self.GAP) + 30   # 7 dias + labels
        self.setFixedSize(w, h)

    def carregar(self):
        """Lê o banco e popula self._dados."""
        self._dados = {}
        # Prioridade: ERRO(3) > PARCIAL(2) > PENDENTE(1) > OK(1) > vazio(0)
        _PRIORIDADE = {"ERRO": 3, "PARCIAL": 2, "PENDENTE": 1, "OK": 1}
        try:
            with _sqlite3.connect(_DB_PATH) as con:
                rows = con.execute(
                    "SELECT data_inicio, resultado "
                    "FROM execucoes "
                    "WHERE data_inicio IS NOT NULL "
                    "ORDER BY data_inicio"
                ).fetchall()
            for data_str, resultado in rows:
                dia = data_str[:10]   # "AAAA-MM-DD"
                resultado = resultado or "OK"
                anterior  = self._dados.get(dia, "")
                # Mantém o resultado de maior prioridade para o dia
                if _PRIORIDADE.get(resultado, 0) >= _PRIORIDADE.get(anterior, 0):
                    self._dados[dia] = resultado
        except Exception:
            pass
        self.update()


    def paintEvent(self, _):
        from datetime import date, timedelta

        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        p.fillRect(self.rect(), QColor("#111827"))

        hoje    = date.today()
        inicio  = hoje - timedelta(weeks=52)
        # Avança até segunda-feira
        inicio  = inicio - timedelta(days=inicio.weekday())

        passo   = self.CELULA + self.GAP
        off_x   = 24   # espaço para labels de meses
        off_y   = 18   # espaço para labels de dias

        dias_sem = ["Seg", "Ter", "Qua", "Qui", "Sex", "Sáb", "Dom"]
        p.setFont(QFont("Consolas", 7))
        p.setPen(QColor("#6B7280"))
        for i, dia_nome in enumerate(dias_sem):
            if i % 2 == 0:
                p.drawText(2, off_y + i * passo + self.CELULA - 2, dia_nome[:3])

        mes_anterior = -1
        dia_atual    = inicio

        for semana in range(53):
            for dia_semana in range(7):
                d = inicio + timedelta(weeks=semana, days=dia_semana)

                if d > hoje:
                    break

                chave = d.isoformat()
                res   = self._dados.get(chave, "")

                if res == "OK":
                    cor = self._C_OK
                elif res == "PARCIAL":
                    cor = self._C_PARCIAL
                elif res in ("ERRO", "PENDENTE"):
                    cor = self._C_ERRO
                else:
                    cor = self._C_VAZIO

                if chave == self._hover:
                    cor = self._C_HOVER

                x = off_x + semana * passo
                y = off_y + dia_semana * passo

                p.setBrush(QBrush(cor))
                p.setPen(Qt.NoPen)
                p.drawRoundedRect(x, y, self.CELULA, self.CELULA, 2, 2)

                # Label de mês
                if d.month != mes_anterior and dia_semana == 0:
                    mes_anterior = d.month
                    p.setPen(QColor("#9CA3AF"))
                    p.setFont(QFont("Consolas", 7))
                    p.drawText(x, off_y - 4, d.strftime("%b"))

        p.end()

    def mouseMoveEvent(self, event):
        from datetime import date, timedelta

        passo  = self.CELULA + self.GAP
        off_x  = 24
        off_y  = 18
        hoje   = date.today()
        inicio = hoje - timedelta(weeks=52)
        inicio = inicio - timedelta(days=inicio.weekday())

        mx, my = event.position().x(), event.position().y()
        semana     = int((mx - off_x) / passo)
        dia_semana = int((my - off_y) / passo)

        if 0 <= semana < 53 and 0 <= dia_semana < 7:
            d     = inicio + timedelta(weeks=semana, days=dia_semana)
            chave = d.isoformat()
            if chave != self._hover:
                self._hover = chave
                res = self._dados.get(chave, "sem execução")
                self.setToolTip(f"{d.strftime('%d/%m/%Y')}  —  {res or 'sem execução'}")
                self.update()
        else:
            if self._hover:
                self._hover = ""
                self.update()

    def leaveEvent(self, _):
        if self._hover:
            self._hover = ""
            self.update()

def abrir_dashboard(
    empresa, contrato, icj, periodo,
    sucesso_ped, falha_ped,
    sucesso_frs, falha_frs,
    sucesso_rm,  falha_rm,
    sucesso_esp, falha_esp,
    upload_pedidos_ok, upload_frs_ok,
    upload_rm_ok,      upload_espelho_ok,
    email_ok, log_file,
    tempo_total_s=0,
    url_sharepoint="",
    historico_etapas=None,
    n_contratos=1,
):
    """Dashboard executivo final — estilo Fiori/Power BI."""

    historico_etapas = historico_etapas or {}
    n_contratos = max(1, int(n_contratos or 1))

    win = QDialog()
    win.setWindowTitle("✅ Petrobras — Execução Concluída")

    # Calcula 90% da altura da tela disponível
    screen_h = _qapp.primaryScreen().availableGeometry().height()
    screen_w = _qapp.primaryScreen().availableGeometry().width()
    win_h    = min(700, int(screen_h * 0.88))
    win_w    = min(620, int(screen_w * 0.45))
    win.setFixedSize(win_w, win_h)

    win.setWindowFlags(
        Qt.Dialog |
        Qt.WindowMinimizeButtonHint |
        Qt.WindowMaximizeButtonHint |
        Qt.WindowCloseButtonHint
    )

    layout = QVBoxLayout(win)
    layout.setSpacing(0)
    layout.setContentsMargins(0, 0, 0, 0)

    # ── Cabeçalho verde
    header = QFrame()
    header.setStyleSheet(f"background-color: {VERDE_PETRO};")
    header.setFixedHeight(80)
    h_lay  = QVBoxLayout(header)
    h_lay.setContentsMargins(20, 10, 20, 10)
    h_lay.setSpacing(2)

    lbl_titulo = QLabel("EXECUÇÃO CONCLUÍDA")
    lbl_titulo.setFont(QFont("Arial Black", 14, QFont.Bold))
