class _CircularTimelineEtapas(QWidget):
    """Timeline circular animada das etapas conclu?das."""

    _CORES = ["#1F6FEB", "#238636", "#6E40C9", "#D29922", "#00B4D8", "#EC6547"]

    def __init__(self, historico: dict, parent=None):
        super().__init__(parent)
        self._hist = {k: v for k, v in (historico or {}).items() if v > 0}
        self._fase = 0.0
        self.setMinimumHeight(190)
        self.setToolTip("Timeline circular das etapas")
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._tick)
        self._timer.start(33)

    def _tick(self):
        self._fase = (self._fase + 2.0) % 360
        self.update()

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        p.setRenderHint(QPainter.TextAntialiasing)
        W, H = self.width(), self.height()
        cx, cy = W / 2, H / 2 + 4
        r = max(48, min(W, H) * 0.34)
        etapas = list(self._hist.items())
        total = sum(v for _, v in etapas) or 1
        p.setPen(QPen(QColor("#1F2937"), 9))
        p.drawEllipse(QPointF(cx, cy), r, r)
        inicio = int((90 - self._fase * 0.08) * 16)
        for idx, (nome, dur) in enumerate(etapas):
            span = max(8, int(360 * dur / total * 16))
            cor = QColor(self._CORES[idx % len(self._CORES)])
            p.setPen(QPen(cor, 9, Qt.SolidLine, Qt.RoundCap))
            p.drawArc(QRectF(cx-r, cy-r, 2*r, 2*r), inicio, -span)
            inicio -= span
        p.setPen(QColor(BRANCO))
        p.setFont(QFont("Arial", 8, QFont.Bold))
        p.drawText(QRectF(0, cy-r-24, W, 20), Qt.AlignCenter, "TIMELINE CIRCULAR")
        p.setFont(QFont("Consolas", 18, QFont.Bold))
        p.setPen(QColor(AMARELO_PETR))
        p.drawText(QRectF(cx-r, cy-22, 2*r, 28), Qt.AlignCenter, str(len(etapas)))
        p.setFont(QFont("Consolas", 8))
        p.setPen(QColor(TEXTO_OPACO))
        p.drawText(QRectF(cx-r, cy+8, 2*r, 20), Qt.AlignCenter, "etapas")
        p.end()

def _criar_widget_dashboard(
    empresa, contrato, icj, periodo,
    sucesso_ped, falha_ped,
    sucesso_frs, falha_frs,
    sucesso_rm,  falha_rm,
    sucesso_esp, falha_esp,
    upload_pedidos_ok, upload_frs_ok,
    upload_rm_ok,      upload_espelho_ok,
    email_ok, log_file,
    tempo_total_s=0,
    url_sharepoint="",
    historico_etapas=None,
    rotulo_contratos="",
    n_contratos=1,
):
    """
    Versão embutida do dashboard — retorna QWidget em vez de abrir QDialog.
    Usada pela JanelaPrincipal para exibir o resultado na página Dashboard.
    """
    historico_etapas = historico_etapas or {}
    n_contratos = max(1, int(n_contratos or 1))

    container = QWidget()
    container.setStyleSheet(f"background-color: {CINZA_BG};")

    # ── Partículas sutis em background (celebração)
    _total_docs_dash = (
        sucesso_ped + sucesso_frs +
        sucesso_rm  + sucesso_esp
    )
    _todas_ok = (
        falha_ped + falha_frs +
        falha_rm  + falha_esp
    ) == 0

    if _total_docs_dash > 0:
        # V19: background de part?culas no dashboard; mais intenso se tudo OK.
        _part_dash = _ParticleSystem(container)
        _part_dash.setGeometry(0, 0, 900, 760)
        import random as _rnd_d
        for p_d in _part_dash._particulas:
            p_d["vy"]    = _rnd_d.uniform(-0.45, -0.12)
            p_d["alpha"] = _rnd_d.uniform(0.04, 0.14) if _todas_ok else _rnd_d.uniform(0.015, 0.06)
        _part_dash.lower()
        _part_dash.setAttribute(
            Qt.WA_TransparentForMouseEvents
        )

    outer = QVBoxLayout(container)
    outer.setContentsMargins(0, 0, 0, 0)
    outer.setSpacing(0)


    # Cabeçalho verde
    header = QFrame()
    header.setStyleSheet(f"background-color: {VERDE_PETRO};")
    header.setFixedHeight(96)
    h_lay = QVBoxLayout(header)
    h_lay.setContentsMargins(20, 10, 20, 10)
    h_lay.setSpacing(2)
    lbl_titulo = QLabel("EXECUÇÃO CONCLUÍDA")
    lbl_titulo.setFont(QFont("Arial Black", 14, QFont.Bold))
    lbl_titulo.setStyleSheet("color: white; letter-spacing: 2px;")
    h_lay.addWidget(lbl_titulo)
    _linha_emp = (rotulo_contratos or "").strip()
    if not _linha_emp:
        emp_txt = (empresa[:55] + "…") if len(empresa) > 55 else empresa
        _linha_emp = f"{emp_txt}  ·  {contrato}"
    if icj and icj != "—":
        _linha_emp = f"{_linha_emp}  ·  {periodo}"
    else:
        _linha_emp = f"{_linha_emp}  ·  {periodo}"
    lbl_emp = QLabel(_linha_emp)
    lbl_emp.setFont(QFont("Segoe UI", 8))
    lbl_emp.setStyleSheet(f"color: {AMARELO_PETR};")
    lbl_emp.setWordWrap(True)
    h_lay.addWidget(lbl_emp)
    outer.addWidget(header)

    # Scroll para o corpo — reutiliza lógica do abrir_dashboard original
    scroll_area = QScrollArea()
