    def kpi_card(titulo, valor, total, ok_bool):
        cor = COR_SUCESSO if ok_bool else COR_ERRO
        pct = int(valor / total * 100) if total > 0 else 0

        frame = QFrame()
        frame.setObjectName("card")
        frame.setFixedHeight(88)
        v = QVBoxLayout(frame)
        v.setContentsMargins(12, 8, 12, 8)
        v.setSpacing(2)

        # Linha superior: título + sparkline
        h_top = QHBoxLayout()
        h_top.setSpacing(4)

        lbl_t = QLabel(titulo.upper())
