    h_kpi.addWidget(kpi_card("RM",       sucesso_rm,  max(total_rm, 1), falha_rm ==0))
    h_kpi.addWidget(kpi_card("Espelhos", sucesso_esp, max(total_esp,1), falha_esp==0))
    body_lay.addLayout(h_kpi)

    # Status uploads + email
    def status_card(titulo, ok_bool, detalhe=""):
        frame = QFrame()
        frame.setObjectName("card")
        h = QHBoxLayout(frame)
        h.setContentsMargins(14, 10, 14, 10)
        ic = QLabel("✅" if ok_bool else "❌")
