    # ─────────────────────────────────────────────────
    def _trocar_grupo(self, grupo: str):
        self._grupo_atual = grupo
        for g, btn in self._tab_btns.items():
            btn.setChecked(g == grupo)
        self._renderizar_atual()

    def _anterior(self):
        idx = self._indices[self._grupo_atual]
        if idx > 0:
            self._indices[self._grupo_atual] -= 1
            self._renderizar_atual()

    def _proximo(self):
        grupo   = self._grupo_atual
        idx     = self._indices[grupo]
        total   = len(self._grupos[grupo])
        if idx < total - 1:
            self._indices[grupo] += 1
            self._renderizar_atual()
        else:
            # Avança para próximo grupo automaticamente
            grupos  = list(self._grupos.keys())
            i_atual = grupos.index(grupo)
            if i_atual < len(grupos) - 1:
                self._trocar_grupo(grupos[i_atual + 1])

    def _abrir_arquivo(self):
        grupo   = self._grupo_atual
        idx     = self._indices[grupo]
        arquivos = self._grupos[grupo]
        if arquivos and idx < len(arquivos):
            caminho = arquivos[idx]
            if caminho.exists():
                os.startfile(str(caminho))
    def _abrir_pasta_grupo(self):
        """
        Abre no Windows Explorer a pasta do grupo
        atualmente selecionado nas abas.
        """
        grupo    = self._grupo_atual
        arquivos = self._grupos[grupo]
        if not arquivos:
            toast(
                f"Nenhum arquivo no grupo '{grupo}'",
                "aviso", 3000
            )
            return
        pasta = arquivos[0].parent
        if pasta.exists():
            os.startfile(str(pasta))
        else:
            toast(
                f"Pasta não encontrada:\n{pasta}",
                "aviso", 3000
            )


    # ─────────────────────────────────────────────────
    def _renderizar_atual(self):
        """Renderiza a miniatura do PDF atual via PIL."""
        grupo    = self._grupo_atual
        idx      = self._indices[grupo]
        arquivos = self._grupos[grupo]
        total    = len(arquivos)

        # Atualiza navegação
        self._lbl_nav.setText(
            f"{idx + 1} / {total}"
            if total > 0 else "0 / 0"
        )
        self._btn_ant.setEnabled(idx > 0)
        self._btn_prox.setEnabled(
            idx < total - 1
            or list(self._grupos.keys()).index(grupo)
            < len(self._grupos) - 1
        )

        if not arquivos or idx >= total:
            self._lbl_img.setText(
                "Nenhum arquivo neste grupo."
            )
            self._lbl_nome.setText("")
            return

        caminho = arquivos[idx]
        self._lbl_nome.setText(caminho.name)

        # ── Validação do arquivo
        valido, motivo = validar_pdf_gerado(caminho)
        if valido:
            self._lbl_status.setText("✅  Arquivo válido")
            self._lbl_status.setStyleSheet(
                f"color: {COR_SUCESSO}; font-weight: bold;"
            )
        else:
            self._lbl_status.setText(f"❌  {motivo}")
            self._lbl_status.setStyleSheet(
                f"color: {COR_ERRO}; font-weight: bold;"
            )

        # ── Detalhes do arquivo
        try:
            stat    = caminho.stat()
            tamanho = stat.st_size
            criado  = datetime.fromtimestamp(
                stat.st_mtime
            ).strftime("%d/%m/%Y %H:%M")

            if tamanho >= 1024 * 1024:
                tam_txt = f"{tamanho / (1024*1024):.1f} MB"
            else:
                tam_txt = f"{tamanho / 1024:.1f} KB"

            self._lbl_tamanho.setText(f"Tamanho : {tam_txt}")
            self._lbl_criado.setText(f"Criado  : {criado}")
        except Exception:
            pass

        # ── Renderização da miniatura
        self._lbl_img.setText("⏳  Gerando preview...")
        _qapp.processEvents()

        # Roda a renderização em thread para não travar a UI
        import threading as _th
        _th.Thread(
            target=self._renderizar_thread,
            args=(caminho,),
            daemon=True
        ).start()

    def _renderizar_thread(self, caminho: Path):
        """
        Renderiza a primeira página do PDF como imagem.

        Ordem de tentativa:
          1. Cache interno    — instantâneo se já renderizado
          2. PyMuPDF (fitz)   — mais rápido (~3×), pip install pymupdf
          3. pdfplumber + PIL — fallback robusto
          4. PIL puro         — fallback visual com metadados e texto
        """
        from PySide6.QtCore import QTimer
        from PySide6.QtGui  import QPixmap

        RESOLUCAO = 120
        chave = (str(caminho), RESOLUCAO)

        # ── 1. Verifica cache (PC2: LRU)
        _PreviewPDF._inicializar_cache()
        if chave in _PreviewPDF._cache_pixmap:
            _PreviewPDF._cache_pixmap.move_to_end(chave)   # PC2: mais recente
            dado = _PreviewPDF._cache_pixmap[chave]

            if isinstance(dado, bytes):
                # Cache com imagem PNG
                _b = dado
                def _cache_img():
                    try:
                        pixmap = QPixmap()
                        pixmap.loadFromData(_b)
                        scaled = pixmap.scaled(
                            400, 400,
                            Qt.KeepAspectRatio,
                            Qt.SmoothTransformation
                        )
                        self._lbl_img.setPixmap(scaled)
                        self._lbl_img.setText("")
                    except Exception:
                        pass
                QTimer.singleShot(0, _cache_img)
            else:
                # Cache com mensagem textual (fallback)
                _msg = str(dado)
                QTimer.singleShot(
                    0, lambda: self._lbl_img.setText(_msg)
                )
            return

        # ── Variáveis de resultado
        png_bytes = None
        n_pags    = 0

        # ── 2. Tenta PyMuPDF (mais rápido)
        try:
            import fitz as _fitz
            doc    = _fitz.open(str(caminho))
            n_pags = doc.page_count
            page   = doc[0]
            mat    = _fitz.Matrix(1.5, 1.5)
            pix    = page.get_pixmap(matrix=mat, alpha=False)
            png_bytes = bytes(pix.tobytes("png"))
            doc.close()
            print(f"  Preview via PyMuPDF: {caminho.name}")

        except ImportError:
            pass   # PyMuPDF não instalado → tenta pdfplumber
        except Exception as e_fitz:
            registrar_log(
                f"AVISO [PREVIEW]: fitz falhou para "
                f"{caminho.name}: {e_fitz}",
                "AVISO"
            )

        # ── 3. Tenta pdfplumber + PIL
        if not png_bytes:
            try:
                import pdfplumber as _pp
                from io import BytesIO as _BytesIO

                with _pp.open(str(caminho)) as pdf:
                    n_pags = len(pdf.pages)
                    # to_image() usa wand/ghostscript internamente
                    # Se não tiver, lança exceção → vai para fallback 4
                    img_pil = pdf.pages[0].to_image(
                        resolution=RESOLUCAO
                    ).original
                    buf = _BytesIO()
                    img_pil.save(buf, format="PNG")
                    buf.seek(0)
                    png_bytes = buf.read()
                    print(f"  Preview via pdfplumber: {caminho.name}")

            except ImportError:
                pass   # pdfplumber não instalado
            except Exception as e_pp:
                registrar_log(
                    f"AVISO [PREVIEW]: pdfplumber.to_image falhou "
                    f"para {caminho.name}: {e_pp} — usando fallback",
                    "AVISO"
                )

        # ── 4. Fallback PIL puro — gera imagem com metadados e texto
        # Não depende de ghostscript/wand, funciona sempre que PIL
        # estiver instalado (já é dependência do reportlab).
        if not png_bytes:
            try:
                from PIL import Image as _Image
                from PIL import ImageDraw as _Draw
                from io import BytesIO as _BytesIO

                # Metadados do arquivo
                try:
                    stat       = caminho.stat()
                    tam_kb     = stat.st_size // 1024
                    criado_str = datetime.fromtimestamp(
                        stat.st_mtime
                    ).strftime("%d/%m/%Y %H:%M")
                except Exception:
                    tam_kb, criado_str = 0, "—"

                # Tenta extrair texto do PDF para exibir
                texto_pdf  = ""
                try:
                    import pdfplumber as _pp2
                    with _pp2.open(str(caminho)) as pdf2:
                        n_pags = len(pdf2.pages)
                        for pg in pdf2.pages[:2]:
                            texto_pdf += (
                                pg.extract_text() or ""
                            ) + "\n"
                        texto_pdf = texto_pdf[:1200]
                except Exception:
                    pass

                # ── Cria imagem 400×520 com layout de "cartão PDF"
                LARGURA, ALTURA = 400, 520
                COR_FUNDO  = (13,  17,  23)    # CINZA_BG
                COR_VERDE  = (0,   122,  62)   # VERDE_PETRO
                COR_BRANCO = (240, 246, 252)   # BRANCO
                COR_TEXTO  = (201, 209, 217)   # TEXTO_CLARO
                COR_MUTED  = (110, 118, 129)   # TEXTO_OPACO
                COR_BORDA  = (33,  38,  45)    # CINZA_BORDA
                COR_CARD   = (22,  27,  34)    # CINZA_CARD
                COR_AMAR   = (245, 200,  0)    # AMARELO_PETR

                img  = _Image.new("RGB", (LARGURA, ALTURA), COR_FUNDO)
                draw = _Draw.Draw(img)

                # Cabeçalho verde
                draw.rectangle([0, 0, LARGURA, 44], fill=COR_VERDE)
                draw.text(
                    (12, 12),
                    f"  {caminho.name[:42]}",
                    fill=COR_BRANCO
                )

                # Separador
                draw.rectangle([0, 44, LARGURA, 45], fill=COR_BORDA)

                # Card de metadados
                draw.rectangle([8, 52, LARGURA - 8, 108], fill=COR_CARD)
                y = 60
                for rotulo, valor in [
                    ("Tamanho", f"{tam_kb} KB"),
                    ("Páginas", str(n_pags) if n_pags else "?"),
                    ("Criado",  criado_str),
                ]:
                    draw.text(
                        (16, y),
                        f"{rotulo:<10}: {valor}",
                        fill=COR_TEXTO
                    )
                    y += 16

                # Separador
                draw.rectangle(
                    [8, 112, LARGURA - 8, 113],
                    fill=COR_BORDA
                )

                # Conteúdo textual do PDF
                y = 120
                if texto_pdf.strip():
                    draw.text((12, y), "Conteúdo:", fill=COR_VERDE)
                    y += 18
                    for linha in texto_pdf.split("\n"):
                        linha = linha.strip()
                        if not linha:
                            y += 6
                            continue
                        if y > ALTURA - 30:
                            draw.text(
                                (12, y),
                                "  [...]",
                                fill=COR_MUTED
                            )
                            break
                        # Limita largura da linha
                        if len(linha) > 54:
                            linha = linha[:51] + "..."
                        draw.text((12, y), linha, fill=COR_TEXTO)
                        y += 15
                else:
                    draw.text(
                        (12, y),
                        "Texto não extraível neste PDF.",
                        fill=COR_MUTED
                    )
                    y += 20
                    draw.text(
                        (12, y),
                        "Para preview de imagem instale:",
                        fill=COR_MUTED
                    )
                    y += 16
                    draw.text(
                        (12, y),
                        "  pip install pymupdf",
                        fill=COR_AMAR
                    )

                # Rodapé
                draw.rectangle(
                    [0, ALTURA - 20, LARGURA, ALTURA],
                    fill=COR_CARD
                )
                draw.text(
                    (12, ALTURA - 14),
                    "Use 'Abrir Arquivo' para visualizar o PDF completo",
                    fill=COR_MUTED
                )

                buf = _BytesIO()
                img.save(buf, format="PNG")
                buf.seek(0)
                png_bytes = buf.read()
                print(
                    f"  Preview via fallback PIL: {caminho.name}"
                )

            except Exception as e_pil:
                registrar_log(
                    f"AVISO [PREVIEW]: fallback PIL falhou "
                    f"para {caminho.name}: {e_pil}",
                    "AVISO"
                )

        # ── Salva no cache e envia para GUI
        if png_bytes:
            # PC2: LRU real — remover o mais antigo
            _PreviewPDF._inicializar_cache()
            if len(_PreviewPDF._cache_pixmap) >= _PreviewPDF._CACHE_MAX:
                _PreviewPDF._cache_pixmap.popitem(last=False)
            _PreviewPDF._cache_pixmap[chave] = png_bytes


            _b = png_bytes
            _n = n_pags

            def _aplicar():
                try:
                    pixmap = QPixmap()
                    pixmap.loadFromData(_b)
                    scaled = pixmap.scaled(
                        400, 400,
                        Qt.KeepAspectRatio,
                        Qt.SmoothTransformation
                    )
                    self._lbl_img.setPixmap(scaled)
                    self._lbl_img.setText("")
                    if _n:
                        self._lbl_paginas.setText(
                            f"Páginas : {_n}"
                        )
                except Exception as eg:
                    self._lbl_img.setText(
                        f"Erro ao exibir:\n{eg}"
                    )

            QTimer.singleShot(0, _aplicar)

        else:
            msg = (
                f"Preview não disponível\n\n"
                f"Arquivo: {caminho.name}\n\n"
                f"Use 'Abrir Arquivo' para visualizar.\n\n"
                f"Para preview automático:\n"
                f"  pip install pymupdf"
            )
            _PreviewPDF._cache_pixmap[chave] = msg
            QTimer.singleShot(
                0, lambda: self._lbl_img.setText(msg)
            )

    def _atualizar_resumo(self):
        """Atualiza o texto de resumo no rodapé."""
        total = sum(
            len(v) for v in self._grupos.values()
        )
        self._lbl_resumo_val.setText(
            f"Total: {total} arquivo(s) para upload  —  "
            f"Revise antes de confirmar."
        )

