class _BotaoSidebar(QPushButton):
    """Botão de navegação da sidebar."""
    def __init__(self, icone: str, texto: str, parent=None):
        super().__init__(parent)
        self.setText(f"  {icone}  {texto}")
        self.setCheckable(True)
        self.setFixedHeight(44)
        self.setFont(QFont("Segoe UI", 9))
        self.setCursor(Qt.PointingHandCursor)
        self._aplicar_estilo(False)

    def _aplicar_estilo(self, ativo: bool):
        if ativo:
            self.setStyleSheet(f"""
                QPushButton {{
                    background-color: {VERDE_PETRO};
                    color: white;
                    border: none;
                    border-radius: 0px;
                    text-align: left;
                    padding-left: 12px;
                    font-weight: bold;
                }}
            """)
        else:
            self.setStyleSheet(f"""
                QPushButton {{
                    background-color: transparent;
                    color: {TEXTO_OPACO};
                    border: none;
                    border-radius: 0px;
                    text-align: left;
                    padding-left: 12px;
                }}
                QPushButton:hover {{
                    background-color: {CINZA_CARD};
                    color: {TEXTO_CLARO};
                }}
            """)

    def setChecked(self, checked: bool):
        super().setChecked(checked)
        self._aplicar_estilo(checked)

class _PaginaAssistente(QWidget):
    """
    Assistente de histórico: consultas em linguagem
    natural (simplificada) sobre o banco de execuções.
    Sem LLM — respostas baseadas em SQL pré-definido.
    """

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setStyleSheet(f"background-color: {CINZA_BG};")
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        # Cabeçalho
        hdr = QFrame()
        hdr.setStyleSheet(f"background-color: {VERDE_PETRO};")
        hdr.setFixedHeight(56)
        h_lay = QHBoxLayout(hdr)
        h_lay.setContentsMargins(20, 0, 20, 0)
        lbl_t = QLabel("🤖  Assistente de Histórico")
        lbl_t.setFont(QFont("Arial Black", 12, QFont.Bold))
        lbl_t.setStyleSheet("color: white;")
        h_lay.addWidget(lbl_t)
        h_lay.addStretch()
        lbl_info = QLabel("Consultas sobre execuções registradas")
        lbl_info.setFont(QFont("Consolas", 8))
        lbl_info.setStyleSheet(f"color: {AMARELO_PETR};")
        h_lay.addWidget(lbl_info)
        layout.addWidget(hdr)

        # Corpo
        body = QWidget()
        body.setStyleSheet(f"background-color: {CINZA_BG};")
        b_lay = QVBoxLayout(body)
        b_lay.setContentsMargins(24, 20, 24, 20)
        b_lay.setSpacing(12)

        # Área de conversa
        self._chat = QTableWidget()
        self._chat.setColumnCount(2)
        self._chat.setHorizontalHeaderLabels(["Você", "Assistente"])
        self._chat.horizontalHeader().setSectionResizeMode(
            0, QHeaderView.ResizeToContents
        )
        self._chat.horizontalHeader().setSectionResizeMode(
            1, QHeaderView.Stretch
        )
        self._chat.verticalHeader().setVisible(False)
        self._chat.setEditTriggers(QTableWidget.NoEditTriggers)
        self._chat.setSelectionBehavior(QTableWidget.SelectRows)
        self._chat.setAlternatingRowColors(True)
        self._chat.setStyleSheet(f"""
            QTableWidget {{
                background-color: #0D1117;
                alternate-background-color: #0f1620;
                color: {TEXTO_CLARO};
                gridline-color: {CINZA_BORDA};
                border: 1px solid {CINZA_BORDA};
                border-radius: 4px;
                font-family: Consolas;
                font-size: 9px;
            }}
            QHeaderView::section {{
                background-color: #0a0f1a;
                color: {TEXTO_OPACO};
                border: none;
                border-bottom: 1px solid {CINZA_BORDA};
                font-size: 8px;
                padding: 2px 4px;
            }}
        """)
        b_lay.addWidget(self._chat, stretch=1)

        # Sugestões rápidas
        lbl_sug = QLabel("Perguntas sugeridas:")
        lbl_sug.setFont(QFont("Segoe UI", 8, QFont.Bold))
        lbl_sug.setStyleSheet(f"color: {TEXTO_OPACO};")
        b_lay.addWidget(lbl_sug)

        h_sug = QHBoxLayout()
        h_sug.setSpacing(6)
        sugestoes = [
            "tempo médio",
            "últimas falhas",
            "contrato mais lento",
            "total de execuções",
            "última execução",
        ]
        for sug in sugestoes:
            btn = QPushButton(sug)
            btn.setFixedHeight(24)
            btn.setStyleSheet(f"""
                QPushButton {{
                    background: {CINZA_CARD};
                    color: {VERDE_NEON};
                    border: 1px solid {CINZA_BORDA};
                    border-radius: 4px;
                    font-size: 8px;
                    font-weight: bold;
                    padding: 0 6px;
                    min-width: 0;
                }}
                QPushButton:hover {{
                    background: {VERDE_PETRO};
                    color: white;
                }}
            """)
            _q = sug
            btn.clicked.connect(lambda checked=False, q=_q: self._perguntar(q))
            h_sug.addWidget(btn)
        h_sug.addStretch()
        b_lay.addLayout(h_sug)

        # Campo de entrada
        h_input = QHBoxLayout()
        h_input.setSpacing(8)

        self._entrada = QLineEdit()
        self._entrada.setPlaceholderText(
            "Digite sua pergunta sobre o histórico..."
        )
        self._entrada.setFixedHeight(32)
        self._entrada.setStyleSheet(f"""
            QLineEdit {{
                background: #0D1117;
                color: {TEXTO_CLARO};
                border: 1px solid {CINZA_BORDA};
                border-radius: 6px;
                padding: 4px 10px;
                font-size: 10px;
            }}
            QLineEdit:focus {{
                border-color: {VERDE_NEON};
            }}
        """)
        self._entrada.returnPressed.connect(self._enviar)

        btn_enviar = QPushButton("Perguntar")
        btn_enviar.setObjectName("btn_verde")
        btn_enviar.setFixedHeight(32)
        btn_enviar.setFixedWidth(100)
        btn_enviar.clicked.connect(self._enviar)

        h_input.addWidget(self._entrada, stretch=1)
        h_input.addWidget(btn_enviar)
        b_lay.addLayout(h_input)

        layout.addWidget(body, stretch=1)

    def _perguntar(self, texto: str):
        self._entrada.setText(texto)
        self._enviar()

    def _enviar(self):
        pergunta = self._entrada.text().strip()
        if not pergunta:
            return
        self._entrada.clear()

        resposta = db_consultar_assistente(pergunta)
        row = self._chat.rowCount()
        self._chat.insertRow(row)
        self._chat.setRowHeight(row, max(40, resposta.count("\n") * 16 + 24))

        item_p = QTableWidgetItem(pergunta)
        item_p.setForeground(QColor(VERDE_NEON))
        item_r = QTableWidgetItem(resposta)
        item_r.setForeground(QColor(TEXTO_CLARO))

        self._chat.setItem(row, 0, item_p)
        self._chat.setItem(row, 1, item_r)
        self._chat.scrollToBottom()

class JanelaPrincipal(QMainWindow):
    """
    Janela principal com sidebar corporativa e QStackedWidget.
    Páginas: Execução | Histórico | Dashboard | Config
    """

    # Índices das páginas no QStackedWidget
    PAG_EXECUCAO     = 0
    PAG_HISTORICO    = 1
    PAG_DASHBOARD    = 2
    PAG_CONFIG       = 3
    PAG_FLUXO        = 4
    PAG_DIAGNOSTICO  = 5


    def __init__(self):
        super().__init__()
        self.setWindowTitle("🤖  Petrobras — Automação SAP + SharePoint")
        self.setMinimumSize(1100, 680)
        self.setWindowFlags(
            Qt.Window |
            Qt.WindowTitleHint |
            Qt.CustomizeWindowHint |
            Qt.WindowMinimizeButtonHint |
            Qt.WindowMaximizeButtonHint |
            Qt.WindowCloseButtonHint
        )
class _TitleBar(QFrame):
    """
    Barra de título customizada com:
    - Gradiente verde → escuro
    - Logo Petrobras vetorial
    - Botões minimizar/maximizar/fechar animados
    - Arrastar para mover a janela
    - Indicador de status da execução
    """

    def __init__(self, janela_pai, parent=None):
        super().__init__(parent)
        self._janela     = janela_pai
        self._drag_pos   = None
        self.setFixedHeight(38)
        self.setStyleSheet(f"""
            QFrame {{
                background: {VERDE_PETRO};
                border-bottom: 1px solid {CINZA_BORDA};
            }}
        """)

        h = QHBoxLayout(self)
        h.setContentsMargins(10, 0, 8, 0)
        h.setSpacing(8)

        # Logo mini
        logo = _LogoPetrobras(tamanho=20)
        h.addWidget(logo, alignment=Qt.AlignVCenter)

        # Título
        self._lbl_titulo = QLabel(
            "Petrobras — Automação SAP + SharePoint"
        )
        self._lbl_titulo.setFont(
            QFont("Segoe UI", 9, QFont.Bold)
        )
        self._lbl_titulo.setStyleSheet(
            "color: white; background: transparent;"
        )
        h.addWidget(self._lbl_titulo)

        # Indicador de status (LED)
        self._lbl_status = QLabel("●")
        self._lbl_status.setFont(QFont("Segoe UI Emoji", 8))
        self._lbl_status.setStyleSheet(
            f"color: {CINZA_BORDA}; background: transparent;"
        )
        h.addWidget(self._lbl_status)

        h.addStretch()

        self._btn_atualizar = _criar_botao_verificar_atualizacao(
            janela_pai, compacto=True
        )
        h.addWidget(self._btn_atualizar)

        # Botões de controle da janela
        _estilos_btn = {
            "min": (
                "─", CINZA_CARD, "#1C2128", BRANCO
            ),
            "max": (
                "□", CINZA_CARD, "#1C2128", BRANCO
            ),
            "close": (
                "✕", CINZA_CARD, COR_ERRO, BRANCO
            ),
        }

        for nome, (icone, bg, bg_hover, fg) in \
                _estilos_btn.items():
            btn = QPushButton(icone)
            btn.setFixedSize(32, 28)
            btn.setStyleSheet(f"""
                QPushButton {{
                    background: {bg};
                    color: {fg};
                    border: none;
                    font-size: 11px;
                    font-weight: bold;
                    border-radius: 2px;
                }}
                QPushButton:hover {{
                    background: {bg_hover};
                }}
            """)
            if nome == "min":
                btn.clicked.connect(
                    janela_pai.showMinimized
                )
            elif nome == "max":
                btn.clicked.connect(self._toggle_max)
            elif nome == "close":
                btn.clicked.connect(janela_pai.close)

            h.addWidget(btn)
            setattr(self, f"_btn_{nome}", btn)

    def _toggle_max(self):
        if self._janela.isMaximized():
            self._janela.showNormal()
            self._btn_max.setText("□")
        else:
            self._janela.showMaximized()
            self._btn_max.setText("❐")

    def set_status(self, estado: str):
        """
        estado: 'aguardando' | 'rodando' | 'concluido' | 'erro'
        """
        _cores = {
            "aguardando": CINZA_BORDA,
            "rodando":    VERDE_NEON,
            "concluido":  COR_SUCESSO,
            "erro":       COR_ERRO,
        }
        cor = _cores.get(estado, CINZA_BORDA)
        self._lbl_status.setStyleSheet(
            f"color: {cor}; background: transparent;"
        )

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self._drag_pos = (
                event.globalPosition().toPoint()
                - self._janela.frameGeometry().topLeft()
            )

    def mouseMoveEvent(self, event):
        if (
            event.buttons() == Qt.LeftButton
            and self._drag_pos is not None
            and not self._janela.isMaximized()
        ):
            self._janela.move(
                event.globalPosition().toPoint()
                - self._drag_pos
            )

    def mouseReleaseEvent(self, event):
        self._drag_pos = None

    def mouseDoubleClickEvent(self, event):
        """Duplo clique maximiza/restaura."""
        if event.button() == Qt.LeftButton:
            self._toggle_max()

        # Widget central
        central = QWidget()
        self.setCentralWidget(central)
        h_main = QHBoxLayout(central)
        h_main.setContentsMargins(0, 0, 0, 0)
        h_main.setSpacing(0)

