    # ── Helpers

    def _secao(self, titulo: str):
        lbl = QLabel(titulo)
        lbl.setFont(QFont("Arial", 9, QFont.Bold))
        lbl.setStyleSheet(
            f"color: {VERDE_NEON}; "
            f"letter-spacing: 1px; padding-top: 6px;"
        )
        self._b_lay.addWidget(lbl)
        sep = QFrame()
        sep.setFrameShape(QFrame.HLine)
        sep.setStyleSheet(f"background: {CINZA_BORDA};")
        self._b_lay.addWidget(sep)

    def _info_row(self, rotulo: str, valor: str):
        h = QHBoxLayout()
        l1 = QLabel(f"{rotulo}:")
        l1.setFont(QFont("Segoe UI", 9, QFont.Bold))
        l1.setStyleSheet(f"color: {TEXTO_OPACO};")
        l1.setFixedWidth(180)
        l2 = QLabel(str(valor))
        l2.setFont(QFont("Consolas", 9))
        l2.setStyleSheet(f"color: {TEXTO_CLARO};")
        l2.setWordWrap(True)
        h.addWidget(l1)
        h.addWidget(l2, stretch=1)
        self._b_lay.addLayout(h)

    def _atualizar_stats_db(self):
        try:
            with _sqlite3.connect(_DB_PATH) as con:
                n_exec   = con.execute(
                    "SELECT COUNT(*) FROM execucoes"
                ).fetchone()[0]
                n_erros  = con.execute(
                    "SELECT COUNT(*) FROM erros"
                ).fetchone()[0]
                n_etapas = con.execute(
                    "SELECT COUNT(*) FROM etapas"
                ).fetchone()[0]
            tam_kb = Path(_DB_PATH).stat().st_size // 1024
            for rotulo, valor, cor in [
                ("Execuções registradas", str(n_exec),   VERDE_PETRO),
                ("Erros registrados",     str(n_erros),
                 COR_ERRO if n_erros > 0 else VERDE_PETRO),
                ("Registros de etapas",   str(n_etapas), TEXTO_CLARO),
                ("Tamanho do banco",      f"{tam_kb} KB", TEXTO_CLARO),
            ]:
                h = QHBoxLayout()
                l1 = QLabel(f"{rotulo}:")
                l1.setFont(QFont("Segoe UI", 9, QFont.Bold))
                l1.setStyleSheet(f"color: {TEXTO_OPACO};")
                l1.setFixedWidth(180)
                l2 = QLabel(str(valor))
                l2.setFont(QFont("Consolas", 10, QFont.Bold))
                l2.setStyleSheet(f"color: {cor};")
                h.addWidget(l1)
                h.addWidget(l2, stretch=1)
                self._b_lay.addLayout(h)
        except Exception as e:
            self._info_row("Status", f"Erro: {e}")

    def _validar_url(self):
        txt = self._campo_url.toPlainText().strip()
        if txt.startswith("https://") and "sharepoint.com" in txt:
            self._lbl_url_status.setText("✅  URL válida")
            self._lbl_url_status.setStyleSheet(
                f"color: {COR_SUCESSO}; font-family: Consolas; font-size: 8px;"
            )
        elif txt:
            self._lbl_url_status.setText("⚠  Verifique a URL — deve começar com https://")
            self._lbl_url_status.setStyleSheet(
                f"color: {COR_ALERTA}; font-family: Consolas; font-size: 8px;"
            )
        else:
            self._lbl_url_status.setText(
                "⚠  URL não configurada — informe antes de iniciar."
            )
            self._lbl_url_status.setStyleSheet(
                f"color: {COR_ALERTA}; font-family: Consolas; font-size: 8px;"
            )

    def _salvar_url(self):
        url = self._campo_url.toPlainText().strip()
        if not url.startswith("https://"):
            toast("URL inválida. Deve começar com https://", "aviso", 3000)
            return
        salvar_config_sharepoint(url)
        toast("URL do SharePoint salva com sucesso ✓", "sucesso", 3000)

    def _escolher_pasta_atualizacao(self):
        from PySide6.QtWidgets import QFileDialog
        atual = self._campo_pasta_atualizacao.text().strip()
        inicio = atual or _caminho_oficial_exibido()
        try:
            p = Path(inicio)
            if p.is_file():
                inicio = str(p.parent)
            elif not p.is_dir():
                inicio = str(p.parent) if p.parent.is_dir() else str(Path.home())
        except Exception:
            inicio = str(Path.home())
        caminho, _filtro = QFileDialog.getOpenFileName(
            self,
            "ZIP da versão oficial",
            inicio,
            "ZIP do aplicativo (*.zip);;Todos (*.*)",
        )
        if caminho:
            self._campo_pasta_atualizacao.setText(caminho)

    def _salvar_pasta_atualizacao(self):
        salvar_pasta_atualizacao(
            self._campo_pasta_atualizacao.text().strip(),
            self._chk_atualizacao_abrir.isChecked(),
        )
        toast("Caminho de atualização salvo ✓", "sucesso", 3000)
        self._atualizar_status_atualizacao()

    def _atualizar_status_atualizacao(self):
        info = _consultar_atualizacao()
        if info.get("tem_nova"):
            self._lbl_status_atualizacao.setText(
                f"Nova versão disponível: v{info.get('versao_remota')} "
                f"(você tem v{info.get('versao_local')})."
            )
            self._lbl_status_atualizacao.setStyleSheet(
                f"color: {AMARELO_PETR}; font-family: Consolas; font-size: 8px;"
            )
        elif info.get("ok"):
            self._lbl_status_atualizacao.setText(
                f"Atualizado — v{info.get('versao_local')}."
            )
            self._lbl_status_atualizacao.setStyleSheet(
                f"color: {COR_SUCESSO}; font-family: Consolas; font-size: 8px;"
            )
        else:
            self._lbl_status_atualizacao.setText(info.get("erro") or "")
            self._lbl_status_atualizacao.setStyleSheet(
                f"color: {TEXTO_OPACO}; font-family: Consolas; font-size: 8px;"
            )

    def _verificar_atualizacao(self):
        self._salvar_pasta_atualizacao()
        _dialogo_atualizacao(self, manual=True)


