    # ── PÁGINA 1 — Contrato SAP + serviços do mês
    def showEvent(self, event):
        super().showEvent(event)
        _aplicar_icone(self)
        QTimer.singleShot(0, lambda: _aplicar_icone(self))
        QTimer.singleShot(400, lambda: _aplicar_icone(self))

    def _criar_pagina_contrato(self):
        pag = QWidget()
        pag.setStyleSheet(f"background-color: {CINZA_BG};")
        v = QVBoxLayout(pag)
        v.setContentsMargins(24, 16, 24, 8)
        v.setSpacing(10)

        lbl_titulo = QLabel("📄  Contrato e Serviços do Mês")
        lbl_titulo.setFont(QFont("Arial Black", 12, QFont.Bold))
        lbl_titulo.setStyleSheet(f"color: {TEXTO_CLARO};")
        v.addWidget(lbl_titulo)

        # Mesmo padrão da página de e-mails (Para/Cópia): o miolo
        # rola na vertical quando a janela é baixa ou há muitas linhas,
        # para os campos de baixo não sobreporem o rodapé.
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.NoFrame)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        scroll.setStyleSheet(
            f"QScrollArea {{ border: none; background: {CINZA_BG}; }}"
        )
        miolo = QWidget()
        miolo.setStyleSheet(f"background-color: {CINZA_BG};")
        v_miolo = QVBoxLayout(miolo)
        v_miolo.setContentsMargins(0, 0, 8, 8)
        v_miolo.setSpacing(10)

        # ── Número do contrato + busca SAP
        h_contrato = QHBoxLayout()
        lbl_c = QLabel("Nº do contrato SAP:")
        lbl_c.setFont(QFont("Segoe UI", 9, QFont.Bold))
        lbl_c.setStyleSheet(f"color: {TEXTO_OPACO};")
        self._campo_contrato = QLineEdit(self._config_sap.get("ultimo_contrato", ""))
        self._campo_contrato.setPlaceholderText("Ex: 4600123456")
        # Assim que sair do campo (Tab/Enter/clique fora), mostra na
        # hora os dados salvos desse contrato, sem precisar clicar em
        # "Buscar dados no SAP".
        self._campo_contrato.editingFinished.connect(self._carregar_cache_contrato)
        self._btn_buscar_sap = QPushButton("🔍  Buscar dados no SAP")
        self._btn_buscar_sap.setObjectName("btn_verde")
        self._btn_buscar_sap.clicked.connect(self._buscar_dados_sap)
        h_contrato.addWidget(lbl_c)
        h_contrato.addWidget(self._campo_contrato, stretch=1)
        h_contrato.addWidget(self._btn_buscar_sap)
        v_miolo.addLayout(h_contrato)

        # ── Resultado da consulta SAP (somente leitura)
        card_sap = QFrame()
        card_sap.setObjectName("card")
        v_sap = QVBoxLayout(card_sap)
        v_sap.setContentsMargins(12, 8, 12, 8)
        self._lbl_sap_status = QLabel("Informe o contrato e clique em Buscar dados no SAP.")
        self._lbl_sap_status.setFont(QFont("Consolas", 8))
        self._lbl_sap_status.setStyleSheet(f"color: {TEXTO_OPACO};")
        self._lbl_sap_status.setWordWrap(True)
        v_sap.addWidget(self._lbl_sap_status)
        v_miolo.addWidget(card_sap)

        # ── Ano / Mês de competência
        h_periodo = QHBoxLayout()
        lbl_ano = QLabel("Ano:")
        lbl_ano.setStyleSheet(f"color: {TEXTO_OPACO};")
        self._spin_ano = QSpinBox()
        self._spin_ano.setRange(2020, 2100)
        self._spin_ano.setValue(datetime.now().year)
        lbl_mes = QLabel("Mês:")
        lbl_mes.setStyleSheet(f"color: {TEXTO_OPACO};")
        self._combo_mes = QComboBox()
        for _n, _nome in MESES_PT.items():
            self._combo_mes.addItem(_nome.capitalize(), _n)
        self._combo_mes.setCurrentIndex(datetime.now().month - 1)
        h_periodo.addWidget(lbl_ano)
        h_periodo.addWidget(self._spin_ano)
        h_periodo.addSpacing(16)
        h_periodo.addWidget(lbl_mes)
        h_periodo.addWidget(self._combo_mes)
        h_periodo.addStretch()
        v_miolo.addLayout(h_periodo)
        self._spin_ano.valueChanged.connect(self._carregar_cache_contrato)
        self._combo_mes.currentIndexChanged.connect(self._carregar_cache_contrato)

        # ── Modo só certidões (CND / CRF / CNDT)
        card_cert = QFrame()
        card_cert.setObjectName("card")
        v_cert = QVBoxLayout(card_cert)
        v_cert.setContentsMargins(12, 10, 12, 10)
        v_cert.setSpacing(6)
        self._chk_so_certidoes = QCheckBox(
            "Baixar apenas certidões (CND, CRF e CNDT)"
        )
        self._chk_so_certidoes.setFont(QFont("Segoe UI", 9, QFont.Bold))
        self._chk_so_certidoes.setStyleSheet(f"color: {TEXTO_CLARO};")
        self._chk_so_certidoes.setToolTip(
            "Pula Pedido, FRS, RM, Espelhos e e-mail.\n"
            "Baixa as três certidões e envia para o SharePoint."
        )
        v_cert.addWidget(self._chk_so_certidoes)
        self._lbl_cert_ajuda = QLabel(
            "Neste modo você informa contrato, ano/mês e o link do SharePoint. "
            "O CNPJ da contratada vem ao clicar em 'Buscar dados no SAP'."
        )
        self._lbl_cert_ajuda.setFont(QFont("Segoe UI", 8))
        self._lbl_cert_ajuda.setStyleSheet(f"color: {TEXTO_OPACO};")
        self._lbl_cert_ajuda.setWordWrap(True)
        v_cert.addWidget(self._lbl_cert_ajuda)
        self._campo_cnpj_cert = None
        self._lbl_cnpj_cert = None
        v_miolo.addWidget(card_cert)
        self._chk_so_certidoes.toggled.connect(self._aplicar_modo_so_certidoes)

        self._lbl_fila = QLabel("")
        self._lbl_fila.setFont(QFont("Segoe UI", 8))
        self._lbl_fila.setStyleSheet(f"color: {AMARELO_PETR};")
        self._lbl_fila.setWordWrap(True)
        v_miolo.addWidget(self._lbl_fila)

        # ── Tabela Pedido / FRS / RM / NL
        self._lbl_servicos = QLabel(
            "Serviços do mês  (1 linha = 1 Pedido + 1 FRS + 1 RM + 1 NL):"
        )
        self._lbl_servicos.setFont(QFont("Segoe UI", 9, QFont.Bold))
        self._lbl_servicos.setStyleSheet(f"color: {TEXTO_OPACO}; padding-top: 6px;")
        v_miolo.addWidget(self._lbl_servicos)

        self._tabela_servicos = QTableWidget(0, 4)
        self._tabela_servicos.setHorizontalHeaderLabels(
            ["Pedido", "FRS", "RM", "NL"]
        )
        self._tabela_servicos.horizontalHeader().setStretchLastSection(True)
        self._tabela_servicos.verticalHeader().setVisible(False)
        # Seleção por linha inteira (não só célula) + múltipla seleção
        # com Ctrl (linhas não seguidas) ou Shift (intervalo seguido) —
        # necessário para excluir várias linhas de uma vez com Delete.
        self._tabela_servicos.setSelectionBehavior(
            QAbstractItemView.SelectRows
        )
        self._tabela_servicos.setSelectionMode(
            QAbstractItemView.ExtendedSelection
        )
        self._tabela_servicos.installEventFilter(self)
        # O Qt entrega o teclado pro "viewport" interno da tabela, não
        # pra tabela em si (é assim que QTableWidget funciona por
        # baixo dos panos) — sem instalar o filtro aqui também, Ctrl+C
        # e Delete nunca disparavam quando a célula só estava
        # selecionada (sem editar). Ver eventFilter() para detalhes.
        self._tabela_servicos.viewport().installEventFilter(self)
        self._tabela_servicos.setItemDelegate(
            _DelegateColarServicos(self)
        )
        # A tabela começa com 0 linhas — sem nenhuma célula pra
        # clicar, o teclado nunca chega a focar a tabela, e o Ctrl+V
        # não tinha pra onde colar. Cria 1 linha vazia de largada e já
        # deixa a primeira célula selecionada, pra colar funcionar
        # assim que a tela abre, sem precisar clicar em "Adicionar
        # linha" antes. _carregar_cache_contrato() substitui essa
        # linha vazia pelos dados salvos, se houver.
        self._tabela_servicos.insertRow(0)
        self._tabela_servicos.setCurrentCell(0, 0)
        self._tabela_servicos.setSizePolicy(
            QSizePolicy.Expanding, QSizePolicy.Minimum
        )
        self._tabela_servicos.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self._tabela_servicos.setMinimumHeight(140)
        v_miolo.addWidget(self._tabela_servicos)

        h_btn_tab = QHBoxLayout()
        btn_add = QPushButton("➕  Adicionar linha")
        btn_add.clicked.connect(
            lambda: self._tabela_servicos.insertRow(self._tabela_servicos.rowCount())
        )
        btn_dup = QPushButton("📋  Duplicar linha")
        btn_dup.clicked.connect(self._duplicar_linha_servico)
        btn_rem = QPushButton("➖  Remover linha")
        btn_rem.setObjectName("btn_cancel")
        btn_rem.clicked.connect(self._remover_linha_servico)
        h_btn_tab.addWidget(btn_add)
        h_btn_tab.addWidget(btn_dup)
