    def _modo_so_certidoes_ativo(self) -> bool:
        chk = getattr(self, "_chk_so_certidoes", None)
        return bool(chk is not None and chk.isChecked())

    def _aplicar_modo_so_certidoes(self, ativo: bool = None):
        if ativo is None:
            ativo = self._modo_so_certidoes_ativo()
        for w in getattr(self, "_widgets_fluxo_completo", []) or []:
            try:
                w.setVisible(not ativo)
            except Exception:
                pass
        for w in getattr(self, "_widgets_email_confirmacao", []) or []:
            try:
                w.setVisible(not ativo)
            except Exception:
                pass
        lbl_conf = getattr(self, "_lbl_titulo_confirmacao", None)
        if lbl_conf is not None:
            lbl_conf.setText(
                "✅  Confirmação — Certidões"
                if ativo
                else "✅  Confirmação Final"
            )
        if ativo:
            self._lbl_cert_ajuda.setText(
                "Modo ativo: informe contrato, ano/mês e o link do SharePoint. "
                "Clique em 'Buscar dados no SAP' — o CNPJ vem junto (ME33K/XK03). "
                "Não há etapa de e-mail."
            )
        else:
            self._lbl_cert_ajuda.setText(
                "Neste modo você informa contrato, ano/mês e o link do SharePoint. "
                "O CNPJ da contratada vem ao clicar em 'Buscar dados no SAP'."
            )
        if getattr(self, "_btn_avancar", None) is not None:
            self._atualizar_botoes()

    def _cnpj_contratada_ui(self) -> str:
        return _so_digitos((self._dados_sap or {}).get("cnpj") or "")

    def _cnpj_sap_certidoes_pronto(self, numero: str) -> bool:
        numero = (numero or "").strip()
        if not numero:
            return False
        return (
            getattr(self, "_contrato_sap_consultado", "") == numero
            and len(self._cnpj_contratada_ui()) == 14
        )

    def _aplicar_resultado_consulta_sap_contrato(
        self, numero: str, dados: dict | None, erro: str = "",
    ) -> bool:
        """Atualiza o painel com o retorno ME33K/XK03. True se CNPJ válido."""
        lbl = getattr(self, "_lbl_sap_status", None)
        if erro:
            if lbl is not None:
                lbl.setText(f"❌  Erro ao consultar SAP: {erro}")
                lbl.setStyleSheet(f"color: {COR_ERRO};")
            self._msg_campo(
                "SAP — CNPJ da contratada",
                f"Não foi possível obter o CNPJ pelo contrato {numero}.\n\n"
                f"{erro}\n\n"
                "Confira se o SAP está aberto em "
                "'02 PEP - S/4HANA Produção (SAP SCRIPT)' e tente de novo.",
            )
            return False

        self._dados_sap = dict(dados or {})
        self._contrato_sap_consultado = numero
        self._dados_sap["_atualizado_em"] = datetime.now().strftime(
            "%d/%m/%Y %H:%M"
        )
        cnpj_ok = self._cnpj_contratada_ui()
        cnpj_txt = _formatar_cnpj(cnpj_ok) if len(cnpj_ok) == 14 else "—"
        if lbl is not None:
            lbl.setText(
                f"✅  Última atualização: {self._dados_sap['_atualizado_em']}  "
                f"(consulta ao vivo)\n"
                f"Empresa: {self._dados_sap.get('empresa', '—')}\n"
                f"CNPJ: {cnpj_txt}   |   "
                f"ICJ: {self._dados_sap.get('icj', '—')}   |   "
                f"Status: {self._dados_sap.get('status_contrato') or '—'}"
            )
            lbl.setStyleSheet(
                f"color: {COR_SUCESSO if len(cnpj_ok) == 14 else COR_ERRO};"
            )

        if len(cnpj_ok) != 14:
            self._msg_campo(
                "CNPJ da contratada",
                f"O SAP abriu o contrato {numero}, mas o CNPJ do fornecedor "
                "não foi lido no XK03.\n\n"
                "Confira o fornecedor no ME33K ou clique em "
                "'Buscar dados no SAP' para tentar de novo.",
            )
            return False
        return True

    def _iniciar_busca_cnpj_sap_certidoes(self, numero: str, ao_sucesso) -> None:
        """
        Consulta ME33K/XK03 em thread — não trava a janela (sem QEventLoop).
        A UI continua responsiva: mover, minimizar, etc.
        """
        numero = (numero or "").strip()
        if not numero:
            return
        if self._cnpj_sap_certidoes_pronto(numero):
            ao_sucesso()
            return
        if getattr(self, "_sap_certidoes_buscando", False):
            return

        self._sap_certidoes_buscando = True
        try:
            self._btn_avancar.setEnabled(False)
        except Exception:
            pass
        try:
            self._btn_buscar_sap.setEnabled(False)
        except Exception:
            pass

        lbl = getattr(self, "_lbl_sap_status", None)
        if lbl is not None:
            lbl.setText(
                "🔄  Consultando SAP (ME33K/XK03) para obter o CNPJ... "
                "você pode minimizar ou usar outras janelas."
            )
            lbl.setStyleSheet(f"color: {AMARELO_PETR};")

        _sap_iniciar_segundo_plano(self)
        resultado_ref: dict = {}
        erro_ref: dict = {}

        def _tarefa():
            try:
                import pythoncom
                pythoncom.CoInitialize()
                try:
                    dados, _sess = executar_sap_retomando(
                        consultar_dados_contrato_sap,
                        numero,
                        contexto="CNPJ da contratada (certidões)",
                        maximizar=False,
                    )
                    resultado_ref["dados"] = dados
                finally:
                    pythoncom.CoUninitialize()
            except Exception as e:
                erro_ref["erro"] = str(e)

        th = threading.Thread(target=_tarefa, daemon=True)
        th.start()

        timer_ant = getattr(self, "_sap_certidoes_timer", None)
        if timer_ant is not None:
            try:
                timer_ant.stop()
            except Exception:
                pass

        _timer = QTimer(self)
        self._sap_certidoes_timer = _timer
        self._sap_certidoes_pulso = 0

        def _checar():
            if th.is_alive():
                self._sap_certidoes_pulso += 1
                if self._sap_certidoes_pulso % 3 == 0:
                    _sap_pulso_visibilidade_app()
                return
            _timer.stop()
            self._sap_certidoes_timer = None
            self._sap_certidoes_buscando = False
            _sap_encerrar_segundo_plano()
            try:
                self._btn_avancar.setEnabled(True)
            except Exception:
                pass
            try:
                self._btn_buscar_sap.setEnabled(True)
            except Exception:
                pass
            ok = self._aplicar_resultado_consulta_sap_contrato(
                numero,
                resultado_ref.get("dados"),
                erro_ref.get("erro") or "",
            )
            if ok:
                ao_sucesso()

        _timer.timeout.connect(_checar)
        _timer.start(200)

    def _continuar_avancar_certidoes(self, numero: str) -> None:
        self._linhas_servico = []
        self._pedidos_materiais = []
        self.numero_contrato_resultado = numero
        salvar_config_contrato(numero)
        if self._reusar_url and (self.url_resultado or "").startswith("https://"):
            self._finalizar_job_atual()
            return
        self._stack.setCurrentIndex(1)
        self._atualizar_botoes()

    def _ajustar_altura_tabelas_contrato(self, *args):
        """
        Faz cada tabela crescer com as linhas, para a barra lateral
        da página (não a da tabela) ser o único scroll.
        """
        for tab, min_h in (
            (getattr(self, "_tabela_servicos", None), 140),
            (getattr(self, "_tabela_materiais", None), 88),
        ):
            if tab is None:
                continue
            n = max(tab.rowCount(), 1)
            header = tab.horizontalHeader().sizeHint().height()
            if header <= 0:
                header = 28
            row_h = tab.verticalHeader().defaultSectionSize()
            if row_h <= 0:
                row_h = 28
            tab.setMinimumHeight(max(min_h, header + n * row_h + 10))

    def _duplicar_linha_servico(self):
        row = self._tabela_servicos.currentRow()
        if row < 0:
            return
        nova = row + 1
        self._tabela_servicos.insertRow(nova)
        for col in range(self._tabela_servicos.columnCount()):
            item_origem = self._tabela_servicos.item(row, col)
            texto = item_origem.text() if item_origem else ""
            self._tabela_servicos.setItem(nova, col, QTableWidgetItem(texto))

    def _remover_linha_servico(self):
        self._excluir_linhas_selecionadas_servicos()

    def _remover_linha_material(self):
        tab = getattr(self, "_tabela_materiais", None)
        if tab is None:
            return
        linhas = sorted(
            {i.row() for i in tab.selectedIndexes()}, reverse=True
        )
        if not linhas:
            row = tab.currentRow()
            if row >= 0:
                tab.removeRow(row)
            return
        for linha in linhas:
            tab.removeRow(linha)
        if tab.rowCount() == 0:
            tab.insertRow(0)

    def _copiar_pedidos_materiais(self):
        tab = getattr(self, "_tabela_materiais", None)
        if tab is None:
            return
        indices = tab.selectedIndexes()
        if indices:
            linhas = sorted({indice.row() for indice in indices})
        else:
            linha_atual = tab.currentRow()
            if linha_atual < 0:
                return
            linhas = [linha_atual]
        valores = []
        for linha in linhas:
            item = tab.item(linha, 0)
            valores.append(item.text() if item else "")
        _definir_clipboard_texto("\n".join(valores))

    def _colar_pedidos_materiais(self):
        """
        Igual à tabela de serviços: cola a partir da célula atual e
        cria linhas novas embaixo se o que veio do Excel/Ctrl+C tiver
        mais linhas do que a tabela.
        """
        tab = getattr(self, "_tabela_materiais", None)
        if tab is None:
            return
        texto = _ler_clipboard_texto()
        if not texto.strip():
            return
        linhas = texto.replace("\r\n", "\n").replace("\r", "\n").split("\n")
        if linhas and linhas[-1] == "":
            linhas.pop()
        linha_inicial = tab.currentRow()
        if linha_inicial < 0:
            linha_inicial = 0
        for i, linha_txt in enumerate(linhas):
            valor = linha_txt.split("\t")[0].strip()
            dest = linha_inicial + i
            if dest >= tab.rowCount():
                tab.insertRow(tab.rowCount())
            tab.setItem(dest, 0, QTableWidgetItem(valor))

    def _capturar_pedidos_materiais(self) -> list:
        tab = getattr(self, "_tabela_materiais", None)
        if tab is None:
            return []
        nums = []
        for row in range(tab.rowCount()):
            it = tab.item(row, 0)
            t = it.text().strip() if it else ""
            if t:
                nums.append(t)
        return list(dict.fromkeys(nums))

    def _tabela_materiais_vazia(self) -> bool:
        tab = getattr(self, "_tabela_materiais", None)
        if tab is None or tab.rowCount() <= 0:
            return True
        if tab.rowCount() == 1:
            it = tab.item(0, 0)
            return not (it and it.text().strip())
        return False

    def _persistir_tabelas_periodo_atual(self, linhas=None, pedidos_mat=None):
        """Grava Pedido/FRS/RM/NL e pedidos de material deste contrato+mês."""
        numero = (
            (self._campo_contrato.text() or "").strip()
            or (getattr(self, "numero_contrato_resultado", "") or "")
        )
        if not numero:
            return
        if linhas is None:
            linhas = self._capturar_linhas_tabela_servicos()
        if pedidos_mat is None:
            pedidos_mat = self._capturar_pedidos_materiais()
        ano = self._spin_ano.value()
        mes = self._combo_mes.currentData()
        salvo = carregar_dados_contrato_salvo(numero, ano, mes) or {}
        campo_url = getattr(self, "_campo_url", None)
        url_txt = campo_url.toPlainText().strip() if campo_url is not None else ""
        campo_email = getattr(self, "_campo_email_gerente", None)
        email_g = campo_email.text().strip() if campo_email is not None else ""
        campo_nome = getattr(self, "_campo_nome_preposta", None)
        nome_prep = campo_nome.text().strip() if campo_nome is not None else ""
        emails_para = self._emails_da_lista(
            getattr(self, "_lista_emails_para", None)
        )
        emails_cc = self._emails_da_lista(
            getattr(self, "_lista_emails_cc", None)
        )
        salvar_dados_contrato(
            numero,
            linhas,
            emails_para or list(salvo.get("emails_extra") or []),
            email_g or (salvo.get("email_gerente") or ""),
            getattr(self, "_dados_sap", None) or salvo.get("dados_sap"),
            ano=ano,
            mes=mes,
            url_sharepoint=(
                url_txt
                or (salvo.get("url_sharepoint") or "")
                or (getattr(self, "url_resultado", "") or "")
            ),
            emails_cc_extra=emails_cc or list(salvo.get("emails_cc_extra") or []),
            preposta_nome=nome_prep or (salvo.get("preposta_nome") or ""),
            pedidos_materiais=list(pedidos_mat or []),
        )

    def _preencher_tabela_materiais(self, numeros: list):
        tab = getattr(self, "_tabela_materiais", None)
        if tab is None:
            return
        tab.setRowCount(0)
        for num in numeros or []:
            if not str(num).strip():
                continue
            row = tab.rowCount()
            tab.insertRow(row)
            tab.setItem(row, 0, QTableWidgetItem(str(num).strip()))
        if tab.rowCount() == 0:
            tab.insertRow(0)

    def _extrair_servicos_sap(self):
        th = getattr(self, "_th_extrair", None)
        if th is not None and th.isRunning():
            return
        numero = self._campo_contrato.text().strip()
        if not numero:
            self._msg_campo("Contrato", "Digite o número do contrato.")
            self._campo_contrato.setFocus()
            return
        ano = self._spin_ano.value()
        mes = self._combo_mes.currentData()
        existentes = self._capturar_linhas_tabela_servicos()
        rms_conhecidos = []
        vistos_rm = set()
        for lin in existentes:
            rm = str(lin.get("rm") or "").strip()
            if rm and rm not in vistos_rm:
                vistos_rm.add(rm)
                rms_conhecidos.append(rm)
        if existentes:
            r = QMessageBox.question(
                self,
                "Extrair dados do SAP",
                "A tabela de serviços já tem linhas.\n\n"
                "Substituir pelos dados extraídos do SAP?",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if r != QMessageBox.Yes:
                return
        dlg = _DialogoAguardarExtracao(
            numero, f"{mes:02d}/{ano}", self
        )
        dlg.show()
        dlg.raise_()
        QApplication.processEvents()
        self._dlg_extrair = dlg
        _sap_iniciar_segundo_plano(self, dlg)
        self.raise_()
        dlg.raise_()
        btn = getattr(self, "_btn_extrair_sap", None)
        if btn is not None:
            btn.setEnabled(False)

        th = _ThreadExtrairYsx(numero, str(ano), str(mes), rms_conhecidos, self)
        th.ok.connect(self._on_extracao_ok)
        th.erro.connect(self._on_extracao_erro)
        self._th_extrair = th
        th.start()

        tv = getattr(self, "_sap_extrair_vis_timer", None)
        if tv is not None:
            try:
                tv.stop()
            except Exception:
                pass
        tv = QTimer(self)
        self._sap_extrair_vis_timer = tv

        def _pulso_extrair():
            if th.isRunning():
                _sap_pulso_visibilidade_app()
                return
            tv.stop()
            self._sap_extrair_vis_timer = None

        tv.timeout.connect(_pulso_extrair)
        tv.start(500)

    def _encerrar_dlg_extrair(self):
        tv = getattr(self, "_sap_extrair_vis_timer", None)
        if tv is not None:
            try:
                tv.stop()
            except Exception:
                pass
            self._sap_extrair_vis_timer = None
        _sap_encerrar_segundo_plano()
        dlg = getattr(self, "_dlg_extrair", None)
        self._dlg_extrair = None
        if dlg is not None:
            try:
                dlg.close()
                dlg.deleteLater()
            except Exception:
                pass
        btn = getattr(self, "_btn_extrair_sap", None)
        if btn is not None:
            btn.setEnabled(True)

    def _on_extracao_erro(self, msg: str):
        self._encerrar_dlg_extrair()
        self._msg_campo(
            "Falha na extração",
            "Não foi possível extrair os dados do SAP.\n\n"
            f"{msg}\n\nDeixe o SAP logado (SCRIPT) e tente de novo.",
        )

    def _on_extracao_ok(self, dados):
        dados = dados or {}
        linhas_brutas = dados.get("linhas") or []
        cancelados = list(dados.get("rms_cancelados") or [])
        linhas = []
        for l in linhas_brutas:
            linhas.append(
                {
                    "pedido": l.get("pedido") or "",
                    "frs": l.get("frs") or "",
                    "rm": l.get("rm") or "",
                    "nl": l.get("nl") or "",
                }
            )
        dlg = getattr(self, "_dlg_extrair", None)
        n_ped = len({x["pedido"] for x in linhas if x.get("pedido")})
        n_frs = len({x["frs"] for x in linhas if x.get("frs")})
        n_rm = len({x["rm"] for x in linhas if x.get("rm")})
        n_nl = len({x["nl"] for x in linhas if x.get("nl")})
        dur_txt = ""
        if dlg is not None and hasattr(dlg, "concluir"):
            try:
                dlg.concluir(n_ped, n_frs, n_rm, n_nl, cancelados)
                if hasattr(dlg, "duracao_segundos"):
                    s = int(dlg.duracao_segundos())
                    dur_txt = (
                        f"{s // 60}m {s % 60}s" if s >= 60 else f"{s}s"
                    )
                QApplication.processEvents()
            except Exception:
                pass
        if not linhas:
            extra_canc = ""
            if cancelados:
                extra_canc = (
                    "\n\nRM(s) cancelado(s): " + ", ".join(cancelados)
                )
            self._encerrar_dlg_extrair()
            self._msg_campo(
                "Nenhum dado",
                "O SAP não devolveu Pedido/FRS/RM/NL para este "
                "contrato e mês. Confira o período ou preencha à mão."
                + extra_canc,
            )
            return
        self._tabela_servicos.setRowCount(0)
        for l in linhas:
            row = self._tabela_servicos.rowCount()
            self._tabela_servicos.insertRow(row)
            for col, chave in enumerate(["pedido", "frs", "rm", "nl"]):
                self._tabela_servicos.setItem(
                    row, col, QTableWidgetItem(l.get(chave) or "")
                )
        self._tabela_servicos.setCurrentCell(0, 0)
        try:
            self._persistir_tabelas_periodo_atual(
                linhas=[
                    {
                        "pedido": l.get("pedido") or "",
                        "frs": l.get("frs") or "",
                        "rm": l.get("rm") or "",
                        "nl": l.get("nl") or "",
                        "centro": "",
                    }
                    for l in linhas
                ]
            )
        except Exception:
            pass
        extra_canc = ""
        if cancelados:
            extra_canc = (
                "\n\nRM(s) cancelado(s): " + ", ".join(cancelados)
            )
        resumo = (
            "Extração concluída com sucesso.\n\n"
            f"Tempo total: {dur_txt or '—'}\n"
            f"Pedidos : {n_ped}\n"
            f"FRS     : {n_frs}\n"
            f"RM      : {n_rm}\n"
            f"NL      : {n_nl}"
            f"{extra_canc}\n\n"
            "Os dados já foram preenchidos na tabela de serviços."
        )
        self._encerrar_dlg_extrair()
        self.raise_()
        self.activateWindow()
        QMessageBox.information(self, "Extração concluída", resumo)

    def _excluir_linhas_selecionadas_servicos(self):
        """
        Remove todas as linhas com QUALQUER célula selecionada —
        funciona tanto para linhas seguidas (Shift+clique) quanto
        para linhas espalhadas (Ctrl+clique). Remove de trás para
        frente para os índices das linhas não mudarem no meio da
        exclusão.
        """
        linhas = sorted(
            {indice.row() for indice in self._tabela_servicos.selectedIndexes()},
            reverse=True,
        )
        if not linhas:
            # Nada selecionado — mantém o comportamento antigo do
            # botão "Remover linha": remove a linha atual, se houver.
            row = self._tabela_servicos.currentRow()
            if row >= 0:
                self._tabela_servicos.removeRow(row)
            return
        for linha in linhas:
            self._tabela_servicos.removeRow(linha)

    def eventFilter(self, obj, event):
        """
        Captura o Ctrl+C (copia células selecionadas), o Ctrl+V (cola
        em massa) e a tecla Delete (exclui linhas selecionadas) na
        tabela de serviços.

        Com uma célula só selecionada (sem entrar em edição), o Qt
        entrega o evento de teclado pro "viewport" interno da tabela,
        não pra tabela (self._tabela_servicos) em si — por isso o
        filtro precisa estar instalado nos dois (ver o `__init__` da
        página de serviços). `obj` pode ser a tabela, o viewport dela,
        ou o editor de uma célula específica (instalado via
        _DelegateColarServicos.createEditor) — os três casos são
        tratados da mesma forma para o Ctrl+V, por isso não precisa
        checar `obj` nesse caso.

        Já o Ctrl+C e o Delete, na tabela/viewport (célula só
        selecionada), copiam/apagam a linha. Se a célula ESTIVER em
        edição, Ctrl+C/V do texto interno NÃO são interceptados —
        senão o modelo antigo (ou o clipboard de fora) ia no lugar
        do que a pessoa copiou dentro do Pedido/FRS/RM/NL/Centro.
        Colar em massa (várias linhas/colunas, TAB) continua
        interceptado também no editor.
        """
        from PySide6.QtCore import QEvent
        from PySide6.QtGui import QKeySequence
        if event.type() == QEvent.Wheel:
            scroll = getattr(self, "_scroll_pagina_contrato", None)
            alvos = []
            for _nome in ("_tabela_servicos", "_tabela_materiais"):
                _tab = getattr(self, _nome, None)
                if _tab is not None:
                    alvos.extend((_tab, _tab.viewport()))
            if scroll is not None and obj in alvos:
                barra = scroll.verticalScrollBar()
                barra.setValue(barra.value() - event.angleDelta().y())
                return True
        if event.type() == QEvent.KeyPress and event.key() in (
            Qt.Key_Delete, Qt.Key_Backspace
        ):
            for _attr in ("_lista_emails_para", "_lista_emails_cc"):
                _lst = getattr(self, _attr, None)
                if _lst is not None and obj in (_lst, _lst.viewport()):
                    self._excluir_emails_lista(_lst)
                    return True
        tab_m = getattr(self, "_tabela_materiais", None)
        if tab_m is not None and event.type() == QEvent.KeyPress:
            alvo_mat = obj in (tab_m, tab_m.viewport())
            w_mat = QApplication.focusWidget()
            foco_mat = False
            while w_mat is not None:
                if w_mat is tab_m or w_mat is tab_m.viewport():
                    foco_mat = True
                    break
                try:
                    w_mat = w_mat.parentWidget()
                except Exception:
                    break
            if alvo_mat or foco_mat:
                editor_mat = not alvo_mat
                if event.matches(QKeySequence.Copy):
                    if editor_mat:
                        return False
                    self._copiar_pedidos_materiais()
                    return True
                if event.matches(QKeySequence.Paste):
                    texto_clip = _ler_clipboard_texto()
                    eh_planilha = (
                        "\t" in texto_clip
                        or "\n" in texto_clip.replace("\r", "").strip()
                    )
                    if editor_mat and not eh_planilha:
                        return False
                    self._colar_pedidos_materiais()
                    return True
                if alvo_mat and event.key() == Qt.Key_Delete:
                    self._remover_linha_material()
                    return True
        alvo_tabela = obj in (
            self._tabela_servicos,
            self._tabela_servicos.viewport(),
        )
        w = QApplication.focusWidget()
        foco_tabela = False
        while w is not None:
            if w is self._tabela_servicos or w is self._tabela_servicos.viewport():
                foco_tabela = True
                break
            try:
                w = w.parentWidget()
            except Exception:
                break
        if not (alvo_tabela or foco_tabela):
            return super().eventFilter(obj, event)
        editor_ativo = not alvo_tabela
        if event.type() == QEvent.KeyPress:
            if event.matches(QKeySequence.Copy):
                if editor_ativo:
                    return False
                self._copiar_dados_servicos()
                return True
            if event.matches(QKeySequence.Paste):
                texto_clip = _ler_clipboard_texto()
                eh_planilha = (
                    "\t" in texto_clip
                    or "\n" in texto_clip.replace("\r", "").strip()
                )
                if editor_ativo and not eh_planilha:
                    return False
                self._colar_dados_servicos()
                return True
            if alvo_tabela and event.key() == Qt.Key_Delete:
                self._excluir_linhas_selecionadas_servicos()
                return True
        return super().eventFilter(obj, event)

    def _copiar_dados_servicos(self):
        """
        Copia as células selecionadas da tabela de serviços para a
        área de transferência, no mesmo formato de planilha (colunas
        separadas por TAB, linhas separadas por quebra de linha) que
        _colar_dados_servicos() já sabe interpretar — permite copiar
        de uma linha e colar em outra dentro da própria tabela, igual
        um Ctrl+C/Ctrl+V de Excel.

        Se a tabela não reportar nenhuma célula "selecionada" no
        momento exato do Ctrl+C (às vezes acontece dependendo de como
        a célula foi clicada), cai pra célula ATUAL
        (currentRow/currentColumn) em vez de desistir — sem isso, um
        Ctrl+C "silencioso" deixava a área de transferência com o
        valor antigo (de fora), e o Ctrl+V colava esse valor errado
        sem avisar nada.
        """
        indices = self._tabela_servicos.selectedIndexes()
        if indices:
            linhas = sorted({indice.row() for indice in indices})
            colunas = sorted({indice.column() for indice in indices})
        else:
            linha_atual = self._tabela_servicos.currentRow()
            coluna_atual = self._tabela_servicos.currentColumn()
            if linha_atual < 0 or coluna_atual < 0:
                print(
                    "⚠ Ctrl+C: nenhuma célula selecionada/atual — "
                    "nada foi copiado."
                )
                return
            linhas = [linha_atual]
            colunas = [coluna_atual]
        linhas_texto = []
        for linha in linhas:
            valores = []
            for coluna in colunas:
                item = self._tabela_servicos.item(linha, coluna)
                valores.append(item.text() if item else "")
            linhas_texto.append("\t".join(valores))
        texto_copiado = "\n".join(linhas_texto)
        _definir_clipboard_texto(texto_copiado)
        print(f"📋 Ctrl+C na tabela — copiado: {texto_copiado!r}")

    def _colar_dados_servicos(self):
        """
        Cola dados copiados do Excel (ou de texto separado por
        TAB/quebra de linha) na tabela de serviços, a partir da
        célula selecionada — na vertical (várias linhas, 1 coluna),
        na horizontal (1 linha, várias colunas) ou em bloco (várias
        linhas × várias colunas), como um Ctrl+V normal de planilha.
        Cria linhas novas na tabela automaticamente se precisar.
        """
        texto = _ler_clipboard_texto()
        if not texto.strip():
            print("⚠ Ctrl+V: área de transferência vazia — nada colado.")
            return
        print(f"📋 Ctrl+V na tabela — colando: {texto!r}")

        linha_inicial = self._tabela_servicos.currentRow()
        coluna_inicial = self._tabela_servicos.currentColumn()
        if linha_inicial < 0:
            linha_inicial = 0
        if coluna_inicial < 0:
            coluna_inicial = 0

        linhas = texto.replace("\r\n", "\n").replace("\r", "\n").split("\n")
        # Remove a última linha vazia (comum ao copiar do Excel)
        if linhas and linhas[-1] == "":
            linhas.pop()

        n_colunas = self._tabela_servicos.columnCount()

        for i, linha_txt in enumerate(linhas):
            valores = linha_txt.split("\t")
            linha_destino = linha_inicial + i
            if linha_destino >= self._tabela_servicos.rowCount():
                self._tabela_servicos.insertRow(
                    self._tabela_servicos.rowCount()
                )
            for j, valor in enumerate(valores):
                coluna_destino = coluna_inicial + j
                if coluna_destino >= n_colunas:
                    break
                self._tabela_servicos.setItem(
                    linha_destino, coluna_destino,
                    QTableWidgetItem(valor.strip())
                )

    def _capturar_linhas_tabela_servicos(self) -> list:
        linhas = []
        for row in range(self._tabela_servicos.rowCount()):
            def _txt(col, _row=row):
                it = self._tabela_servicos.item(_row, col)
                return it.text().strip() if it else ""
            pedido, frs, rm, nl = (
                _txt(0), _txt(1), _txt(2), _txt(3)
            )
            if not any([pedido, frs, rm, nl]):
                continue
            linhas.append(
                {"pedido": pedido, "frs": frs, "rm": rm, "nl": nl, "centro": ""}
            )
        return linhas

    def _limpar_dados_do_contrato_na_ui(self, manter_url=True):
        """Zera e-mails/nome deste contrato. O link do SharePoint pode ficar."""
        self._fiscais_extra = []
        self._emails_cc_extra = []
        self._preencher_lista_emails(getattr(self, "_lista_emails_para", None), [])
        self._preencher_lista_emails(getattr(self, "_lista_emails_cc", None), [])
        campo_para = getattr(self, "_campo_emails_para", None)
        if campo_para is not None:
            campo_para.clear()
        campo_cc = getattr(self, "_campo_email_extra", None)
        if campo_cc is not None:
            campo_cc.clear()
        campo_nome = getattr(self, "_campo_nome_preposta", None)
        if campo_nome is not None:
            campo_nome.clear()
        campo_ger = getattr(self, "_campo_email_gerente", None)
        if campo_ger is not None:
            campo_ger.clear()
        self._dados_sap = {}
        self._contrato_sap_consultado = ""
        lbl = getattr(self, "_lbl_sap_status", None)
        if lbl is not None:
            lbl.setText("Informe o contrato e clique em Buscar dados no SAP.")
            lbl.setStyleSheet(f"color: {TEXTO_OPACO};")
        if not manter_url:
            campo_url = getattr(self, "_campo_url", None)
            if campo_url is not None:
                campo_url.clear()
            self.url_resultado = ""

    def _carregar_cache_contrato(self):
        """
        Mostra na hora os últimos dados salvos deste contrato
        (Empresa/ICJ/Gerente/Fiscais/Status e o e-mail do gerente), sem
        esperar uma consulta ao SAP. "Buscar dados no SAP" continua
        disponível para atualizar com uma consulta ao vivo quando quiser.
        """
        numero = self._campo_contrato.text().strip()
        if not numero:
            return
        ano_ui = self._spin_ano.value()
        mes_ui = self._combo_mes.currentData()
        chave_ui = f"{numero}|{ano_ui}|{mes_ui}"
        chave_ant = getattr(self, "_chave_cache_ui", None)
        if chave_ant and chave_ant != chave_ui:
            partes = str(chave_ant).split("|")
            if len(partes) == 3:
                try:
                    num_ant = partes[0]
                    linhas_ant = self._capturar_linhas_tabela_servicos()
                    campo_url = getattr(self, "_campo_url", None)
                    url_txt = ""
                    if campo_url is not None:
                        url_txt = campo_url.toPlainText().strip()
                    campo_email = getattr(self, "_campo_email_gerente", None)
                    email_g = campo_email.text().strip() if campo_email is not None else ""
                    campo_nome = getattr(self, "_campo_nome_preposta", None)
                    nome_prep = campo_nome.text().strip() if campo_nome is not None else ""
                    emails_para_ui = self._emails_da_lista(
                        getattr(self, "_lista_emails_para", None)
                    ) or list(getattr(self, "_fiscais_extra", []) or [])
                    emails_cc_ui = self._emails_da_lista(
                        getattr(self, "_lista_emails_cc", None)
                    ) or list(getattr(self, "_emails_cc_extra", []) or [])
                    salvar_dados_contrato(
                        num_ant,
                        linhas_ant,
                        emails_para_ui,
                        email_g,
                        getattr(self, "_dados_sap", None),
                        ano=int(partes[1]),
                        mes=int(partes[2]),
                        url_sharepoint=url_txt or (getattr(self, "url_resultado", "") or ""),
                        emails_cc_extra=emails_cc_ui,
                        preposta_nome=nome_prep,
                        pedidos_materiais=self._capturar_pedidos_materiais(),
                    )
                except Exception:
                    pass
        mudou_contexto = chave_ant != chave_ui
        mudou_contrato_num = bool(
            chave_ant and str(chave_ant).split("|")[0] != numero
        )
        if mudou_contexto:
            self._chave_cache_ui = chave_ui
        if mudou_contrato_num:
            self._limpar_dados_do_contrato_na_ui(manter_url=True)
        salvo = carregar_dados_contrato_salvo(numero, ano_ui, mes_ui)
        if not salvo:
            if mudou_contexto:
                self._tabela_servicos.setRowCount(0)
                self._tabela_servicos.insertRow(0)
                self._tabela_servicos.setCurrentCell(0, 0)
                self._preencher_tabela_materiais([])
                self._limpar_dados_do_contrato_na_ui(manter_url=True)
            return

        dados_sap_salvo = salvo.get("dados_sap") or {}
        if dados_sap_salvo:
            self._dados_sap = dados_sap_salvo
            cnpj_cache = _so_digitos(dados_sap_salvo.get("cnpj") or "")
            if len(cnpj_cache) == 14:
                self._contrato_sap_consultado = numero
            _atualizado_em = dados_sap_salvo.get("_atualizado_em", "—")
            cnpj_txt = _formatar_cnpj(cnpj_cache) if len(cnpj_cache) == 14 else "—"
            self._lbl_sap_status.setText(
                f"📦  Última atualização: {_atualizado_em}  "
                f"(clique em '🔍 Buscar dados no SAP' para atualizar)\n"
                f"Empresa: {dados_sap_salvo.get('empresa', '—')}\n"
                f"CNPJ: {cnpj_txt}   |   "
                f"ICJ: {dados_sap_salvo.get('icj', '—')}   |   "
                f"Gerente: {dados_sap_salvo.get('gerente', '—')}   |   "
                f"Fiscais: {', '.join(dados_sap_salvo.get('fiscais', [])) or '—'}   |   "
                f"Status: {dados_sap_salvo.get('status_contrato') or '—'}"
            )
            self._lbl_sap_status.setStyleSheet(f"color: {TEXTO_CLARO};")

        _tabela_vazia = self._tabela_servicos.rowCount() == 0 or (
            self._tabela_servicos.rowCount() == 1
            and not any(
                (self._tabela_servicos.item(0, col) or QTableWidgetItem()).text().strip()
                for col in range(self._tabela_servicos.columnCount())
            )
        )
        if (mudou_contexto or _tabela_vazia) and salvo.get("linhas"):
            self._tabela_servicos.setRowCount(0)
            for linha in salvo.get("linhas", []):
                row = self._tabela_servicos.rowCount()
                self._tabela_servicos.insertRow(row)
                for col, chave in enumerate(
                    ["pedido", "frs", "rm", "nl"]
                ):
                    self._tabela_servicos.setItem(
                        row, col, QTableWidgetItem(linha.get(chave, ""))
                    )
        elif mudou_contexto and not salvo.get("linhas"):
            self._tabela_servicos.setRowCount(0)
            self._tabela_servicos.insertRow(0)

        if mudou_contexto or self._tabela_materiais_vazia():
            self._preencher_tabela_materiais(salvo.get("pedidos_materiais") or [])

        if mudou_contexto:
            self._fiscais_extra = list(salvo.get("emails_extra") or [])
            self._emails_cc_extra = list(salvo.get("emails_cc_extra") or [])
        else:
            for email in salvo.get("emails_extra", []):
                if email not in self._fiscais_extra:
                    self._fiscais_extra.append(email)
            for email in salvo.get("emails_cc_extra", []):
                if email not in self._emails_cc_extra:
                    self._emails_cc_extra.append(email)
        self._preencher_lista_emails(
            getattr(self, "_lista_emails_para", None),
            self._fiscais_extra,
        )
        self._preencher_lista_emails(
            getattr(self, "_lista_emails_cc", None),
            self._emails_cc_extra,
        )
        campo_nome = getattr(self, "_campo_nome_preposta", None)
        nome_salvo = (salvo.get("preposta_nome") or "").strip()
        if campo_nome is not None and (
            mudou_contexto or mudou_contrato_num or not campo_nome.text().strip()
        ):
            campo_nome.setText(nome_salvo)

        email_gerente_salvo = salvo.get("email_gerente", "")
        campo_email = getattr(self, "_campo_email_gerente", None)
        if (
            campo_email is not None
            and email_gerente_salvo
            and (mudou_contexto or not campo_email.text().strip())
        ):
            campo_email.setText(email_gerente_salvo)

        url_salva_c = (salvo.get("url_sharepoint") or "").strip()
        campo_url = getattr(self, "_campo_url", None)
        if campo_url is not None and url_salva_c and (
            mudou_contexto or not campo_url.toPlainText().strip()
        ):
            campo_url.setPlainText(url_salva_c)
            self.url_resultado = url_salva_c

        if self._tabela_servicos.rowCount() == 0:
            self._tabela_servicos.insertRow(0)
        self._tabela_servicos.setCurrentCell(0, 0)

        self._atualizar_botoes()

    def _buscar_dados_sap(self):
        numero = self._campo_contrato.text().strip()
        if not numero:
            toast("Informe o número do contrato antes de buscar.", "aviso", 3000)
            return
        self._btn_buscar_sap.setEnabled(False)
        self._lbl_sap_status.setText("🔄  Consultando SAP... aguarde.")
        self._lbl_sap_status.setStyleSheet(f"color: {AMARELO_PETR};")
        _sap_iniciar_segundo_plano(self)

        resultado_ref = {}
        erro_ref = {}

        def _tarefa():
            try:
                import pythoncom
                pythoncom.CoInitialize()
                try:
                    dados, _sess = executar_sap_retomando(
                        consultar_dados_contrato_sap,
                        numero,
                        contexto="consulta do contrato",
                        maximizar=False,
                    )
                    resultado_ref["dados"] = dados
                finally:
                    pythoncom.CoUninitialize()
            except Exception as e:
                erro_ref["erro"] = str(e)

        th = threading.Thread(target=_tarefa, daemon=True)
        th.start()

        _timer = QTimer(self)
        self._sap_busca_pulso = 0

        def _checar():
            if th.is_alive():
                self._sap_busca_pulso += 1
                if self._sap_busca_pulso % 3 == 0:
                    _sap_pulso_visibilidade_app()
                return
            _timer.stop()
            _sap_encerrar_segundo_plano()
            self._btn_buscar_sap.setEnabled(True)
            if erro_ref.get("erro"):
                self._lbl_sap_status.setText(f"❌  Erro ao consultar SAP: {erro_ref['erro']}")
                self._lbl_sap_status.setStyleSheet(f"color: {COR_ERRO};")
                return
            self._dados_sap = resultado_ref.get("dados", {})
            self._contrato_sap_consultado = numero
            self._dados_sap["_atualizado_em"] = datetime.now().strftime("%d/%m/%Y %H:%M")
            cnpj_sap = _so_digitos(self._dados_sap.get("cnpj") or "")
            cnpj_txt = _formatar_cnpj(cnpj_sap) if len(cnpj_sap) == 14 else "—"
            self._lbl_sap_status.setText(
                f"✅  Última atualização: {self._dados_sap['_atualizado_em']}  (consulta ao vivo)\n"
                f"Empresa: {self._dados_sap.get('empresa', '—')}\n"
                f"CNPJ: {cnpj_txt}   |   "
                f"ICJ: {self._dados_sap.get('icj', '—')}   |   "
                f"Gerente: {self._dados_sap.get('gerente', '—')}   |   "
                f"Fiscais: {', '.join(self._dados_sap.get('fiscais', [])) or '—'}   |   "
                f"Status: {self._dados_sap.get('status_contrato') or '—'}"
            )
            self._lbl_sap_status.setStyleSheet(f"color: {COR_SUCESSO};")

            # Pré-preenche com o que foi salvo da última vez que esse
            # contrato foi usado (só se a tabela ainda estiver vazia, pra
            # não sobrescrever o que você já digitou nesta sessão).
            if self._tabela_servicos.rowCount() == 0:
                salvo = carregar_dados_contrato_salvo(
                    numero,
                    self._spin_ano.value(),
                    self._combo_mes.currentData(),
                )
                for linha in salvo.get("linhas", []):
                    row = self._tabela_servicos.rowCount()
                    self._tabela_servicos.insertRow(row)
                    for col, chave in enumerate(
                        ["pedido", "frs", "rm", "nl", "centro"]
                    ):
                        self._tabela_servicos.setItem(
                            row, col, QTableWidgetItem(linha.get(chave, ""))
                        )
                for email in salvo.get("emails_extra", []):
                    if email not in self._fiscais_extra:
                        self._fiscais_extra.append(email)
                for email in salvo.get("emails_cc_extra", []):
                    if email not in getattr(self, "_emails_cc_extra", []):
                        self._emails_cc_extra.append(email)
                self._preencher_lista_emails(
                    getattr(self, "_lista_emails_para", None),
                    self._fiscais_extra,
                )
                self._preencher_lista_emails(
                    getattr(self, "_lista_emails_cc", None),
                    getattr(self, "_emails_cc_extra", []),
                )
                _email_gerente_salvo = salvo.get("email_gerente", "")
                if _email_gerente_salvo and not self._campo_email_gerente.text().strip():
                    self._campo_email_gerente.setText(_email_gerente_salvo)
                _nome_prep = (salvo.get("preposta_nome") or "").strip()
                campo_nome = getattr(self, "_campo_nome_preposta", None)
                if campo_nome is not None and _nome_prep and not campo_nome.text().strip():
                    campo_nome.setText(_nome_prep)
                if salvo.get("linhas") or salvo.get("emails_extra") or _email_gerente_salvo:
                    toast(
                        "E-mails salvos deste contrato foram carregados "
                        "(Gerente + Apoios/Contratada). Quer alterar algo? "
                        "Edite na tela de confirmação antes de avançar.",
                        "info", 6000
                    )
            if self._tabela_materiais_vazia():
                _salvo_mat = carregar_dados_contrato_salvo(
                    numero,
                    self._spin_ano.value(),
                    self._combo_mes.currentData(),
                )
                self._preencher_tabela_materiais(
                    _salvo_mat.get("pedidos_materiais") or []
                )

            self._atualizar_botoes()

        _timer.timeout.connect(_checar)
        _timer.start(300)

