    def _criar_bloco_lista_emails(self, placeholder: str):
        campo = QPlainTextEdit()
        campo.setPlaceholderText(placeholder)
        campo.setMinimumHeight(72)
        campo.setMaximumHeight(110)
        lista = QListWidget()
        lista.setMinimumHeight(72)
        lista.setSelectionMode(QAbstractItemView.ExtendedSelection)
        lista.setToolTip("Selecione um ou mais e-mails e clique em Excluir, ou pressione Delete.")
        lista.installEventFilter(self)
        lista.viewport().installEventFilter(self)
        h = QHBoxLayout()
        h.setContentsMargins(0, 0, 0, 0)
        btn_add = QPushButton("➕  Adicionar")
        btn_exc = QPushButton("Excluir selecionado")
        btn_add.clicked.connect(
            lambda _c=False, campo=campo, lista=lista: self._adicionar_emails_na_lista(campo, lista)
        )
        btn_exc.clicked.connect(
            lambda _c=False, lista=lista: self._excluir_emails_lista(lista)
        )
        h.addWidget(btn_add)
        h.addWidget(btn_exc)
        h.addStretch()
        return campo, lista, h

    def _emails_da_lista(self, lista) -> list:
        if lista is None:
            return []
        return [lista.item(i).text() for i in range(lista.count())]

    def _preencher_lista_emails(self, lista, emails):
        if lista is None:
            return
        lista.clear()
        vistos = set()
        for em in emails or []:
            em = str(em).strip()
            chave = em.lower()
            if not em or chave in vistos:
                continue
            vistos.add(chave)
            lista.addItem(em)

    def _adicionar_emails_na_lista(self, campo, lista):
        texto = campo.toPlainText() if hasattr(campo, "toPlainText") else campo.text()
        tokens = _tokens_campo_email(texto)
        if not tokens:
            QMessageBox.warning(
                self,
                "E-mail não informado",
                "Digite um e-mail no formato nome@dominio "
                "(precisa ter @), por exemplo ana@empresa.com, "
                "e clique em Adicionar.\n\n"
                "Em Para isso é obrigatório. Em Cópia é opcional "
                "(gerente e fiscais já entram automaticamente).",
            )
            return
        validos = []
        invalidos = []
        for tok in tokens:
            em, ruim = _classificar_token_email(tok)
            if em:
                validos.append(em)
            elif ruim:
                invalidos.append(ruim)
        if invalidos:
            QMessageBox.warning(
                self,
                "E-mail inválido",
                "Digite um e-mail correto no formato nome@dominio "
                "(precisa ter @), por exemplo ana@empresa.com.\n\n"
                "Inválido: " + ", ".join(invalidos),
            )
        atuais = {e.lower() for e in self._emails_da_lista(lista)}
        for email in validos:
            if email.lower() not in atuais:
                lista.addItem(email)
                atuais.add(email.lower())
        if invalidos:
            campo.setPlainText("\n".join(invalidos))
        else:
            campo.clear()
        if lista is getattr(self, "_lista_emails_para", None):
            self._fiscais_extra = self._emails_da_lista(lista)
        elif lista is getattr(self, "_lista_emails_cc", None):
            self._emails_cc_extra = self._emails_da_lista(lista)

    def _emails_invalidos_para_e_cc(self) -> tuple:
        """Itens inválidos em Para e em Cópia (lista + texto ainda não adicionado)."""
        ruins_para = []
        ruins_cc = []

        def _coletar(lista, campo):
            ruins = []
            for em in self._emails_da_lista(lista):
                _, ruim = _classificar_token_email(em)
                if ruim:
                    ruins.append(ruim)
            texto = ""
            if campo is not None:
                texto = (
                    campo.toPlainText()
                    if hasattr(campo, "toPlainText")
                    else campo.text()
                )
            for tok in _tokens_campo_email(texto):
                _, ruim = _classificar_token_email(tok)
                if ruim:
                    ruins.append(ruim)
            return ruins

        ruins_para = _coletar(
            getattr(self, "_lista_emails_para", None),
            getattr(self, "_campo_emails_para", None),
        )
        ruins_cc = _coletar(
            getattr(self, "_lista_emails_cc", None),
            getattr(self, "_campo_email_extra", None),
        )
        return ruins_para, ruins_cc

    def _excluir_emails_lista(self, lista):
        if lista is None:
            return
        for item in lista.selectedItems():
            lista.takeItem(lista.row(item))
        if lista is getattr(self, "_lista_emails_para", None):
            self._fiscais_extra = self._emails_da_lista(lista)
        elif lista is getattr(self, "_lista_emails_cc", None):
            self._emails_cc_extra = self._emails_da_lista(lista)

    def _preencher_confirmacao(self):
        while self._v_confirmacao.count():
            item = self._v_confirmacao.takeAt(0)
            if item.widget():
                item.widget().deleteLater()

        mes_nome = MESES_PT[self._combo_mes.currentData()]
        ano_ref  = self._spin_ano.value()

        card = QFrame()
        card.setObjectName("card")
        v_d = QVBoxLayout(card)
        v_d.setContentsMargins(16, 12, 16, 12)
        v_d.setSpacing(6)

        def _row(rot, val, cor=None):
            h = QHBoxLayout()
            l1 = QLabel(f"{rot}:")
            l1.setFont(QFont("Segoe UI", 8, QFont.Bold))
            l1.setStyleSheet(f"color: {TEXTO_OPACO};")
            l1.setFixedWidth(120)
            l2 = QLabel(str(val))
            l2.setFont(QFont("Consolas", 9))
            l2.setStyleSheet(f"color: {cor or TEXTO_CLARO};")
            l2.setWordWrap(True)
            h.addWidget(l1)
            h.addWidget(l2, stretch=1)
            w = QWidget()
            w.setStyleSheet("background: transparent;")
            w.setLayout(h)
            v_d.addWidget(w)

        _row("Contrato", self.numero_contrato_resultado, AMARELO_PETR)
        _row("Empresa", self._dados_sap.get("empresa", "—"))
        if self._modo_so_certidoes_ativo():
            cnpj = self._cnpj_contratada_ui()
            _row(
                "CNPJ",
                _formatar_cnpj(cnpj) if len(cnpj) == 14 else "—",
                VERDE_PETRO,
            )
            _row("Modo", "Apenas certidões (CND, CRF, CNDT)")
            _row("Período", f"{mes_nome.capitalize()}/{ano_ref}", VERDE_PETRO)
            url_sp = (self.url_resultado or "").strip()
            if url_sp:
                _row(
                    "SharePoint",
                    url_sp if len(url_sp) <= 72 else url_sp[:69] + "...",
                )
        else:
            _row("ICJ", self._dados_sap.get("icj", "—"))
            _row("Gerente", self._dados_sap.get("gerente", "—"))
            _row("Fiscais", ", ".join(self._dados_sap.get("fiscais", [])) or "—")
            _row("Período", f"{mes_nome.capitalize()}/{ano_ref}", VERDE_PETRO)
            _row("Pedidos Serviços", len(self._linhas_servico))
            _n_mat = len(getattr(self, "_pedidos_materiais", []) or [])
            if _n_mat:
                _row("Pedidos Materiais", _n_mat)
        if self.fila_jobs:
            _row("Já na fila", self._texto_fila(), AMARELO_PETR)

        self._v_confirmacao.addWidget(card)
        self._v_confirmacao.addStretch()

    def _montar_dados_finais(self):
        mes_num  = self._combo_mes.currentData()
        ano_ref  = self._spin_ano.value()
        data_ref = datetime(ano_ref, mes_num, 1)

        pedidos = [l["pedido"] for l in self._linhas_servico]
        folhas  = [l["frs"]    for l in self._linhas_servico]
        rms     = [
            {"rm": l["rm"], "nl": l["nl"], "centro": l["centro"]}
            for l in self._linhas_servico
        ]

        email_gerente_manual = ""
        _g_sap = (self._dados_sap.get("gerente") or "").strip()
        gerentes = (
            [_normalizar_nome_pessoa_sap(_g_sap) or _g_sap] if _g_sap else []
        )
        # Fiscal igual ao gerente: nunca vai cru (caixa alta / NBSP / código)
        fiscais = []
        for _f in (self._dados_sap.get("fiscais") or []):
            _fl = _normalizar_nome_pessoa_sap(_f) or str(_f or "").strip()
            if _fl and _fl not in fiscais:
                fiscais.append(_fl)
        emails_para = [
            em for em in self._emails_da_lista(
                getattr(self, "_lista_emails_para", None)
            )
            if _email_formato_padrao(em)
        ]
        if hasattr(self, "_campo_emails_para"):
            for tok in _tokens_campo_email(self._campo_emails_para.toPlainText()):
                em, ruim = _classificar_token_email(tok)
                if em and em.lower() not in {e.lower() for e in emails_para}:
                    emails_para.append(em)
        emails_cc_extra = [
            em for em in self._emails_da_lista(
                getattr(self, "_lista_emails_cc", None)
            )
            if _email_formato_padrao(em)
        ]
        if hasattr(self, "_campo_email_extra"):
            for tok in _tokens_campo_email(self._campo_email_extra.toPlainText()):
                em, ruim = _classificar_token_email(tok)
                if em and em.lower() not in {e.lower() for e in emails_cc_extra}:
                    emails_cc_extra.append(em)
        self._fiscais_extra = list(emails_para)
        self._emails_cc_extra = list(emails_cc_extra)
        preposta_nome = ""
        if hasattr(self, "_campo_nome_preposta"):
            preposta_nome = self._campo_nome_preposta.text().strip()
        preposta_tratamento = _tratamento_por_nome(preposta_nome)

        self._dados_planilha = (
            self._dados_sap.get("empresa", ""),
            self.numero_contrato_resultado,
            data_ref,
            self._dados_sap.get("icj", ""),
            pedidos,
            folhas,
            rms,
            gerentes,
            fiscais,
        )
        self._job_atual = {
            "empresa": self._dados_sap.get("empresa", ""),
            "contrato": self.numero_contrato_resultado,
            "data_ref": data_ref,
            "ano": ano_ref,
            "mes": mes_num,
            "icj": self._dados_sap.get("icj", ""),
            "pedidos": pedidos,
            "folhas": folhas,
            "rms": rms,
            "gerentes": gerentes,
            "fiscais": fiscais,
            "url_sharepoint": self.url_resultado,
            "linhas": list(self._linhas_servico),
            "pedidos_materiais": list(getattr(self, "_pedidos_materiais", []) or []),
            "emails_extra": list(self._fiscais_extra),
            "emails_para": list(emails_para),
            "emails_cc_extra": list(emails_cc_extra),
            "preposta_email": "",
            "preposta_nome": preposta_nome,
            "preposta_tratamento": preposta_tratamento,
            "email_gerente": email_gerente_manual,
            "dados_sap": dict(self._dados_sap or {}),
            "so_certidoes": self._modo_so_certidoes_ativo(),
            "cnpj_contratada": self._cnpj_contratada_ui(),
        }

    def _texto_fila(self) -> str:
        itens = [
            f"{j.get('contrato')} ({MESES_PT.get(j.get('mes'), j.get('mes'))}/{j.get('ano')})"
            for j in self.fila_jobs
        ]
        if not itens:
            return ""
        return "Na fila: " + "  →  ".join(itens)

    def _atualizar_lbl_fila(self):
        lbl = getattr(self, "_lbl_fila", None)
        if lbl is None:
            return
        txt = self._texto_fila()
        lbl.setText(txt if txt else "")

    def _perguntar_itens_comuns(self) -> dict | None:
        dlg = QDialog(self)
        dlg.setWindowTitle("O que permanece em comum?")
        dlg.setMinimumWidth(480)
        dlg.setStyleSheet(f"QDialog {{ background: {CINZA_BG}; color: {TEXTO_CLARO}; }}")
        v = QVBoxLayout(dlg)
        info = QLabel(
            "Este contrato vai para a fila. O próximo precisa de dados "
            "próprios (número, Pedido/FRS/RM/NL/Centro, e-mails).\n\n"
            "Marque só o que pode reaproveitar:"
        )
        info.setWordWrap(True)
        v.addWidget(info)
        ck_url = QCheckBox("Mesmo link do SharePoint")
        ck_url.setChecked(True)
        ck_ano = QCheckBox("Mesmo ano")
        ck_ano.setChecked(False)
        ck_mes = QCheckBox("Mesmo mês")
        ck_mes.setChecked(False)
        for ck in (ck_url, ck_ano, ck_mes):
            ck.setStyleSheet(f"color: {TEXTO_CLARO};")
            v.addWidget(ck)
        aviso = QLabel(
            "E-mail (gerente/fiscais/cópias), Pedido, FRS, RM, NL, "
            "Centro e os dados do contrato no SAP são sempre diferentes."
        )
        aviso.setWordWrap(True)
        aviso.setStyleSheet(f"color: {TEXTO_OPACO};")
        v.addWidget(aviso)
        h = QHBoxLayout()
        btn_ok = QPushButton("Continuar")
        btn_ok.setObjectName("btn_verde")
        btn_ok.clicked.connect(dlg.accept)
        btn_no = QPushButton("Cancelar")
        btn_no.clicked.connect(dlg.reject)
        h.addStretch()
        h.addWidget(btn_no)
        h.addWidget(btn_ok)
        v.addLayout(h)
        if dlg.exec() != QDialog.Accepted:
            return None
        return {
            "url": ck_url.isChecked(),
            "ano": ck_ano.isChecked(),
            "mes": ck_mes.isChecked(),
        }

    def _preparar_proximo_contrato(self, comum: dict):
        self._campo_contrato.clear()
        self._dados_sap = {}
        self._contrato_sap_consultado = ""
        self._linhas_servico = []
        self._pedidos_materiais = []
        self._fiscais_extra = []
        self._emails_cc_extra = []
        self._chave_cache_ui = None
        self._preencher_lista_emails(getattr(self, "_lista_emails_para", None), [])
        self._preencher_lista_emails(getattr(self, "_lista_emails_cc", None), [])
        campo_para = getattr(self, "_campo_emails_para", None)
        if campo_para is not None:
            campo_para.clear()
        campo_cc = getattr(self, "_campo_email_extra", None)
        if campo_cc is not None:
            campo_cc.clear()
        campo_nome = getattr(self, "_campo_nome_preposta", None)
        if campo_nome is not None:
            campo_nome.clear()
        campo_ger = getattr(self, "_campo_email_gerente", None)
        if campo_ger is not None:
            campo_ger.clear()
        self._lbl_sap_status.setText(
            "Informe o próximo contrato e clique em Buscar dados no SAP."
        )
        self._lbl_sap_status.setStyleSheet(f"color: {TEXTO_OPACO};")
        self._tabela_servicos.setRowCount(0)
        self._tabela_servicos.insertRow(0)
        self._tabela_servicos.setCurrentCell(0, 0)
        self._preencher_tabela_materiais([])
        if not comum.get("url"):
            if getattr(self, "_campo_url", None) is not None:
                self._campo_url.clear()
            self.url_resultado = ""
            self._reusar_url = False
        else:
            self._reusar_url = bool(self.url_resultado)
        if not comum.get("ano"):
            self._spin_ano.blockSignals(True)
            self._spin_ano.setValue(datetime.now().year)
            self._spin_ano.blockSignals(False)
        if not comum.get("mes"):
            self._combo_mes.blockSignals(True)
            self._combo_mes.setCurrentIndex(datetime.now().month - 1)
            self._combo_mes.blockSignals(False)
        self._stack.setCurrentIndex(0)
        self._btn_avancar.setText("Avançar  ▶")
        self._atualizar_lbl_fila()
        self._atualizar_botoes()

    def _adicionar_contrato_fila(self):
        if not self._validar_pagina_atual_para_captura():
            return
        self._montar_dados_finais()
        job = dict(getattr(self, "_job_atual") or {})
        if not job.get("contrato"):
            toast("Contrato incompleto.", "aviso", 3000)
            return
        self.fila_jobs.append(job)
        salvar_dados_contrato(
            job["contrato"],
            job.get("linhas") or [],
            job.get("emails_extra") or [],
            job.get("email_gerente") or "",
            job.get("dados_sap"),
            ano=job.get("ano"),
            mes=job.get("mes"),
            url_sharepoint=job.get("url_sharepoint") or "",
            emails_cc_extra=job.get("emails_cc_extra") or [],
            preposta_nome=job.get("preposta_nome") or "",
            pedidos_materiais=job.get("pedidos_materiais") or [],
        )
        self._atualizar_lbl_fila()
        comum = self._perguntar_itens_comuns()
        if comum is None:
            self.fila_jobs.pop()
            self._atualizar_lbl_fila()
            return
        toast(
            f"Contrato {job['contrato']} na fila "
            f"({len(self.fila_jobs)}). Preencha o próximo.",
            "sucesso",
            5000,
        )
        self._preparar_proximo_contrato(comum)

    def _msg_campo(self, titulo: str, texto: str):
        """Aviso que o usuário precisa fechar — o toast do canto está desligado."""
        QMessageBox.warning(self, titulo, texto)

    def _validar_emails_digitados(self) -> bool:
        ruins_para, ruins_cc = self._emails_invalidos_para_e_cc()
        if not (ruins_para or ruins_cc):
            return True
        partes = []
        if ruins_para:
            partes.append("Para: " + ", ".join(ruins_para))
        if ruins_cc:
            partes.append("Cópia: " + ", ".join(ruins_cc))
        self._msg_campo(
            "E-mail inválido",
            "Digite um e-mail correto no formato nome@dominio "
            "(precisa ter @), por exemplo ana@empresa.com.\n\n"
            + "\n".join(partes)
            + "\n\nPara é obrigatório. Cópia é opcional "
            "(pode ficar só com gerente e fiscais automáticos).",
        )
        return False

    def _validar_pagina_atual_para_captura(self) -> bool:
        if self._modo_so_certidoes_ativo():
            numero = (
                self.numero_contrato_resultado
                or self._campo_contrato.text().strip()
            )
            if not numero:
                self._msg_campo(
                    "Contrato",
                    "Digite o número do contrato.",
                )
                return False
            if not self._cnpj_sap_certidoes_pronto(numero):
                self._msg_campo(
                    "CNPJ da contratada",
                    "O CNPJ ainda não foi obtido no SAP.\n\n"
                    "Na primeira tela, clique em 'Buscar dados no SAP' "
                    "e aguarde aparecer o CNPJ no painel abaixo do contrato.",
                )
                return False
            if not (self.url_resultado or "").startswith("https://"):
                self._msg_campo(
                    "URL do SharePoint",
                    "Digite a URL do SharePoint deste contrato "
                    "(deve começar com https://).",
                )
                return False
            return True
        if not self.numero_contrato_resultado or not self._linhas_servico:
            self._msg_campo(
                "Campos obrigatórios",
                "Volte e complete o contrato e os serviços "
                "(Pedido, FRS, RM e NL).",
            )
            return False
        if not (self.url_resultado or "").startswith("https://"):
            self._msg_campo(
                "URL do SharePoint",
                "Digite a URL do SharePoint deste contrato "
                "(deve começar com https://).",
            )
            return False
        if not self._validar_emails_digitados():
            return False
        lista_para = self._emails_da_lista(getattr(self, "_lista_emails_para", None))
        tem_para = any(_email_formato_padrao(e) for e in lista_para)
        campo_para = getattr(self, "_campo_emails_para", None)
        if campo_para is not None and not tem_para:
            for tok in _tokens_campo_email(
                campo_para.toPlainText()
                if hasattr(campo_para, "toPlainText")
                else campo_para.text()
            ):
                em, _ruim = _classificar_token_email(tok)
                if em:
                    tem_para = True
                    break
        if not tem_para:
            self._msg_campo(
                "E-mail em Para",
                "Digite pelo menos um e-mail em Para no formato "
                "nome@dominio (exemplo: ana@empresa.com).\n\n"
                "Cópia (CC) é opcional — pode ficar vazia, só com "
                "gerente e fiscais automáticos.",
            )
            try:
                self._campo_emails_para.setFocus()
            except Exception:
                pass
            return False
        return True

    # ── Navegação
    def _avancar(self):
        idx = self._stack.currentIndex()

        if idx == 0:
            numero = self._campo_contrato.text().strip()
            if not numero:
                self._msg_campo(
                    "Contrato",
                    "Digite o número do contrato.",
                )
                self._campo_contrato.setFocus()
                return

            if self._modo_so_certidoes_ativo():
                if not self._cnpj_sap_certidoes_pronto(numero):
                    self._msg_campo(
                        "CNPJ da contratada",
                        "Clique em 'Buscar dados no SAP' para obter o CNPJ "
                        "da contratada (ME33K + XK03) antes de avançar.",
                    )
                    try:
                        self._btn_buscar_sap.setFocus()
                    except Exception:
                        pass
                    return
                self._continuar_avancar_certidoes(numero)
                return

            if not self._dados_sap:
                self._msg_campo(
                    "Buscar dados no SAP",
                    "Clique em 'Buscar dados no SAP' antes de avançar.",
                )
                try:
                    self._btn_buscar_sap.setFocus()
                except Exception:
                    pass
                return

            linhas = []
            for row in range(self._tabela_servicos.rowCount()):
                def _txt(col):
                    it = self._tabela_servicos.item(row, col)
                    return it.text().strip() if it else ""
                pedido, frs, rm, nl = (
                    _txt(0), _txt(1), _txt(2), _txt(3)
                )
                if not any([pedido, frs, rm, nl]):
                    continue
                faltando = []
                if not pedido:
                    faltando.append("Pedido")
                if not frs:
                    faltando.append("FRS")
                if not rm:
                    faltando.append("RM")
                if not nl:
                    faltando.append("NL")
                if faltando:
                    self._msg_campo(
                        "Campo obrigatório",
                        f"Linha {row + 1}: digite "
                        + ", ".join(faltando)
                        + ".",
                    )
                    self._tabela_servicos.setCurrentCell(row, 0)
                    return
                err_p = _msg_digitos_documento("Pedido", pedido)
                err_f = _msg_digitos_documento("FRS", frs)
                if err_p or err_f:
                    self._msg_campo(
                        "Pedido ou FRS incorreto",
                        f"Linha {row + 1}: verifique o número.\n\n"
                        f"{err_p or err_f}\n\n"
                        "Pedido e FRS precisam ter exatamente 10 dígitos. "
                        "Corrija na tabela e clique em Avançar de novo.",
                    )
                    self._tabela_servicos.setCurrentCell(
                        row, 0 if err_p else 1
                    )
                    return
                linhas.append(
                    {"pedido": pedido, "frs": frs, "rm": rm, "nl": nl, "centro": ""}
                )

            if not linhas:
                self._msg_campo(
                    "Serviços do mês",
                    "Digite pelo menos uma linha com Pedido, FRS, RM e NL.",
                )
                self._tabela_servicos.setCurrentCell(0, 0)
                return

            pedidos_mat = []
            tab_m = getattr(self, "_tabela_materiais", None)
            if tab_m is not None:
                for row in range(tab_m.rowCount()):
                    it = tab_m.item(row, 0)
                    ped_m = it.text().strip() if it else ""
                    if not ped_m:
                        continue
                    err_m = _msg_digitos_documento("Pedido", ped_m)
                    if err_m:
                        self._msg_campo(
                            "Pedido de material incorreto",
                            f"Linha {row + 1} de materiais: verifique o número.\n\n"
                            f"{err_m}\n\n"
                            "Pedido de material precisa ter exatamente 10 dígitos. "
                            "Corrija na tabela e clique em Avançar de novo.",
                        )
                        tab_m.setCurrentCell(row, 0)
                        return
                    pedidos_mat.append(ped_m)
            self._pedidos_materiais = list(dict.fromkeys(pedidos_mat))

            self._linhas_servico = linhas
            self.numero_contrato_resultado = numero
            salvar_config_contrato(numero)
            try:
                self._persistir_tabelas_periodo_atual(
                    linhas=linhas,
                    pedidos_mat=self._pedidos_materiais,
                )
            except Exception:
                pass
            if self._reusar_url and (self.url_resultado or "").startswith("https://"):
                self._preencher_confirmacao()
                self._stack.setCurrentIndex(2)
                n = len(self.fila_jobs) + 1
                self._btn_avancar.setText(
                    f"▶  Iniciar ({n} contrato" + ("s" if n > 1 else "") + ")"
                )
            else:
                self._stack.setCurrentIndex(1)

        elif idx == 1:
            url = self._campo_url.toPlainText().strip()
            if not url:
                self._msg_campo(
                    "URL do SharePoint",
                    "Digite a URL do SharePoint deste contrato.",
                )
                self._campo_url.setFocus()
                return
            if not url.startswith("https://"):
                self._msg_campo(
                    "URL do SharePoint",
                    "A URL deve começar com https://. "
                    "Digite a URL completa do SharePoint.",
                )
                self._campo_url.setFocus()
                return
            self.url_resultado = url
            salvar_config_sharepoint(url)
            if self._modo_so_certidoes_ativo():
                self._finalizar_job_atual()
                return
            self._preencher_confirmacao()
            self._stack.setCurrentIndex(2)
            self._btn_avancar.setText("▶  Iniciar Automação")

        elif idx == 2:
            self._finalizar_job_atual()
            return

        self._atualizar_botoes()

    def _finalizar_job_atual(self):
        self._montar_dados_finais()
        job = dict(getattr(self, "_job_atual") or {})
        if not job.get("so_certidoes"):
            if not self._validar_emails_digitados():
                return
            if not job.get("emails_para"):
                self._msg_campo(
                    "E-mail em Para",
                    "Digite pelo menos um e-mail em Para no formato "
                    "nome@dominio (exemplo: ana@empresa.com).\n\n"
                    "Cópia (CC) é opcional — pode ficar vazia, só com "
                    "gerente e fiscais automáticos.",
                )
                try:
                    self._campo_emails_para.setFocus()
                except Exception:
                    pass
                return
        if not job.get("so_certidoes") and not (job.get("preposta_nome") or "").strip():
            self._msg_campo(
                "Nome da preposta/preposto",
                "Digite o nome da preposta/preposto para a "
                "saudação do e-mail.",
            )
            try:
                self._campo_nome_preposta.setFocus()
            except Exception:
                pass
            return
        salvar_dados_contrato(
            self.numero_contrato_resultado,
            self._linhas_servico,
            self._fiscais_extra,
            self._campo_email_gerente.text().strip(),
            self._dados_sap,
            ano=self._spin_ano.value(),
            mes=self._combo_mes.currentData(),
            url_sharepoint=self.url_resultado,
            emails_cc_extra=self._emails_cc_extra,
            preposta_nome=job.get("preposta_nome") or "",
            pedidos_materiais=getattr(self, "_pedidos_materiais", []) or [],
        )
        if job.get("contrato"):
            self.fila_jobs.append(job)
        self.accept()

    def _voltar(self):
        idx = self._stack.currentIndex()
        if idx > 0:
            self._stack.setCurrentIndex(idx - 1)
            if idx == 2:
                self._btn_avancar.setText("Avançar  ▶")
        self._atualizar_botoes()

    def _atualizar_botoes(self):
        idx = self._stack.currentIndex()
        self._btn_voltar.setEnabled(idx > 0)
        nfila = len(self.fila_jobs)
        extra = f"  ·  {nfila} na fila" if nfila else ""
        so_cert = self._modo_so_certidoes_ativo()
        total_etapas = 2 if so_cert else 3
        self._lbl_etapa.setText(f"Etapa {idx + 1} de {total_etapas}{extra}")
        self._barra_etapas.setMaximum(total_etapas)
        self._barra_etapas.setValue(idx + 1)
        if getattr(self, "_btn_fila", None) is not None:
            self._btn_fila.setVisible(idx == 2)

        if idx == 0:
            self._btn_avancar.setEnabled(True)
            self._btn_avancar.setText("Avançar  ▶")
        elif idx == 1:
            self._btn_avancar.setEnabled(True)
            if so_cert:
                n = nfila + 1
                self._btn_avancar.setText(
                    f"▶  Iniciar ({n} contrato" + ("s" if n > 1 else "") + ")"
                )
            else:
                self._btn_avancar.setText("Avançar  ▶")
        else:
            self._btn_avancar.setEnabled(True)
            n = nfila + 1
            self._btn_avancar.setText(
                f"▶  Iniciar ({n} contrato" + ("s" if n > 1 else "") + ")"
            )
        self._atualizar_lbl_fila()

